
                    // ===== SECURITY HELPERS =====
                    function sanitizeHTML(str) {
                        if (!str) return '';
                        const div = document.createElement('div');
                        div.textContent = str;
                        return div.innerHTML;
                    }
                    function sanitizeInput(str) {
                        if (!str) return '';
                        return str.replace(/[<>&"']/g, function (m) {
                            return { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": "'" }[m];
                        });
                    }
                    function validateEmail(email) {
                        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
                    }
                    let csrfToken = (function () {
                        const arr = new Uint8Array(32);
                        crypto.getRandomValues(arr);
                        return Array.from(arr, b => b.toString(16).padStart(2, '0')).join('');
                    })();
                    // ===== END SECURITY HELPERS =====

                    function escHtml(str) { if (!str) return ''; return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;'); }

                    function customFollowupTableSearchFilter() {
                        var input = document.getElementById("followupSearchInput").value.toLowerCase();
                        var tableBody = document.getElementById("followupCasesTableBody");
                        if (!tableBody) return;
                        var rows = tableBody.getElementsByTagName("tr");

                        for (var i = 0; i < rows.length; i++) {
                            var rowText = rows[i].textContent.toLowerCase();
                            if (rowText.includes(input)) {
                                rows[i].style.display = "";
                            } else {
                                rows[i].style.display = "none";
                            }
                        }
                    }
