                    // Dynamically calculates leave balances (Caps minus approved taken leaves)
                    function calculateRosterLeaveBalances(email) {
                        const user = globalRosterRepository.find(u => u.email === email);

                        const maxSick = parseFloat(document.getElementById('lSickCeil')?.value) || 30;
                        const maxAnnual = parseFloat(document.getElementById('lAnnualCeil')?.value) || 30;
                        const maxFamily = parseFloat(document.getElementById('lFamilyCeil')?.value) || 15;

                        if (!user) return { sickTaken: 0, sickLeft: maxSick, annualTaken: 0, annualLeft: maxAnnual, familyTaken: 0, familyLeft: maxFamily };

                        let sickTaken = 0, annualTaken = 0, familyTaken = 0;
                        const approvedLeaves = globalLeaveRepository.filter(l => l.email === email && l.status === "Approved");

                        approvedLeaves.forEach(l => {
                            if (l.type === "Sick Leave") sickTaken += parseFloat(l.duration) || 0;
                            if (l.type === "Annual Leave") annualTaken += parseFloat(l.duration) || 0;
                            if (l.type === "Family Leave" || l.type === "Family Responsibility Leave") familyTaken += parseFloat(l.duration) || 0;
                        });

                        return {
                            sickTaken: sickTaken,
                            sickLeft: Math.max(0, maxSick - sickTaken),
                            annualTaken: annualTaken,
                            annualLeft: Math.max(0, maxAnnual - annualTaken),
                            familyTaken: familyTaken,
                            familyLeft: Math.max(0, maxFamily - familyTaken)
                        };
                    }
                    function onFollowupYearChange() {
                        renderFollowupCasesTable();
                    }
                    function getTodayFormattedDDMMYYYY() {
                        const now = new Date();
                        const year = now.getFullYear();
                        const month = String(now.getMonth() + 1).padStart(2, '0');
                        const day = String(now.getDate()).padStart(2, '0');
                        return `${day}/${month}/${year}`;
                    }
                    function getTodayISOString() {
                        const now = new Date();
                        const year = now.getFullYear();
                        const month = String(now.getMonth() + 1).padStart(2, '0');
                        const day = String(now.getDate()).padStart(2, '0');
                        return `${year}-${month}-${day}`;
                    }
                    function populateReferenceYearSelector() {
                        const yearSel = document.getElementById('referenceYearSelector');
                        if (!yearSel) return;
                        yearSel.innerHTML = '<option value="all">All Years</option>';

                        const currentYear = new Date().getFullYear(); // Evaluates to 2026

                        // Populate chronologically descending from 2099 down to 2022
                        for (let yr = 2099; yr >= 2022; yr--) {
                            const opt = document.createElement('option');
                            opt.value = String(yr);
                            opt.innerText = String(yr);
                            if (yr === currentYear) {
                                opt.selected = true; // Auto-select current year (2026)
                            }
                            yearSel.appendChild(opt);
                        }
                    }
                    function syncDatePickerToVisibleInput(val) {
                        const visibleInput = document.getElementById('docRefField_date_visible');
                        if (visibleInput && val) {
                            const parts = val.split('-');
                            if (parts.length === 3) {
                                visibleInput.value = `${parts[2]}/${parts[1]}/${parts[0]}`;
                            }
                        }
                        updateSequentialIDLivePreview();
                    }

                    function formatDateToDDMMYYYY(dateStr) {
                        if (!dateStr || dateStr === "N/A" || dateStr === "") return "-";

                        // Handle ISO YYYY-MM-DD format (outputs dd/mm/yyyy)
                        const parts = dateStr.split('-');
                        if (parts.length === 3) {
                            const yyyy = parts[0];
                            const mm = parts[1].padStart(2, '0');
                            const dd = parts[2].padStart(2, '0');
                            return `${dd}/${mm}/${yyyy}`;
                        }

                        // Handle M/D/YYYY slash format (outputs dd/mm/yyyy)
                        const slashParts = dateStr.split('/');
                        if (slashParts.length === 3) {
                            const mm = slashParts[0].padStart(2, '0');
                            const dd = slashParts[1].padStart(2, '0');
                            const yyyy = slashParts[2].length === 2 ? "20" + slashParts[2] : slashParts[2];
                            return `${dd}/${mm}/${yyyy}`;
                        }

                        return dateStr;
                    }

                    function onFollowupMonthChange() {
                        renderFollowupCasesTable();
                    }
                    function renderFutureModuleTable() {
                        // 1. Get the value from the new input ID
                        const cycleSelectorValue = document.getElementById('futureModuleSearchSelector') ? document.getElementById('futureModuleSearchSelector').value : "";

                        // 2. Filter the source data
                        const filteredRecords = globalFollowupCasesRepository.filter(record => {
                            // Use the 7-character substring match ("YYYY-MM")
                            const recordCycle = record.date ? record.date.substring(0, 7) : "";
                            // Return matching records or all if input is empty
                            return (!cycleSelectorValue || recordCycle === cycleSelectorValue);
                        });

                        // 3. Update the follow-up table UI with filteredRecords
                        const tbody = document.getElementById('followupCasesTableBody');
                        if (!tbody) return;
                        tbody.innerHTML = "";
                        if (filteredRecords.length === 0) {
                            tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; color:var(--text-muted); font-style:italic; padding:12px;">No follow-up cases found for the selected cycle.</td></tr>`;
                            return;
                        }
                        filteredRecords.forEach(r => {
                            const tr = document.createElement('tr');
                            tr.innerHTML = `
            <td>${formatDateToDDMMYYYY(r.date)}</td>
            <td><strong>${r.patient || '-'}</strong></td>
            <td>${r.diagnosis || '-'}</td>
            <td>${r.therapist || '-'}</td>
            <td>${r.notes || '-'}</td>
            <td><span class="badge badge-warning">${r.status || 'Pending'}</span></td>
        `;
                            tbody.appendChild(tr);
                        });
                    }



                    // ===== PS CALENDAR DATA & CONFIG =====
                    let psCalendarData = {
                        2026: {},
                        2025: {},
                        2027: {}
                    };

                    let psCalendarTypes = {
                        "working": { label: "Working Day", bg: "var(--bg-inner)", border: "var(--border)", text: "var(--text-body)" },
                        "holiday": { label: "Holiday", bg: "#fecaca", border: "#f87171", text: "#991b1b" },
                        "prof-dev": { label: "Prof. Development", bg: "#dbeafe", border: "#60a5fa", text: "#1e40af" },
                        "special": { label: "Special Day", bg: "#fde68a", border: "#fbbf24", text: "#92400e" }
                    };

                    let psCalendarSelectedType = 'holiday';
                    let psCalendarCurrentYear = 2026;

                    // Initialize with Maldives 2026 holidays
                    function initializePSCalendarDefaults() {
                        // No default holidays
                    }

                    function renderPSCalendarGrid() {
                        const yearEl = document.getElementById('psCalendarYearSelector');
                        const year = yearEl ? parseInt(yearEl.value) || psCalendarCurrentYear : psCalendarCurrentYear;
                        psCalendarCurrentYear = year;
                        const grid = document.getElementById('psCalendarYearGrid');
                        if (!grid) return;

                        grid.innerHTML = '';
                        const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
                        const dayHeaders = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

                        let stats = { working: 0, holiday: 0, 'prof-dev': 0, special: 0 };

                        months.forEach((monthName, monthIndex) => {
                            const monthCard = document.createElement('div');
                            monthCard.className = 'ps-calendar-month-card';

                            const title = document.createElement('div');
                            title.className = 'ps-calendar-month-title';
                            title.innerText = monthName + ' ' + year;
                            monthCard.appendChild(title);

                            const daysGrid = document.createElement('div');
                            daysGrid.className = 'ps-calendar-days-grid';

                            // Day headers
                            dayHeaders.forEach(d => {
                                const h = document.createElement('div');
                                h.className = 'ps-calendar-day-header';
                                h.innerText = d;
                                daysGrid.appendChild(h);
                            });

                            // Calculate days
                            const firstDay = new Date(year, monthIndex, 1);
                            const lastDay = new Date(year, monthIndex + 1, 0);
                            const startDayOfWeek = firstDay.getDay();
                            const daysInMonth = lastDay.getDate();

                            // Empty cells before first day
                            for (let i = 0; i < startDayOfWeek; i++) {
                                const empty = document.createElement('div');
                                empty.className = 'ps-calendar-day-cell';
                                empty.style.visibility = 'hidden';
                                daysGrid.appendChild(empty);
                            }

                            // Day cells
                            for (let d = 1; d <= daysInMonth; d++) {
                                const dateStr = year + '-' + String(monthIndex + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0');
                                const dayOfWeek = new Date(year, monthIndex, d).getDay();
                                const isFriday = dayOfWeek === 5;
                                const isToday = dateStr === new Date().toISOString().split('T')[0];

                                let dayType = 'working';
                                let dayName = '';

                                if (psCalendarData[year] && psCalendarData[year][dateStr]) {
                                    dayType = psCalendarData[year][dateStr].type;
                                    dayName = psCalendarData[year][dateStr].name || '';
                                } else if (isFriday) {
                                    dayType = 'friday';
                                }

                                stats[dayType] = (stats[dayType] || 0) + 1;
                                if (dayType === 'working' && !isFriday) stats.working++;

                                const cell = document.createElement('div');
                                cell.className = 'ps-calendar-day-cell ' + dayType + (isToday ? ' today' : '');
                                cell.innerText = d;
                                cell.title = dayName || (isFriday ? 'Friday (Off)' : 'Working Day');
                                cell.onclick = function () { togglePSCalendarDay(dateStr, dayType); };

                                if (dayName) {
                                    const indicator = document.createElement('span');
                                    indicator.className = 'day-indicator';
                                    indicator.style.background = psCalendarTypes[dayType] ? psCalendarTypes[dayType].border : '#999';
                                    cell.appendChild(indicator);
                                }

                                daysGrid.appendChild(cell);
                            }

                            monthCard.appendChild(daysGrid);
                            grid.appendChild(monthCard);
                        });

                        // Update stats
                        document.getElementById('psCalendarStatWorking').innerText = stats.working || 0;
                        document.getElementById('psCalendarStatHoliday').innerText = stats.holiday || 0;
                        document.getElementById('psCalendarStatProfDev').innerText = stats['prof-dev'] || 0;
                        document.getElementById('psCalendarStatSpecial').innerText = stats.special || 0;

                        renderPSCalendarUpcoming();
                    }

                    function selectPSCalendarType(type) {
                        psCalendarSelectedType = type;
                        document.querySelectorAll('.ps-calendar-type-chip').forEach(chip => {
                            chip.classList.toggle('active', chip.dataset.type === type);
                        });
                    }

                    function togglePSCalendarDay(dateStr, currentType) {
                        const isAdmin = allowedBroadcasterRoles.includes(currentActiveSessionUser.position);
                        if (!isAdmin) {
                            customAlert("Only authorized personnel can modify the calendar.");
                            return;
                        }

                        const year = psCalendarCurrentYear;
                        if (!psCalendarData[year]) psCalendarData[year] = {};

                        if (currentType === psCalendarSelectedType) {
                            // Remove the marking
                            delete psCalendarData[year][dateStr];
                        } else {
                            // Add/change the marking
                            psCalendarData[year][dateStr] = { type: psCalendarSelectedType, name: psCalendarTypes[psCalendarSelectedType].label };
                        }

                        renderPSCalendarGrid();
                    }

                    function addPSCalendarCustomType() {
                        const name = document.getElementById('psCalendarNewTypeName').value.trim();
                        const bgColor = document.getElementById('psCalendarNewTypeColor').value;
                        const textColor = document.getElementById('psCalendarNewTypeTextColor').value;

                        if (!name) { customAlert("Please enter a type name."); return; }

                        const typeId = 'custom_' + Date.now();
                        psCalendarTypes[typeId] = { label: name, bg: bgColor, border: bgColor, text: textColor };

                        // Add to UI
                        const manager = document.getElementById('psCalendarTypeManager');
                        const chip = document.createElement('div');
                        chip.className = 'ps-calendar-type-chip';
                        chip.dataset.type = typeId;
                        chip.style.background = bgColor;
                        chip.style.color = textColor;
                        chip.innerHTML = '<span style="width: 8px; height: 8px; background: ' + bgColor + '; border: 1px solid ' + textColor + '; border-radius: 2px; display: inline-block;"></span> ' + name;
                        chip.onclick = function () { selectPSCalendarType(typeId); };
                        manager.appendChild(chip);

                        document.getElementById('psCalendarNewTypeName').value = '';
                        customAlert("Custom type '" + name + "' added successfully!");
                    }

                    function renderPSCalendarUpcoming() {
                        const list = document.getElementById('psCalendarUpcomingList');
                        if (!list) return;
                        list.innerHTML = '';

                        const today = new Date();
                        const thirtyDaysLater = new Date();
                        thirtyDaysLater.setDate(today.getDate() + 30);

                        const upcoming = [];
                        const year = psCalendarCurrentYear;

                        if (psCalendarData[year]) {
                            Object.keys(psCalendarData[year]).forEach(dateStr => {
                                const date = new Date(dateStr);
                                if (date >= today && date <= thirtyDaysLater) {
                                    upcoming.push({
                                        date: dateStr,
                                        type: psCalendarData[year][dateStr].type,
                                        name: psCalendarData[year][dateStr].name || psCalendarTypes[psCalendarData[year][dateStr].type].label
                                    });
                                }
                            });
                        }

                        // Sort by date
                        upcoming.sort((a, b) => new Date(a.date) - new Date(b.date));

                        if (upcoming.length === 0) {
                            list.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-style: italic; padding: 20px;">No upcoming special days in the next 30 days.</div>';
                            return;
                        }

                        upcoming.forEach(item => {
                            const typeConfig = psCalendarTypes[item.type] || psCalendarTypes['special'];
                            const div = document.createElement('div');
                            div.className = 'ps-calendar-upcoming-item';
                            div.innerHTML = '<span class="ps-calendar-upcoming-date">' + formatDateToDDMMYYYY(item.date) + '</span><span class="ps-calendar-upcoming-name">' + item.name + '</span><span class="ps-calendar-upcoming-type" style="background: ' + typeConfig.bg + '; color: ' + typeConfig.text + ';">' + item.type + '</span>';
                            list.appendChild(div);
                        });
                    }

                    // Check if a date is a holiday/special day (used by other modules)
                    function isPSCalendarHoliday(dateStr) {
                        const year = parseInt(dateStr.split('-')[0]);
                        if (psCalendarData[year] && psCalendarData[year][dateStr]) {
                            return psCalendarData[year][dateStr].type !== 'working';
                        }
                        const gp = dateStr.split('-');
                        const dayOfWeek = new Date(parseInt(gp[0]), parseInt(gp[1]) - 1, parseInt(gp[2])).getDay();
                        return dayOfWeek === 5; // Friday is always off
                    }

                    function getPSCalendarDayType(dateStr) {
                        const year = parseInt(dateStr.split('-')[0]);
                        if (psCalendarData[year] && psCalendarData[year][dateStr]) {
                            return psCalendarData[year][dateStr].type;
                        }
                        const gp = dateStr.split('-');
                        const dayOfWeek = new Date(parseInt(gp[0]), parseInt(gp[1]) - 1, parseInt(gp[2])).getDay();
                        return dayOfWeek === 5 ? 'friday' : 'working';
                    }



                    // ===== PS CALENDAR SYSTEM =====
                    let psCalData = {};
                    let psCalSelType = 'holiday';

                    let psCalCustomTypes = {}; // Store custom type definitions: { typeId: { label, bg, border, text } }
                    let psCalSyncedModules = { roster: true, masterOT: true, leave: false };

                    function savePSCalDataToStorage() {
                        try { localStorage.setItem('psCalData', JSON.stringify(psCalData)); } catch (e) { }
                        try { localStorage.setItem('psCalCustomTypes', JSON.stringify(psCalCustomTypes)); } catch (e) { }
                    }

                    function loadPSCalDataFromStorage() {
                        try {
                            const saved = localStorage.getItem('psCalData');
                            if (saved) { psCalData = JSON.parse(saved); return true; }
                        } catch (e) { }
                        return false;
                    }

                    function initPSCal() {
                        // Load saved data from localStorage first
                        if (loadPSCalDataFromStorage()) {
                            try {
                                const savedTypes = localStorage.getItem('psCalCustomTypes');
                                if (savedTypes) psCalCustomTypes = JSON.parse(savedTypes);
                            } catch (e) { }
                            return;
                        }
                        // No default holidays - start empty
                        psCalData = {};
                        psCalCustomTypes = {};
                        psCalSyncedModules = { roster: true, masterOT: true, leave: false };
                        savePSCalDataToStorage();
                    }

                    function renderPSCal() {
                        const year = document.getElementById('psCalYear').value;
                        const grid = document.getElementById('psCalGrid');
                        if (!grid) return;

                        grid.innerHTML = '';
                        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                        const dayH = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
                        let stats = { work: 0, hol: 0, prof: 0, spec: 0, fri: 0, totalDays: 0, customCounts: {} };

                        months.forEach((m, mi) => {
                            const box = document.createElement('div');
                            box.className = 'ps-cal-month-box';
                            box.innerHTML = '<div class="ps-cal-month-title">' + m + ' ' + year + '</div>';

                            const days = document.createElement('div');
                            days.className = 'ps-cal-days';

                            dayH.forEach(d => days.innerHTML += '<div class="ps-cal-day-h">' + d + '</div>');

                            const first = new Date(parseInt(year), mi, 1);
                            const last = new Date(parseInt(year), mi + 1, 0);
                            const startDay = first.getDay();
                            const numDays = last.getDate();

                            for (let i = 0; i < startDay; i++) {
                                days.innerHTML += '<div class="ps-cal-day" style="visibility:hidden"></div>';
                            }

                            for (let d = 1; d <= numDays; d++) {
                                const ds = year + '-' + String(mi + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0');
                                const dow = new Date(parseInt(year), mi, d).getDay();
                                const isFri = dow === 5;
                                stats.totalDays++;
                                if (isFri) stats.fri++;
                                const isToday = ds === new Date().toISOString().split('T')[0];
                                const entry = psCalData[ds];

                                let cls = 'work';
                                let title = 'Working Day';
                                let displayName = '';
                                let cellStyle = '';

                                if (isFri) {
                                    cls = 'fri';
                                    title = 'Friday (Off)';
                                }

                                if (entry) {
                                    cls = entry.t;
                                    title = entry.n;
                                    displayName = entry.n;

                                    // Get color config for this type
                                    const typeConfig = getPSCalTypeConfig(entry.t);
                                    if (typeConfig) {
                                        cellStyle = `background: ${typeConfig.bg}; color: ${typeConfig.text}; border-color: ${typeConfig.border};`;
                                    }

                                    if (entry.t === 'holiday') stats.hol++;
                                    else if (entry.t === 'prof-dev') stats.prof++;
                                    else if (entry.t === 'special') stats.spec++;
                                    else if (psCalCustomTypes[entry.t]) { if (!stats.customCounts[entry.t]) stats.customCounts[entry.t] = 0; stats.customCounts[entry.t]++; }
                                }
                                else if (!isFri) { stats.work++; }

                                const cell = document.createElement('div');
                                cell.className = 'ps-cal-day ' + cls + (isToday ? ' today' : '');
                                cell.innerText = d;
                                cell.title = title;
                                if (cellStyle) cell.style.cssText = cellStyle;
                                cell.onclick = function () { clickPSCalDay(ds, cls); };

                                // Add event name label inside the cell (not just a dot)
                                if (displayName) {
                                    const label = document.createElement('span');
                                    label.className = 'day-label';
                                    label.innerText = displayName.length > 6 ? displayName.substring(0, 5) + '..' : displayName;
                                    cell.appendChild(label);
                                }

                                days.appendChild(cell);
                            }

                            box.appendChild(days);
                            grid.appendChild(box);
                        });

                        renderPSCalStats(stats);
                        renderPSCalUpcoming();
                        updatePSCalLegend();
                        highlightActiveTypeChip();

                        // Show admin box for editors
                        const isEd = allowedPSCalendarEditorRoles.includes(currentActiveSessionUser ? currentActiveSessionUser.position : '');
                        const ab = document.getElementById('psCalAdminBox');
                        if (ab) ab.style.display = isEd ? 'block' : 'none';

                        // Show sync panel for editors
                        const syncPanel = document.getElementById('psCalSyncPanel');
                        if (syncPanel) syncPanel.style.display = isEd ? 'block' : 'none';
                    }

                    function renderPSCalStats(stats) {
                        const container = document.getElementById('psCalStatsContainer');
                        if (!container) return;
                        let tiles = [];

                        const openDays = stats.totalDays - (stats.fri || 0) - (stats.hol || 0);
                        const workedPct = stats.totalDays > 0 ? Math.round(openDays / stats.totalDays * 100) : 0;

                        const builtInTypes = [
                            { key: 'working', label: 'Working', color: 'var(--primary)', icon: '⚪' },
                            { key: 'holiday', label: 'Holidays', color: 'var(--danger)', icon: '🔴' },
                            { key: 'prof-dev', label: 'Prof. Dev', color: '#1e40af', icon: '🔵' },
                            { key: 'special', label: 'Special', color: '#92400e', icon: '🟡' },
                            { key: 'fri', label: 'Fridays', color: '#6b7280', icon: '⬜' },
                            { key: 'open', label: 'Open Days', color: 'var(--success)', icon: '📆' },
                            { key: 'workedPct', label: 'Worked %', color: 'var(--primary)', icon: '📊' },
                        ];
                        // Override counts for computed stats
                        const computedStats = { ...stats, open: openDays, workedPct: workedPct + '%' };

                        builtInTypes.forEach(t => {
                            const statKey = t.key === 'working' ? 'work' : t.key === 'holiday' ? 'hol' : t.key === 'prof-dev' ? 'prof' : t.key === 'special' ? 'spec' : t.key;
                            const count = computedStats[statKey] || 0;
                            tiles.push({ label: t.label, count: count, color: t.color, icon: t.icon });
                        });

                        Object.keys(psCalCustomTypes).forEach(key => {
                            const cfg = psCalCustomTypes[key];
                            const count = stats.customCounts && stats.customCounts[key] ? stats.customCounts[key] : 0;
                            tiles.push({ label: cfg.label, count: count, color: cfg.text, icon: '🟣' });
                        });

                        if (tiles.length === 0) { container.innerHTML = '<div style="color:var(--text-muted);font-size:9px;">No data</div>'; return; }

                        container.innerHTML = tiles.map(t => `
        <div style="background:var(--bg-inner);padding:8px;border-radius:4px;text-align:center;border:1px solid var(--border);">
            <span style="font-size:10px;color:var(--text-muted);display:block;">${t.icon} ${t.label}</span>
            <span style="font-size:14px;font-weight:800;color:${t.color};">${t.count}</span>
        </div>
    `).join('');
                    }

                    function getPSCalTypeConfig(typeKey) {
                        // Built-in types
                        const builtIn = {
                            "holiday": { bg: "#fecaca", border: "#f87171", text: "#991b1b" },
                            "prof-dev": { bg: "#dbeafe", border: "#60a5fa", text: "#1e40af" },
                            "special": { bg: "#fde68a", border: "#fbbf24", text: "#92400e" },
                            "working": { bg: "var(--bg-inner)", border: "var(--border)", text: "var(--text-body)" },
                            "friday": { bg: "#e5e7eb", border: "#d1d5db", text: "#6b7280" }
                        };

                        if (builtIn[typeKey]) return builtIn[typeKey];
                        if (psCalCustomTypes[typeKey]) return psCalCustomTypes[typeKey];
                        return null;
                    }

                    function selectPSCalType(type) {
                        psCalSelType = type;
                        highlightActiveTypeChip();

                    }

                    function highlightActiveTypeChip() {
                        document.querySelectorAll('.ps-cal-type-chip').forEach(chip => {
                            const isActive = chip.dataset.type === psCalSelType;
                            chip.classList.toggle('active', isActive);
                        });
                    }

                    function clickPSCalDay(ds, curType) {
                        const isEd = allowedPSCalendarEditorRoles.includes(currentActiveSessionUser ? currentActiveSessionUser.position : '');
                        if (!isEd) { customAlert("Read only. Contact admin to edit."); return; }

                        const entry = psCalData[ds];
                        const dateDisplay = formatDateToDDMMYYYY(ds);

                        // Build type options for the select dropdown
                        let typeOptions = '';
                        const allTypes = [
                            { key: 'holiday', label: 'Holiday' },
                            { key: 'prof-dev', label: 'Prof. Dev' },
                            { key: 'special', label: 'Special' },
                            { key: 'working', label: 'Working Day' }
                        ];

                        // Add custom types
                        if (typeof psCalCustomTypes !== 'undefined') {
                            Object.keys(psCalCustomTypes).forEach(key => {
                                const t = psCalCustomTypes[key];
                                allTypes.push({ key: key, label: t.label });
                            });
                        }

                        allTypes.forEach(t => {
                            const selected = (entry && entry.t === t.key) || (!entry && t.key === 'working') ? 'selected' : '';
                            typeOptions += '<option value="' + t.key + '" ' + selected + '>' + t.label + '</option>';
                        });

                        const currentName = entry ? entry.n : '';

                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `
        <div class="system-inline-modal-overlay">
            <div class="system-inline-modal-box" style="width: 360px;">
                <h3 style="margin-bottom: 12px; font-size: 14px;">📅 Edit Calendar Day</h3>
                <div style="background: var(--primary-light); padding: 8px 12px; border-radius: 6px; margin-bottom: 12px; font-weight: 700; font-size: 12px; color: var(--primary);">
                    ${dateDisplay}
                </div>

                <div class="form-group" style="margin-bottom: 10px;">
                    <label style="font-size: 9px; font-weight: 700; text-transform: uppercase; color: var(--text-muted);">Event Name</label>
                    <input type="text" id="psCalEditName" value="${currentName}" placeholder="e.g. Eid Holiday" style="margin-top: 4px; padding: 6px 8px; font-size: 11px; width: 100%;">
                </div>

                <div class="form-group" style="margin-bottom: 10px;">
                    <label style="font-size: 9px; font-weight: 700; text-transform: uppercase; color: var(--text-muted);">Day Type</label>
                    <select id="psCalEditType" style="margin-top: 4px; padding: 6px 8px; font-size: 11px; width: 100%; border-radius: 6px; border: 1px solid var(--border); background: var(--bg-inner); color: var(--text-body);">
                        ${typeOptions}
                    </select>
                </div>

                <div style="display: flex; gap: 8px; margin-top: 16px;">
                    <button class="action-btn" style="background: var(--danger); flex: 1; justify-content: center;" onclick="deletePSCalDay('${ds}')">🗑️ Delete</button>
                    <button class="action-btn" style="background: var(--success); flex: 1; justify-content: center;" onclick="savePSCalDayEdit('${ds}')">💾 Save</button>
                    <button class="action-btn" style="background: var(--text-muted); flex: 1; justify-content: center;" onclick="closeSystemModalBox()">Cancel</button>
                </div>
            </div>
        </div>
    `;
                    }

                    function savePSCalDayEdit(ds) {
                        const name = document.getElementById('psCalEditName').value.trim();
                        const type = document.getElementById('psCalEditType').value;

                        if (!name && type !== 'working') {
                            customAlert("Please enter an event name.");
                            return;
                        }

                        if (type === 'working') {
                            delete psCalData[ds];
                        } else {
                            const typeConfig = getPSCalTypeConfig(type);
                            psCalData[ds] = { t: type, n: name || (typeConfig ? typeConfig.label : type) };
                        }

                        savePSCalDataToStorage();
                        closeSystemModalBox();
                        renderPSCal();
                        customAlert("Calendar day updated successfully.");
                    }

                    function deletePSCalDay(ds) {
                        customConfirm("Delete this calendar marking?", function () {
                            delete psCalData[ds];
                            savePSCalDataToStorage();
                            closeSystemModalBox();
                            renderPSCal();
                            customAlert("Calendar marking deleted.");
                        });
                    }


                    function addPSCalEvent() {
                        const isEd = allowedPSCalendarEditorRoles.includes(currentActiveSessionUser ? currentActiveSessionUser.position : '');
                        if (!isEd) { customAlert("Only editors can add events."); return; }

                        const name = document.getElementById('psCalEventName').value.trim();
                        const type = document.getElementById('psCalEventType').value;
                        const from = document.getElementById('psCalEventFrom').value;
                        const to = document.getElementById('psCalEventTo').value;

                        if (!name || !from || !to) { customAlert("Fill all fields."); return; }
                        if (new Date(from) > new Date(to)) { customAlert("From must be before To."); return; }

                        const fp = from.split('-');
                        const tp = to.split('-');
                        const cur = new Date(parseInt(fp[0]), parseInt(fp[1]) - 1, parseInt(fp[2]));
                        const end = new Date(parseInt(tp[0]), parseInt(tp[1]) - 1, parseInt(tp[2]));
                        let cnt = 0;

                        while (cur <= end) {
                            const ds = cur.getFullYear() + '-' + String(cur.getMonth() + 1).padStart(2, '0') + '-' + String(cur.getDate()).padStart(2, '0');
                            psCalData[ds] = { t: type, n: name };
                            cnt++;
                            cur.setDate(cur.getDate() + 1);
                        }

                        document.getElementById('psCalEventName').value = '';
                        document.getElementById('psCalEventFrom').value = '';
                        document.getElementById('psCalEventTo').value = '';
                        savePSCalDataToStorage();
                        customAlert("'" + name + "' added: " + cnt + " day(s).");
                        renderPSCal();
                    }

                    function renderPSCalUpcoming() {
                        const list = document.getElementById('psCalUpcoming');
                        if (!list) return;
                        list.innerHTML = '';

                        const today = new Date();
                        const later = new Date();
                        later.setDate(today.getDate() + 30);

                        // Collect all events with their dates
                        const allEvents = [];
                        Object.keys(psCalData).forEach(ds => {
                            const dp = ds.split('-');
                            const d = new Date(parseInt(dp[0]), parseInt(dp[1]) - 1, parseInt(dp[2]));
                            if (d >= today && d <= later) {
                                allEvents.push({ ds: ds, d: d, ...psCalData[ds] });
                            }
                        });

                        // Sort by date
                        allEvents.sort((a, b) => a.d - b.d);

                        // Merge consecutive dates with same name and type into ranges
                        const mergedEvents = [];
                        let currentGroup = null;

                        allEvents.forEach((item, idx) => {
                            if (!currentGroup) {
                                currentGroup = {
                                    name: item.n,
                                    type: item.t,
                                    startDs: item.ds,
                                    endDs: item.ds,
                                    startD: item.d,
                                    endD: item.d
                                };
                            } else if (item.n === currentGroup.name && item.t === currentGroup.type && isNextDay(currentGroup.endDs, item.ds)) {
                                // Extend current group
                                currentGroup.endDs = item.ds;
                                currentGroup.endD = item.d;
                            } else {
                                // Save current group and start new
                                mergedEvents.push(currentGroup);
                                currentGroup = {
                                    name: item.n,
                                    type: item.t,
                                    startDs: item.ds,
                                    endDs: item.ds,
                                    startD: item.d,
                                    endD: item.d
                                };
                            }
                        });

                        if (currentGroup) mergedEvents.push(currentGroup);

                        if (mergedEvents.length === 0) {
                            list.innerHTML = '<div style="color:var(--text-muted); font-size:12px; font-style:italic; padding:10px;">No upcoming events.</div>';
                            return;
                        }

                        mergedEvents.forEach(group => {
                            const typeConfig = getPSCalTypeConfig(group.type);
                            const col = typeConfig || { bg: '#e5e7eb', border: '#d1d5db', text: '#6b7280' };

                            const daysUntil = Math.ceil((group.startD - today) / 86400000);
                            const daysText = daysUntil === 0 ? 'Today' : daysUntil === 1 ? 'Tomorrow' : daysUntil + ' days';

                            // Format date range
                            let dateRangeText;
                            if (group.startDs === group.endDs) {
                                dateRangeText = formatDateToDDMMYYYY(group.startDs);
                            } else {
                                dateRangeText = formatDateToDDMMYYYY(group.startDs) + ' to ' + formatDateToDDMMYYYY(group.endDs);
                            }

                            const div = document.createElement('div');
                            div.className = 'ps-cal-up-item';
                            div.innerHTML = '<div class="ps-cal-up-dot" style="background:' + col.bg + '; border:1px solid ' + col.border + ';"></div><div class="ps-cal-up-info"><div class="ps-cal-up-name">' + group.name + '</div><div class="ps-cal-up-meta">' + dateRangeText + ' &bull; ' + daysText + '</div></div>';
                            list.appendChild(div);
                        });
                    }

                    function isNextDay(dateStr1, dateStr2) {
                        const d1 = new Date(dateStr1);
                        const d2 = new Date(dateStr2);
                        const diff = (d2 - d1) / 86400000;
                        return diff === 1;
                    }

                    function addPSCalType() {
                        const name = document.getElementById('psCalNewTypeName').value.trim();
                        const bg = document.getElementById('psCalNewTypeBg').value;
                        const text = document.getElementById('psCalNewTypeText').value;
                        if (!name) { customAlert("Enter type name."); return; }

                        const typeId = 'custom_' + Date.now();

                        // Store the type configuration
                        psCalCustomTypes[typeId] = {
                            label: name,
                            bg: bg,
                            border: text,
                            text: text
                        };

                        // Add chip to the chips area
                        const typeArea = document.getElementById('psCalTypeArea');
                        if (typeArea) {
                            const btn = document.createElement('button');
                            btn.className = 'ps-cal-type-chip';
                            btn.dataset.type = typeId;
                            btn.style.cssText = 'background: ' + bg + '; color: ' + text + '; border-color: ' + text + ';';
                            btn.innerHTML = '<span style="width: 8px; height: 8px; background: ' + bg + '; border: 1px solid ' + text + '; border-radius: 2px; display: inline-block; margin-right: 3px;"></span> ' + name;
                            btn.onclick = function () { selectPSCalType(typeId); };
                            typeArea.appendChild(btn);
                        }

                        // Also add to the admin event type selector
                        const adminTypeSel = document.getElementById('psCalEventType');
                        if (adminTypeSel) {
                            const opt = document.createElement('option');
                            opt.value = typeId;
                            opt.innerText = name;
                            adminTypeSel.appendChild(opt);
                        }

                        customAlert("Type '" + name + "' added! Click it to select.");
                        document.getElementById('psCalNewTypeName').value = '';

                        // Update legend and re-render stats
                        updatePSCalLegend();
                        renderPSCal();
                    }

                    function updatePSCalLegend() {
                        const legend = document.getElementById('psCalLegend');
                        if (!legend) return;

                        let html = '';

                        // Built-in types
                        const builtInTypes = [
                            { key: 'working', label: 'Working', bg: 'var(--bg-inner)', border: 'var(--border)' },
                            { key: 'holiday', label: 'Holiday', bg: '#fecaca', border: '#f87171' },
                            { key: 'prof-dev', label: 'Prof. Dev', bg: '#dbeafe', border: '#60a5fa' },
                            { key: 'special', label: 'Special', bg: '#fde68a', border: '#fbbf24' },
                            { key: 'friday', label: 'Friday', bg: '#e5e7eb', border: '#d1d5db' }
                        ];

                        builtInTypes.forEach(t => {
                            html += '<div class="ps-cal-leg-item"><div class="ps-cal-leg-dot" style="background: ' + t.bg + '; border-color: ' + t.border + ';"></div>' + t.label + '</div>';
                        });

                        // Custom types
                        Object.keys(psCalCustomTypes).forEach(key => {
                            const t = psCalCustomTypes[key];
                            html += '<div class="ps-cal-leg-item"><div class="ps-cal-leg-dot" style="background: ' + t.bg + '; border-color: ' + t.border + ';"></div>' + t.label + '</div>';
                        });

                        legend.innerHTML = html;
                    }

                    function isPSCalHoliday(ds) {
                        const entry = psCalData[ds];
                        return entry && (entry.t === 'holiday' || entry.t === 'special');
                    }

                    function isPSCalDayOff(ds) {
                        const entry = psCalData[ds];
                        const dp = ds.split('-');
                        const dow = new Date(parseInt(dp[0]), parseInt(dp[1]) - 1, parseInt(dp[2])).getDay();

                        // Friday is always off
                        if (dow === 5) return true;

                        // Check if it's a holiday or special day (configured as off)
                        if (entry && (entry.t === 'holiday' || entry.t === 'special')) return true;

                        return false;
                    }

                    function getPSCalDayType(ds) {
                        const dp = ds.split('-');
                        const dow = new Date(parseInt(dp[0]), parseInt(dp[1]) - 1, parseInt(dp[2])).getDay();
                        if (dow === 5) return 'friday';
                        const entry = psCalData[ds];
                        return entry ? entry.t : 'working';
                    }

                    function getPSCalDayName(ds) {
                        const entry = psCalData[ds];
                        return entry ? entry.n : '';
                    }

                    // ===== SYNC FUNCTIONS =====
                    function executePSCalSync() {
                        const syncRoster = document.getElementById('psCalSyncRoster')?.checked;
                        const syncMasterOT = document.getElementById('psCalSyncMasterOT')?.checked;
                        const syncLeave = document.getElementById('psCalSyncLeave')?.checked;

                        const year = document.getElementById('psCalYear').value;
                        let syncCount = 0;

                        // Get all holiday/special days for the selected year
                        const holidayDates = [];
                        Object.keys(psCalData).forEach(ds => {
                            if (ds.startsWith(year) && (psCalData[ds].t === 'holiday' || psCalData[ds].t === 'special')) {
                                holidayDates.push(ds);
                            }
                        });

                        // Store synced holidays globally for other modules to access
                        window.syncedCalendarHolidays = holidayDates.reduce((acc, ds) => {
                            acc[ds] = psCalData[ds];
                            return acc;
                        }, {});

                        if (syncRoster) {
                            // Mark holidays as HOLIDAY in ALL roster cycles for the year
                            Object.keys(rosterDraftData).forEach(cycle => {
                                if (cycle.startsWith(year)) {
                                    const roster = rosterDraftData[cycle];
                                    if (roster && roster.therapists) {
                                        roster.therapists.forEach(t => {
                                            holidayDates.forEach(ds => {
                                                const dateObj = new Date(ds);
                                                const dateStr = formatDateToRoster(dateObj);
                                                // Check if this date exists in the roster dates
                                                const dateExists = roster.dates.some(d => d.dateStr === dateStr);
                                                if (dateExists) {
                                                    if (!roster.assignments[t.email]) roster.assignments[t.email] = {};
                                                    roster.assignments[t.email][dateStr] = 'HOLIDAY';
                                                    syncCount++;
                                                }
                                            });
                                        });
                                    }
                                }
                            });

                            // Also sync to published rosters
                            Object.keys(rosterPublishedData).forEach(cycle => {
                                if (cycle.startsWith(year)) {
                                    const roster = rosterPublishedData[cycle];
                                    if (roster && roster.therapists) {
                                        roster.therapists.forEach(t => {
                                            holidayDates.forEach(ds => {
                                                const dateObj = new Date(ds);
                                                const dateStr = formatDateToRoster(dateObj);
                                                const dateExists = roster.dates.some(d => d.dateStr === dateStr);
                                                if (dateExists) {
                                                    if (!roster.assignments[t.email]) roster.assignments[t.email] = {};
                                                    roster.assignments[t.email][dateStr] = 'HOLIDAY';
                                                    syncCount++;
                                                }
                                            });
                                        });
                                    }
                                }
                            });
                        }

                        if (syncMasterOT) {
                            // Sync holidays to ALL OT months in the year
                            const months = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12'];
                            months.forEach(month => {
                                const cycleKey = year + '-' + month;
                                globalRosterRepository.forEach(staff => {
                                    // Initialize database structure
                                    if (!globalTherapistOTSubmissions[staff.email]) globalTherapistOTSubmissions[staff.email] = {};
                                    if (!globalTherapistOTSubmissions[staff.email][year]) globalTherapistOTSubmissions[staff.email][year] = {};
                                    if (!globalTherapistOTSubmissions[staff.email][year][month]) globalTherapistOTSubmissions[staff.email][year][month] = {};

                                    if (!globalAdminComparativeDatabase[staff.email]) globalAdminComparativeDatabase[staff.email] = {};
                                    if (!globalAdminComparativeDatabase[staff.email][year]) globalAdminComparativeDatabase[staff.email][year] = {};
                                    if (!globalAdminComparativeDatabase[staff.email][year][month]) globalAdminComparativeDatabase[staff.email][year][month] = {};

                                    holidayDates.forEach(ds => {
                                        if (ds.startsWith(year + '-' + month)) {
                                            const holidayEntry = {
                                                patients150: 0,
                                                patients200: 0,
                                                hours: 0,
                                                attendance: 'Holiday',
                                                notes: psCalData[ds].n || 'Public Holiday'
                                            };
                                            globalTherapistOTSubmissions[staff.email][year][month][ds] = holidayEntry;
                                            globalAdminComparativeDatabase[staff.email][year][month][ds] = holidayEntry;
                                            syncCount++;
                                        }
                                    });
                                });
                            });
                        }

                        if (syncLeave) {
                            // Set global flag that holidays should be excluded from leave
                            window.psCalLeaveSyncEnabled = true;
                            customAlert("Leave sync active: Holidays excluded from leave duration calculations.");
                        }

                        // Save to localStorage for persistence
                        try {
                            localStorage.setItem('psCalSyncedHolidays', JSON.stringify(window.syncedCalendarHolidays || {}));
                            localStorage.setItem('psCalLeaveSyncEnabled', window.psCalLeaveSyncEnabled ? 'true' : 'false');
                        } catch (e) { }

                        customAlert("Calendar sync completed! " + syncCount + " entries updated across modules.");

                        // Re-render affected modules if visible
                        if (syncRoster && document.getElementById('mod_roster_engine') && !document.getElementById('mod_roster_engine').classList.contains('hidden')) {
                            // Full Time
                            const ftCycle = document.getElementById('rosterCycleMonth')?.value;
                            if (ftCycle && rosterState.ft.draftData[ftCycle]) {
                                currentRosterTab = 'fulltime';
                                renderRosterGrid(rosterState.ft.draftData[ftCycle], false);
                            }
                            // Part Time
                            const ptCycle = document.getElementById('ptRosterCycleMonth')?.value;
                            if (ptCycle && ptState.draftData[ptCycle]) {
                                ptRenderGrid(ptState.draftData[ptCycle]);
                            }
                            currentRosterTab = 'fulltime';
                        }

                        // Refresh dashboard if visible
                        if (document.getElementById('mod_my_dashboard') && !document.getElementById('mod_my_dashboard').classList.contains('hidden')) {
                            renderMyDashboard();
                        }
                    }

                    // ===== END PS CALENDAR =====


                    // ===== END PS CALENDAR =====

                    // ==========================================
                    // DYNAMIC DISCHARGE AND SECURITY MATCHERS
                    // ==========================================

                    // Generates dropdown options dynamically based on the years and months of actual database records
                    function populateRoleConfiguratorSelectors() {
                        const templateSel = document.getElementById('newRoleTemplateSelector');
                        const renameSel = document.getElementById('renameRoleTargetSelector');
                        const deleteSel = document.getElementById('deleteRoleTargetSelector');
                        if (!templateSel || !renameSel) return;

                        const roles = Object.keys(globalRolePermissionsMatrix);
                        templateSel.innerHTML = "";
                        renameSel.innerHTML = "";
                        if (deleteSel) deleteSel.innerHTML = "";

                        roles.forEach(role => {
                            templateSel.innerHTML += `<option value="${role}">${role}</option>`;
                            renameSel.innerHTML += `<option value="${role}">${role}</option>`;
                            if (deleteSel) deleteSel.innerHTML += `<option value="${role}">${role}</option>`;
                        });
                    }

                    function renderPortalWorkspaceSwitcher() {
                        const select = document.getElementById('switcherSelectField');
                        if (!select) return;
                        const currentSelectedEmail = currentActiveSessionUser ? currentActiveSessionUser.email : "";

                        select.innerHTML = "";
                        globalRosterRepository.forEach(u => {
                            const opt = document.createElement('option');
                            opt.value = u.email;
                            opt.innerText = `${u.name} (${lookupTranslationValue(u.position)})`;
                            if (u.email === currentSelectedEmail) {
                                opt.selected = true;
                            }
                            select.appendChild(opt);
                        });
                    }

                    function createNewSystemRole() {
                        const roleName = document.getElementById('newRoleInputName').value.trim();
                        const templateRole = document.getElementById('newRoleTemplateSelector').value;

                        if (!roleName) {
                            customAlert("Please enter a valid role name.");
                            return;
                        }
                        if (globalRolePermissionsMatrix[roleName]) {
                            customAlert("A role with this name already exists.");
                            return;
                        }

                        const permissions = globalRolePermissionsMatrix[templateRole]
                            ? [...globalRolePermissionsMatrix[templateRole]]
                            : ["my_dashboard", "my_profile"];

                        globalRolePermissionsMatrix[roleName] = permissions;
                        systemTextDictionary[roleName] = roleName;

                        document.getElementById('newRoleInputName').value = "";

                        synchronizeWorkspaceCoreStatus();
                        rebuildDynamicPortalMenus();
                    }

                    function renameSystemRole() {
                        const oldName = document.getElementById('renameRoleTargetSelector').value;
                        const newName = document.getElementById('renameRoleNewNameInput').value.trim();

                        if (!newName) {
                            customAlert("Please enter a valid new role name.");
                            return;
                        }
                        if (oldName === newName) {
                            customAlert("New name must be different from current name.");
                            return;
                        }
                        if (globalRolePermissionsMatrix[newName]) {
                            customAlert("A role with this name already exists.");
                            return;
                        }

                        // 1. Move permissions to new key name
                        globalRolePermissionsMatrix[newName] = [...globalRolePermissionsMatrix[oldName]];
                        delete globalRolePermissionsMatrix[oldName];

                        // 2. Safely migrate associated roster positions
                        globalRosterRepository.forEach(staff => {
                            if (staff.position === oldName) {
                                staff.position = newName;
                            }
                        });

                        // 3. Update active session properties if affected
                        if (currentActiveSessionUser && currentActiveSessionUser.position === oldName) {
                            currentActiveSessionUser.position = newName;
                            document.getElementById('userMatrixRole').innerText = lookupTranslationValue(newName);
                            document.getElementById('activeRoleIndicator').innerText = lookupTranslationValue(newName);
                        }

                        // 4. Update all core authorization arrays
                        const allRoleArrays = [
                            allowedBroadcasterRoles, allowedPSCalendarEditorRoles,
                            allowedProfileApproverRoles, allowedInventoryManagerRoles,
                            allowedAlertPanelRoles, allowedRosterPublisherRoles,
                            allowedStaffEditorRoles, allowedDischargeApproverRoles,
                            allowedSystemConfiguratorRoles,
                            allowedVolumeEntryRoles,
                            allowedDischargeEditAfterLockRoles,
                            allowedStaffExpiryViewerRoles
                        ];
                        allRoleArrays.forEach(arr => {
                            const idx = arr.indexOf(oldName);
                            if (idx !== -1) arr[idx] = newName;
                        });

                        // 5. Update Translation Dictionary keys
                        systemTextDictionary[newName] = newName;
                        delete systemTextDictionary[oldName];

                        customAlert(`Role "${oldName}" successfully renamed to "${newName}". All associated users and settings updated.`);
                        document.getElementById('renameRoleNewNameInput').value = "";

                        synchronizeWorkspaceCoreStatus();
                        rebuildDynamicPortalMenus();
                    }

                    function deleteSystemRole() {
                        const roleName = document.getElementById('deleteRoleTargetSelector').value;
                        if (!roleName) { customAlert("Please select a role to delete."); return; }

                        customConfirm(`Permanently delete the role "${roleName}"? It will be removed from all permission matrices, authorization grants, and staff with this role will be re-assigned to "Unassigned".`, function () {
                            // 1. Remove from page permissions matrix
                            delete globalRolePermissionsMatrix[roleName];

                            // 2. Remove from all authorization arrays
                            Object.keys(globalPermissionRegistry).forEach(key => {
                                globalPermissionRegistry[key] = globalPermissionRegistry[key].filter(r => r !== roleName);
                            });

                            // 3. Remove from translation dictionary
                            delete systemTextDictionary[roleName];

                            // 4. Clear position for staff members with this role
                            globalRosterRepository.forEach(staff => {
                                if (staff.position === roleName) {
                                    staff.position = "Unassigned";
                                }
                            });

                            // 5. If active user had this role, fall back to "Unassigned"
                            if (currentActiveSessionUser && currentActiveSessionUser.position === roleName) {
                                currentActiveSessionUser.position = "Unassigned";
                                const posEl = document.getElementById('userMatrixRole');
                                const indEl = document.getElementById('activeRoleIndicator');
                                if (posEl) posEl.innerText = "Unassigned";
                                if (indEl) indEl.innerText = "Unassigned";
                            }

                            customAlert(`Role "${roleName}" has been permanently deleted.`);
                            synchronizeWorkspaceCoreStatus();
                            rebuildDynamicPortalMenus();
                        });
                    }

                    // Resolves character casing mismatches dynamically to prevent empty sidebars
                    function getAllowedModulesForRole(roleName) {
                        if (!roleName) return ["my_dashboard", "my_profile"];
                        if (globalRolePermissionsMatrix[roleName]) {
                            return globalRolePermissionsMatrix[roleName];
                        }
                        const lowercaseRole = roleName.toLowerCase().trim();
                        for (let key in globalRolePermissionsMatrix) {
                            if (key.toLowerCase().trim() === lowercaseRole) {
                                return globalRolePermissionsMatrix[key];
                            }
                        }
                        return ["my_dashboard", "my_profile"];
                    }
                    // Opens edit dialog only if the record is under 24 hours old
