                    const rosterState = {
                        ft: { draftData: {}, publishedData: {}, currentCycle: _curCycleStr, currentDraftVersion: null, myRosterViewCycle: _curCycleStr },
                        pt: { draftData: {}, publishedData: {}, currentCycle: _curCycleStr, currentDraftVersion: null, myRosterViewCycle: _curCycleStr }
                    };
                    let rosterDraftData = rosterState.ft.draftData; // backward compat
                    let rosterPublishedData = rosterState.ft.publishedData;
