                    function rs() { const m = currentRosterTab === 'parttime' ? 'pt' : 'ft'; rosterDraftData = rosterState[m].draftData; rosterPublishedData = rosterState[m].publishedData; rosterCurrentCycle = rosterState[m].currentCycle; rosterCurrentDraftVersion = rosterState[m].currentDraftVersion; myRosterViewCycle = rosterState[m].myRosterViewCycle; return rosterState[m]; }
