                    function getRosterOffDays() {
                        const container = rId('rosterOffDaysContainer');
                        if (!container) return [5];
                        const checked = container.querySelectorAll('input[type=checkbox]:checked');
                        const days = [];
                        checked.forEach(cb => days.push(parseInt(cb.value)));
                        return days.length > 0 ? days : [5];
                    }

                    function onRosterOffDaysChange() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (!R.draftData[cycleMonth]) return;
                        const offDays = getRosterOffDays();
                        const data = R.draftData[cycleMonth];
                        // Ensure Date objects (survive localStorage round-trip check)
                        if (data.dates && data.dates.length && typeof data.dates[0].date === 'string') {
                            data.dates.forEach(d => { d.date = new Date(d.date); });
                        }
                        const oldOffDays = data._cachedOffDays || [];
                        data._cachedOffDays = offDays;

                        data.dates.forEach(dateInfo => {
                            const dayOfWeek = dateInfo.date.getDay();
                            const dateStr = dateInfo.dateStr;
                            const isNowOff = offDays.includes(dayOfWeek);
                            const wasOff = oldOffDays.includes(dayOfWeek);

                            data.therapists.forEach((t, tIdx) => {
                                const curr = data.assignments[t.email][dateStr];
                                if (isNowOff && !wasOff) {
                                    // Newly off — set to OFF if it was a regular shift
                                    if (curr && curr !== 'OFF' && curr !== 'LEAVE' && curr !== 'HOLIDAY') {
                                        data.assignments[t.email][dateStr] = 'OFF';
                                    }
                                } else if (!isNowOff && wasOff) {
                                    // No longer off — restore from OFF to default morning shift
                                    if (curr === 'OFF') {
                                        const floor = (tIdx % 2 === 0) ? '1ST' : '2ND';
                                        data.assignments[t.email][dateStr] = floor + '_MR';
                                    }
                                }
                            });
                        });
                        renderRosterGrid(data, false);
                        // Mark as modified (not saved)
                        const badge = rId('rosterDraftStatusBadge');
                        if (badge) {
                            const ver = badge.innerText;
                            if (ver && ver !== 'EMPTY' && ver !== 'PUBLISHED') {
                                badge.innerText = ver + ' (modified)';
                            }
                        }
                    }

                    function getTherapistStaff() {
                        return getSelectedRosterStaff();
                    }

                    function getRosterEffectiveRange(cycleMonth) {
                        const from = rId('rosterDateFrom').value;
                        const to = rId('rosterDateTo').value;
                        const [cy, cm] = cycleMonth.split('-').map(Number);
                        const start = from ? new Date(from + 'T12:00:00') : new Date(cy, cm - 1, 1);
                        const end = to ? new Date(to + 'T12:00:00') : new Date(cy, cm, 0);
                        return { start, end };
                    }

                    function onRosterRangeChange() {
                        const range = getRosterEffectiveRange(rId('rosterCycleMonth').value);
                        const fromEl = rId('rosterDateFrom');
                        const toEl = rId('rosterDateTo');
                        if (fromEl.value && toEl.value && fromEl.value > toEl.value) {
                            customAlert('Start date cannot be after end date.');
                        }
                    }

                    function generateRosterDates(cycleMonth, rangeOverride) {
                        const range = rangeOverride || getRosterEffectiveRange(cycleMonth);
                        let { start, end } = range;
                        const dates = [];

                        // Pad start to align with Sunday (for calendar display)
                        const startDayOfWeek = start.getDay();
                        for (let i = startDayOfWeek; i > 0; i--) {
                            const d = new Date(start);
                            d.setDate(d.getDate() - i);
                            dates.push({ date: d, dateStr: formatDateToRoster(d), dayName: d.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase(), inMonth: d >= range.start && d <= range.end });
                        }

                        // All days in range
                        let d = new Date(start);
                        while (d <= end) {
                            dates.push({ date: new Date(d), dateStr: formatDateToRoster(d), dayName: d.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase(), inMonth: true });
                            d.setDate(d.getDate() + 1);
                        }

                        // Pad end to align with Saturday (for calendar display)
                        const endDayOfWeek = end.getDay();
                        for (let i = 1; i < 7 - endDayOfWeek; i++) {
                            const pad = new Date(end);
                            pad.setDate(pad.getDate() + i);
                            dates.push({ date: pad, dateStr: formatDateToRoster(pad), dayName: pad.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase(), inMonth: false });
                        }

                        return dates;
                    }

                    function formatDateToRoster(date) {
                        const d = String(date.getDate()).padStart(2, '0');
                        const m = date.toLocaleDateString('en-US', { month: 'short' });
                        const y = String(date.getFullYear()).slice(-2);
                        return `${d}-${m}-${y}`;
                    }

                    function formatDateToISO(date) {
                        return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                    }

                    function getTherapistLeavesForCycle(email, cycleMonth) {
                        return globalLeaveRepository.filter(l =>
                            l.email === email &&
                            l.status === "Approved" &&
                            l.date && l.date.startsWith(cycleMonth)
                        );
                    }

                    function isLeaveDay(email, dateStr, cycleMonth) {
                        const leaves = getTherapistLeavesForCycle(email, cycleMonth);
                        const checkDate = new Date(dateStr.split('-').reverse().join('-'));

                        for (let leave of leaves) {
                            const leaveStart = new Date(leave.date);
                            const leaveEnd = new Date(leaveStart);
                            leaveEnd.setDate(leaveStart.getDate() + (parseInt(leave.duration) || 1) - 1);

                            if (checkDate >= leaveStart && checkDate <= leaveEnd) {
                                return true;
                            }
                        }
                        return false;
                    }
                    function parseDDMMYYYY(str) {
                        if (!str) return "";
                        const m = str.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
                        return m ? `${m[3]}-${m[2]}-${m[1]}` : "";
                    }

                    function generateAI_Roster() {
                        const R = rs();
                        const cycleMonth = rId('rosterCycleMonth').value;
                        if (!cycleMonth) {
                            customAlert("Please select a roster cycle month first.");
                            return;
                        }

                        const therapists = getTherapistStaff();
                        if (therapists.length === 0) {
                            customAlert("No active therapists found in the roster.");
                            return;
                        }

                        const dates = generateRosterDates(cycleMonth);
                        const afternoonTarget = parseInt(rId('rosterAfternoonDaysTarget').value) || 8;
                        const grouping = rId('rosterAfternoonGrouping').value;
                        const thursdayStart = rId('rosterThursdayStartPattern').value;
                        const floorStrategy = rId('rosterFloorStrategy').value;

                        const rosterData = {
                            cycle: cycleMonth,
                            dates: dates,
                            therapists: therapists.map(t => ({
                                email: t.email,
                                name: t.name,
                                initials: t.avatar || t.name.split(" ").map(n => n[0]).join("").toUpperCase().substring(0, 2),
                                color: t.accentColor || "#004b87"
                            })),
                            assignments: {}
                        };

                        // Assign each therapist to a Thursday group (A or B) — half on one Thursday, half on the other
                        therapists.forEach((t, i) => t._thuGroup = i % 2);

                        therapists.forEach((therapist, tIdx) => {
                            const email = therapist.email;
                            rosterData.assignments[email] = {};

                            let afternoonCount = 0;
                            let floorAssignment = (tIdx % 2 === 0) ? 1 : 2;
                            let lastThursdayFloor = (thursdayStart === 'odd') ? ((tIdx % 2 === 0) ? 1 : 2) : ((tIdx % 2 === 0) ? 2 : 1);

                            // Count Thursday dates in the month (global index)
                            let thuGlobalIdx = 0;

                            dates.forEach((dateInfo, dIdx) => {
                                const dateStr = dateInfo.dateStr;
                                const isoDate = formatDateToISO(dateInfo.date);
                                const dayOfWeek = dateInfo.date.getDay();
                                const offDays = getRosterOffDays();
                                const isOffDay = offDays.includes(dayOfWeek);
                                const isThursday = dayOfWeek === 4;

                                if (isLeaveDay(email, isoDate, cycleMonth)) {
                                    rosterData.assignments[email][dateStr] = "LEAVE";
                                    return;
                                }

                                if (isOffDay) {
                                    rosterData.assignments[email][dateStr] = "OFF";
                                    return;
                                }

                                // Check if it's a holiday from PS Calendar
                                if (psCalData[isoDate] && (psCalData[isoDate].t === 'holiday' || psCalData[isoDate].t === 'special')) {
                                    rosterData.assignments[email][dateStr] = "HOLIDAY";
                                    return;
                                }

                                if (isThursday) {
                                    thuGlobalIdx++;
                                    const isFirstGroup = thuGlobalIdx % 2 === 1;
                                    const therapistGoes = isFirstGroup ? (therapist._thuGroup === 0) : (therapist._thuGroup === 1);
                                    if (therapistGoes) {
                                        rosterData.assignments[email][dateStr] = lastThursdayFloor === 1 ? "THU_1ST" : "THU_2ND";
                                    } else {
                                        rosterData.assignments[email][dateStr] = "OFF";
                                    }
                                    return;
                                }

                                let shiftType;

                                if (afternoonCount < afternoonTarget) {
                                    if (grouping === 'consecutive' && afternoonCount > 0) {
                                        const prevDate = dates[dIdx - 1];
                                        if (prevDate && rosterData.assignments[email][prevDate.dateStr] &&
                                            rosterData.assignments[email][prevDate.dateStr].includes('AF')) {
                                            shiftType = 'afternoon';
                                        } else if (afternoonCount === 0 || Math.random() > 0.3) {
                                            shiftType = 'afternoon';
                                        } else {
                                            shiftType = 'morning';
                                        }
                                    } else if (grouping === 'split') {
                                        shiftType = Math.random() < (afternoonTarget / dates.filter(d => d.inMonth && d.date.getDay() !== 5 && d.date.getDay() !== 4).length) ? 'afternoon' : 'morning';
                                    } else {
                                        const remainingDays = dates.filter((d, i) => i >= dIdx && d.inMonth && d.date.getDay() !== 5 && d.date.getDay() !== 4).length;
                                        const remainingAfternoons = afternoonTarget - afternoonCount;
                                        shiftType = (remainingAfternoons > 0 && Math.random() < (remainingAfternoons / remainingDays)) ? 'afternoon' : 'morning';
                                    }
                                } else {
                                    shiftType = 'morning';
                                }

                                if (floorStrategy === 'sticky') {
                                    // Keep same floor
                                } else if (floorStrategy === 'rotate_weekly') {
                                    if (dIdx > 0 && dIdx % 7 === 0) floorAssignment = floorAssignment === 1 ? 2 : 1;
                                } else if (floorStrategy === 'rotate_biweekly') {
                                    if (dIdx > 0 && dIdx % 14 === 0) floorAssignment = floorAssignment === 1 ? 2 : 1;
                                } else if (floorStrategy === 'mixed') {
                                    if (dIdx > 0 && dIdx % 5 === 0) floorAssignment = floorAssignment === 1 ? 2 : 1;
                                }

                                if (shiftType === 'afternoon') {
                                    rosterData.assignments[email][dateStr] = floorAssignment === 1 ? "1ST_AF" : "2ND_AF";
                                    afternoonCount++;
                                } else {
                                    rosterData.assignments[email][dateStr] = floorAssignment === 1 ? "1ST_MR" : "2ND_MR";
                                }
                            });
                        });

                        // Post-generation: Ensure afternoon coverage minimum (from editable constraints)
                        const minAfternoon = parseInt(rId('rosterMinAfternoon').value) || 3;
                        const minFloor1 = parseInt(rId('rosterMinFloor1').value) || 1;
                        const minFloor2 = parseInt(rId('rosterMinFloor2').value) || 1;
                        const offDays = getRosterOffDays();
                        dates.forEach(dateInfo => {
                            if (!dateInfo.inMonth || offDays.includes(dateInfo.date.getDay()) || dateInfo.date.getDay() === 4) return;

                            const dateStr = dateInfo.dateStr;
                            let afternoonCount = 0;
                            let floor1Afternoon = 0;
                            let floor2Afternoon = 0;

                            therapists.forEach(t => {
                                const assignment = rosterData.assignments[t.email][dateStr];
                                if (assignment && assignment.includes('AF')) {
                                    afternoonCount++;
                                    if (assignment === '1ST_AF') floor1Afternoon++;
                                    if (assignment === '2ND_AF') floor2Afternoon++;
                                }
                            });

                            let attempts = 0;
                            while ((afternoonCount < minAfternoon || floor1Afternoon < minFloor1 || floor2Afternoon < minFloor2) && attempts < therapists.length * 2) {
                                const candidates = therapists.filter(t => {
                                    const a = rosterData.assignments[t.email][dateStr];
                                    return a === '1ST_MR' || a === '2ND_MR';
                                });

                                if (candidates.length === 0) break;

                                const candidate = candidates.find(t => {
                                    const a = rosterData.assignments[t.email][dateStr];
                                    if (floor1Afternoon < minFloor1 && a === '1ST_MR') return true;
                                    if (floor2Afternoon < minFloor2 && a === '2ND_MR') return true;
                                    if (afternoonCount < minAfternoon) return true;
                                    return false;
                                }) || candidates[0];

                                const currentAssignment = rosterData.assignments[candidate.email][dateStr];
                                rosterData.assignments[candidate.email][dateStr] = currentAssignment === '1ST_MR' ? '1ST_AF' : '2ND_AF';
                                afternoonCount++;
                                if (currentAssignment === '1ST_MR') floor1Afternoon++;
                                else floor2Afternoon++;
                                attempts++;
                            }
                        });

                        R.draftData[cycleMonth] = rosterData;
                        R.currentCycle = cycleMonth;

                        // Auto-save as new version
                        let versions = getRosterVersions(cycleMonth);
                        const maxNum = versions.reduce((max, v) => {
                            const num = parseInt(v.replace('R', ''), 10);
                            return isNaN(num) ? max : Math.max(max, num);
                        }, 0);
                        const version = 'R' + (maxNum + 1);
                        try {
                            localStorage.setItem(rKey('rosterDraft') + '_' + cycleMonth + '_' + version, JSON.stringify(rosterData));
                        } catch (e) {
                            console.warn('Failed to save roster draft to localStorage');
                        }
                        versions.push(version);
                        saveRosterVersionList(cycleMonth, versions);
                        R.currentDraftVersion = version;

                        renderRosterGrid(rosterData, false);
                        populateRosterVersionSelect(cycleMonth);

                        rId('rosterDraftStatusBadge').innerText = version;
                        rId('rosterDraftStatusBadge').className = "badge badge-warning";

                        customAlert(`AI Roster generated for ${cycleMonth} — saved as ${version}. ${therapists.length} therapists. Afternoon target: ${afternoonTarget} days each.`);
                    }

                    function renderRosterGrid(rosterData, isPublished) {
                        const header = rId('rosterGridHeader');
                        const body = rId('rosterGridBody');
                        if (!header || !body) return;

                        header.innerHTML = "";
                        body.innerHTML = "";

                        let headerHtml = `<tr style="background: var(--primary-light);">
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 0; z-index: 10; background: var(--primary-light); min-width: 70px;">DATE</th>
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 70px; z-index: 10; background: var(--primary-light); min-width: 45px;">DAYS</th>`;

                        rosterData.therapists.forEach(t => {
                            headerHtml += `<th style="padding: 8px 6px; text-align: center; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; min-width: 65px; background: ${t.color}22;">${t.name.split(' ')[0]}<br><span style="font-size: 8px; opacity: 0.7;">${t.name.split(' ').slice(1).join(' ')}</span></th>`;
                        });
                        headerHtml += `</tr>`;
                        header.innerHTML = headerHtml;

                        rosterData.dates.forEach(dateInfo => {
                            const dateStr = dateInfo.dateStr;
                            const dayOfWeek = dateInfo.date.getDay();
                            const offDaysRender = getRosterOffDays();
                            const isOffDayRender = offDaysRender.includes(dayOfWeek);
                            const isThursday = dayOfWeek === 4;
                            const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

                            let rowHtml = `<tr style="${!dateInfo.inMonth ? 'opacity: 0.5;' : ''} ${isOffDayRender ? 'background: #f3f4f6;' : ''} ${isWeekend ? 'background: #fafafa;' : ''}">`;

                            rowHtml += `<td style="padding: 6px; border: 1px solid var(--border); font-weight: 700; font-size: 9px; position: sticky; left: 0; background: ${!dateInfo.inMonth ? '#f9fafb' : (isOffDayRender ? '#f3f4f6' : 'var(--bg-card)')}; z-index: 5; white-space: nowrap;">${dateStr}</td>`;

                            rowHtml += `<td style="padding: 6px; border: 1px solid var(--border); font-weight: 600; font-size: 9px; position: sticky; left: 70px; background: ${!dateInfo.inMonth ? '#f9fafb' : (isOffDayRender ? '#f3f4f6' : 'var(--bg-card)')}; z-index: 5;">${dateInfo.dayName}</td>`;

                            rosterData.therapists.forEach(t => {
                                const assignment = rosterData.assignments[t.email][dateStr] || "OFF";
                                const shiftDef = ROSTER_SHIFT_TYPES[assignment] || ROSTER_SHIFT_TYPES["OFF"];

                                const clickHandler = `onclick="cycleRosterCell('${t.email}', '${dateStr}')"`;
                                const cursorStyle = 'cursor: pointer;';

                                // Get holiday name if it's a HOLIDAY assignment
                                let cellLabel = shiftDef.code;
                                let cellTitle = shiftDef.label + (shiftDef.time !== '-' ? ' (' + shiftDef.time + ')' : '');

                                if (assignment === 'HOLIDAY') {
                                    // Look up the actual holiday name from psCalData using LOCAL date (not UTC)
                                    const localIsoDate = dateInfo.date.getFullYear() + '-' + String(dateInfo.date.getMonth() + 1).padStart(2, '0') + '-' + String(dateInfo.date.getDate()).padStart(2, '0');
                                    if (psCalData[localIsoDate] && psCalData[localIsoDate].n) {
                                        cellLabel = psCalData[localIsoDate].n;
                                        if (cellLabel.length > 8) cellLabel = cellLabel.substring(0, 7) + '..';
                                        cellTitle = psCalData[localIsoDate].n + ' (Public Holiday)';
                                    }
                                }

                                rowHtml += `<td ${clickHandler} style="padding: 4px 2px; border: 1px solid var(--border); text-align: center; font-size: 9px; font-weight: 700; ${cursorStyle} background: ${shiftDef.color}; color: ${shiftDef.textColor}; transition: all 0.15s ease;" title="${cellTitle}">${cellLabel}</td>`;
                            });

                            rowHtml += `</tr>`;
                            body.innerHTML += rowHtml;
                        });

                        renderCoverageSummary(rosterData);
                    }

                    function cycleRosterCell(therapistEmail, dateStr) {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        const rosterData = R.draftData[cycleMonth];
                        if (!rosterData) return;

                        const currentAssignment = rosterData.assignments[therapistEmail][dateStr] || "OFF";

                        // Build option buttons for each shift type, grouped
                        function ftBtn(key) {
                            const s = ROSTER_SHIFT_TYPES[key];
                            const sel = key === currentAssignment ? 'outline:2px solid #000;outline-offset:1px;' : 'outline:none;';
                            return `<button class="action-btn ft-pick-opt" data-ftopt="${key}" onclick="ftSelectPickerOpt('${key}')" style="flex:1;min-width:80px;padding:5px 4px;font-size:8px;font-weight:700;background:${s.color};border:1px solid ${s.borderColor};border-radius:3px;color:${s.textColor};cursor:pointer;${sel}text-align:center;margin-bottom:2px;">${s.code}<br><span style="font-size:7px;font-weight:400;">${s.time}</span></button>`;
                        }

                        const tName = rosterData.therapists.find(t => t.email === therapistEmail)?.name || therapistEmail.split('@')[0];
                        ftPickerSelectedOpt = null;
                        ptState._ftPickerCtx = { therapistEmail, dateStr, rosterData };

                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `<div class="system-inline-modal-overlay">
        <div class="system-inline-modal-box" style="width:320px;">
            <div style="padding:10px;">
                <div style="font-size:9px;color:var(--text-muted);margin-bottom:6px;">${dateStr} — ${tName}</div>
                <div style="font-size:8px;font-weight:600;color:var(--text-muted);margin-bottom:2px;">Select shift:</div>
                <div style="display:flex;flex-wrap:wrap;gap:3px;margin-bottom:4px;">
                    ${ftBtn('1ST_MR')}${ftBtn('1ST_AF')}${ftBtn('2ND_MR')}${ftBtn('2ND_AF')}
                </div>
                <div style="display:flex;flex-wrap:wrap;gap:3px;margin-bottom:4px;">
                    ${ftBtn('THU_1ST')}${ftBtn('THU_2ND')}
                </div>
                <div style="display:flex;flex-wrap:wrap;gap:3px;">
                    ${ftBtn('OFF')}${ftBtn('LEAVE')}${ftBtn('HOLIDAY')}
                </div>
                <div style="display:flex;gap:6px;justify-content:flex-end;margin-top:6px;">
                    <button class="action-btn" onclick="closeSystemModalBox()" style="padding:5px 12px;font-size:10px;background:var(--text-muted);">Cancel</button>
                    <button class="action-btn" onclick="ftApplyCellChanges()" style="padding:5px 12px;font-size:10px;background:var(--primary);">Apply</button>
                </div>
            </div>
        </div>
    </div>`;
                    }

                    let ftPickerSelectedOpt = null;

                    function ftSelectPickerOpt(key) {
                        ftPickerSelectedOpt = key;
                        document.querySelectorAll('.ft-pick-opt').forEach(b => {
                            b.style.outline = b.dataset.ftopt === key ? '2px solid #000' : 'none';
                            b.style.outlineOffset = b.dataset.ftopt === key ? '1px' : '0';
                        });
                    }

                    function ftApplyCellChanges() {
                        const ctx = ptState._ftPickerCtx;
                        const opt = ftPickerSelectedOpt;
                        ftPickerSelectedOpt = null;
                        closeSystemModalBox();
                        if (!ctx || !opt) return;
                        const { therapistEmail, dateStr, rosterData } = ctx;
                        rosterData.assignments[therapistEmail][dateStr] = opt;
                        renderRosterGrid(rosterData, false);
                        showRosterToast(`Updated: ${rosterData.therapists.find(t => t.email === therapistEmail)?.name || therapistEmail} → ${ROSTER_SHIFT_TYPES[opt].code}`);
                    }

                    function showRosterToast(message) {
                        const toast = document.createElement('div');
                        toast.className = 'toast-notification';
                        toast.style.cssText = 'position: fixed; bottom: 20px; right: 20px; background: var(--primary); color: white; padding: 10px 16px; border-radius: 8px; font-size: 11px; font-weight: 600; z-index: 100000; box-shadow: var(--glass-shadow); animation: slideInRight 0.3s ease;';
                        toast.innerText = message;
                        document.body.appendChild(toast);
                        setTimeout(() => toast.remove(), 2000);
                    }

                    function renderCoverageSummary(rosterData) {
                        const container = rId('rosterCoverageBars');
                        if (!container) return;
                        container.innerHTML = "";

                        const coverageStats = {};
                        rosterData.dates.filter(d => d.inMonth).forEach(dateInfo => {
                            const dateStr = dateInfo.dateStr;
                            let morningCount = 0, afternoonCount = 0, offCount = 0, leaveCount = 0;
                            let floor1Morning = 0, floor2Morning = 0, floor1Afternoon = 0, floor2Afternoon = 0;

                            rosterData.therapists.forEach(t => {
                                const assignment = rosterData.assignments[t.email][dateStr] || "OFF";
                                if (assignment === '1ST_MR') { morningCount++; floor1Morning++; }
                                else if (assignment === '2ND_MR') { morningCount++; floor2Morning++; }
                                else if (assignment === '1ST_AF') { afternoonCount++; floor1Afternoon++; }
                                else if (assignment === '2ND_AF') { afternoonCount++; floor2Afternoon++; }
                                else if (assignment === 'OFF') offCount++;
                                else if (assignment === 'LEAVE') leaveCount++;
                            });

                            coverageStats[dateStr] = { morningCount, afternoonCount, offCount, leaveCount, floor1Morning, floor2Morning, floor1Afternoon, floor2Afternoon };
                        });

                        const sampleDates = rosterData.dates.filter(d => d.inMonth).slice(0, 7);

                        sampleDates.forEach(dateInfo => {
                            const stats = coverageStats[dateInfo.dateStr];
                            if (!stats) return;

                            const total = rosterData.therapists.length;
                            const morningPct = (stats.morningCount / total) * 100;
                            const afternoonPct = (stats.afternoonCount / total) * 100;
                            const offPct = (stats.offCount / total) * 100;
                            const leavePct = (stats.leaveCount / total) * 100;

                            const isUnderstaffed = stats.afternoonCount < 3;

                            container.innerHTML += `
            <div style="display: flex; align-items: center; gap: 8px; font-size: 9px;">
                <span style="min-width: 60px; font-weight: 700; color: var(--text-heading);">${dateInfo.dateStr}</span>
                <div style="flex: 1; display: flex; height: 16px; border-radius: 4px; overflow: hidden; border: 1px solid var(--border);">
                    <div style="width: ${morningPct}%; background: #60a5fa; display: flex; align-items: center; justify-content: center; color: white; font-size: 8px; font-weight: 700;">${stats.morningCount > 0 ? stats.morningCount + 'M' : ''}</div>
                    <div style="width: ${afternoonPct}%; background: #f59e0b; display: flex; align-items: center; justify-content: center; color: white; font-size: 8px; font-weight: 700;">${stats.afternoonCount > 0 ? stats.afternoonCount + 'A' : ''}</div>
                    <div style="width: ${offPct}%; background: #9ca3af; display: flex; align-items: center; justify-content: center; color: white; font-size: 8px; font-weight: 700;">${stats.offCount > 0 ? stats.offCount + 'O' : ''}</div>
                    <div style="width: ${leavePct}%; background: #f87171; display: flex; align-items: center; justify-content: center; color: white; font-size: 8px; font-weight: 700;">${stats.leaveCount > 0 ? stats.leaveCount + 'L' : ''}</div>
                </div>
                ${isUnderstaffed ? '<span style="color: var(--danger); font-weight: 700; font-size: 8px;">⚠️ UNDER</span>' : '<span style="color: var(--success); font-weight: 700; font-size: 8px;">✓ OK</span>'}
            </div>
        `;
                        });
                    }

                    function getRosterVersions(cycleMonth) {
                        try {
                            const list = localStorage.getItem(rKey('rosterDraftVersionList') + '_' + cycleMonth);
                            return list ? JSON.parse(list) : [];
                        } catch (e) { return []; }
                    }

                    function saveRosterVersionList(cycleMonth, versions) {
                        try { localStorage.setItem(rKey('rosterDraftVersionList') + '_' + cycleMonth, JSON.stringify(versions)); } catch (e) { }
                    }

                    function populateRosterVersionSelect(cycleMonth) {
                        const sel = rId('rosterVersionSelect');
                        const label = rId('rosterVersionLabel');
                        if (!sel) return;
                        const versions = getRosterVersions(cycleMonth);
                        if (versions.length === 0) {
                            sel.style.display = 'none';
                            if (label) { label.style.display = 'none'; label.innerText = ''; }
                            return;
                        }
                        sel.style.display = 'inline-block';
                        if (label) { label.style.display = 'inline'; label.innerText = '📂 Ver: '; }
                        sel.innerHTML = '';
                        versions.forEach(v => {
                            const opt = document.createElement('option');
                            opt.value = v;
                            opt.textContent = v;
                            sel.appendChild(opt);
                        });
                        sel.value = versions[versions.length - 1];
                    }

                    function loadRosterVersion(version) {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (!version) return;
                        try {
                            const saved = localStorage.getItem(rKey('rosterDraft') + '_' + cycleMonth + '_' + version);
                            if (saved) {
                                const data = JSON.parse(saved);
                                if (data.dates) {
                                    data.dates.forEach(d => { d.date = new Date(d.date); });
                                }
                                R.draftData[cycleMonth] = data;
                                R.currentDraftVersion = version;
                                renderRosterGrid(R.draftData[cycleMonth], false);
                                rId('rosterDraftStatusBadge').innerText = version;
                                rId('rosterDraftStatusBadge').className = 'badge badge-warning';
                            } else {
                                customAlert(`Version ${version} not found for ${cycleMonth}.`);
                                rId('rosterGridHeader').innerHTML = '';
                                rId('rosterGridBody').innerHTML = '';
                                rId('rosterCoverageBars').innerHTML = `<div style="text-align:center;color:var(--text-muted);font-style:italic;padding:20px;">No data for ${version}.</div>`;
                            }
                        } catch (e) {
                            console.warn('loadRosterVersion error:', e);
                            customAlert('Error loading roster version. See console for details.');
                        }
                    }

                    function saveRosterDraft() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (!R.draftData[cycleMonth]) {
                            customAlert("No roster data to save. Generate a roster first.");
                            return;
                        }

                        let versions = getRosterVersions(cycleMonth);
                        let version = R.currentDraftVersion;
                        const pubVersions = getRosterPublishedVersions(cycleMonth);

                        if (!version || pubVersions.includes(version)) {
                            const maxNum = versions.reduce((max, v) => {
                                const num = parseInt(v.replace('R', ''), 10);
                                return isNaN(num) ? max : Math.max(max, num);
                            }, 0);
                            version = 'R' + (maxNum + 1);
                        }

                        try {
                            localStorage.setItem(rKey('rosterDraft') + '_' + cycleMonth + '_' + version, JSON.stringify(R.draftData[cycleMonth]));
                        } catch (e) {
                            customAlert("Failed to save roster draft. Storage may be full.");
                            return;
                        }

                        if (!versions.includes(version)) {
                            versions.push(version);
                            saveRosterVersionList(cycleMonth, versions);
                        }
                        R.currentDraftVersion = version;
                        populateRosterVersionSelect(cycleMonth);

                        rId('rosterDraftStatusBadge').innerText = version;
                        rId('rosterDraftStatusBadge').className = "badge badge-primary";

                        customAlert(`Roster draft for ${cycleMonth} saved as ${version}.`);
                    }

                    function clearRosterDraft() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (R.draftData[cycleMonth]) {
                            delete R.draftData[cycleMonth];
                        }
                        rId('rosterGridHeader').innerHTML = "";
                        rId('rosterGridBody').innerHTML = "";
                        rId('rosterCoverageBars').innerHTML = "";

                        rId('rosterDraftStatusBadge').innerText = "EMPTY";
                        rId('rosterDraftStatusBadge').className = "badge badge-dark";

                        customAlert("Roster draft cleared.");
                    }

                    function publishRosterToTherapists() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (!R.draftData[cycleMonth]) {
                            customAlert("No roster draft to publish. Generate and save a draft first.");
                            return;
                        }

                        customConfirm("Publish this roster to all therapists? They will see their individual schedules. This action cannot be undone.", () => {
                            R.publishedData[cycleMonth] = JSON.parse(JSON.stringify(R.draftData[cycleMonth]));

                            try {
                                let versions = getRosterVersions(cycleMonth);
                                let latestVer = versions.length > 0 ? versions[versions.length - 1] : 'PUBLISHED';
                                const pubVersions = getRosterPublishedVersions(cycleMonth);
                                // If this version is already published, auto-increment so therapists see a new version
                                if (latestVer !== 'PUBLISHED' && pubVersions.includes(latestVer)) {
                                    const maxNum = versions.reduce((max, v) => {
                                        const num = parseInt(v.replace('R', ''), 10);
                                        return isNaN(num) ? max : Math.max(max, num);
                                    }, 0);
                                    latestVer = 'R' + (maxNum + 1);
                                    // Update the draft version list and re-save draft under the new version
                                    const freshData = JSON.parse(JSON.stringify(R.draftData[cycleMonth]));
                                    freshData.version = latestVer;
                                    saveRosterVersionList(cycleMonth, [...versions, latestVer]);
                                    localStorage.setItem(rKey('rosterDraft') + '_' + cycleMonth + '_' + latestVer, JSON.stringify(freshData));
                                }
                                localStorage.setItem(rKey('rosterPublished') + '_' + cycleMonth + '_' + latestVer, JSON.stringify(R.publishedData[cycleMonth]));
                                if (!pubVersions.includes(latestVer)) {
                                    pubVersions.push(latestVer);
                                    localStorage.setItem(rKey('rosterPublishedVersionList') + '_' + cycleMonth, JSON.stringify(pubVersions));
                                }
                            } catch (e) { }

                            R.currentDraftVersion = null;
                            rId('rosterDraftStatusBadge').innerText = "PUBLISHED";
                            rId('rosterDraftStatusBadge').className = "badge badge-success";

                            const therapistNames = R.draftData[cycleMonth].therapists.map(t => t.name).join(', ');
                            systemAlertLogs.unshift({
                                text: `Roster for ${cycleMonth} published. Therapists: ${therapistNames} can now view their schedules.`,
                                tier: 'success',
                                timestamp: new Date().toLocaleString(),
                                lifespan: '24 hours',
                                channel: 'Roster System'
                            });

                            renderOperationalAlertsFeed();
                            customAlert(`Roster published successfully! ${R.draftData[cycleMonth].therapists.length} therapists notified.`);
                        });
                    }

                    function onRosterCycleChange() {
                        const R = rs();
                        const cycleMonth = rId('rosterCycleMonth').value;
                        R.currentCycle = cycleMonth;

                        const versions = getRosterVersions(cycleMonth);
                        populateRosterVersionSelect(cycleMonth);

                        // Try loading latest draft version first
                        if (versions.length > 0) {
                            const latest = versions[versions.length - 1];
                            loadRosterVersion(latest);
                            if (R.draftData[cycleMonth]) return;
                        }

                        // Try loading published data (check cache or localStorage)
                        const published = tryLoadPublishedRoster(cycleMonth);
                        if (published) {
                            R.publishedData[cycleMonth] = published;
                            renderRosterGrid(published, true);
                            rId('rosterDraftStatusBadge').innerText = "PUBLISHED";
                            rId('rosterDraftStatusBadge').className = "badge badge-success";
                            return;
                        }

                        rId('rosterGridHeader').innerHTML = "";
                        rId('rosterGridBody').innerHTML = "";
                        rId('rosterCoverageBars').innerHTML = `<div style="text-align: center; color: var(--text-muted); font-style: italic; padding: 20px;">No roster data for ${cycleMonth}. Click "AI Generate Roster" to create one.</div>`;
                        rId('rosterDraftStatusBadge').innerText = "EMPTY";
                        rId('rosterDraftStatusBadge').className = "badge badge-dark";
                    }

                    function tryLoadPublishedRoster(cycleMonth) {
                        const R = rs();
                        if (R.publishedData[cycleMonth]) return R.publishedData[cycleMonth];
                        try {
                            const versionList = getRosterPublishedVersions(cycleMonth);
                            if (versionList.length > 0) {
                                const latestPub = versionList[versionList.length - 1];
                                const data = localStorage.getItem(rKey('rosterPublished') + '_' + cycleMonth + '_' + latestPub);
                                if (data) {
                                    const parsed = JSON.parse(data);
                                    if (parsed.dates) parsed.dates.forEach(d => { d.date = new Date(d.date); });
                                    return parsed;
                                }
                            }
                        } catch (e) { }
                        try {
                            const pub = localStorage.getItem(rKey('rosterPublished') + '_' + cycleMonth);
                            if (pub) {
                                const parsed = JSON.parse(pub);
                                if (parsed.dates) parsed.dates.forEach(d => { d.date = new Date(d.date); });
                                return parsed;
                            }
                        } catch (e) { }
                        return null;
                    }

                    function getRosterPublishedVersions(cycleMonth) {
                        try {
                            const list = localStorage.getItem(rKey('rosterPublishedVersionList') + '_' + cycleMonth);
                            return list ? JSON.parse(list) : [];
                        } catch (e) { return []; }
                    }

                    function switchMyRosterTab(tab) {
                        document.querySelectorAll('.my-roster-tab-btn').forEach(b => {
                            if (b.dataset.myrostertab === tab) {
                                b.style.background = 'var(--primary)'; b.style.color = '#fff'; b.style.fontWeight = '700';
                            } else {
                                b.style.background = 'transparent'; b.style.color = 'var(--text-muted)'; b.style.fontWeight = '600';
                            }
                        });
                        document.getElementById('myRoster_tab_personal').style.display = tab === 'personal' ? 'block' : 'none';
                        document.getElementById('myRoster_tab_full').style.display = tab === 'full' ? 'block' : 'none';
                        document.getElementById('myRoster_tab_pt').style.display = tab === 'pt' ? 'block' : 'none';
                        if (tab === 'full') renderFullTherapistsRoster();
                        if (tab === 'personal') renderMyRosterView();
                        if (tab === 'pt') renderMyPtRosterView();
                    }

                    function updateMyRosterNavDisplay() {
                        const R = rs();
                        const picker = document.getElementById('myRosterMonthPicker');
                        if (picker) picker.value = R.myRosterViewCycle;
                    }

                    function myRosterSetMonth(value) {
                        if (!value) return;
                        const R = rs();
                        R.myRosterViewCycle = value;
                        const fullPanel = document.getElementById('myRoster_tab_full');
                        const ptPanel = document.getElementById('myRoster_tab_pt');
                        if (fullPanel && fullPanel.style.display !== 'none') renderFullTherapistsRoster();
                        else if (ptPanel && ptPanel.style.display !== 'none') renderMyPtRosterView();
                        else renderMyRosterView();
                    }

                    function myRosterChangeMonth(delta) {
                        const R = rs();
                        const parts = R.myRosterViewCycle.split('-');
                        let y = parseInt(parts[0]), m = parseInt(parts[1]) + delta;
                        if (m > 12) { m = 1; y++; }
                        if (m < 1) { m = 12; y--; }
                        R.myRosterViewCycle = y + '-' + String(m).padStart(2, '0');
                        updateMyRosterNavDisplay();
                        const fullPanel = document.getElementById('myRoster_tab_full');
                        const ptPanel = document.getElementById('myRoster_tab_pt');
                        if (fullPanel && fullPanel.style.display !== 'none') renderFullTherapistsRoster();
                        else if (ptPanel && ptPanel.style.display !== 'none') renderMyPtRosterView();
                        else renderMyRosterView();
                    }

                    function renderFullTherapistsRoster() {
                        currentRosterTab = 'fulltime';
                        const header = document.getElementById('fullRosterHeader');
                        const body = document.getElementById('fullRosterBody');
                        if (!header || !body) return;

                        const cycleMonth = rs().myRosterViewCycle;
                        // Always read the latest published data from localStorage (bypass cache)
                        let rosterData = null;
                        try {
                            const versionList = getRosterPublishedVersions(cycleMonth);
                            if (versionList.length > 0) {
                                const latestPub = versionList[versionList.length - 1];
                                const saved = localStorage.getItem(`rosterPublished_${cycleMonth}_${latestPub}`);
                                if (saved) {
                                    rosterData = JSON.parse(saved);
                                    if (rosterData.dates) rosterData.dates.forEach(d => { d.date = new Date(d.date); });
                                }
                            }
                        } catch (e) { }
                        if (rosterData) rosterPublishedData[cycleMonth] = rosterData;

                        if (!rosterData || !rosterData.dates || !rosterData.therapists || rosterData.therapists.length === 0) {
                            header.innerHTML = '';
                            body.innerHTML = '<tr><td colspan="100" style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px;"><div style="font-size:32px;margin-bottom:10px;">👥</div><strong>No Published Roster Available</strong><br><span style="font-size:11px;">Publish a roster first from the Grid Roster Engine.</span></td></tr>';
                            return;
                        }

                        // Build header: DATE | DAYS | Therapist1 | Therapist2 | ... (same style as grid engine)
                        let headHtml = `<tr style="background: var(--primary-light);">
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 0; z-index: 10; background: var(--primary-light); min-width: 70px;">DATE</th>
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 70px; z-index: 10; background: var(--primary-light); min-width: 45px;">DAYS</th>`;
                        rosterData.therapists.forEach(t => {
                            if (!t.name || !t.name.trim()) return;
                            const firstName = t.name.split(' ')[0];
                            const lastName = t.name.split(' ').slice(1).join(' ');
                            const bgColor = t.color ? t.color + '22' : 'var(--primary-light)';
                            headHtml += `<th style="padding: 8px 6px; text-align: center; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; min-width: 65px; background: ${bgColor};">${escHtml(firstName)}<br><span style="font-size: 8px; opacity: 0.7;">${escHtml(lastName)}</span></th>`;
                        });
                        headHtml += `</tr>`;
                        header.innerHTML = headHtml;

                        // Build body: one row per date (same style as grid engine)
                        let bodyHtml = '';
                        rosterData.dates.forEach(dateInfo => {
                            const dateStr = dateInfo.dateStr;
                            const dayOfWeek = dateInfo.date.getDay();
                            const isOffDay = getRosterOffDays().includes(dayOfWeek);
                            const isThursday = dayOfWeek === 4;
                            const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

                            let rowStyle = '';
                            if (!dateInfo.inMonth) rowStyle += 'opacity: 0.5;';
                            if (isOffDay) rowStyle += 'background: #f3f4f6;';
                            else if (isWeekend) rowStyle += 'background: #fafafa;';

                            const dateBg = !dateInfo.inMonth ? '#f9fafb' : (isOffDay ? '#f3f4f6' : 'var(--bg-card)');
                            bodyHtml += `<tr style="${rowStyle}">
            <td style="padding: 6px; border: 1px solid var(--border); font-weight: 700; font-size: 9px; position: sticky; left: 0; background: ${dateBg}; z-index: 5; white-space: nowrap;">${dateStr}</td>
            <td style="padding: 6px; border: 1px solid var(--border); font-weight: 600; font-size: 9px; position: sticky; left: 70px; background: ${dateBg}; z-index: 5;">${dateInfo.dayName}</td>`;

                            rosterData.therapists.forEach(t => {
                                if (!t.name || !t.name.trim()) return;
                                const assignment = rosterData.assignments && rosterData.assignments[t.email] ? rosterData.assignments[t.email][dateStr] : null;
                                const shiftKey = assignment || 'OFF';
                                const shiftDef = ROSTER_SHIFT_TYPES[shiftKey] || ROSTER_SHIFT_TYPES['OFF'];

                                let cellLabel = shiftDef.code;
                                let cellTitle = shiftDef.label + (shiftDef.time !== '-' ? ' (' + shiftDef.time + ')' : '');

                                if (shiftKey === 'HOLIDAY') {
                                    const localIsoDate = dateInfo.date.getFullYear() + '-' + String(dateInfo.date.getMonth() + 1).padStart(2, '0') + '-' + String(dateInfo.date.getDate()).padStart(2, '0');
                                    if (window.psCalData && psCalData[localIsoDate] && psCalData[localIsoDate].n) {
                                        cellLabel = psCalData[localIsoDate].n;
                                        if (cellLabel.length > 8) cellLabel = cellLabel.substring(0, 7) + '..';
                                        cellTitle = psCalData[localIsoDate].n + ' (Public Holiday)';
                                    }
                                }

                                bodyHtml += `<td style="padding: 4px 2px; border: 1px solid var(--border); text-align: center; font-size: 9px; font-weight: 700; background: ${shiftDef.color}; color: ${shiftDef.textColor}; cursor: default;" title="${cellTitle}">${cellLabel}</td>`;
                            });
                            bodyHtml += '</tr>';
                        });
                        body.innerHTML = bodyHtml;
                    }

                    function renderMyRosterView() {
                        currentRosterTab = 'fulltime';
                        const R = rs();
                        const cycleMonth = R.myRosterViewCycle;
                        const myEmail = currentActiveSessionUser.email;

                        let rosterData = R.publishedData[cycleMonth];
                        if (!rosterData) {
                            rosterData = tryLoadPublishedRoster(cycleMonth);
                            if (rosterData) R.publishedData[cycleMonth] = rosterData;
                        }

                        const tbody = document.getElementById('myRosterBody');
                        if (!tbody) return;
                        tbody.innerHTML = "";

                        if (!rosterData) {
                            tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; padding: 40px; color: var(--text-muted); font-style: italic;">No published roster available for ${cycleMonth}. Please check with your supervisor.</td></tr>`;
                            document.getElementById('myRosterTotalDays').innerText = "-";
                            document.getElementById('myRosterMorningCount').innerText = "-";
                            document.getElementById('myRosterAfternoonCount').innerText = "-";
                            document.getElementById('myRosterOffCount').innerText = "-";
                            return;
                        }

                        const myData = rosterData.therapists.find(t => t.email === myEmail);
                        if (!myData) {
                            tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; padding: 40px; color: var(--text-muted); font-style: italic;">You are not assigned to the ${cycleMonth} roster.</td></tr>`;
                            document.getElementById('myRosterTotalDays').innerText = "-";
                            document.getElementById('myRosterMorningCount').innerText = "-";
                            document.getElementById('myRosterAfternoonCount').innerText = "-";
                            document.getElementById('myRosterOffCount').innerText = "-";
                            return;
                        }

                        let totalDays = 0, morningCount = 0, afternoonCount = 0, offCount = 0;

                        rosterData.dates.forEach(dateInfo => {
                            if (!dateInfo.inMonth) return;

                            const dateStr = dateInfo.dateStr;
                            const assignment = rosterData.assignments[myEmail][dateStr] || "OFF";
                            const shiftDef = ROSTER_SHIFT_TYPES[assignment] || ROSTER_SHIFT_TYPES["OFF"];

                            if (assignment !== 'OFF' && assignment !== 'LEAVE') totalDays++;
                            if (assignment.includes('MR')) morningCount++;
                            if (assignment.includes('AF')) afternoonCount++;
                            if (assignment === 'OFF') offCount++;

                            const tr = document.createElement('tr');
                            tr.style.borderBottom = '1px solid var(--border)';
                            tr.innerHTML = `
            <td style="padding: 10px; font-weight: 700; color: var(--text-heading);">${dateStr}</td>
            <td style="padding: 10px; color: var(--text-muted); font-weight: 600;">${dateInfo.dayName}</td>
            <td style="padding: 10px; text-align: center;">
                <span style="display: inline-block; padding: 4px 10px; border-radius: 4px; font-weight: 700; font-size: 10px; background: ${shiftDef.color}; color: ${shiftDef.textColor}; border: 1px solid ${shiftDef.borderColor};">${shiftDef.code}</span>
            </td>
            <td style="padding: 10px; text-align: center; font-weight: 600; color: var(--text-body);">${shiftDef.floor > 0 ? 'Floor ' + shiftDef.floor : '-'}</td>
            <td style="padding: 10px; text-align: center; color: var(--text-muted); font-size: 10px;">${shiftDef.time}</td>
            <td style="padding: 10px; text-align: center;">
                <span class="badge ${assignment === 'OFF' ? 'badge-dark' : assignment === 'LEAVE' ? 'badge-danger' : 'badge-primary'}" style="font-size: 9px;">${shiftDef.label}</span>
            </td>
        `;
                            tbody.appendChild(tr);
                        });

                        document.getElementById('myRosterTotalDays').innerText = totalDays;
                        document.getElementById('myRosterMorningCount').innerText = morningCount;
                        document.getElementById('myRosterAfternoonCount').innerText = afternoonCount;
                        document.getElementById('myRosterOffCount').innerText = offCount;
                    }

                    function renderMyPtRosterView() {
                        const header = document.getElementById('myPtRosterHead');
                        const body = document.getElementById('myPtRosterBody');
                        if (!header || !body) return;

                        const cycleMonth = document.getElementById('myRosterMonthPicker').value;
                        const sel = document.getElementById('myPtRosterVersionSelect');

                        const pubVersions = ptGetPublishedVersions(cycleMonth);
                        const currentVer = sel ? sel.value : '';
                        if (sel) {
                            sel.innerHTML = '';
                            if (pubVersions.length === 0) {
                                sel.innerHTML = '<option value="">No published versions</option>';
                            } else {
                                pubVersions.forEach(v => {
                                    const opt = document.createElement('option');
                                    opt.value = v; opt.textContent = v;
                                    sel.appendChild(opt);
                                });
                                if (currentVer && pubVersions.includes(currentVer)) sel.value = currentVer;
                                else sel.value = pubVersions[pubVersions.length - 1];
                            }
                        }

                        const version = sel ? sel.value : '';
                        if (!version || pubVersions.length === 0) {
                            header.innerHTML = '';
                            body.innerHTML = '<tr><td colspan="100" style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px;"><div style="font-size:32px;margin-bottom:10px;">👥</div><strong>No Published PT Roster</strong><br><span style="font-size:11px;">Publish a part-time roster first from the Part-Time Roster Engine.</span></td></tr>';
                            return;
                        }

                        let rosterData = null;
                        try {
                            const saved = localStorage.getItem('ptRosterPublished_' + cycleMonth + '_' + version);
                            if (saved) rosterData = JSON.parse(saved);
                        } catch (e) { }
                        if (!rosterData || !rosterData.dates || !rosterData.therapists || rosterData.therapists.length === 0) {
                            header.innerHTML = '';
                            body.innerHTML = '<tr><td colspan="100" style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px;"><div style="font-size:32px;margin-bottom:10px;">👥</div><strong>No Data</strong><br><span style="font-size:11px;">No part-time roster data for this version.</span></td></tr>';
                            return;
                        }

                        const therapists = rosterData.therapists;

                        // Build header: DATE | DAYS | Therapist1 | Therapist2 | ...
                        let headHtml = `<tr style="background: var(--primary-light);">
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 0; z-index: 10; background: var(--primary-light); min-width: 70px;">DATE</th>
        <th style="padding: 8px 6px; text-align: left; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; position: sticky; left: 70px; z-index: 10; background: var(--primary-light); min-width: 45px;">DAYS</th>`;
                        therapists.forEach(t => {
                            if (!t.name || !t.name.trim()) return;
                            const firstName = t.name.split(' ')[0];
                            const lastName = t.name.split(' ').slice(1).join(' ');
                            const bgColor = t.color ? t.color + '22' : 'var(--primary-light)';
                            headHtml += `<th style="padding: 8px 6px; text-align: center; border: 1px solid var(--border); font-weight: 700; color: var(--primary); font-size: 9px; min-width: 75px; background: ${bgColor};">${escHtml(firstName)}<br><span style="font-size: 8px; opacity: 0.7;">${escHtml(lastName)}</span></th>`;
                        });
                        headHtml += `</tr>`;
                        header.innerHTML = headHtml;

                        // Build body: one row per date
                        let bodyHtml = '';
                        rosterData.dates.forEach(dateInfo => {
                            if (!dateInfo.inMonth) return;
                            const dateStr = dateInfo.dateStr;
                            const dayOfWeek = new Date(dateStr.split('/').reverse().join('-')).getDay();
                            const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
                            const rowStyle = isWeekend ? 'background: #fafafa;' : '';
                            const dateBg = isWeekend ? '#fafafa' : 'var(--bg-card)';

                            bodyHtml += `<tr style="${rowStyle}">
            <td style="padding: 6px; border: 1px solid var(--border); font-weight: 700; font-size: 9px; position: sticky; left: 0; background: ${dateBg}; z-index: 5; white-space: nowrap;">${dateStr}</td>
            <td style="padding: 6px; border: 1px solid var(--border); font-weight: 600; font-size: 9px; position: sticky; left: 70px; background: ${dateBg}; z-index: 5;">${dateInfo.dayName}</td>`;

                            therapists.forEach(t => {
                                if (!t.name || !t.name.trim()) return;
                                const assignments = rosterData.assignments[t.email] || {};
                                const cell = assignments[dateStr];
                                let cellHtml = '';

                                if (!cell) {
                                    cellHtml = '<span style="color:var(--text-muted);font-size:8px;">-</span>';
                                } else if (cell.type === 'LEAVE') {
                                    const c = PT_COLORS.LEAVE;
                                    cellHtml = `<span style="background:${c.color};border:1px solid ${c.borderColor};border-radius:3px;padding:2px 5px;font-size:8px;font-weight:700;color:${c.textColor};">On Leave</span>`;
                                } else if (cell.type === 'HOLIDAY') {
                                    const c = PT_COLORS.HOLIDAY;
                                    cellHtml = `<span style="background:${c.color};border:1px solid ${c.borderColor};border-radius:3px;padding:2px 5px;font-size:8px;font-weight:700;color:${c.textColor};">HOLIDAY</span>`;
                                } else if (cell.off || !cell.slots || cell.slots.length === 0) {
                                    const c = PT_COLORS.OFF;
                                    cellHtml = `<span style="background:${c.color};border:1px solid ${c.borderColor};border-radius:3px;padding:2px 5px;font-size:8px;font-weight:700;color:${c.textColor};">OFF</span>`;
                                } else {
                                    // Multiple slots - stack them
                                    const parts = cell.slots.map(s => {
                                        const c = PT_COLORS[s.floor] || PT_COLORS["1ST"];
                                        const floorLabel = s.floor === '1ST' ? '1st' : '2nd';
                                        return `<div style="background:${c.color};border:1px solid ${c.borderColor};border-radius:3px;padding:2px 4px;margin:1px 0;font-size:8px;font-weight:700;color:${c.textColor};line-height:1.4;">${floorLabel}<br><span style="font-size:7px;opacity:0.8;">${s.start}-${s.end}</span></div>`;
                                    });
                                    cellHtml = parts.join('');
                                }

                                bodyHtml += `<td style="padding: 3px 2px; border: 1px solid var(--border); text-align: center; font-size: 9px; vertical-align: middle;">${cellHtml}</td>`;
                            });
                            bodyHtml += '</tr>';
                        });
                        body.innerHTML = bodyHtml;
                    }

                    function exportRosterToPDF() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        const rosterData = R.draftData[cycleMonth] || R.publishedData[cycleMonth];
                        if (!rosterData) {
                            customAlert("No roster data to export.");
                            return;
                        }

                        let tableHtml = `<table style="width: 100%; border-collapse: collapse; font-size: 8px; font-family: Arial, sans-serif;">
        <thead><tr style="background: #f1f5f9;">
            <th style="border: 1px solid #000; padding: 4px; text-align: left;">DATE</th>
            <th style="border: 1px solid #000; padding: 4px; text-align: left;">DAY</th>`;

                        rosterData.therapists.forEach(t => {
                            tableHtml += `<th style="border: 1px solid #000; padding: 4px; text-align: center; background: ${t.color}22;">${t.name}</th>`;
                        });
                        tableHtml += `</tr></thead><tbody>`;

                        rosterData.dates.forEach(dateInfo => {
                            tableHtml += `<tr>`;
                            tableHtml += `<td style="border: 1px solid #000; padding: 3px; font-weight: bold;">${dateInfo.dateStr}</td>`;
                            tableHtml += `<td style="border: 1px solid #000; padding: 3px;">${dateInfo.dayName}</td>`;

                            rosterData.therapists.forEach(t => {
                                const assignment = rosterData.assignments[t.email][dateInfo.dateStr] || "OFF";
                                const shiftDef = ROSTER_SHIFT_TYPES[assignment] || ROSTER_SHIFT_TYPES["OFF"];
                                tableHtml += `<td style="border: 1px solid #000; padding: 3px; text-align: center; background: ${shiftDef.color}; color: ${shiftDef.textColor}; font-weight: bold;">${shiftDef.code}</td>`;
                            });

                            tableHtml += `</tr>`;
                        });

                        tableHtml += `</tbody></table>`;

                        let legendHtml = `<div style="margin-top: 15px; display: flex; flex-wrap: wrap; gap: 10px; font-size: 9px;">
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #dbeafe; border: 1px solid #93c5fd; margin-right: 4px;"></span>1ST/MR (1st Floor Morning)</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #fef3c7; border: 1px solid #fbbf24; margin-right: 4px;"></span>1ST/AF (1st Floor Afternoon)</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #d1fae5; border: 1px solid #34d399; margin-right: 4px;"></span>2ND/MR (2nd Floor Morning)</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #fce7f3; border: 1px solid #f472b6; margin-right: 4px;"></span>2ND/AF (2nd Floor Afternoon)</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #c7d2fe; border: 1px solid #818cf8; margin-right: 4px;"></span>1st/2nd (Thursday)</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #e5e7eb; border: 1px solid #9ca3af; margin-right: 4px;"></span>OFF</div>
        <div><span style="display: inline-block; width: 12px; height: 12px; background: #fecaca; border: 1px solid #f87171; margin-right: 4px;"></span>On Leave</div>
    </div>`;

                        openPrintablePDFWindow('Physiotherapy Roster - ' + cycleMonth, '<span><strong>Cycle:</strong> ' + cycleMonth + '</span>', tableHtml + legendHtml);
                    }

                    function exportRosterToExcel() {
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        const rosterData = R.draftData[cycleMonth] || R.publishedData[cycleMonth];
                        if (!rosterData) {
                            customAlert("No roster data to export.");
                            return;
                        }

                        let csvContent = "DATE,DAY,";
                        csvContent += rosterData.therapists.map(t => t.name).join(",") + "\n"; // Fixed: added \n instead of a raw line break

                        rosterData.dates.forEach(dateInfo => {
                            csvContent += `${dateInfo.dateStr},${dateInfo.dayName},`;
                            csvContent += rosterData.therapists.map(t => {
                                const assignment = rosterData.assignments[t.email][dateInfo.dateStr] || "OFF";
                                const shiftDef = ROSTER_SHIFT_TYPES[assignment] || ROSTER_SHIFT_TYPES["OFF"];
                                return shiftDef.code;
                            }).join(",") + "\n"; // Fixed: added \n instead of a raw line break
                        });

                        downloadCSVAsXlsx(`Physio_Roster_${cycleMonth}.csv`, csvContent);
                    }

                    function exportMyRosterToPDF() {
                        exportRosterToPDF();
                    }

                    // Color management functions
                    function updateRosterShiftColor(shiftKey, colorValue) {
                        if (ROSTER_SHIFT_TYPES[shiftKey]) {
                            ROSTER_SHIFT_TYPES[shiftKey].color = colorValue;

                            // Update the preview swatch for both tabs
                            const preview = document.getElementById(`colorPreview_${shiftKey}`);
                            if (preview) preview.style.background = colorValue;
                            const previewPt = document.getElementById(`colorPreview_${shiftKey}_pt`);
                            if (previewPt) previewPt.style.background = colorValue;

                            // Re-render the grid if there's data
                            const R = rs();
                            const cycleMonth = R.currentCycle;
                            if (R.draftData[cycleMonth]) {
                                renderRosterGrid(R.draftData[cycleMonth], false);
                            } else if (R.publishedData[cycleMonth]) {
                                renderRosterGrid(R.publishedData[cycleMonth], true);
                            }

                            showRosterToast(`${ROSTER_SHIFT_TYPES[shiftKey].label} color updated`);
                        }
                    }

                    function saveRosterColorDefaults() {
                        const colorConfig = {};
                        Object.keys(ROSTER_SHIFT_TYPES).forEach(key => {
                            colorConfig[key] = ROSTER_SHIFT_TYPES[key].color;
                        });

                        try {
                            localStorage.setItem('rosterColorDefaults', JSON.stringify(colorConfig));
                        } catch (e) { }

                        customAlert("Shift colors saved as defaults. All future rosters will use these colors.");
                    }

                    function resetRosterColorDefaults() {
                        const defaults = {
                            "1ST_MR": "#dbeafe",
                            "1ST_AF": "#fef3c7",
                            "2ND_MR": "#d1fae5",
                            "2ND_AF": "#fce7f3",
                            "THU_1ST": "#c7d2fe",
                            "THU_2ND": "#ddd6fe",
                            "OFF": "#e5e7eb",
                            "LEAVE": "#fecaca",
                            "HOLIDAY": "#fed7aa"
                        };

                        Object.keys(defaults).forEach(key => {
                            if (ROSTER_SHIFT_TYPES[key]) {
                                ROSTER_SHIFT_TYPES[key].color = defaults[key];
                            }
                            ['', '_pt'].forEach(sfx => {
                                const picker = document.getElementById(`colorPicker_${key}${sfx}`);
                                if (picker) picker.value = defaults[key];
                                const preview = document.getElementById(`colorPreview_${key}${sfx}`);
                                if (preview) preview.style.background = defaults[key];
                            });
                        });

                        try {
                            localStorage.removeItem('rosterColorDefaults');
                        } catch (e) { }

                        // Re-render both tabs
                        const R = rs();
                        const cycleMonth = R.currentCycle;
                        if (R.draftData[cycleMonth]) {
                            renderRosterGrid(R.draftData[cycleMonth], false);
                        } else if (R.publishedData[cycleMonth]) {
                            renderRosterGrid(R.publishedData[cycleMonth], true);
                        }

                        customAlert("Colors reset to factory defaults.");
                    }

                    function loadRosterColorDefaults() {
                        try {
                            const saved = localStorage.getItem('rosterColorDefaults');
                            if (saved) {
                                const colorConfig = JSON.parse(saved);
                                Object.keys(colorConfig).forEach(key => {
                                    if (ROSTER_SHIFT_TYPES[key]) {
                                        ROSTER_SHIFT_TYPES[key].color = colorConfig[key];
                                    }
                                    ['', '_pt'].forEach(sfx => {
                                        const picker = document.getElementById(`colorPicker_${key}${sfx}`);
                                        if (picker) picker.value = colorConfig[key];
                                        const preview = document.getElementById(`colorPreview_${key}${sfx}`);
                                        if (preview) preview.style.background = colorConfig[key];
                                    });
                                });
                            }
                        } catch (e) { }
                    }

                    // ==========================================
                    // PART-TIME ROSTER SYSTEM (All functions)
                    // ==========================================

                    function ptInit() {
                        const cycle = document.getElementById('ptRosterCycleMonth').value || ptState.cycle;
                        ptState.cycle = cycle;
                        ptState.therapists = [];
                        ptState.daySlots = {};
                        ptState.overrides = {};
                        // Load saved config from localStorage (with migration from old 'slots' format)
                        try {
                            const saved = localStorage.getItem('ptRosterConfig_' + cycle);
                            if (saved) {
                                const cfg = JSON.parse(saved);
                                ptState.therapists = cfg.therapists || [];
                                if (cfg.daySlots) {
                                    ptState.daySlots = cfg.daySlots;
                                } else if (cfg.slots) {
                                    // Migrate from old single-array format to per-day format
                                    ptState.daySlots = {};
                                    Object.keys(cfg.slots).forEach(email => {
                                        const oldSlots = cfg.slots[email];
                                        ptState.daySlots[email] = {};
                                        for (let di = 0; di < 7; di++) {
                                            ptState.daySlots[email][di] = oldSlots.map(s => ({ start: s.start || '08:40', end: s.end || '12:00' }));
                                        }
                                    });
                                }
                                ptState.overrides = cfg.overrides || {};
                                // Clear old-format config after migration
                                if (cfg.slots && !cfg.daySlots) ptSaveConfig();
                            }
                        } catch (e) { }
                        ptRenderConfig();
                        ptPopulateVersionSelect();
                        ptTryLoadDraft(cycle);
                    }

                    function ptGetPtStaff() {
                        return (globalRosterRepository || []).filter(u => u.active !== false && u.style === 'Part-Time');
                    }

                    function ptAddTherapist() {
                        const allPt = ptGetPtStaff();
                        if (allPt.length === 0) {
                            customAlert("No part-time staff found in the staff directory. Register them first.");
                            return;
                        }
                        const addedEmails = ptState.therapists.map(t => t.email);
                        const available = allPt.filter(u => !addedEmails.includes(u.email));
                        if (available.length === 0) {
                            customAlert("All part-time therapists (" + allPt.map(u => u.name).join(', ') + ") are already in the roster.");
                            return;
                        }
                        let opts = allPt.map((u, i) => {
                            const isAvail = available.includes(u);
                            return `<option value="${i}" ${isAvail ? '' : 'disabled style="color:var(--text-muted);"'}>${u.name} — ${u.position || 'Staff'}${isAvail ? '' : ' (added)'}</option>`;
                        }).join('');
                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `<div class="system-inline-modal-overlay">
        <div class="system-inline-modal-box" style="width: 340px;">
            <div style="padding:14px;">
                <h3 style="margin-bottom:12px;font-size:13px;">Select Part-Time Therapist</h3>
                <select id="ptAddTherapistSelect" style="width:100%;padding:6px;border-radius:4px;border:1px solid var(--border);font-size:12px;margin-bottom:14px;">${opts}</select>
                <div style="display:flex;gap:8px;justify-content:flex-end;">
                    <button class="action-btn" style="padding:6px 16px;font-size:11px;background:var(--text-muted);" onclick="closeSystemModalBox()">Cancel</button>
                    <button class="action-btn" style="padding:6px 16px;font-size:11px;background:var(--primary);" onclick="ptConfirmAddTherapist()">Add</button>
                </div>
            </div>
        </div>
    </div>`;
                    }

                    function ptConfirmAddTherapist() {
                        try {
                            const sel = document.getElementById('ptAddTherapistSelect');
                            if (!sel) { console.warn('ptAddTherapistSelect not found'); closeSystemModalBox(); return; }
                            const idx = parseInt(sel.value, 10);
                            const allPt = ptGetPtStaff();
                            if (idx >= 0 && idx < allPt.length) {
                                const u = allPt[idx];
                                if (ptState.therapists.find(t => t.email === u.email)) {
                                    customAlert(u.name + ' is already in the roster.');
                                    closeSystemModalBox(); return;
                                }
                                if (!u || !u.email) { console.warn('Invalid therapist at index', idx); closeSystemModalBox(); return; }
                                ptState.therapists.push({ email: u.email, name: u.name, color: u.color || '#004b87' });
                                ptState.daySlots[u.email] = {};
                                for (let di = 0; di < 7; di++) {
                                    ptState.daySlots[u.email][di] = di === 5 ? [] : [{ start: "08:00", end: "11:20" }];
                                }
                                ptSaveConfig();
                                ptRenderConfig();
                            }
                            closeSystemModalBox();
                        } catch (e) { console.error('ptConfirmAddTherapist error:', e); closeSystemModalBox(); }
                    }

                    function ptRemoveTherapist(email) {
                        ptState.therapists = ptState.therapists.filter(t => t.email !== email);
                        delete ptState.daySlots[email];
                        delete ptState.overrides[email];
                        ptSaveConfig();
                        ptRenderConfig();
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (ptState.therapists.length > 0 && data) {
                            // Remove therapist from draft data and re-render
                            data.therapists = data.therapists.filter(t => t.email !== email);
                            delete data.assignments[email];
                            if (data._weekFloors) delete data._weekFloors[email];
                            ptRenderGrid(data);
                            const badge = document.getElementById('ptRosterStatusBadge');
                            if (badge) {
                                badge.style.display = 'inline-block';
                                badge.innerText = (ptState.currentVersion || 'DRAFT') + ' (modified)';
                                badge.className = "badge badge-warning";
                            }
                        } else {
                            ptClearGrid();
                            ptState.currentVersion = null;
                            const badge = document.getElementById('ptRosterStatusBadge');
                            if (badge) {
                                badge.style.display = 'inline-block';
                                badge.innerText = "MODIFIED";
                                badge.className = "badge badge-warning";
                            }
                        }
                    }

                    function ptSaveConfig() {
                        try {
                            localStorage.setItem('ptRosterConfig_' + ptState.cycle, JSON.stringify({
                                therapists: ptState.therapists,
                                daySlots: ptState.daySlots,
                                overrides: ptState.overrides
                            }));
                        } catch (e) { }
                    }

                    function ptRenderConfig() {
                        const container = document.getElementById('ptTherapistConfigContainer');
                        if (!container) return;
                        if (ptState.therapists.length === 0) {
                            container.innerHTML = '<div style="color:var(--text-muted);font-size:10px;text-align:center;padding:12px;border:1px dashed var(--border);border-radius:6px;">No therapists added yet. Click "➕ Add Therapist" to begin.</div>';
                            return;
                        }
                        const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
                        let html = '';
                        ptState.therapists.forEach(t => {
                            const ds = ptState.daySlots[t.email] || {};
                            let daysHtml = '';
                            dayNames.forEach((d, di) => {
                                const dayEmpty = !ds[di] || ds[di].length === 0;
                                let slots = ds[di] || [];
                                if (slots.length === 0) slots = [{ start: "08:00", end: "11:20" }];
                                let slotsHtml = '';
                                slots.forEach((s, si) => {
                                    slotsHtml += `<div style="display:flex;gap:2px;align-items:center;margin-bottom:1px;">
                    <input type="time" value="${s.start}" onchange="ptUpdateDaySlot('${t.email}',${di},${si},'start',this.value)" style="width:78px;padding:2px 4px;border:1px solid var(--border);border-radius:2px;font-size:9px;background:var(--bg-main);color:var(--text-body);box-sizing:border-box;">
                    <span style="font-size:8px;color:var(--text-muted);">→</span>
                    <input type="time" value="${s.end}" onchange="ptUpdateDaySlot('${t.email}',${di},${si},'end',this.value)" style="width:78px;padding:2px 4px;border:1px solid var(--border);border-radius:2px;font-size:9px;background:var(--bg-main);color:var(--text-body);box-sizing:border-box;">
                    <button class="action-btn" style="padding:0px 5px;font-size:8px;background:var(--danger);line-height:16px;" onclick="ptRemoveDaySlot('${t.email}',${di},${si})">✕</button>
                    <button class="action-btn" style="padding:0px 5px;font-size:8px;background:var(--primary);line-height:16px;" onclick="ptAddDaySlot('${t.email}',${di})">+</button>
                </div>`;
                                });
                                const dayBg = dayEmpty ? '#fef2f2' : 'transparent';
                                daysHtml += `<div style="border:1px solid var(--border);border-radius:4px;padding:4px;background:${dayBg};min-width:175px;flex:1;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px;">
                    <span style="font-size:9px;font-weight:700;color:${dayEmpty ? 'var(--danger)' : 'var(--text-heading)'};">${d}</span>
                    ${dayEmpty ? '<span style="font-size:8px;color:var(--danger);font-weight:600;">OFF</span>' : ''}
                </div>
                ${slotsHtml}
            </div>`;
                            });
                            html += `<div style="border:1px solid var(--border);border-radius:6px;padding:8px;background:var(--bg-card);font-size:11px;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
                <strong style="color:var(--text-heading);font-size:11px;">${t.name}</strong>
                <div style="font-size:8px;color:var(--text-muted);font-style:italic;">Floor auto-assigned</div>
                <button class="action-btn" style="padding:2px 6px;font-size:9px;background:var(--danger);" onclick="ptRemoveTherapist('${t.email}')">✕</button>
            </div>
            <div style="display:flex;flex-wrap:wrap;gap:3px;">${daysHtml}</div>
        </div>`;
                        });
                        container.innerHTML = html;
                    }

                    function ptUpdateDaySlot(email, dayIdx, slotIdx, field, value) {
                        if (!ptState.daySlots[email]) ptState.daySlots[email] = {};
                        if (!ptState.daySlots[email][dayIdx] || ptState.daySlots[email][dayIdx].length === 0) {
                            ptState.daySlots[email][dayIdx] = [{ start: "08:00", end: "11:20" }];
                        }
                        if (slotIdx >= 0 && slotIdx < ptState.daySlots[email][dayIdx].length) {
                            ptState.daySlots[email][dayIdx][slotIdx][field] = value;
                        }
                        ptSaveConfig();
                        const badge = document.getElementById('ptRosterStatusBadge');
                        if (badge) {
                            badge.style.display = 'inline-block';
                            badge.innerText = "MODIFIED";
                            badge.className = "badge badge-warning";
                        }
                    }

                    function ptAddDaySlot(email, dayIdx) {
                        if (!ptState.daySlots[email]) ptState.daySlots[email] = {};
                        if (!ptState.daySlots[email][dayIdx]) ptState.daySlots[email][dayIdx] = [];
                        ptState.daySlots[email][dayIdx].push({ start: "08:00", end: "11:20" });
                        ptSaveConfig();
                        ptRenderConfig();
                    }

                    function ptRemoveDaySlot(email, dayIdx, slotIdx) {
                        if (!ptState.daySlots[email] || !ptState.daySlots[email][dayIdx]) return;
                        ptState.daySlots[email][dayIdx].splice(slotIdx, 1);
                        ptSaveConfig();
                        ptRenderConfig();
                    }

                    function ptGenerateDates() {
                        const cycleMonth = ptState.cycle;
                        const [cy, cm] = cycleMonth.split('-').map(Number);
                        const from = document.getElementById('ptRosterDateFrom')?.value;
                        const to = document.getElementById('ptRosterDateTo')?.value;
                        const start = from ? new Date(from + 'T12:00:00') : new Date(cy, cm - 1, 1);
                        const end = to ? new Date(to + 'T12:00:00') : new Date(cy, cm, 0);
                        const dates = [];
                        // Pad to Sunday-Saturday weeks
                        const padStart = new Date(start);
                        padStart.setDate(padStart.getDate() - padStart.getDay());
                        const padEnd = new Date(end);
                        padEnd.setDate(padEnd.getDate() + (6 - padEnd.getDay()));
                        const d = new Date(padStart);
                        while (d <= padEnd) {
                            const dd = String(d.getDate()).padStart(2, '0');
                            const mm = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][d.getMonth()];
                            const yy = String(d.getFullYear()).slice(-2);
                            const dateStr = dd + '-' + mm + '-' + yy;
                            const dayName = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][d.getDay()];
                            const iso = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + dd;
                            dates.push({
                                date: new Date(d),
                                dateStr: dateStr,
                                isoDate: iso,
                                dayName: dayName,
                                inMonth: d >= start && d <= end
                            });
                            d.setDate(d.getDate() + 1);
                        }
                        return dates;
                    }

                    function ptGenerateRoster() {
                        if (ptState.therapists.length === 0) {
                            customAlert("Please add at least one therapist before generating a roster.");
                            return;
                        }

                        // Prompt for version handling if a draft already exists for this cycle
                        const cycleMonth = ptState.cycle;
                        const existingVersions = ptGetVersions(cycleMonth);
                        const currentVer = ptState.currentVersion;

                        function ptGetNextVersion() {
                            const maxNum = existingVersions.reduce((max, v) => {
                                const num = parseInt(v.replace('R', ''), 10);
                                return isNaN(num) ? max : Math.max(max, num);
                            }, 0);
                            return 'R' + (maxNum + 1);
                        }

                        function ptExecGenerate() {
                            const dates = ptGenerateDates();
                            ptState.dates = dates;

                            const assignments = {};
                            const holidays = typeof psCalData !== 'undefined' ? psCalData : {};

                            ptState.therapists.forEach(t => {
                                assignments[t.email] = {};
                                let daySlots = ptState.daySlots[t.email] || {};
                                // If therapist has no daySlots at all, provide one default slot per day
                                if (Object.keys(daySlots).length === 0) {
                                    daySlots = {};
                                    for (let di = 0; di < 7; di++) daySlots[di] = di === 5 ? [] : [{ start: "08:00", end: "11:20" }];
                                }

                                dates.forEach(d => {
                                    if (!d.inMonth) { assignments[t.email][d.dateStr] = { slots: [], off: true }; return; }
                                    if (holidays[d.isoDate]) { assignments[t.email][d.dateStr] = { slots: [], off: false, type: 'HOLIDAY' }; return; }
                                    if (typeof isLeaveDay === 'function' && isLeaveDay(t.email, d.dateStr, cycleMonth)) { assignments[t.email][d.dateStr] = { slots: [], off: false, type: 'LEAVE' }; return; }
                                    if (ptState.overrides[t.email] && ptState.overrides[t.email][d.dateStr]) {
                                        const ov = ptState.overrides[t.email][d.dateStr];
                                        if (Array.isArray(ov)) {
                                            assignments[t.email][d.dateStr] = { slots: ov, off: ov.length === 0 };
                                        } else {
                                            assignments[t.email][d.dateStr] = { slots: ov.slots || [], off: !!ov.off, type: ov.type || undefined };
                                        }
                                        return;
                                    }
                                    const dayOfWeek = d.date.getDay();
                                    const dayS = daySlots[dayOfWeek];
                                    if (dayS && dayS.length > 0) {
                                        assignments[t.email][d.dateStr] = { slots: dayS.map(s => ({ ...s })), off: false };
                                    } else {
                                        assignments[t.email][d.dateStr] = { slots: [], off: true };
                                    }
                                });
                            });

                            // Auto-assign floor per week based on FT roster occupancy
                            const weekFloorMap = {};
                            const ftData = (rosterState && rosterState.ft && (rosterState.ft.publishedData[cycleMonth] || rosterState.ft.draftData[cycleMonth])) || null;

                            function timeToMins(t) { const [h, m] = t.split(':').map(Number); return h * 60 + m; }

                            function countFTFloor(dateStr, slotStart, slotEnd) {
                                if (!ftData) return { f1: 0, f2: 0 };
                                let f1 = 0, f2 = 0;
                                const sMins = timeToMins(slotStart), eMins = timeToMins(slotEnd);
                                const overlapsMR = sMins < 940 && eMins > 480;
                                const overlapsAF = sMins < 1320 && eMins > 860;
                                ftData.therapists.forEach(ft => {
                                    const a = ftData.assignments[ft.email]?.[dateStr];
                                    if (!a || a === 'OFF' || a === 'LEAVE' || a === 'HOLIDAY') return;
                                    const isMR = a.includes('MR') || a === 'THU_1ST' || a === 'THU_2ND';
                                    const isAF = a.includes('AF');
                                    const is1ST = a.includes('1ST') || a === 'THU_1ST';
                                    if ((isMR && overlapsMR) || (isAF && overlapsAF)) {
                                        if (is1ST) f1++; else f2++;
                                    }
                                });
                                return { f1, f2 };
                            }

                            // Track assigned PT occupancy so the next PT therapist considers it
                            const ptOccupied = {}; // {weekKey: [{dateStr, start, end, floor}, ...]}

                            ptState.therapists.forEach(t => {
                                weekFloorMap[t.email] = {};
                                const weeks = {};
                                dates.forEach(d => {
                                    if (!d.inMonth) return;
                                    const cell = assignments[t.email]?.[d.dateStr];
                                    if (!cell || cell.off || cell.type || !cell.slots || cell.slots.length === 0) return;
                                    if (ptState.overrides[t.email]?.[d.dateStr] !== undefined) return;
                                    const dObj = d.date;
                                    const weekStart = new Date(dObj);
                                    weekStart.setDate(dObj.getDate() - dObj.getDay());
                                    const key = weekStart.toISOString().slice(0, 10);
                                    if (!weeks[key]) weeks[key] = { start: weekStart, days: [] };
                                    weeks[key].days.push(d);
                                });
                                Object.keys(weeks).forEach(key => {
                                    const w = weeks[key];
                                    let total1 = 0, total2 = 0;
                                    w.days.forEach(d => {
                                        const cell = assignments[t.email][d.dateStr];
                                        cell.slots.forEach(s => {
                                            // Count FT therapists on each floor during this slot
                                            const cnt = countFTFloor(d.dateStr, s.start, s.end);
                                            total1 += cnt.f1; total2 += cnt.f2;
                                            // Count previously-assigned PT therapists overlapping this slot
                                            (ptOccupied[key] || []).forEach(pa => {
                                                if (pa.dateStr !== d.dateStr) return;
                                                const sMins = timeToMins(s.start), eMins = timeToMins(s.end);
                                                const paStart = timeToMins(pa.start), paEnd = timeToMins(pa.end);
                                                if (sMins < paEnd && eMins > paStart) {
                                                    if (pa.floor === '1ST') total1++; else total2++;
                                                }
                                            });
                                        });
                                    });
                                    const floor = total1 <= total2 ? '1ST' : '2ND';
                                    weekFloorMap[t.email][w.start.toISOString().slice(0, 10)] = floor;
                                    // Record this PT therapist's slots for subsequent PT therapists
                                    w.days.forEach(d => {
                                        const cell = assignments[t.email][d.dateStr];
                                        if (cell.off || cell.type) return;
                                        cell.slots.forEach(s => {
                                            if (!ptOccupied[key]) ptOccupied[key] = [];
                                            ptOccupied[key].push({ dateStr: d.dateStr, start: s.start, end: s.end, floor: floor });
                                        });
                                    });
                                    // Apply floor to this PT therapist's slots
                                    w.days.forEach(d => {
                                        const cell = assignments[t.email][d.dateStr];
                                        if (cell.off || cell.type) return;
                                        cell.slots.forEach(s => { s.floor = floor; });
                                    });
                                });
                            });

                            // Floor fallback for override/manual cells that might have missing floors
                            ptState.therapists.forEach(t => {
                                dates.forEach(d => {
                                    const cell = assignments[t.email]?.[d.dateStr];
                                    if (!cell || cell.off || cell.type || !cell.slots) return;
                                    const weekStart = new Date(d.date);
                                    weekStart.setDate(d.date.getDate() - d.date.getDay());
                                    const wk = weekStart.toISOString().slice(0, 10);
                                    const wkFloor = weekFloorMap[t.email]?.[wk] || '1ST';
                                    cell.slots.forEach(s => { if (!s.floor) s.floor = wkFloor; });
                                });
                            });

                            const rosterData = {
                                cycle: cycleMonth,
                                version: ptState.currentVersion,
                                dates: dates,
                                therapists: ptState.therapists.map(t => ({ ...t })),
                                assignments: assignments,
                                _weekFloors: weekFloorMap
                            };
                            rosterData._config = {
                                daySlots: JSON.parse(JSON.stringify(ptState.daySlots)),
                                overrides: JSON.parse(JSON.stringify(ptState.overrides))
                            };
                            ptState.draftData[cycleMonth] = rosterData;
                            ptState.isPublished = false;
                            ptRenderGrid(rosterData);
                            ptPopulateVersionSelect();
                            const badge = document.getElementById('ptRosterStatusBadge');
                            if (badge) {
                                badge.style.display = 'inline-block';
                                badge.innerText = ptState.currentVersion;
                                badge.className = "badge badge-primary";
                            }
                            ptRenderSummary(rosterData);
                        }

                        // Version decision with modal (not native confirm)
                        if (currentVer && existingVersions.includes(currentVer) && ptState.isPublished) {
                            ptState.currentVersion = ptGetNextVersion();
                            ptExecGenerate();
                        } else if (currentVer && existingVersions.includes(currentVer)) {
                            const mount = document.getElementById('systemGlobalModalMount');
                            mount.innerHTML = `
            <div class="system-inline-modal-overlay">
                <div class="system-inline-modal-box" style="width: 360px; text-align: center;">
                    <h3 style="margin-bottom: 12px;">Version Conflict</h3>
                    <p style="margin-bottom: 8px; font-size: 11px; color: var(--text-body);">A draft version (<strong>${currentVer}</strong>) already exists for this cycle.</p>
                    <p style="margin-bottom: 16px; font-size: 11px; color: var(--text-muted);">Save as new version or overwrite current?</p>
                    <div style="display: flex; justify-content: center; gap: 8px;">
                        <button class="action-btn" style="background: var(--danger);" onclick="closeSystemModalBox(); ptState.currentVersion = '${currentVer}'; ptExecGenerate();">Overwrite</button>
                        <button class="action-btn" style="background: var(--primary);" onclick="closeSystemModalBox(); ptState.currentVersion = '${ptGetNextVersion()}'; ptExecGenerate();">Save as New</button>
                    </div>
                </div>
            </div>
        `;
                        } else {
                            ptState.currentVersion = ptGetNextVersion();
                            ptExecGenerate();
                        }
                    }

                    function ptRenderGrid(rosterData) {
                        const header = document.getElementById('ptRosterGridHeader');
                        const body = document.getElementById('ptRosterGridBody');
                        if (!header || !body) return;
                        if (!rosterData || !rosterData.dates || !rosterData.therapists) {
                            header.innerHTML = '';
                            body.innerHTML = '<tr><td colspan="10" style="padding:30px;text-align:center;color:var(--text-muted);">No roster data. Add therapists and generate a roster.</td></tr>';
                            return;
                        }

                        const dates = rosterData.dates;
                        const therapists = rosterData.therapists;
                        const assignments = rosterData.assignments || {};

                        // Header
                        let headerHtml = '<tr><th class="sticky-col" style="text-align:left;padding:8px 10px;background:var(--bg-card);border-bottom:2px solid var(--primary);font-size:11px;font-weight:700;position:sticky;top:0;z-index:3;min-width:80px;">DATE</th>';
                        headerHtml += '<th class="sticky-col" style="text-align:center;padding:8px 6px;background:var(--bg-card);border-bottom:2px solid var(--primary);font-size:11px;font-weight:700;position:sticky;top:0;z-index:3;min-width:50px;">DAY</th>';
                        therapists.forEach(t => {
                            const bg = t.color + '22';
                            headerHtml += `<th style="padding:8px 6px;background:${bg};border-bottom:2px solid var(--primary);font-size:11px;font-weight:700;text-align:center;min-width:120px;position:sticky;top:0;z-index:2;"><span style="display:block;">${t.name}</span></th>`;
                        });
                        headerHtml += '</tr>';
                        header.innerHTML = headerHtml;

                        // Body
                        let bodyHtml = '';
                        dates.forEach(d => {
                            const rowBg = !d.inMonth ? 'opacity:0.5;' : (d.dayName === 'FRI' ? 'background:#fafafa;' : '');
                            bodyHtml += `<tr style="${rowBg}border-bottom:1px solid var(--border);">`;
                            bodyHtml += `<td class="sticky-col" style="text-align:left;padding:6px 10px;font-size:11px;font-weight:600;color:var(--text-heading);background:var(--bg-card);position:sticky;left:0;z-index:1;border-right:1px solid var(--border);white-space:nowrap;">${d.dateStr}</td>`;
                            bodyHtml += `<td style="text-align:center;padding:6px 6px;font-size:10px;font-weight:600;color:var(--text-muted);background:var(--bg-card);border-right:1px solid var(--border);">${d.dayName}</td>`;

                            therapists.forEach(t => {
                                const assign = assignments[t.email] ? assignments[t.email][d.dateStr] : null;
                                if (!assign || !d.inMonth) {
                                    bodyHtml += `<td style="padding:6px;text-align:center;font-size:10px;color:var(--text-muted);"></td>`;
                                } else if (assign.type === 'LEAVE') {
                                    const c = PT_COLORS.LEAVE;
                                    bodyHtml += `<td style="padding:6px;text-align:center;background:${c.color};border:1px solid ${c.borderColor};border-radius:4px;font-size:10px;font-weight:700;color:${c.textColor};cursor:pointer;" onclick="ptCycleCell('${t.email}','${d.dateStr}')">On Leave</td>`;
                                } else if (assign.type === 'HOLIDAY') {
                                    const c = PT_COLORS.HOLIDAY;
                                    bodyHtml += `<td style="padding:6px;text-align:center;background:${c.color};border:1px solid ${c.borderColor};border-radius:4px;font-size:10px;font-weight:700;color:${c.textColor};cursor:pointer;" onclick="ptCycleCell('${t.email}','${d.dateStr}')">HOLIDAY</td>`;
                                } else if (assign.off || !assign.slots || assign.slots.length === 0) {
                                    const c = PT_COLORS.OFF;
                                    bodyHtml += `<td style="padding:6px;text-align:center;background:${c.color};border:1px solid ${c.borderColor};border-radius:4px;font-size:10px;font-weight:700;color:${c.textColor};cursor:pointer;" onclick="ptCycleCell('${t.email}','${d.dateStr}')">OFF</td>`;
                                } else {
                                    let cellHtml = '';
                                    assign.slots.forEach(s => {
                                        const c = PT_COLORS[s.floor] || PT_COLORS["1ST"];
                                        const floorLabel = s.floor === '1ST' ? '1st' : '2nd';
                                        cellHtml += `<div style="background:${c.color};border:1px solid ${c.borderColor};border-radius:3px;padding:3px 5px;margin-bottom:1px;font-size:10px;font-weight:600;text-align:center;color:${c.textColor};">${floorLabel}(${s.start}-${s.end})</div>`;
                                    });
                                    bodyHtml += `<td style="padding:3px;cursor:pointer;" onclick="ptCycleCell('${t.email}','${d.dateStr}')">${cellHtml}</td>`;
                                }
                            });

                            bodyHtml += '</tr>';
                        });
                        body.innerHTML = bodyHtml;
                    }

                    function ptCycleCell(email, dateStr) {
                        ptPickerSelectedOpt = null;
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (!data || !data.assignments || !data.assignments[email] || !data.assignments[email][dateStr]) return;

                        const daySlots = ptState.daySlots[email] || {};
                        const dd = parseInt(dateStr.split('-')[0], 10);
                        const mmStr = dateStr.split('-')[1];
                        const mm = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].indexOf(mmStr);
                        const yy = parseInt(dateStr.split('-')[2], 10) + 2000;
                        const dObj = new Date(yy, mm, dd);
                        const dayOfWeek = dObj.getDay();
                        const weekStart = new Date(dObj);
                        weekStart.setDate(dObj.getDate() - dObj.getDay());
                        const weekKey = weekStart.toISOString().slice(0, 10);
                        const weekFloor = (data._weekFloors?.[email]?.[weekKey]) || '1ST';

                        const cell = data.assignments[email][dateStr];
                        const currentFloor = (!cell.off && cell.slots && cell.slots.length > 0) ? (cell.slots[0].floor || '1ST') : null;
                        const is1ST = !cell.off && !cell.type && currentFloor === '1ST';
                        const is2ND = !cell.off && !cell.type && currentFloor === '2ND';
                        const isOFF = !!(cell.off);
                        const isLEAVE = cell.type === 'LEAVE';
                        const isHOLIDAY = cell.type === 'HOLIDAY';

                        // Build slot time input rows based on current cell slots or daySlots
                        const activeSlots = (!cell.off && !cell.type && cell.slots && cell.slots.length > 0)
                            ? cell.slots
                            : (daySlots[dayOfWeek] || [{ start: "08:00", end: "11:20" }]);
                        let slotRows = '';
                        activeSlots.forEach((s, i) => {
                            slotRows += `<div style="display:flex;gap:3px;align-items:center;margin-bottom:2px;">
            <input type="time" id="ptPickerStart_${i}" value="${s.start}" style="width:72px;padding:2px 3px;border:1px solid var(--border);border-radius:2px;font-size:10px;background:var(--bg-main);color:var(--text-body);">
            <span style="font-size:8px;color:var(--text-muted);">→</span>
            <input type="time" id="ptPickerEnd_${i}" value="${s.end}" style="width:72px;padding:2px 3px;border:1px solid var(--border);border-radius:2px;font-size:10px;background:var(--bg-main);color:var(--text-body);">
        </div>`;
                        });

                        function optBtn(opt, label, color, borderColor, isSel) {
                            const sel = isSel ? 'outline:2px solid #000;outline-offset:1px;' : 'outline:none;';
                            return `<button class="action-btn pt-pick-opt" data-opt="${opt}" onclick="ptSelectPickerOpt('${opt}')" style="flex:1;padding:5px 4px;font-size:9px;font-weight:700;background:${color};border:1px solid ${borderColor};border-radius:3px;color:var(--text-heading);cursor:pointer;${sel}text-align:center;">${label}</button>`;
                        }

                        ptState._pickerCtx = { email, dateStr, data, dayOfWeek, weekFloor, cycleMonth };
                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `<div class="system-inline-modal-overlay">
        <div class="system-inline-modal-box" style="width:260px;">
            <div style="padding:10px;">
                <div style="font-size:9px;color:var(--text-muted);margin-bottom:6px;">${dateStr} — ${email.split('@')[0]}</div>
                <div style="margin-bottom:6px;">
                    <div style="font-size:8px;font-weight:600;color:var(--text-muted);margin-bottom:2px;">Times for this day:</div>
                    ${slotRows}
                </div>
                <div style="display:flex;gap:3px;margin-bottom:4px;">
                    ${optBtn('1ST', '1ST', '#dbeafe', '#93c5fd', is1ST)}
                    ${optBtn('2ND', '2ND', '#d1fae5', '#34d399', is2ND)}
                    ${optBtn('OFF', 'OFF', '#e5e7eb', '#9ca3af', isOFF)}
                    ${optBtn('LEAVE', 'Leave', '#fecaca', '#f87171', isLEAVE)}
                    ${optBtn('HOLIDAY', 'Holiday', '#fed7aa', '#fb923c', isHOLIDAY)}
                </div>
                <div style="display:flex;gap:6px;justify-content:flex-end;margin-top:6px;">
                    <button class="action-btn" onclick="closeSystemModalBox()" style="padding:5px 12px;font-size:10px;background:var(--text-muted);">Cancel</button>
                    <button class="action-btn" onclick="ptApplyCellChanges()" style="padding:5px 12px;font-size:10px;background:var(--primary);">Apply</button>
                </div>
            </div>
        </div>
    </div>`;
                    }

                    let ptPickerSelectedOpt = null;

                    function ptSelectPickerOpt(opt) {
                        ptPickerSelectedOpt = opt;
                        document.querySelectorAll('.pt-pick-opt').forEach(b => {
                            b.style.outline = b.dataset.opt === opt ? '2px solid #000' : 'none';
                            b.style.outlineOffset = b.dataset.opt === opt ? '1px' : '0';
                        });
                    }

                    function ptApplyCellChanges() {
                        const ctx = ptState._pickerCtx;
                        if (!ctx) { closeSystemModalBox(); return; }

                        // Read time values BEFORE destroying the modal
                        const inputCount = document.querySelectorAll('[id^="ptPickerStart_"]').length;
                        const rawTimes = [];
                        for (let i = 0; i < inputCount; i++) {
                            const st = document.getElementById('ptPickerStart_' + i);
                            const en = document.getElementById('ptPickerEnd_' + i);
                            if (st && en && st.value && en.value) rawTimes.push({ start: st.value, end: en.value });
                            else rawTimes.push(null);
                        }
                        const opt = ptPickerSelectedOpt;

                        closeSystemModalBox();
                        const { email, dateStr, data, dayOfWeek, weekFloor } = ctx;
                        const cell = data.assignments[email][dateStr];
                        if (!cell) return;

                        const daySlots = ptState.daySlots[email] || {};
                        const defaultSlots = (daySlots[dayOfWeek] || [{ start: "08:00", end: "11:20" }]).map(s => ({ ...s, floor: weekFloor }));

                        // Build edited slots from saved raw times
                        const editedSlots = [];
                        rawTimes.forEach((t, i) => {
                            if (t) {
                                const src = defaultSlots[i] || defaultSlots[0] || { floor: '1ST' };
                                editedSlots.push({ start: t.start, end: t.end, floor: src.floor || weekFloor });
                            }
                        });

                        if (opt === '1ST' || opt === '2ND') {
                            // Apply the selected floor to the edited slots
                            cell.slots = editedSlots.map(s => ({ ...s, floor: opt }));
                            cell.off = false;
                            delete cell.type;
                        } else if (opt === 'OFF') {
                            cell.slots = [];
                            cell.off = true;
                            delete cell.type;
                        } else if (opt === 'LEAVE') {
                            cell.slots = [];
                            cell.off = false;
                            cell.type = 'LEAVE';
                        } else if (opt === 'HOLIDAY') {
                            cell.slots = [];
                            cell.off = false;
                            cell.type = 'HOLIDAY';
                        } else {
                            // No floor/status selected → just save the time edits as override
                            if (editedSlots.length > 0) {
                                cell.slots = editedSlots;
                                cell.off = false;
                                delete cell.type;
                            } else {
                                closeSystemModalBox();
                                return;
                            }
                        }

                        if (!ptState.overrides[email]) ptState.overrides[email] = {};
                        ptState.overrides[email][dateStr] = {
                            slots: cell.slots.map(s => ({ ...s })),
                            off: !!cell.off,
                            type: cell.type || undefined
                        };
                        ptSaveConfig();
                        ptRenderGrid(data);
                        ptPickerSelectedOpt = null;
                        const badge = document.getElementById('ptRosterStatusBadge');
                        if (badge) {
                            badge.style.display = 'inline-block';
                            badge.innerText = (ptState.currentVersion || 'DRAFT') + ' (modified)';
                            badge.className = "badge badge-warning";
                        }
                    }

                    function ptRenderSummary(rosterData) {
                        const el = document.getElementById('ptRosterSummaryContent');
                        if (!el) return;
                        if (!rosterData || !rosterData.therapists || !rosterData.dates) {
                            el.innerHTML = '<span style="color:var(--text-muted);font-style:italic;">No roster data yet. Add therapists and generate a roster.</span>';
                            return;
                        }
                        const activeDates = rosterData.dates.filter(d => d.inMonth);
                        const totalDays = activeDates.length;
                        let html = `<div style="font-size:10px;color:var(--text-body);"><strong>${rosterData.therapists.length}</strong> therapist(s) · <strong>${totalDays}</strong> days</div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">`;
                        rosterData.therapists.forEach(t => {
                            const assign = rosterData.assignments[t.email] || {};
                            let floor1Days = 0, floor2Days = 0, offCount = 0;
                            activeDates.forEach(d => {
                                const cell = assign[d.dateStr];
                                if (!cell) return;
                                if (cell.type === 'LEAVE' || cell.type === 'HOLIDAY') offCount++;
                                else if (cell.off || !cell.slots || cell.slots.length === 0) offCount++;
                                else {
                                    cell.slots.forEach(s => {
                                        if (s.floor === '1ST') floor1Days++;
                                        else if (s.floor === '2ND') floor2Days++;
                                    });
                                }
                            });
                            html += `<div style="border:1px solid var(--border);border-radius:4px;padding:4px 8px;font-size:9px;background:var(--bg-card);">
            <strong>${t.name.split(' ')[0]}</strong>: 1st=${floor1Days} 2nd=${floor2Days} OFF=${offCount}d
        </div>`;
                        });
                        html += '</div>';
                        el.innerHTML = html;
                    }

                    function ptClearGrid() {
                        document.getElementById('ptRosterGridHeader').innerHTML = '';
                        document.getElementById('ptRosterGridBody').innerHTML = '';
                        document.getElementById('ptRosterSummaryContent').innerHTML = '<span style="color:var(--text-muted);font-style:italic;">No roster data yet. Add therapists and generate a roster.</span>';
                    }

                    // ---- Version Management ----

                    function ptGetVersions(cycleMonth) {
                        try {
                            const list = localStorage.getItem('ptRosterVersionList_' + (cycleMonth || ptState.cycle));
                            return list ? JSON.parse(list) : [];
                        } catch (e) { return []; }
                    }

                    function ptSaveVersionList(cycleMonth, versions) {
                        try { localStorage.setItem('ptRosterVersionList_' + (cycleMonth || ptState.cycle), JSON.stringify(versions)); } catch (e) { }
                    }

                    function ptGetPublishedVersions(cycleMonth) {
                        try {
                            const list = localStorage.getItem('ptRosterPublishedVersionList_' + (cycleMonth || ptState.cycle));
                            return list ? JSON.parse(list) : [];
                        } catch (e) { return []; }
                    }

                    function ptSavePublishedVersionList(cycleMonth, versions) {
                        try { localStorage.setItem('ptRosterPublishedVersionList_' + (cycleMonth || ptState.cycle), JSON.stringify(versions)); } catch (e) { }
                    }

                    function ptPopulateVersionSelect() {
                        const sel = document.getElementById('ptRosterVersionSelect');
                        const label = document.getElementById('ptRosterVersionLabel');
                        if (!sel) return;
                        const versions = ptGetVersions(ptState.cycle);
                        const pubVersions = ptGetPublishedVersions(ptState.cycle);
                        const all = [...new Set([...versions, ...pubVersions])];
                        if (all.length === 0) {
                            sel.style.display = 'none';
                            if (label) label.style.display = 'none';
                            return;
                        }
                        sel.style.display = 'inline-block';
                        if (label) label.style.display = 'inline';
                        sel.innerHTML = '';
                        all.forEach(v => {
                            const opt = document.createElement('option');
                            opt.value = v;
                            opt.textContent = v + (pubVersions.includes(v) ? ' (PUBLISHED)' : '');
                            sel.appendChild(opt);
                        });
                        if (ptState.currentVersion && all.includes(ptState.currentVersion)) {
                            sel.value = ptState.currentVersion;
                        } else {
                            sel.value = all[all.length - 1];
                        }
                    }

                    function ptTryLoadDraft(cycleMonth) {
                        const versions = ptGetVersions(cycleMonth);
                        if (versions.length > 0) {
                            ptLoadVersion(versions[versions.length - 1]);
                        } else {
                            const pubVersions = ptGetPublishedVersions(cycleMonth);
                            if (pubVersions.length > 0) {
                                ptLoadVersion(pubVersions[pubVersions.length - 1]);
                            } else {
                                ptClearGrid();
                                const badge = document.getElementById('ptRosterStatusBadge');
                                if (badge) {
                                    badge.innerText = "";
                                    badge.className = "badge badge-dark";
                                    badge.style.display = "none";
                                }
                            }
                        }
                    }

                    function ptLoadVersion(version) {
                        if (!version) return;
                        const cycleMonth = ptState.cycle;
                        try {
                            // Try draft first, then published
                            let saved = localStorage.getItem('ptRosterDraft_' + cycleMonth + '_' + version);
                            let isPub = false;
                            if (!saved) {
                                saved = localStorage.getItem('ptRosterPublished_' + cycleMonth + '_' + version);
                                isPub = true;
                            }
                            if (saved) {
                                const data = JSON.parse(saved);
                                if (data.dates) data.dates.forEach(d => { d.date = new Date(d.date); });
                                ptState.draftData[cycleMonth] = data;
                                ptState.currentVersion = version;
                                ptState.isPublished = isPub;
                                ptRenderGrid(data);
                                ptRenderSummary(data);
                                const badge = document.getElementById('ptRosterStatusBadge');
                                if (badge) {
                                    badge.style.display = 'inline-block';
                                    badge.innerText = version + (isPub ? ' (PUBLISHED)' : '');
                                    badge.className = isPub ? "badge badge-success" : "badge badge-warning";
                                }
                                // Restore config
                                if (data.therapists) {
                                    ptState.therapists = data.therapists.map(t => ({ ...t }));
                                    ptState.daySlots = {};
                                    ptState.overrides = {};
                                    if (data._config) {
                                        ptState.daySlots = data._config.daySlots || {};
                                        ptState.overrides = data._config.overrides || {};
                                    }
                                    ptRenderConfig();
                                }
                            } else {
                                customAlert('Version ' + version + ' not found for ' + cycleMonth);
                            }
                        } catch (e) {
                            console.warn('ptLoadVersion error:', e);
                            customAlert('Error loading version.');
                        }
                    }

                    // ---- Save / Clear / Publish ----

                    function ptSaveDraft() {
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (!data || !data.dates) {
                            customAlert("No roster data to save. Generate a roster first.");
                            return;
                        }

                        let versions = ptGetVersions(cycleMonth);
                        let version = ptState.currentVersion;
                        const pubVersions = ptGetPublishedVersions(cycleMonth);

                        if (!version || pubVersions.includes(version)) {
                            const maxNum = versions.reduce((max, v) => {
                                const num = parseInt(v.replace('R', ''), 10);
                                return isNaN(num) ? max : Math.max(max, num);
                            }, 0);
                            version = 'R' + (maxNum + 1);
                            ptState.currentVersion = version;
                        }

                        data.version = version;
                        try {
                            localStorage.setItem('ptRosterDraft_' + cycleMonth + '_' + version, JSON.stringify(data));
                        } catch (e) {
                            customAlert("Failed to save. Storage may be full.");
                            return;
                        }

                        if (!versions.includes(version)) {
                            versions.push(version);
                            ptSaveVersionList(cycleMonth, versions);
                        }

                        ptPopulateVersionSelect();
                        ptState.isPublished = false;
                        document.getElementById('ptRosterStatusBadge').innerText = version;
                        document.getElementById('ptRosterStatusBadge').className = "badge badge-primary";
                        customAlert('Part-Time roster saved as ' + version + '.');
                    }

                    function ptClearDraft() {
                        const cycleMonth = ptState.cycle;
                        if (ptState.draftData[cycleMonth]) {
                            delete ptState.draftData[cycleMonth];
                        }
                        ptClearGrid();
                        const badge = document.getElementById('ptRosterStatusBadge');
                        if (badge) {
                            badge.innerText = "";
                            badge.className = "badge badge-dark";
                            badge.style.display = "none";
                        }
                        customAlert("Part-Time roster draft cleared.");
                    }

                    function ptPublishRoster() {
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (!data || !data.dates) {
                            customAlert("No roster draft to publish. Generate and save a draft first.");
                            return;
                        }

                        customConfirm("Publish this roster to all therapists? They will see their individual schedules. After publishing, any edit will create a new version.", () => {
                            ptState.isPublished = true;
                            ptState.publishedData[cycleMonth] = JSON.parse(JSON.stringify(data));
                            let version = ptState.currentVersion || 'PUBLISHED';
                            try {
                                const pubVersions = ptGetPublishedVersions(cycleMonth);
                                // If this version is already published, auto-increment so therapists see a new version
                                if (version !== 'PUBLISHED' && pubVersions.includes(version)) {
                                    const allVers = ptGetVersions(cycleMonth);
                                    const maxNum = allVers.reduce((max, v) => {
                                        const num = parseInt(v.replace('R', ''), 10);
                                        return isNaN(num) ? max : Math.max(max, num);
                                    }, 0);
                                    version = 'R' + (maxNum + 1);
                                    ptState.currentVersion = version;
                                    // Re-save draft under the new version
                                    const freshData = JSON.parse(JSON.stringify(data));
                                    freshData.version = version;
                                    ptSaveVersionList(cycleMonth, [...allVers, version]);
                                    localStorage.setItem('ptRosterDraft_' + cycleMonth + '_' + version, JSON.stringify(freshData));
                                }
                                localStorage.setItem('ptRosterPublished_' + cycleMonth + '_' + version, JSON.stringify(ptState.publishedData[cycleMonth]));
                                if (!pubVersions.includes(version)) {
                                    pubVersions.push(version);
                                    ptSavePublishedVersionList(cycleMonth, pubVersions);
                                }
                            } catch (e) { }

                            const badge = document.getElementById('ptRosterStatusBadge');
                            if (badge) {
                                badge.style.display = 'inline-block';
                                badge.innerText = version + ' (PUBLISHED)';
                                badge.className = "badge badge-success";
                            }
                            ptPopulateVersionSelect();
                            customAlert('Part-Time roster published successfully!');
                        });
                    }

                    // ---- Cycle / Range Change ----

                    function ptOnCycleChange() {
                        ptState.cycle = document.getElementById('ptRosterCycleMonth').value;
                        // Clear and reload
                        ptState.therapists = [];
                        ptState.daySlots = {};
                        ptState.overrides = {};
                        ptState.currentVersion = null;
                        ptState.isPublished = false;
                        ptClearGrid();
                        ptInit();
                    }

                    function ptOnRangeChange() {
                        const from = document.getElementById('ptRosterDateFrom')?.value;
                        const to = document.getElementById('ptRosterDateTo')?.value;
                        if (from && to && from > to) {
                            customAlert("Start date cannot be after end date.");
                            return;
                        }
                        // Refresh the grid if data exists
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (data && data.dates) {
                            ptGenerateRoster();
                        }
                    }

                    // ---- Color Management ----

                    function ptUpdateColor(key, value) {
                        if (PT_COLORS[key]) {
                            PT_COLORS[key].color = value;
                            // Update border/text colors based on luminance
                            PT_COLORS[key].borderColor = value;
                            PT_COLORS[key].textColor = '#1e293b';
                            // Update preview
                            const preview = document.getElementById('ptColorPreview_' + key);
                            if (preview) preview.style.background = value;
                            // Re-render grid if data exists
                            const cycleMonth = ptState.cycle;
                            const data = ptState.draftData[cycleMonth];
                            if (data) ptRenderGrid(data);
                        }
                    }

                    function ptSaveColors() {
                        try {
                            localStorage.setItem('ptRosterColors', JSON.stringify(PT_COLORS));
                        } catch (e) { }
                        customAlert("Colors saved!");
                    }

                    function ptResetColors() {
                        const defaults = {
                            "1ST": { color: "#dbeafe", borderColor: "#93c5fd", textColor: "#1e40af", label: "1st Floor" },
                            "2ND": { color: "#d1fae5", borderColor: "#34d399", textColor: "#065f46", label: "2nd Floor" },
                            "OFF": { color: "#e5e7eb", borderColor: "#9ca3af", textColor: "#4b5563", label: "Off Day" },
                            "LEAVE": { color: "#fecaca", borderColor: "#f87171", textColor: "#991b1b", label: "On Leave" },
                            "HOLIDAY": { color: "#fed7aa", borderColor: "#fb923c", textColor: "#9a3412", label: "Public Holiday" }
                        };
                        Object.keys(defaults).forEach(k => {
                            Object.assign(PT_COLORS[k], defaults[k]);
                            const preview = document.getElementById('ptColorPreview_' + k);
                            if (preview) preview.style.background = defaults[k].color;
                            const picker = preview?.nextElementSibling?.querySelector?.('input[type=color]');
                            if (picker) picker.value = defaults[k].color;
                        });
                        try { localStorage.removeItem('ptRosterColors'); } catch (e) { }
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (data) ptRenderGrid(data);
                        customAlert("Colors reset to defaults.");
                    }

                    // ---- Export ----

                    function ptExportPDF() {
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (!data) {
                            customAlert("No roster to export. Generate a roster first.");
                            return;
                        }
                        const ptCol = PT_COLORS;
                        const ptStyle = function(key) {
                            const c = ptCol[key];
                            return 'background:' + c.color + ';border:1px solid ' + c.borderColor + ';color:' + c.textColor + ';border-radius:3px;padding:1px 4px;font-size:9px;font-weight:600;';
                        };
                        let tableHtml = '<table style="width:100%;border-collapse:collapse;font-size:10px;font-family:Arial,sans-serif;">';
                        tableHtml += '<thead><tr style="background:#f1f5f9;">';
                        tableHtml += '<th style="padding:6px 8px;border:1px solid #ccc;text-align:left;">DATE</th>';
                        tableHtml += '<th style="padding:6px 4px;border:1px solid #ccc;text-align:center;">DAY</th>';
                        data.therapists.forEach(t => {
                            tableHtml += `<th style="padding:6px 4px;border:1px solid #ccc;text-align:center;background:${t.color}22;">${t.name}</th>`;
                        });
                        tableHtml += '</tr></thead><tbody>';
                        data.dates.forEach(d => {
                            if (!d.inMonth) return;
                            tableHtml += '<tr>';
                            tableHtml += `<td style="padding:4px 8px;border:1px solid #ccc;font-weight:600;">${d.dateStr}</td>`;
                            tableHtml += `<td style="padding:4px 4px;border:1px solid #ccc;text-align:center;">${d.dayName}</td>`;
                            data.therapists.forEach(t => {
                                const assign = data.assignments[t.email]?.[d.dateStr];
                                tableHtml += '<td style="padding:2px 4px;border:1px solid #ccc;text-align:center;">';
                                if (!assign) { tableHtml += ''; }
                                else if (assign.type === 'LEAVE') { tableHtml += '<span style="' + ptStyle('LEAVE') + '">On Leave</span>'; }
                                else if (assign.type === 'HOLIDAY') { tableHtml += '<span style="' + ptStyle('HOLIDAY') + '">HOLIDAY</span>'; }
                                else if (assign.off || !assign.slots || assign.slots.length === 0) { tableHtml += '<span style="' + ptStyle('OFF') + '">OFF</span>'; }
                                else {
                                    assign.slots.forEach(s => {
                                        const floorStyle = s.floor === '1ST' ? ptStyle('1ST') : ptStyle('2ND');
                                        tableHtml += '<span style="display:inline-block;margin:1px;' + floorStyle + '">' + (s.floor === '1ST' ? '1st' : '2nd') + '(' + s.start + '-' + s.end + ')</span>';
                                    });
                                }
                                tableHtml += '</td>';
                            });
                            tableHtml += '</tr>';
                        });
                        tableHtml += '</tbody></table>';

                        openPrintablePDFWindow('Part-Time Roster - ' + cycleMonth, '<span><strong>Version:</strong> ' + (data.version || '') + '</span>', tableHtml);
                    }

                    function ptExportExcel() {
                        const cycleMonth = ptState.cycle;
                        const data = ptState.draftData[cycleMonth];
                        if (!data) {
                            customAlert("No roster to export.");
                            return;
                        }
                        let csv = 'DATE,DAY';
                        data.therapists.forEach(t => { csv += ',' + t.name; });
                        csv += '\n';
                        data.dates.forEach(d => {
                            if (!d.inMonth) return;
                            csv += d.dateStr + ',' + d.dayName;
                            data.therapists.forEach(t => {
                                const assign = data.assignments[t.email]?.[d.dateStr];
                                let val = '';
                                if (!assign) val = '';
                                else if (assign.type === 'LEAVE') val = 'On Leave';
                                else if (assign.type === 'HOLIDAY') val = 'HOLIDAY';
                                else if (assign.off || !assign.slots || assign.slots.length === 0) val = 'OFF';
                                else {
                                    val = assign.slots.map(s => `${s.floor === '1ST' ? '1st' : '2nd'}(${s.start}-${s.end})`).join(' | ');
                                }
                                csv += ',"' + val + '"';
                            });
                            csv += '\n';
                        });
                        downloadCSVAsXlsx('PartTime_Roster_' + cycleMonth + '.csv', csv);
                    }

