                    let isScanningTranslation = false; // Global lock variable

                    function initializeTranslationObserver() {
                        const observer = new MutationObserver((mutationsList) => {
                            if (isScanningTranslation) return; // Prevent triggering recursively

                            let shouldScan = false;
                            for (const mutation of mutationsList) {
                                if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
                                    for (const node of mutation.addedNodes) {
                                        if (node.nodeType === Node.ELEMENT_NODE) {
                                            if (
                                                node.closest('#fullscreenDictionaryGridAnchor') ||
                                                node.closest('#systemGlobalModalMount')
                                            ) {
                                                continue;
                                            }
                                            shouldScan = true;
                                            break;
                                        }
                                    }
                                }
                                if (shouldScan) break;
                            }

                            if (shouldScan) {
                                isScanningTranslation = true;
                                observer.disconnect();
                                autoScanAndRegisterAllLayoutElements();
                                observer.observe(document.body, { childList: true, subtree: true });
                                isScanningTranslation = false;
                            }
                        });

                        observer.observe(document.body, { childList: true, subtree: true });
                    }


                    function isExcludedFromDictionary(key) {
                        if (!key) return true;
                        const trimmed = key.trim();

                        // 1. Check if the string is a raw number (e.g., "12", "30", "1.5")
                        if (/^\d+(\.\d+)?$/.test(trimmed)) return true;

                        // 2. Check if it matches month + year (e.g., "Mar 2028", "January 2025")
                        const monthYearRegex = /^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]* \d{4}$/i;
                        if (monthYearRegex.test(trimmed)) return true;

                        // 3. Check if it matches a numeric date format (e.g., "2026-05-21", "05/21/2026", "21/05/2026")
                        const numericDateRegex = /^(\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4})/;
                        if (numericDateRegex.test(trimmed)) return true;

                        return false;
                    }
                    function lookupTranslationValue(key) {
                        if (key && systemTextDictionary[key] === undefined) {
                            // Skip adding dates or numbers to the dictionary object
                            if (!isExcludedFromDictionary(key)) {
                                systemTextDictionary[key] = key;
                            }
                        }
                        return systemTextDictionary[key] || key;
                    }
                    window.executeSimulatedAuthenticationChallenge = function () {
                        const btn = document.getElementById('lbl_auth_btn_l');
                        if (btn) {
                            btn.disabled = true;
                            btn.innerHTML = '<span class="spinner"></span> Authenticating...';
                        }
                        setTimeout(function () {
                            const emailInput = document.getElementById('authFieldUserEmail');
                            const passInput = document.getElementById('authFieldUserPassword');
                            const email = emailInput ? emailInput.value.trim() : '';
                            const pass = passInput ? passInput.value.trim() : '';

                            // If no staff exist, auto-create admin from login form
                            if (globalRosterRepository.length === 0 && email && pass) {
                                const name = email.split('@')[0].replace(/[._-]/g, ' ');
                                const newAdmin = {
                                    name: name, username: email.split('@')[0], email: email,
                                    position: "Admin", department: "Administration Hub", dob: "", idCard: "",
                                    avatar: name.charAt(0).toUpperCase(), idCardExpiry: "", healthLicence: "",
                                    healthLicenceExpiry: "", password: pass, phone: "", emergencyContact: "",
                                    style: "Full-Time", visaExpiry: "", passportExpiry: "", hireDate: "",
                                    accentColor: "#004b87", sickBalance: 30, annualBalance: 30, familyBalance: 15,
                                    photoUrl: "", extraFieldsData: {}, active: true,
                                    joiningDate: new Date().toISOString().slice(0, 10),
                                    contractExpiryDate: "", lastDayOfWorking: ""
                                };
                                globalRosterRepository.push(newAdmin);
                            }

                            // Validate credentials against the roster
                            const matchedUser = globalRosterRepository.find(u => u.email === email);
                            if (matchedUser && matchedUser.password === pass) {
                                initializeAuthenticatedSessionContext(matchedUser);
                            } else if (matchedUser) {
                                if (btn) { btn.disabled = false; btn.innerHTML = 'Login'; }
                                customAlert("Invalid password. Please try again.");
                            } else {
                                if (btn) { btn.disabled = false; btn.innerHTML = 'Login'; }
                                customAlert("No account found with that email.");
                            }
                        }, 50);
                    };

