                    function toggleGlobalThemeSystem() {
                        globalSystemThemeMode = (globalSystemThemeMode === 'light') ? 'dark' : 'light';
                        document.documentElement.setAttribute('data-theme', globalSystemThemeMode);
                    }

                    // Helper: returns the currently visible login form area (split or compact)
                    function getActiveAuthFormArea() {
                        const splitVisible = !document.getElementById('authContainerSplit').classList.contains('hidden');
                        return document.getElementById(splitVisible ? 'authDynamicFormAreaSplit' : 'authDynamicFormArea');
                    }

                    function renderForgotPasswordFormStepOne() {
                        const formArea = getActiveAuthFormArea();
                        formArea.innerHTML = `
                <h3 style="margin-bottom:6px;">🔐 Phase 1: Security Recovery Stream</h3>
                <p style="color:var(--text-muted); margin-bottom:12px; font-size:10px;">Enter your verified corporate account email route to receive authentication recovery vectors.</p>
                <div class="form-group">
                    <label>Verified Clinical Email</label>
                    <input type="email" id="recoveryEmailField" placeholder="email@domain.com">
                </div>
                <button class="action-btn" style="width:100%; justify-content:center; margin-bottom:8px;" onclick="executeRecoveryStepOneSubmit()">Generate Code Sequence</button>
                <button class="action-btn" style="width:100%; justify-content:center; background:var(--text-muted);" onclick="renderAuthViewLayoutBox()">${lookupTranslationValue("Back to Sign In")}</button>
            `;
                    }

                    function executeRecoveryStepOneSubmit() {
                        const email = document.getElementById('recoveryEmailField').value.trim();
                        if (!email) { customAlert("Please provide valid verified criteria."); return; }
                        customAlert(`Secured 6-Digit authorization OTP code dispatched to clinic route: ${email}. Simulation Code: 889912`);
                        renderForgotPasswordFormStepTwo(email);
                    }

                    function renderForgotPasswordFormStepTwo(targetEmailAddress) {
                        const formArea = getActiveAuthFormArea();
                        formArea.innerHTML = `
                <h3 style="margin-bottom:6px;">🔐 Phase 2: Enter Verification Key Code</h3>
                <p style="color:var(--text-muted); margin-bottom:12px; font-size:10px;">Input the 6-Digit token sent to: <strong>${targetEmailAddress}</strong></p>
                <div class="form-group">
                    <label>6-Digit Verification Token</label>
                    <input type="text" id="recoveryOtpField" placeholder="889912" maxlength="6">
                </div>
                <button class="action-btn" style="width:100%; justify-content:center; margin-bottom:8px;" onclick="executeRecoveryStepTwoSubmit('${targetEmailAddress}')">Verify Token Security Match</button>
                <button class="action-btn" style="width:100%; justify-content:center; background:var(--text-muted);" onclick="renderForgotPasswordFormStepOne()">Restart Recovery Sequence</button>
            `;
                    }

                    function executeRecoveryStepTwoSubmit(email) {
                        const otp = document.getElementById('recoveryOtpField').value.trim();
                        if (otp !== "889912") { customAlert("OTP code verification failed. Match sequence invalid."); return; }
                        renderForgotPasswordFormStepThree(email);
                    }

                    function renderForgotPasswordFormStepThree(email) {
                        const formArea = getActiveAuthFormArea();
                        formArea.innerHTML = `
                <h3 style="margin-bottom:6px;">🔐 Phase 3: Set Credentials</h3>
                <p style="color:var(--text-muted); margin-bottom:12px; font-size:10px;">Select a strong cryptographic password string containing at least 8 characters.</p>
                <div class="form-group">
                    <label>New Passphrase</label>
                    <input type="password" id="recoveryNewPass" placeholder="••••••••" oninput="assessPassComplexityStrength()">
                    <div id="passStrengthMeter" style="height:4px; background:#e2e8f0; border-radius:2px; margin-top:4px;"></div>
                </div>
                <div class="form-group">
                    <label>Confirm Passphrase</label>
                    <input type="password" id="recoveryConfirmPass" placeholder="••••••••">
                </div>
                <button class="action-btn" style="width:100%; justify-content:center; margin-bottom:8px;" onclick="executeRecoveryFinalSubmit('${email}')">Compile Credentials Overwrite</button>
            `;
                    }
                    function getActiveGroupId() {
                        return chatActiveGroupId || (chatActivePeerEmail && chatActivePeerEmail.startsWith("group_") ? chatActivePeerEmail : null);
                    }

                    function assessPassComplexityStrength() {
                        const val = document.getElementById('recoveryNewPass').value;
                        const meter = document.getElementById('passStrengthMeter');
                        if (!meter) return;
                        if (val.length === 0) {
                            meter.style.width = "0%";
                            meter.style.backgroundColor = "transparent";
                        } else if (val.length < 5) {
                            meter.style.width = "30%";
                            meter.style.backgroundColor = "var(--danger)";
                        } else if (val.length < 8) {
                            meter.style.width = "60%";
                            meter.style.backgroundColor = "var(--warning)";
                        } else {
                            meter.style.width = "100%";
                            meter.style.backgroundColor = "var(--success)";
                        }
                    }

                    function executeRecoveryFinalSubmit(email) {
                        const p1 = document.getElementById('recoveryNewPass').value;
                        const p2 = document.getElementById('recoveryConfirmPass').value;
                        if (p1.length < 8) { customAlert("Complexity standards not met. Passwords must span 8+ characters."); return; }
                        if (p1 !== p2) { customAlert("Passphrases do not match."); return; }

                        const matchedUser = globalRosterRepository.find(u => u.email === email);
                        if (matchedUser) matchedUser.password = p1;
                        customAlert("Cryptographic records modified cleanly. Please access terminal via updated pass.");
                        renderAuthViewLayoutBox();
                    }

                    window.triggerGoogleOAuthSimulatedFlow = function () {
                        const emailInput = document.getElementById('authFieldUserEmail');
                        const email = emailInput ? emailInput.value.trim() : '';
                        const matchedUser = globalRosterRepository.find(u => u.email === email);
                        if (matchedUser) {
                            customAlert(`Simulated Google SSO Authentication success! Logged in as: ${matchedUser.name}`);
                            initializeAuthenticatedSessionContext(matchedUser);
                        } else if (globalRosterRepository.length > 0) {
                            customAlert("Google SSO: No account matches that email in the roster.");
                        } else {
                            customAlert("No staff accounts exist. Please add staff first.");
                        }
                    };

                    window.toggleBiometricSetting = function (enabled) {
                        localStorage.setItem('physioBiometricEnabled', enabled ? 'true' : '');
                        if (enabled) {
                            document.getElementById('biometricStatus').textContent = 'Biometric login is enabled. Register your fingerprint/face below.';
                            document.getElementById('registerBiometricBtn').style.display = 'flex';
                        } else {
                            document.getElementById('biometricStatus').textContent = 'Biometric login is disabled.';
                            document.getElementById('registerBiometricBtn').style.display = 'none';
                            document.getElementById('biometricRegisteredInfo').style.display = 'none';
                            localStorage.removeItem('physioBiometricCredentialId');
                        }
                        updateBiometricLoginButtonVisibility();
                    };

                    window.updateBiometricLoginButtonVisibility = function () {
                        const btn = document.getElementById('biometricLoginBtn');
                        if (!btn) return;
                        const enabled = localStorage.getItem('physioBiometricEnabled') === 'true';
                        const hasCredential = !!localStorage.getItem('physioBiometricCredentialId');
                        btn.style.display = (enabled && hasCredential) ? 'flex' : 'none';
                    };

                    window.isWebAuthnAvailable = function () {
                        return window.PublicKeyCredential &&
                            location.protocol !== 'file:' &&
                            typeof navigator.credentials?.create === 'function';
                    };

                    window.registerBiometricCredential = async function () {
                        if (window.isWebAuthnAvailable()) {
                            try {
                                const challenge = new Uint8Array(32);
                                window.crypto.getRandomValues(challenge);
                                const publicKey = {
                                    challenge: challenge,
                                    rp: { name: 'Physio Solutions' },
                                    user: { id: new Uint8Array([1, 2, 3, 4]), name: 'user@physiosolutions.mv', displayName: 'Staff Member' },
                                    pubKeyCredParams: [{ alg: -7, type: 'public-key' }],
                                    authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required' },
                                    timeout: 60000
                                };
                                const credential = await navigator.credentials.create({ publicKey });
                                localStorage.setItem('physioBiometricCredentialId', credential.id);
                            } catch (err) {
                                if (err.name === 'NotAllowedError') {
                                    customAlert('Biometric registration was cancelled or denied.');
                                } else {
                                    customAlert('Biometric registration failed: ' + err.message);
                                }
                                return;
                            }
                        } else {
                            localStorage.setItem('physioBiometricCredentialId', 'simulated_' + Date.now());
                        }
                        document.getElementById('biometricRegisteredInfo').style.display = 'block';
                        document.getElementById('biometricRegisteredInfo').textContent = '?? Biometric registered successfully on this device.';
                        document.getElementById('registerBiometricBtn').style.display = 'none';
                        customAlert('Fingerprint / Face registered successfully!');
                        updateBiometricLoginButtonVisibility();
                    };

                    window.authenticateWithBiometric = async function () {
                        const credentialId = localStorage.getItem('physioBiometricCredentialId');
                        if (!credentialId) {
                            customAlert('No biometric credential registered. Register in My Professional Profile first.');
                            return;
                        }
                        if (window.isWebAuthnAvailable()) {
                            try {
                                const challenge = new Uint8Array(32);
                                window.crypto.getRandomValues(challenge);
                                const publicKey = {
                                    challenge: challenge,
                                    allowCredentials: [{ id: Uint8Array.from(atob(credentialId), c => c.charCodeAt(0)), type: 'public-key' }],
                                    userVerification: 'required',
                                    timeout: 60000
                                };
                                const assertion = await navigator.credentials.get({ publicKey });
                                if (!assertion) return;
                            } catch (err) {
                                if (err.name === 'NotAllowedError') {
                                    customAlert('Biometric authentication cancelled or denied.');
                                } else {
                                    customAlert('Biometric authentication failed: ' + err.message);
                                }
                                return;
                            }
                        }
                        const defaultUser = globalRosterRepository[0];
                        initializeAuthenticatedSessionContext(defaultUser);
                    };

                    // Show/hide biometric login button when login form renders
                    const origRenderAuth = renderAuthViewLayoutBox;
                    renderAuthViewLayoutBox = function () {
                        origRenderAuth.apply(this, arguments);
                        updateBiometricLoginButtonVisibility();
                    };

                    function initializeAuthenticatedSessionContext(userObject) {
                        // Check if user account is active (not disabled/resigned)
                        if (userObject.active === false) {
                            customAlert("Account Access Denied: This user account has been deactivated. Please contact your administrator.");
                            return;
                        }
                        currentActiveSessionUser = userObject;
                        syncPatientTrackerVisibility();
                        document.getElementById('authContainer').classList.add('hidden');
                        document.getElementById('authContainerSplit').classList.add('hidden');
                        const container = document.getElementById('appContainer');
                        container.classList.remove('hidden');

                        document.getElementById('userMatrixName').innerText = userObject.name;
                        document.getElementById('userMatrixRole').innerText = lookupTranslationValue(userObject.position);
                        // Automatically synchronize top-right header profile photo/initials
                        const headerAvatar = document.getElementById('headerProfileAvatar');
                        if (headerAvatar) {
                            const initials = userObject.avatar || userObject.name.split(" ").map(n => n[0]).join("").toUpperCase().substring(0, 2);
                            if (userObject.photoUrl) {
                                headerAvatar.innerHTML = `<img src="${userObject.photoUrl}" style="width:100%; height:100%; object-fit:cover; border-radius:50%; display:block;">`;
                            } else {
                                headerAvatar.innerText = initials;
                                headerAvatar.innerHTML = initials; // Clear any old image structures
                                headerAvatar.style.background = `${userObject.accentColor || '#004b87'}22`;
                                headerAvatar.style.color = userObject.accentColor || '#004b87';
                                headerAvatar.style.borderColor = `${userObject.accentColor || '#004b87'}44`;
                            }
                        }
                        document.getElementById('activeRoleIndicator').innerText = lookupTranslationValue(userObject.position);

                        if (allowedPortalSwitcherRoles.includes(userObject.position)) {
                            document.getElementById('adminPortalSwitcher').classList.remove('hidden');
                            renderPortalWorkspaceSwitcher(); // Populates the switcher dropdown dynamically
                            document.getElementById('switcherSelectField').value = userObject.email; // Selects the logged-in user by email
                        } else {
                            document.getElementById('adminPortalSwitcher').classList.add('hidden');
                        }

                        // Login already logged in executeSimulatedAuthenticationChallenge — no duplicate needed
                        rebuildDynamicPortalMenus();

                        let initialView = "my_profile";
                        if (globalRolePermissionsMatrix[userObject.position].includes("my_dashboard")) {
                            initialView = "my_dashboard";
                        } else if (globalRolePermissionsMatrix[userObject.position].includes("admin_hub")) {
                            initialView = "admin_hub";
                        }
                        triggerSelectedModuleShift(initialView);
                        synchronizeWorkspaceCoreStatus();
                        checkAndResetLeaveBalances();
                    }

                    function checkAndResetLeaveBalances() {
                        const today = new Date();
                        globalRosterRepository.forEach(staff => {
                            if (!staff.joiningDate) return;
                            const joinDate = new Date(staff.joiningDate);
                            const lastReset = staff.lastLeaveReset ? new Date(staff.lastLeaveReset) : null;
                            if (lastReset && today < new Date(lastReset.getFullYear() + 1, lastReset.getMonth(), lastReset.getDate())) return;
                            if (!lastReset && today < new Date(joinDate.getFullYear() + 1, joinDate.getMonth(), joinDate.getDate())) return;
                            const style = staff.style || "Full-Time";
                            staff.sickBalance = style === "Full-Time" ? 30 : 0;
                            staff.annualBalance = style === "Full-Time" ? 30 : 0;
                            staff.familyBalance = style === "Full-Time" ? 15 : 0;
                            staff.umrahBalance = 15;
                            staff.hajjBalance = 15;
                            staff.noPaidBalance = 15;
                            staff.maternityBalance = 90;
                            staff.paternityBalance = 10;
                            staff.specialBalance = 15;
                            staff.lastLeaveReset = today.toISOString().slice(0, 10);
                        });
                    }

                    function switchTestingProfileView(selectedPortalEmail) {
                        const targetUser = globalRosterRepository.find(u => u.email === selectedPortalEmail);
                        if (targetUser) {
                            currentActiveSessionUser = targetUser;
                            document.getElementById('userMatrixName').innerText = targetUser.name;
                            document.getElementById('userMatrixRole').innerText = lookupTranslationValue(targetUser.position);
                            document.getElementById('activeRoleIndicator').innerText = lookupTranslationValue(targetUser.position);

                            // Re-evaluate portal switcher visibility for the target user
                            if (allowedPortalSwitcherRoles.includes(targetUser.position)) {
                                document.getElementById('adminPortalSwitcher').classList.remove('hidden');
                            } else {
                                document.getElementById('adminPortalSwitcher').classList.add('hidden');
                            }

                            rebuildDynamicPortalMenus();

                            const allowed = getAllowedModulesForRole(targetUser.position);
                            if (allowed.length > 0) {
                                if (!allowed.includes(globalActiveViewportModule)) {
                                    triggerSelectedModuleShift(allowed[0]);
                                } else {
                                    triggerSelectedModuleShift(globalActiveViewportModule);
                                }
                            }

                            synchronizeWorkspaceCoreStatus();

                            // Staged Toasts Handler: Catch up on unread notifications immediately upon switching views
                            const missedNotifs = notificationStore.filter(n => !n.read && n.recipientEmail === targetUser.email);
                            missedNotifs.forEach(n => {
                                showCommsToast(n.text, n.tier, n.icon, n.senderEmail);
                            });
                        }
                    }

