                    function renderAccessControlMatrix() {
                        const matrixTable = document.getElementById('accessControlMatrixTable');
                        if (!matrixTable) return;
                        matrixTable.innerHTML = "";

                        const roles = Object.keys(globalRolePermissionsMatrix);
                        const moduleTitleMap = {
                            my_dashboard: "Workspace Dashboard",
                            admin_hub: "Administrative Core",
                            staff_directory: "Personnel Directory",
                            roster_engine: "Grid Roster Engine",
                            ps_calendar: "PS Calendar",
                            overtime_tracker: "Attendance & Overtime",
                            master_ot_sheet: "Master OT Sheet",
                            admin_master_ot: "Admin Overtime Ledger",
                            discharge_followup: "Discharge",
                            discharge_summary: "Discharge Summary Sheet",
                            notes_tasks: "Tasks & Calendar Notes",
                            inventory: "Supplies & Consumables",
                            reference_tracker: "Document Sequential ID",
                            export_hub: "Central Operational Export Data Hub",
                            comms_center: "Communications Hub",
                            leave_management: "Leave Management",
                            leave_summary: "🌴 Leave Summary Sheet",
                            therapist_volume: "Therapist Volume Tracking",
                            my_roster: "My Personal Roster",
                            my_profile: "My Professional Profile",
                            fdo_sheets: "FDO's Sheets",
                            fdo_attendance: "FDO Attendance Sheet",
                            solarelle_patients: "Solarelle Patients",
                            seales: "💰 Sales Tracker",
                            aasandha_assessment: "Assessment & Discharge Fill",
                            expiry_tracker: "⏰ Expiry Tracker",
                            personal_expiry: "🔒 Personal Expiry Dates",
                            followup_cases: "Follow Up Cases"
                        };

                        // Start with sidebar order, then append any extra modules from permissions
                        let modules = [...globalSidebarOrder];
                        roles.forEach(role => {
                            if (globalRolePermissionsMatrix[role]) {
                                globalRolePermissionsMatrix[role].forEach(mod => {
                                    if (!modules.includes(mod)) {
                                        modules.push(mod);
                                    }
                                });
                            }
                        });

                        let headRow = `<tr><th>Module / Page Context</th>`;
                        roles.forEach(role => {
                            headRow += `<th style="min-width: 100px;">${lookupTranslationValue(role)}</th>`;
                        });
                        headRow += `<th style="min-width:50px; text-align:center; font-size:9px;">Select All</th></tr>`;
                        matrixTable.innerHTML += headRow;

                        modules.forEach(mod => {
                            const modKey = mod;
                            const displayName = moduleTitleMap[mod] || mod.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
                            let row = `<tr data-mod="${modKey}"><td style="text-align:left; font-weight:600;">${displayName}</td>`;
                            roles.forEach(role => {
                                const isAllowed = globalRolePermissionsMatrix[role] && globalRolePermissionsMatrix[role].includes(mod);
                                row += `<td><input type="checkbox" class="matrix-checkbox" id="perm_${role}_${mod}" ${isAllowed ? 'checked' : ''}></td>`;
                            });
                            row += `<td style="text-align:center; font-size:9px;">
                                <a href="#" onclick="event.preventDefault(); var m='${modKey}'; document.querySelectorAll('#accessControlMatrixTable tr[data-mod=\"'+m+'\"] input[type=checkbox]').forEach(function(cb){cb.checked=true;});" style="color:var(--primary);">All</a> |
                                <a href="#" onclick="event.preventDefault(); var m='${modKey}'; document.querySelectorAll('#accessControlMatrixTable tr[data-mod=\"'+m+'\"] input[type=checkbox]').forEach(function(cb){cb.checked=false;});" style="color:var(--text-muted);">Clear</a>
                            </td>`;
                            row += `</tr>`;
                            matrixTable.innerHTML += row;
                        });
                    }

                    function saveAccessControlMatrix() {
                        const roles = Object.keys(globalRolePermissionsMatrix);
                        const modules = [...globalSidebarOrder];
                        roles.forEach(role => {
                            if (globalRolePermissionsMatrix[role]) {
                                globalRolePermissionsMatrix[role].forEach(mod => {
                                    if (!modules.includes(mod)) modules.push(mod);
                                });
                            }
                        });
                        modules.forEach(mod => {
                            roles.forEach(role => {
                                const cb = document.getElementById(`perm_${role}_${mod}`);
                                if (!cb) return;
                                const arr = globalRolePermissionsMatrix[role];
                                const idx = arr.indexOf(mod);
                                if (cb.checked && idx === -1) {
                                    arr.push(mod);
                                } else if (!cb.checked && idx !== -1) {
                                    arr.splice(idx, 1);
                                }
                            });
                        });
                        rebuildDynamicPortalMenus();
                        customAlert("All role permissions saved and synchronized.");
                    }

                    function renderActiveTableHeaders() {
                        const setHeader = (id, columns) => {
                            const el = document.getElementById(id);
                            if (!el || !columns) return;
                            el.innerHTML = "";
                            let row = "<tr>";
                            columns.forEach(col => {
                                row += `<th style="background:var(--primary);color:#fff;">${lookupTranslationValue(col.name)}</th>`;
                            });
                            row += "</tr>";
                            el.innerHTML = row;
                        };
                        setHeader("dischargeTableHead", globalTableSchemas.discharge);
                        setHeader("dischargeSummaryTableHead", globalTableSchemas.discharge);
                        setHeader("inventoryTableHead", globalTableSchemas.inventory);
                        setHeader("sequentialReferenceTableHeader", globalTableSchemas.sequential_id);
                        setHeader("volumeTableHead", globalTableSchemas.therapist_volume);
                    }

                    // --- SYSTEM TABLE SCHEMA ARCHITECT CUSTOM COLUMN IMPLEMENTATION ---
                    function loadActiveSchemaStructure(tableName) {
                        const container = document.getElementById('builderFieldsContainer');
                        if (!container) return;

                        if (!globalTableSchemaArchitectData[tableName]) {
                            globalTableSchemaArchitectData[tableName] = [
                                { name: "id", type: "number", required: true }
                            ];
                        }

                        container.innerHTML = "";

                        globalTableSchemaArchitectData[tableName].forEach((column, idx) => {
                            const row = document.createElement('div');
                            row.style.display = "flex";
                            row.style.gap = "4px";
                            row.style.alignItems = "center";
                            row.style.background = "var(--bg-inner)";
                            row.style.padding = "4px 6px";
                            row.style.border = "1px solid var(--border)";
                            row.style.borderRadius = "4px";
                            row.className = "schema-column-row";

                            row.innerHTML = `
                    <span style="font-size:8px; color:var(--text-muted); min-width:16px; text-align:center;">${idx + 1}</span>
                    <div class="form-group" style="margin-bottom:0; flex:2;">
                        <input type="text" value="${column.name}" placeholder="Column Key Name" oninput="updateArchitectColumnData('${tableName}', ${idx}, 'name', this.value)" style="padding:2px 4px; font-size:9px; min-height:unset !important;">
                    </div>
                    <div class="form-group" style="margin-bottom:0; flex:1.2;">
                        <select onchange="updateArchitectColumnData('${tableName}', ${idx}, 'type', this.value)" style="padding:2px 4px; font-size:9px; min-height:unset !important;">
                            <option value="text" ${column.type === 'text' ? 'selected' : ''}>Text</option>
                            <option value="number" ${column.type === 'number' ? 'selected' : ''}>Number</option>
                            <option value="date" ${column.type === 'date' ? 'selected' : ''}>Date</option>
                        </select>
                    </div>
                    <div class="form-group" style="margin-bottom:0; display:flex; align-items:center; gap:2px;">
                        <input type="checkbox" ${column.required ? 'checked' : ''} onchange="updateArchitectColumnData('${tableName}', ${idx}, 'required', this.checked)" style="width:12px; height:12px;">
                        <span style="font-size:8px;">Req</span>
                    </div>
                    <button class="action-btn" style="padding:1px 4px; font-size:8px; min-height:unset;" onclick="moveArchitectColumnRow('${tableName}', ${idx}, -1)" ${idx === 0 ? 'disabled' : ''}>▲</button>
                    <button class="action-btn" style="padding:1px 4px; font-size:8px; min-height:unset;" onclick="moveArchitectColumnRow('${tableName}', ${idx}, 1)" ${idx === globalTableSchemaArchitectData[tableName].length - 1 ? 'disabled' : ''}>▼</button>
                    <button class="action-btn" style="background:var(--danger); padding:1px 4px; font-size:8px; min-height:unset;" onclick="removeArchitectColumnRow('${tableName}', ${idx})">🗑️</button>
                `;
                            container.appendChild(row);
                        });
                    }

                    function updateArchitectColumnData(tableName, index, field, value) {
                        if (globalTableSchemaArchitectData[tableName] && globalTableSchemaArchitectData[tableName][index]) {
                            globalTableSchemaArchitectData[tableName][index][field] = value;
                        }
                    }

                    function addBuilderFieldRow() {
                        const tableSelector = document.getElementById('builderTableSelector');
                        if (!tableSelector) return;
                        const currentTable = tableSelector.value;

                        if (!globalTableSchemaArchitectData[currentTable]) {
                            globalTableSchemaArchitectData[currentTable] = [];
                        }

                        const nextIndex = globalTableSchemaArchitectData[currentTable].length + 1;
                        globalTableSchemaArchitectData[currentTable].push({
                            name: "New Column " + nextIndex,
                            key: "new_column_" + nextIndex,
                            type: "text",
                            required: false
                        });

                        loadActiveSchemaStructure(currentTable);
                    }

                    function removeArchitectColumnRow(tableName, index) {
                        if (globalTableSchemaArchitectData[tableName]) {
                            globalTableSchemaArchitectData[tableName].splice(index, 1);
                            loadActiveSchemaStructure(tableName);
                        }
                    }

                    function moveArchitectColumnRow(tableName, index, direction) {
                        const target = index + direction;
                        if (target < 0 || target >= globalTableSchemaArchitectData[tableName].length) return;
                        const arr = globalTableSchemaArchitectData[tableName];
                        [arr[index], arr[target]] = [arr[target], arr[index]];
                        loadActiveSchemaStructure(tableName);
                    }

                    function showSchemaBuilderModal() {
                        const existing = document.getElementById('schemaBuilderModalOverlay');
                        if (existing) existing.remove();

                        const tableSelector = document.getElementById('builderTableSelector');
                        const currentTable = tableSelector ? tableSelector.value : 'overtime';
                        const columns = globalTableSchemaArchitectData[currentTable] || [];

                        let itemsHtml = columns.map((col, idx) => {
                            const typeLabels = { text: 'Text', number: 'Number', date: 'Date' };
                            return `
                    <div style="display:flex; align-items:center; gap:6px; padding:8px 12px; background:var(--bg-inner); border:1px solid var(--border); border-radius:6px;">
                        <span style="min-width:18px; font-size:11px; color:var(--text-muted); font-weight:700;">${idx + 1}.</span>
                        <input type="text" value="${escapeHtml(col.name)}" onchange="updateArchitectColumnData('${currentTable}', ${idx}, 'name', this.value)" style="flex:2; padding:4px 6px; font-size:11px; border:1px solid var(--border); border-radius:4px; background:var(--bg-main); color:var(--text-body);">
                        <select onchange="updateArchitectColumnData('${currentTable}', ${idx}, 'type', this.value)" style="flex:1; padding:4px 6px; font-size:11px; border:1px solid var(--border); border-radius:4px; background:var(--bg-main); color:var(--text-body);">
                            <option value="text" ${col.type === 'text' ? 'selected' : ''}>Text</option>
                            <option value="number" ${col.type === 'number' ? 'selected' : ''}>Number</option>
                            <option value="date" ${col.type === 'date' ? 'selected' : ''}>Date</option>
                        </select>
                        <label style="display:flex; align-items:center; gap:3px; font-size:10px; cursor:pointer; white-space:nowrap;">
                            <input type="checkbox" ${col.required ? 'checked' : ''} onchange="updateArchitectColumnData('${currentTable}', ${idx}, 'required', this.checked)" style="width:13px; height:13px;">
                            Req
                        </label>
                        <button class="action-btn" style="padding:2px 6px; font-size:9px; min-height:unset;" onclick="moveArchitectColumnRow('${currentTable}', ${idx}, -1); showSchemaBuilderModal();" ${idx === 0 ? 'disabled' : ''}>▲</button>
                        <button class="action-btn" style="padding:2px 6px; font-size:9px; min-height:unset;" onclick="moveArchitectColumnRow('${currentTable}', ${idx}, 1); showSchemaBuilderModal();" ${idx === columns.length - 1 ? 'disabled' : ''}>▼</button>
                        <button class="action-btn" style="background:var(--danger); padding:2px 6px; font-size:9px; min-height:unset;" onclick="removeArchitectColumnRow('${currentTable}', ${idx}); showSchemaBuilderModal();">🗑️</button>
                    </div>`;
                        }).join("");

                        const overlay = document.createElement('div');
                        overlay.id = 'schemaBuilderModalOverlay';
                        overlay.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); display:flex; align-items:center; justify-content:center; z-index:10000;";
                        overlay.innerHTML = `
                <div style="background:var(--bg-card); border-radius:12px; padding:24px; width:600px; max-width:90vw; max-height:80vh; display:flex; flex-direction:column; box-shadow:0 20px 60px rgba(0,0,0,0.3);">
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
                        <h3 style="margin:0; font-size:14px;">🛠️ Schema: ${lookupTranslationValue(currentTable)}</h3>
                        <button class="action-btn" style="padding:4px 10px; font-size:10px; background:var(--danger);" onclick="closeSchemaBuilderModal()">✕ Close</button>
                    </div>
                    <div style="flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:6px; padding:4px;">
                        ${itemsHtml || '<p style="text-align:center; color:var(--text-muted); font-size:12px;">No columns configured yet.</p>'}
                    </div>
                    <button class="action-btn" style="width:100%; justify-content:center; background:var(--success); margin-top:16px;" onclick="closeSchemaBuilderModal()">Done</button>
                </div>
            `;
                        overlay.addEventListener('click', e => { if (e.target === overlay) closeSchemaBuilderModal(); });
                        document.body.appendChild(overlay);
                    }

                    function closeSchemaBuilderModal() {
                        const el = document.getElementById('schemaBuilderModalOverlay');
                        if (el) el.remove();
                    }

                    function compileDynamicTableDefinition() {
                        const tableSelector = document.getElementById('builderTableSelector');
                        if (!tableSelector) return;
                        const currentTable = tableSelector.value;

                        const architectColumns = globalTableSchemaArchitectData[currentTable] || [];

                        // Map the editor definitions over to the live layout schema array
                        globalTableSchemas[currentTable] = architectColumns.map(col => {
                            const derivedKey = col.key ? col.key : col.name.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_').replace(/_+/g, '_');
                            return {
                                name: col.name,
                                key: derivedKey,
                                type: col.type
                            };
                        });

                        customAlert(`Architecture Definition Compiled! Schema configuration for entry target '${currentTable}' has been compiled and applied live across operations workspaces.`);

                        // Instantly redraw active table structures and column grids
                        synchronizeWorkspaceCoreStatus();
                    }

                    function toggleModulePlacementFieldVisibility(placementVal) {
                        const targetWrapper = document.getElementById('newModuleTargetPageWrapper');
                        const rolesWrapper = document.getElementById('newModuleRoleAccessWrapper');
                        if (placementVal === 'existing') {
                            targetWrapper.style.display = 'block';
                            rolesWrapper.style.display = 'none';
                        } else {
                            targetWrapper.style.display = 'none';
                            rolesWrapper.style.display = 'block';
                        }
                    }

                    function deployCustomSystemModule() {
                        const modKey = document.getElementById('newModuleKeyId').value.trim().toLowerCase().replace(/ /g, '_');
                        const modName = document.getElementById('newModuleName').value.trim();
                        const placement = document.getElementById('newModulePlacement').value;

                        if (!modKey || !modName) {
                            customAlert("Please designate a unique key and visual title description.");
                            return;
                        }

                        globalTableSchemas[modKey] = [
                            { name: "Entry Log Code", key: "entry_id", type: "text" },
                            { name: "Creation Date", key: "date", type: "date" },
                            { name: "Details Data Description", key: "description", type: "text" }
                        ];

                        const builderSelect = document.getElementById('builderTableSelector');
                        const opt = document.createElement('option');
                        opt.value = modKey;
                        opt.innerText = `${modName} (${modKey})`;
                        builderSelect.appendChild(opt);

                        if (placement === 'new_page') {
                            const checkboxes = document.querySelectorAll('#newModuleRolesChecklist input[type="checkbox"]');
                            checkboxes.forEach(cb => {
                                if (cb.checked) {
                                    const role = cb.value;
                                    if (globalRolePermissionsMatrix[role] && !globalRolePermissionsMatrix[role].includes(modKey)) {
                                        globalRolePermissionsMatrix[role].push(modKey);
                                    }
                                }
                            });
                            customAlert(`Custom Module Standalone Page deployed cleanly. Permission matrices rewritten.`);
                        } else {
                            const targetPage = document.getElementById('newModuleTargetPage').value;
                            customAlert(`Custom Embedded dataset successfully compiled inside the chosen viewport frame.`);
                        }

                        document.getElementById('newModuleKeyId').value = "";
                        document.getElementById('newModuleName').value = "";

                        synchronizeWorkspaceCoreStatus();
                        rebuildDynamicPortalMenus();
                    }

                    function renderDynamicPageModuleInWorkspace(modKey) {
                        let parentGrid = document.getElementById(`mod_${modKey}`);
                        if (!parentGrid) {
                            const workspaceDiv = document.querySelector('.workspace');
                            parentGrid = document.createElement('div');
                            parentGrid.id = `mod_${modKey}`;
                            parentGrid.className = "grid-layout view-module hidden";
                            workspaceDiv.appendChild(parentGrid);
                        }

                        parentGrid.innerHTML = `
                <div class="module-card span-12">
                    <h2>📋 Custom Database Deployed: ${modKey.replace(/_/g, ' ').toUpperCase()}</h2>
                    <p style="color:var(--text-muted); margin-bottom:12px;">This clinical operation table was provisioned dynamically using the table schema architect.</p>
                    
                    <div style="background:var(--bg-inner); border:1px solid var(--border); padding:14px; border-radius:8px; margin-bottom:14px;">
                        <h3 style="margin-bottom:8px;">➕ Register Entry</h3>
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:10px;">
<div class="form-group"><label>Creation Date</label><input type="date" id="custEntryDate_${modKey}" value="${getTodayISOString()}"></div>                            <div class="form-group"><label>Details Data Description</label><input type="text" id="custEntryDesc_${modKey}"></div>
                        </div>
                        <button class="action-btn" onclick="commitCustomRegisteredTableEntry('${modKey}')">Commit Log Entry</button>
                    </div>

                    <table class="premium-table">
                        <thead>
                            <tr>
                                <th>Entry Log Code</th>
                                <th>Creation Date</th>
                                <th>Details Data Description</th>
                            </tr>
                        </thead>
                        <tbody id="customRegisteredTableBody_${modKey}">
                            <tr><td colspan="3" style="text-align:center; color:var(--text-muted); font-style:italic;">No custom logs recorded.</td></tr>
                        </tbody>
                    </table>
                </div>
            `;
                    }

                    function commitCustomRegisteredTableEntry(modKey) {
                        const date = document.getElementById(`custEntryDate_${modKey}`).value;
                        const desc = document.getElementById(`custEntryDesc_${modKey}`).value.trim();
                        if (!desc) { customAlert("Please include descriptive details before committing."); return; }

                        const tbody = document.getElementById(`customRegisteredTableBody_${modKey}`);
                        const row = document.createElement('tr');
                        row.innerHTML = `
                <td><strong>#C-${Math.floor(Math.random() * 9000 + 1000)}</strong></td>
                <td>${date}</td>
                <td>${desc}</td>
            `;
                        if (tbody.innerHTML.includes("No custom logs recorded")) tbody.innerHTML = "";
                        tbody.appendChild(row);

                        document.getElementById(`custEntryDesc_${modKey}`).value = "";
                        customAlert("Log entry added to custom schema instance.");
                    }

