                    let globalVisibleLeaveTypes = ["Umrah Leave", "Hajj Leave", "No Paid Leave", "Maternity Leave", "Paternity Leave", "Special Leave", "Sick Leave", "Annual Leave", "Family Leave"];

                    function getCeilingLimit(type, mcStatus) {
                        const defaults = {
                            "Umrah Leave": 15, "Hajj Leave": 15, "No Paid Leave": 15,
                            "Maternity Leave": 90, "Paternity Leave": 10, "Special Leave": 15,
                            "Annual Leave": 30, "Family Leave": 15
                        };
                        try {
                            const saved = localStorage.getItem('physioLeaveCeilings');
                            if (saved) {
                                const cfg = JSON.parse(saved);
                                if (type === 'Sick Leave') {
                                    if (mcStatus === 'With MC') return cfg['Sick Leave (With MC)'] || 30;
                                    const noMcEl = document.getElementById('withoutMcLimitInput');
                                    const noMcVal = noMcEl ? parseInt(noMcEl.value) || 3 : 3;
                                    if (cfg['Sick Leave (Without MC)'] !== undefined) return cfg['Sick Leave (Without MC)'];
                                    return noMcVal;
                                }
                                if (cfg[type] !== undefined) return cfg[type];
                                return defaults[type] || 30;
                            }
                        } catch (e) { }
                        if (type === 'Sick Leave') {
                            const noMcEl = document.getElementById('withoutMcLimitInput');
                            const noMcVal = noMcEl ? parseInt(noMcEl.value) || 3 : 3;
                            return mcStatus === 'With MC' ? 30 : noMcVal;
                        }
                        return defaults[type] || 30;
                    }

                    function saveDashboardLeaveVisibility() {
                        const map = [
                            { id: "Umrah Leave", cb: "dashShowUmrah" },
                            { id: "Hajj Leave", cb: "dashShowHajj" },
                            { id: "No Paid Leave", cb: "dashShowNoPaid" },
                            { id: "Maternity Leave", cb: "dashShowMaternity" },
                            { id: "Paternity Leave", cb: "dashShowPaternity" },
                            { id: "Special Leave", cb: "dashShowSpecial" },
                            { id: "Sick Leave (With MC)", cb: "dashShowSickMc" },
                            { id: "Sick Leave (Without MC)", cb: "dashShowSickNoMc" },
                            { id: "Annual Leave", cb: "dashShowAnnual" },
                            { id: "Family Leave", cb: "dashShowFamily" }
                        ];
                        const selected = map.filter(m => {
                            const el = document.getElementById(m.cb);
                            return el && el.checked;
                        }).map(m => m.id);
                        localStorage.setItem('physioDashboardLeaveTypes', JSON.stringify(selected));
                        customAlert("Dashboard leave visibility saved.");
                    }

                    function loadDashboardLeaveVisibility() {
                        try {
                            const saved = localStorage.getItem('physioDashboardLeaveTypes');
                            if (!saved) {
                                const def = { "dashShowSickMc": true, "dashShowSickNoMc": true, "dashShowAnnual": true, "dashShowFamily": true };
                                Object.keys(def).forEach(id => { const el = document.getElementById(id); if (el) el.checked = def[id]; });
                                return;
                            }
                            const types = JSON.parse(saved);
                            const map = {
                                "Umrah Leave": "dashShowUmrah",
                                "Hajj Leave": "dashShowHajj",
                                "No Paid Leave": "dashShowNoPaid",
                                "Maternity Leave": "dashShowMaternity",
                                "Paternity Leave": "dashShowPaternity",
                                "Special Leave": "dashShowSpecial",
                                "Sick Leave (With MC)": "dashShowSickMc",
                                "Sick Leave (Without MC)": "dashShowSickNoMc",
                                "Annual Leave": "dashShowAnnual",
                                "Family Leave": "dashShowFamily"
                            };
                            Object.keys(map).forEach(key => {
                                const el = document.getElementById(map[key]);
                                if (el) el.checked = types.includes(key);
                            });
                        } catch (e) { }
                    }

                    function getStaffAnniversaryCycleRange(email) {
                        const staff = globalRosterRepository.find(u => u.email === email);
                        if (!staff) return null;
                        const startStr = staff.joiningDate || staff.hireDate || "2022-04-21";
                        let start = new Date(startStr);
                        if (isNaN(start.getTime())) start = new Date("2022-04-21");
                        const now = new Date();
                        let cycleStart = new Date(start);
                        while (cycleStart <= now) {
                            let next = new Date(cycleStart);
                            next.setFullYear(next.getFullYear() + 1);
                            if (now < next) break;
                            cycleStart = next;
                        }
                        let cycleEnd = new Date(cycleStart);
                        cycleEnd.setFullYear(cycleEnd.getFullYear() + 1);
                        cycleEnd.setDate(cycleEnd.getDate() - 1);
                        return { start: cycleStart, end: cycleEnd };
                    }

                    function getStaffUsedLeaveDays(email, type, mcStatus) {
                        const cycle = getStaffAnniversaryCycleRange(email);
                        if (!cycle) return 0;
                        let leaves = globalLeaveRepository.filter(l =>
                            l.email === email && l.type === type && l.status === 'Approved'
                        );
                        if (mcStatus) {
                            leaves = leaves.filter(l => l.mcStatus === mcStatus);
                        }
                        return leaves.reduce((sum, l) => {
                            const d = l.duration || 1;
                            const lDate = new Date(l.date);
                            if (lDate >= cycle.start && lDate <= cycle.end) return sum + d;
                            return sum;
                        }, 0);
                    }

                    function isLeaveExhausted(email, type, mcStatus) {
                        const used = getStaffUsedLeaveDays(email, type, mcStatus);
                        const limit = getCeilingLimit(type, mcStatus);
                        return used >= limit;
                    }

                    function saveLeaveCeilingLimits() {
                        const types = [
                            { id: "Umrah Leave", show: "lUmrahShow", ceil: "lUmrahCeil" },
                            { id: "Hajj Leave", show: "lHajjShow", ceil: "lHajjCeil" },
                            { id: "No Paid Leave", show: "lNoPaidShow", ceil: "lNoPaidCeil" },
                            { id: "Maternity Leave", show: "lMaternityShow", ceil: "lMaternityCeil" },
                            { id: "Paternity Leave", show: "lPaternityShow", ceil: "lPaternityCeil" },
                            { id: "Special Leave", show: "lSpecialShow", ceil: "lSpecialCeil" },
                            { id: "Sick Leave (With MC)", show: "lSickMcShow", ceil: "lSickMcCeil" },
                            { id: "Sick Leave (Without MC)", show: "lSickNoMcShow", ceil: "lSickNoMcCeil" },
                            { id: "Annual Leave", show: "lAnnualShow", ceil: "lAnnualCeil" },
                            { id: "Family Leave", show: "lFamilyShow", ceil: "lFamilyCeil" }
                        ];
                        globalVisibleLeaveTypes = types.filter(t => {
                            const el = document.getElementById(t.show);
                            return el && el.checked;
                        }).map(t => t.id);
                        localStorage.setItem('physioVisibleLeaveTypes', JSON.stringify(globalVisibleLeaveTypes));
                        const ceilings = {};
                        types.forEach(t => {
                            const el = document.getElementById(t.ceil);
                            if (el) ceilings[t.id] = parseInt(el.value) || 30;
                        });
                        localStorage.setItem('physioLeaveCeilings', JSON.stringify(ceilings));
                        populateLeaveTypeDropdown();
                        customAlert("Roster leave rules ceiling values successfully written.");
                    }

                    function populateLeaveTypeDropdown() {
                        const sel = document.getElementById('formLeaveType');
                        if (!sel) return;
                        try {
                            const saved = localStorage.getItem('physioVisibleLeaveTypes');
                            if (saved) globalVisibleLeaveTypes = JSON.parse(saved);
                        } catch (e) { }
                        let formTypes = globalVisibleLeaveTypes.filter(t => t !== 'Sick Leave (With MC)' && t !== 'Sick Leave (Without MC)');
                        if (globalVisibleLeaveTypes.includes('Sick Leave (With MC)') || globalVisibleLeaveTypes.includes('Sick Leave (Without MC)')) {
                            if (!formTypes.includes('Sick Leave')) formTypes.push('Sick Leave');
                        }
                        const userEmail = currentActiveSessionUser?.email;
                        sel.innerHTML = formTypes.map(t => {
                            let exhausted = false, label = t;
                            if (t === 'Sick Leave') {
                                const mcEx = userEmail ? isLeaveExhausted(userEmail, 'Sick Leave', 'With MC') : false;
                                const noMcEx = userEmail ? isLeaveExhausted(userEmail, 'Sick Leave', 'Without MC') : false;
                                exhausted = mcEx && noMcEx;
                                if (exhausted) label += ' (exhausted)';
                            } else {
                                exhausted = userEmail ? isLeaveExhausted(userEmail, t, null) : false;
                                if (exhausted) label += ' (exhausted)';
                            }
                            return `<option value="${t}" ${exhausted ? 'disabled style="color:var(--text-muted);"' : ''}>${label}</option>`;
                        }).join('');
                    }

