                    function toggleStaffActiveStatus(email, isActive) {
                        const staff = globalRosterRepository.find(u => u.email === email);
                        if (!staff) return;

                        // Only Admin can toggle active status
                        if (currentActiveSessionUser.position !== "Admin") {
                            customAlert("Only Admin can change staff active status.");
                            return;
                        }

                        staff.active = isActive;
                        const status = isActive ? "activated" : "deactivated";
                        customAlert(`${staff.name} has been ${status}. ${isActive ? 'They can now log in.' : 'They can no longer access the portal.'}`);

                        // If deactivating the currently logged-in user, log them out
                        if (!isActive && currentActiveSessionUser.email === email) {
                            customAlert("You have deactivated your own account. Logging out...");
                            setTimeout(() => terminateSession(), 2000);
                        }

                        renderStaffComplianceDirectory();
                    }

                    function isStaffWithinProbationTimeline(hireDateString) {
                        if (!hireDateString) return false;
                        const hire = new Date(hireDateString);
                        const limit = new Date(hire.setMonth(hire.getMonth() + 3));
                        return new Date() < limit;
                    }

                    function getComplianceAlertState(dateStr) {
                        if (!dateStr || dateStr === "N/A") return { label: 'active', color: complianceColorActive };
                        const targetDate = new Date(dateStr);
                        const currentDate = new Date();

                        if (targetDate < currentDate) {
                            return { label: 'expired', color: complianceColorExpired };
                        }

                        const diffTime = Math.abs(targetDate - currentDate);
                        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                        if (diffDays <= complianceWarningDaysThreshold) {
                            return { label: 'warning', color: complianceColorWarning };
                        }

                        return { label: 'active', color: complianceColorActive };
                    }

                    function filterStaffDirectoryRows() {
                        const searchVal = document.getElementById('staffDirectorySearchField').value.trim().toLowerCase();
                        const contractFilter = document.getElementById('directoryContractFilter').value;
                        const roleGroupFilter = document.getElementById('directoryRoleGroupFilter').value;
                        const cards = document.querySelectorAll('#directoryGridAnchor .staff-card');

                        // Detect if the user is typing search group terms
                        const isFdoGroup = searchVal.length > 1 && ("fdo".includes(searchVal) || "front office".includes(searchVal) || "front desk".includes(searchVal));
                        const isTherapistGroup = searchVal.length > 1 && ("therapist".includes(searchVal) || "physiotherapist".includes(searchVal) || "physio".includes(searchVal));
                        const isManagementGroup = searchVal.length > 1 && ("management".includes(searchVal) || "manager".includes(searchVal) || "admin".includes(searchVal));
                        const isOtherGroup = searchVal.length > 1 && ("other".includes(searchVal) || "others".includes(searchVal) || "support".includes(searchVal) || "it".includes(searchVal));

                        cards.forEach((card, index) => {
                            const staff = globalRosterRepository[index];
                            if (!staff) return;

                            const posLower = staff.position.toLowerCase();

                            // Define structural role groups
                            const isFdo = (posLower.includes("fdo") || posLower.includes("front desk") || posLower.includes("front office"));
                            const isTherapist = (posLower.includes("physiotherapist") || posLower.includes("head of physio") || posLower.includes("training and recruitment"));
                            const isManagement = (posLower.includes("admin") || posLower.includes("general manager") || posLower.includes("operations manager") || posLower.includes("head of physio") || posLower.includes("training and recruitment"));

                            // "Other" is a catch-all for any role that is NOT FDO, Therapist, or Management
                            const isOther = !isFdo && !isTherapist && !isManagement;

                            // 1. Text Search Matching
                            const nameMatch = staff.name.toLowerCase().includes(searchVal);
                            const emailMatch = staff.email.toLowerCase().includes(searchVal);
                            let textMatch = nameMatch || emailMatch || posLower.includes(searchVal);

                            if (isFdoGroup && isFdo) {
                                textMatch = true;
                            }
                            if (isTherapistGroup && isTherapist) {
                                textMatch = true;
                            }
                            if (isManagementGroup && isManagement) {
                                textMatch = true;
                            }
                            if (isOtherGroup && isOther) {
                                textMatch = true;
                            }

                            // 2. Employment Contract Style Dropdown Match (including L and F checking)
                            const firstChar = staff.idCard ? staff.idCard.trim().toUpperCase().charAt(0) : "";
                            const isLocal = (firstChar === 'A');

                            let contractMatch = true;
                            if (contractFilter === "Full-Time" || contractFilter === "Part-Time") {
                                contractMatch = (staff.style === contractFilter);
                            } else if (contractFilter === "L") {
                                contractMatch = isLocal;
                            } else if (contractFilter === "F") {
                                contractMatch = !isLocal;
                            }

                            // 3. Role Group Dropdown Match
                            let roleGroupMatch = true;
                            if (roleGroupFilter === "fdo") {
                                roleGroupMatch = isFdo;
                            } else if (roleGroupFilter === "therapist") {
                                roleGroupMatch = isTherapist;
                            } else if (roleGroupFilter === "management") {
                                roleGroupMatch = isManagement;
                            } else if (roleGroupFilter === "other") {
                                roleGroupMatch = isOther;
                            }

                            // Render matching cards and hide the rest
                            if (textMatch && contractMatch && roleGroupMatch) {
                                card.classList.remove('hidden');
                            } else {
                                card.classList.add('hidden');
                            }
                        });
                    }

