function compressLogoWithBgRemove(file, maxDimension) {
    return new Promise(function (resolve, reject) {
        if (!file.type.startsWith('image/')) {
            var fr = new FileReader();
            fr.onloadend = function () { resolve(fr.result); };
            fr.onerror = reject;
            fr.readAsDataURL(file);
            return;
        }
        var reader = new FileReader();
        reader.onload = function (e) {
            var img = new Image();
            img.onload = function () {
                var w = img.width, h = img.height;
                if (w > maxDimension || h > maxDimension) {
                    if (w > h) { h = h * maxDimension / w; w = maxDimension; }
                    else { w = w * maxDimension / h; h = maxDimension; }
                }
                var canvas = document.createElement('canvas');
                canvas.width = Math.round(w);
                canvas.height = Math.round(h);
                var ctx = canvas.getContext('2d');
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                var imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                var data = imageData.data;
                var edgePixels = [];
                for (var x = 0; x < canvas.width; x++) {
                    for (var y = 0; y < canvas.height; y++) {
                        if (x === 0 || y === 0 || x === canvas.width - 1 || y === canvas.height - 1) {
                            var idx = (y * canvas.width + x) * 4;
                            edgePixels.push({ r: data[idx], g: data[idx + 1], b: data[idx + 2] });
                        }
                    }
                }
                var avgR = 0, avgG = 0, avgB = 0;
                edgePixels.forEach(function (p) { avgR += p.r; avgG += p.g; avgB += p.b; });
                var len = edgePixels.length || 1;
                avgR = Math.round(avgR / len); avgG = Math.round(avgG / len); avgB = Math.round(avgB / len);
                var threshold = 60;
                for (var i = 0; i < data.length; i += 4) {
                    var dr = Math.abs(data[i] - avgR);
                    var dg = Math.abs(data[i + 1] - avgG);
                    var db = Math.abs(data[i + 2] - avgB);
                    if (dr + dg + db < threshold) {
                        data[i + 3] = 0;
                    }
                }
                ctx.putImageData(imageData, 0, 0);
                resolve(canvas.toDataURL('image/png'));
            };
            img.onerror = function () { resolve(e.target.result); };
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

function compressAndResizeImage(file, maxDimension, quality) {
    if (quality === undefined) quality = 0.85;
    return new Promise(function (resolve, reject) {
        if (!file.type.startsWith('image/')) {
            const fallbackReader = new FileReader();
            fallbackReader.onloadend = function () { resolve(fallbackReader.result); };
            fallbackReader.onerror = reject;
            fallbackReader.readAsDataURL(file);
            return;
        }
        var reader = new FileReader();
        reader.onload = function (e) {
            var img = new Image();
            img.onload = function () {
                var w = img.width, h = img.height;
                if (w > maxDimension || h > maxDimension) {
                    if (w > h) { h = h * maxDimension / w; w = maxDimension; }
                    else { w = w * maxDimension / h; h = maxDimension; }
                }
                if (w >= img.width && h >= img.height) {
                    resolve(e.target.result);
                    return;
                }
                var canvas = document.createElement('canvas');
                canvas.width = Math.round(w);
                canvas.height = Math.round(h);
                var ctx = canvas.getContext('2d');
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                resolve(canvas.toDataURL('image/jpeg', quality));
            };
            img.onerror = function () { resolve(e.target.result); };
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

function handleSimulatedStaffRegisterPhotoChange(inputElement, event) {
    if (event) event.stopPropagation();
    const file = inputElement.files[0];
    if (!file) return;
    compressAndResizeImage(file, 300).then(function (data) {
        newlyAddedStaffProfilePhotoBase64 = data;
    });
}

