                    // Dialog Modal to manage diagnosis options (add, edit, delete)
                    function openAddDiagnosisOptionModal() {
                        const mount = document.getElementById('systemGlobalModalMount');
                        let existingHtml = globalDiagnosisOptions.map((opt, idx) => `
                <div style="display:flex; gap:6px; align-items:center; margin-bottom:4px;">
                    <input type="text" id="editDiagOption_${idx}" value="${escapeHtml(opt)}" style="flex:1; padding:6px; border-radius:4px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-size:11px;">
                    <button class="action-btn" onclick="commitEditDiagnosisOption(${idx})" style="padding:2px 6px; font-size:9px; background:var(--primary);">💾</button>
                    <button class="action-btn" onclick="commitDeleteDiagnosisOption(${idx})" style="padding:2px 6px; font-size:9px; background:var(--danger);">🗑️</button>
                </div>
            `).join("");

                        mount.innerHTML = `
                <div class="system-inline-modal-overlay">
                    <div class="system-inline-modal-box" style="width: 400px;">
                        <h3 style="margin-bottom: 12px; border-bottom:1px solid var(--border); padding-bottom:6px;">Manage Diagnosis Options</h3>
                        <div style="margin-bottom:12px; max-height:200px; overflow-y:auto;">
                            ${existingHtml || '<p style="color:var(--text-muted); font-size:11px;">No options yet.</p>'}
                        </div>
                        <div style="border-top:1px solid var(--border); padding-top:12px;">
                            <label style="font-weight:600; font-size:11px;">Add New Diagnosis</label>
                            <div style="display:flex; gap:6px;">
                                <input type="text" id="newDiagnosisOptionName" placeholder="e.g. Rotator Cuff Tear" style="flex:1; padding:6px; border-radius:4px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-size:11px;">
                                <button class="action-btn" style="background:var(--success);" onclick="commitAddDiagnosisOption()">➕ Add</button>
                            </div>
                        </div>
                        <div style="display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px;">
                            <button class="action-btn" style="background: var(--danger);" onclick="closeSystemModalBox()">Close</button>
                        </div>
                    </div>
                </div>
            `;
                    }

                    function commitAddDiagnosisOption() {
                        const inputVal = document.getElementById('newDiagnosisOptionName').value.trim();
                        if (!inputVal) {
                            customAlert("Please enter a valid diagnosis name.");
                            return;
                        }
                        if (globalDiagnosisOptions.includes(inputVal)) {
                            customAlert("This option is already registered.");
                            return;
                        }
                        globalDiagnosisOptions.push(inputVal);
                        renderDischargeCustomFieldsFormInputs();
                        openAddDiagnosisOptionModal();
                    }

                    function commitEditDiagnosisOption(idx) {
                        const inputEl = document.getElementById(`editDiagOption_${idx}`);
                        if (!inputEl) return;
                        const newVal = inputEl.value.trim();
                        if (!newVal) {
                            customAlert("Diagnosis name cannot be empty.");
                            return;
                        }
                        const oldVal = globalDiagnosisOptions[idx];
                        if (newVal !== oldVal && globalDiagnosisOptions.includes(newVal)) {
                            customAlert("This option is already registered.");
                            return;
                        }
                        globalDiagnosisOptions[idx] = newVal;
                        renderDischargeCustomFieldsFormInputs();
                        openAddDiagnosisOptionModal();
                    }

                    function commitDeleteDiagnosisOption(idx) {
                        customConfirm(`Delete "${globalDiagnosisOptions[idx]}"?`, (confirmed) => {
                            if (confirmed) {
                                globalDiagnosisOptions.splice(idx, 1);
                                renderDischargeCustomFieldsFormInputs();
                                openAddDiagnosisOptionModal();
                            }
                        });
                    }

                    function markFieldInvalid(id, msg) {
                        const el = document.getElementById(id);
                        if (el) {
                            el.style.border = "2px solid red";
                            el.style.outline = "2px solid red";
                            el.scrollIntoView({ behavior: "smooth", block: "center" });
                        }
                        customAlert(msg);
                    }

                    function commitDischargeRecordToMemory() {
                        // Clear previous red borders
                        document.querySelectorAll('#dischargeEntryFormInputs input, #dischargeEntryFormInputs select, #dischargeEntryFormInputs textarea').forEach(el => {
                            el.style.border = "";
                            el.style.outline = "";
                        });
                        // Find and validate input fields
                        const nameInput = document.getElementById('pDischargeField_name');
                        const idCardInput = document.getElementById('pDischargeField_idCard');
                        const therapistInput = document.getElementById('pDischargeField_therapistName');
                        const startDateInput = document.getElementById('pDischargeField_startDate');
                        const endDateInput = document.getElementById('pDischargeField_endDate');
                        const sessionsInput = document.getElementById('pDischargeField_sessions');

                        const nameVal = nameInput ? nameInput.value.trim() : "";
                        const idCardVal = idCardInput ? idCardInput.value.trim() : "";
                        const startDateVal = startDateInput ? startDateInput.value : "";
                        const endDateVal = endDateInput ? endDateInput.value : "";
                        const sessionsVal = sessionsInput ? sessionsInput.value.trim() : "";

                        // Strict inputs validation checks (blocks empty submissions)
                        if (!nameVal) {
                            markFieldInvalid('pDischargeField_name', "Validation Error: Please enter a Name.");
                            return;
                        }
                        if (!idCardVal) {
                            markFieldInvalid('pDischargeField_idCard', "Validation Error: Please enter an ID Card number.");
                            return;
                        }
                        if (!startDateVal) {
                            markFieldInvalid('pDischargeField_startDate', "Validation Error: Please select a Start Date.");
                            return;
                        }
                        if (!endDateVal) {
                            markFieldInvalid('pDischargeField_endDate', "Validation Error: Please select an End Date.");
                            return;
                        }
                        if (!sessionsVal) {
                            markFieldInvalid('pDischargeField_sessions', "Validation Error: Please enter Number of Sessions.");
                            return;
                        }
                        const notesVal = (document.getElementById('pDischargeField_notes')?.value || "").trim();
                        if (notesVal.length <= 20) {
                            markFieldInvalid('pDischargeField_notes', "Notes must be more than 20 characters.");
                            return;
                        }

                        const endDateMonth = endDateVal.substring(0, 7);
                        const monthRecords = dischargeRecords.filter(r => r.endDate && r.endDate.startsWith(endDateMonth));
                        const nextNumber = monthRecords.reduce((max, r) => Math.max(max, parseInt(r.number, 10) || 0), 0) + 1;

                        let record = {
                            id: Date.now(),
                            dischargedBy: currentActiveSessionUser.name,
                            dischargedByEmail: currentActiveSessionUser.email,
                            number: nextNumber,
                            name: nameVal,
                            idCard: idCardVal,
                            therapistName: currentActiveSessionUser.name,
                            startDate: startDateVal,
                            endDate: endDateVal,
                            sessions: parseInt(sessionsVal, 10) || 0,
                            diagnosis: (document.getElementById('pDischargeField_diagnosis')?.value || "").trim(),
                            notes: (document.getElementById('pDischargeField_notes')?.value || "").trim()
                        };

                        dischargeRecords.push(record);
                        saveDischargeRecords();

                        // Re-render the form to reset fields and auto-increment Number
                        renderDischargeCustomFieldsFormInputs();

                        // Set the active month pickers to the newly saved month and year
                        const yearStr = endDateVal.substring(0, 4);
                        const monthStr = endDateVal.substring(5, 7);
                        const newCycleVal = `${yearStr}-${monthStr}`;

                        // Populate the new discharge dropdown selectors first
                        const cycleSel = document.getElementById('dischargeCycleSelector');
                        const summarySel = document.getElementById('dischargeSummaryCycleSelector');
                        if (cycleSel) cycleSel.value = newCycleVal;
                        if (summarySel) summarySel.value = newCycleVal;
                        // Instantly refresh the tables on current view
                        renderDischargeRecordsTable();
                        renderDischargeSummaryTable();

                        customAlert(`Discharge entry successfully saved for sheet: ${newCycleVal}`);
                        closeDischargeRegistrationModal();
                    }

