                    // Master rendering router for the Inventory workspace
                    // Master rendering router for the Inventory workspace
                    function renderSuppliesLedgerDashboard() {
                        const parentContainer = document.getElementById('mod_inventory');
                        if (!parentContainer) return;
                        parentContainer.innerHTML = "";

                        const isManagerial = allowedInventoryManagerRoles.includes(currentActiveSessionUser.position);

                        if (isManagerial) {
                            renderManagerSuppliesWorkspace(parentContainer);
                        } else {
                            renderStaffSuppliesWorkspace(parentContainer);
                        }
                    }

                    // Filter inventory items visible to the current user's role
                    function getVisibleInventoryItems() {
                        const userRole = currentActiveSessionUser ? currentActiveSessionUser.position : '';
                        const isManagerial = allowedInventoryManagerRoles.includes(userRole);
                        if (isManagerial && window._invShowAll) return inventoryRepository;
                        return inventoryRepository.filter(item => {
                            if (!item.visibleTo || item.visibleTo === 'all') return true;
                            const roles = item.visibleTo.split(',');
                            return roles.includes(userRole);
                        });
                    }

                    // ==========================================
                    // CORRECTED MANAGER WORKSPACE VIEW
                    // ==========================================
                    function renderManagerSuppliesWorkspace(container) {
                        // Read the cycle value from the persistent global window state, fallback to today's month if unset
                        if (!window.globalInventorySelectedCycle) {
                            window.globalInventorySelectedCycle = getTodayISOString().substring(0, 7);
                        }
                        const cycleVal = window.globalInventorySelectedCycle;

                        // 1. Pinned Supplies Monitors
                        const pinboardSection = document.createElement('div');
                        pinboardSection.className = "module-card span-12";
                        pinboardSection.style.borderTop = "4px solid var(--primary)";
                        pinboardSection.innerHTML = `
        <h3 id="lbl_inventory_pinboard_header">📌 Pinned Supplies Monitoring Center</h3>
        <p style="color:var(--text-muted); margin-bottom:12px; font-size:10px;">High-priority indicators showing absolute stock levels of checked items.</p>
        <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(140px, 1fr)); gap:12px;" id="inventoryPinboardContainer"></div>
    `;
                        container.appendChild(pinboardSection);

                        // Populate monitors
                        const pinboard = pinboardSection.querySelector('#inventoryPinboardContainer');
                        const pinnedSupplies = getVisibleInventoryItems().filter(i => i.pinned === true);
                        if (pinnedSupplies.length === 0) {
                            pinboard.innerHTML = `<div style="grid-column: span 12; text-align:center; color:var(--text-muted); font-style:italic; font-size:11px;">No supplies pinned to indicators. Mark pin checkboxes below.</div>`;
                        } else {
                            pinnedSupplies.forEach(item => {
                                const isLow = item.stock <= item.minLimit;
                                const card = document.createElement('div');
                                card.className = "balance-mini-card";
                                card.style.borderTop = isLow ? "4px solid var(--danger)" : "4px solid var(--success)";
                                card.innerHTML = `
                <h5>${item.name}</h5>
                <div class="counter-value">${item.stock} ${item.unit || 'Units'}</div>
                <span class="badge ${isLow ? 'badge-danger' : 'badge-success'}" style="margin-top:4px;">${isLow ? 'Critical Low' : 'Adequate'}</span>
            `;
                                pinboard.appendChild(card);
                            });
                        }

                        // 2. Master Stock Ledger
                        const ledgerSection = document.createElement('div');
                        ledgerSection.className = "module-card span-12";
                        ledgerSection.style.borderTop = "4px solid var(--primary)";

                        const visibleItems = getVisibleInventoryItems();
                        let tableRowsHtml = "";
                        if (visibleItems.length === 0) {
                            tableRowsHtml = `<tr><td colspan="6" style="text-align:center; color:var(--text-muted); font-style:italic; padding:20px;">No supplies recorded in database.</td></tr>`;
                        } else {
                            visibleItems.forEach(item => {
                                const realIndex = inventoryRepository.findIndex(i => i.id === item.id);
                                const isLow = item.stock <= item.minLimit;
                                tableRowsHtml += `
                <tr>
                    <td>
                        <div style="display:flex; align-items:center; gap:6px;">
                            <input type="checkbox" ${item.pinned ? 'checked' : ''} onchange="toggleInventoryPinState(${realIndex})">
                            <strong>${item.name}</strong>
                        </div>
                    </td>
                    <td>${item.category}</td>
                    <td>
                        <strong>${item.stock} ${item.unit || 'Units'}</strong>
                    </td>
                    <td>
                        <div style="display:flex; align-items:center; gap:6px;">
                            <input type="number" value="${item.minLimit}" style="width:50px; padding:2px; font-size:11px;" onchange="updateInventoryMinLimit(${realIndex}, this.value)">
                            <span class="badge ${isLow ? 'badge-danger' : 'badge-success'}">${isLow ? 'Low Stock' : 'Optimal'}</span>
                        </div>
                    </td>
                    <td><div onclick="changeInventoryVisibleTo(${realIndex})" style="cursor:pointer; display:flex; gap:3px; flex-wrap:wrap; font-size:9px;">
                        ${(!item.visibleTo || item.visibleTo === 'all')
                                        ? '<span style="background:var(--primary-light); padding:1px 6px; border-radius:4px;">All Staff</span>'
                                        : item.visibleTo.split(',').map(r => `<span style="background:var(--bg-inner); border:1px solid var(--border); padding:1px 6px; border-radius:4px;">${r.trim()}</span>`).join('')}
                    </div></td>
                    <td>
                        <div style="display:flex; gap:6px; justify-content:center; align-items:center;">
                            <input type="number" id="managerRefillCount_${item.id}" placeholder="Qty" style="width:50px; padding:2px; font-size:11px; text-align:center;">
                            <button class="action-btn" style="background:var(--success); padding:4px 8px; font-size:10px;" onclick="addInventoryStockFromManager(${realIndex}, ${item.id})">Add</button>
                            <button class="action-btn" style="background:var(--danger); padding:4px 8px; font-size:10px;" onclick="deleteInventoryItem(${realIndex})" title="Delete this supply item">🗑️ Delete</button>
                        </div>
                    </td>
                </tr>
            `;
                            });
                        }

                        ledgerSection.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:12px;">
            <div>
                <h3>📋 Master Stock Inventory</h3>
                <p style="color:var(--text-muted); font-size:10px; margin:0;">Complete view of items, running counts, and refill actions (Supervisors Only).</p>
            </div>
            <div style="display:flex; gap:6px; align-items:center;">
                <label style="font-size:9px; color:var(--text-muted); display:flex; align-items:center; gap:4px; cursor:pointer;">
                    <input type="checkbox" id="invShowAllToggle" ${window._invShowAll ? 'checked' : ''} onchange="window._invShowAll = this.checked; renderSuppliesLedgerDashboard();">
                    Show all items
                </label>
                <button class="action-btn" style="background:var(--primary); padding: 6px 10px; font-size:11px;" onclick="exportInventoryToPDF()">🖨️ Export PDF</button>
                <button class="action-btn" style="background:var(--success); padding: 6px 10px; font-size:11px;" onclick="exportInventoryToExcel()">📥 Export Excel</button>
                <button class="action-btn" onclick="openAddNewInventoryModal()">➕ Add New Supply Item</button>
            </div>
        </div>

        <table class="premium-table" style="margin-top:0;">
            <thead>
                <tr>
                    <th style="text-align:left;">Supply Item</th>
                    <th>Category</th>
                    <th>Remaining Stock</th>
                    <th>Threshold Warnings</th>
                    <th>Visible To</th>
                    <th>Refill Actions</th>
                </tr>
            </thead>
            <tbody>
                ${tableRowsHtml}
            </tbody>
        </table>
    `;
                        container.appendChild(ledgerSection);

                        // 3. Supervisor Audit Log Table (Filtered by persistent Active Cycle state)
                        const auditSection = document.createElement('div');
                        auditSection.className = "module-card span-12";
                        auditSection.style.borderTop = "4px solid var(--primary)";

                        // Filter audit records matching the active cycle
                        const filteredAuditLog = inventoryAuditLog.filter(log => log.cycle === cycleVal);

                        let auditRowsHtml = "";
                        filteredAuditLog.forEach(log => {
                            const badgeClass = log.actionType === 'Used' ? 'badge-warning' : 'badge-success';
                            auditRowsHtml += `
            <tr>
                <td><strong>${log.date}</strong></td>
                <td><strong>${log.itemName}</strong></td>
                <td><span class="badge ${badgeClass}">${log.actionType}</span></td>
                <td><strong>${log.quantity}</strong></td>
                <td><strong>${log.staffName}</strong></td>
                <td style="text-align:left;">${log.remarks || '-'}</td>
            </tr>
        `;
                        });

                        if (filteredAuditLog.length === 0) {
                            auditRowsHtml = `<tr><td colspan="6" style="text-align:center; color:var(--text-muted); font-style:italic; padding:16px;">No transaction logs match the selected cycle month: ${cycleVal}.</td></tr>`;
                        }

                        auditSection.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:12px;">
            <div>
                <h3>📜 Supplies Transaction Log & Audit Ledger</h3>
                <p style="color:var(--text-muted); font-size:10px; margin:0;">Real-time chronological record of stock changes with staff names and dates.</p>
            </div>
            <div class="form-group" style="margin-bottom:0; display:flex; align-items:center; gap:6px;">
                <label style="margin-bottom:0; white-space:nowrap; font-weight:700; font-size:10px; color:var(--text-muted);">SELECT CYCLE:</label>
                <input type="month" id="inventoryCycleSelector" value="${cycleVal}" onchange="window.globalInventorySelectedCycle = this.value; renderSuppliesLedgerDashboard();" style="padding:6px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-family:inherit; font-size:11px; height:28px; cursor:pointer;">
            </div>
        </div>
        <div style="overflow-y:auto; max-height:220px; border:1px solid var(--border); border-radius:8px;">
            <table class="premium-table" style="margin-top:0;">
                <thead>
                    <tr>
                        <th>Date & Time</th>
                        <th>Item</th>
                        <th>Action</th>
                        <th>Quantity</th>
                        <th>Logged By</th>
                        <th style="text-align:left;">Remarks / Usage Notes</th>
                    </tr>
                </thead>
                <tbody>
                    ${auditRowsHtml}
                </tbody>
            </table>
        </div>
    `;
                        container.appendChild(auditSection);
                    }

                    // ==========================================
                    // CORRECTED STAFF WORKSPACE VIEW
                    // ==========================================
                    function renderStaffSuppliesWorkspace(container) {
                        // Read the cycle value from the persistent global window state, fallback to today's month if unset
                        if (!window.globalStaffInventorySelectedCycle) {
                            window.globalStaffInventorySelectedCycle = getTodayISOString().substring(0, 7);
                        }
                        const staffCycleVal = window.globalStaffInventorySelectedCycle;

                        // 1. Report Supply Consumption Form
                        const requestSection = document.createElement('div');
                        requestSection.className = "module-card span-4";
                        requestSection.style.borderTop = "4px solid var(--primary)";

                        let itemOptions = getVisibleInventoryItems().map(i => `<option value="${i.id}">${i.name} (${i.category})</option>`).join("");

                        requestSection.innerHTML = `
        <h3>✍️ Report Supply Consumption</h3>
        <p style="color:var(--text-muted); font-size:10px; margin-bottom:14px;">Select the clinical item you used, state the quantity, and write the purpose.</p>
        
        <div style="display:flex; flex-direction:column; gap:12px;">
            <div class="form-group" style="margin-bottom:0;">
                <label>Select Item Used</label>
                <select id="staffUsageItemSelector" style="width:100%; height:32px;">
                    ${itemOptions}
                </select>
            </div>
            <div class="form-group" style="margin-bottom:0;">
                <label>Quantity Taken</label>
                <input type="number" id="staffUsageQuantity" value="1" min="1" max="100" style="height:32px;">
            </div>
            <div class="form-group" style="margin-bottom:0;">
                <label>Purpose / Treatment Notes</label>
                <textarea id="staffUsageRemarks" placeholder="Add rehab patient reference, treatment floor, or custom notes..." style="height:60px; resize:none;"></textarea>
            </div>
            <button class="action-btn" style="background:var(--primary); justify-content:center; padding:10px;" onclick="commitStaffSupplyUsage()">
                Submit Stock Consumption
            </button>
        </div>
    `;
                        container.appendChild(requestSection);

                        // 2. Personal Usage History Log
                        const historySection = document.createElement('div');
                        historySection.className = "module-card span-8";
                        historySection.style.borderTop = "4px solid var(--primary)";

                        // Filter personal logs matching both the staff name and the chosen month cycle
                        const myLogs = inventoryAuditLog.filter(log =>
                            log.staffName === currentActiveSessionUser.name &&
                            log.actionType === 'Used' &&
                            log.cycle === staffCycleVal
                        );

                        let historyRowsHtml = "";
                        myLogs.forEach(log => {
                            historyRowsHtml += `
            <tr>
                <td><strong>${log.date}</strong></td>
                <td><strong>${log.itemName}</strong></td>
                <td><strong>${log.quantity}</strong></td>
                <td style="text-align:left;">${log.remarks || '-'}</td>
            </tr>
        `;
                        });

                        if (myLogs.length === 0) {
                            historyRowsHtml = `<tr><td colspan="4" style="text-align:center; color:var(--text-muted); font-style:italic; padding:16px;">No usages logged during cycle month: ${staffCycleVal}.</td></tr>`;
                        }

                        historySection.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:12px;">
            <div>
                <h3>📜 Your Logged Usage History</h3>
                <p style="color:var(--text-muted); font-size:10px; margin:0;">Your personal chronological tracking list of consumed materials.</p>
            </div>
            <div style="display:flex; gap:6px; align-items:center;">
                <button class="action-btn" style="background:var(--primary); padding: 4px 8px; height:28px;" onclick="exportInventoryToPDF()">🖨️ PDF</button>
                <button class="action-btn" style="background:var(--success); padding: 4px 8px; height:28px;" onclick="exportInventoryToExcel()">📥 Excel</button>
            </div>
            <div class="form-group" style="margin-bottom:0; display:flex; align-items:center; gap:6px;">
                <label style="margin-bottom:0; white-space:nowrap; font-weight:700; font-size:10px; color:var(--text-muted);">SELECT CYCLE:</label>
                <input type="month" id="staffInventoryCycleSelector" value="${staffCycleVal}" onchange="window.globalStaffInventorySelectedCycle = this.value; renderSuppliesLedgerDashboard();" style="padding:6px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-family:inherit; font-size:11px; height:28px; cursor:pointer;">
            </div>
        </div>
        
        <div style="overflow-y:auto; max-height:300px; border:1px solid var(--border); border-radius:8px;">
            <table class="premium-table" style="margin-top:0;">
                <thead>
                    <tr>
                        <th>Date & Time</th>
                        <th>Supply Item</th>
                        <th>Quantity Used</th>
                        <th style="text-align:left;">Remarks & Clinical Intent</th>
                    </tr>
                </thead>
                <tbody>
                    ${historyRowsHtml}
                </tbody>
            </table>
        </div>
    `;
                        container.appendChild(historySection);
                    }

                    // Staff submits a stock usage subtraction
                    function commitStaffSupplyUsage() {
                        const itemId = parseInt(document.getElementById('staffUsageItemSelector').value);
                        const qty = parseInt(document.getElementById('staffUsageQuantity').value) || 0;
                        const remarks = document.getElementById('staffUsageRemarks').value.trim();

                        const item = inventoryRepository.find(i => i.id === itemId);
                        if (!item) return;

                        if (qty <= 0) {
                            customAlert("Please enter a valid quantity.");
                            return;
                        }

                        // Process subtraction dynamically
                        item.stock = Math.max(0, item.stock - qty);

                        const now = new Date();
                        const yyyy = now.getFullYear();
                        const mm = String(now.getMonth() + 1).padStart(2, '0');
                        const dd = String(now.getDate()).padStart(2, '0');

                        // Create synchronized audit fields
                        const cycleStr = `${yyyy}-${mm}`;
                        const dateStr = `${dd}/${mm}/${yyyy}, ${now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;

                        inventoryAuditLog.unshift({
                            id: Date.now(),
                            date: dateStr,
                            cycle: cycleStr,
                            itemName: item.name,
                            staffName: currentActiveSessionUser.name,
                            actionType: "Used",
                            quantity: qty,
                            remarks: remarks || "Logged from clinic workspace desk"
                        });

                        // Reset Form fields
                        document.getElementById('staffUsageQuantity').value = "1";
                        document.getElementById('staffUsageRemarks').value = "";

                        customAlert(`Usage recorded successfully! Stock subtraction processed.`);
                        renderSuppliesLedgerDashboard();
                    }

                    // Supervisor adds/refills master stock level
                    function addInventoryStockFromManager(repoIndex, itemId) {
                        const input = document.getElementById(`managerRefillCount_${itemId}`);
                        if (!input) return;

                        const qty = parseInt(input.value) || 0;
                        if (qty <= 0) {
                            customAlert("Please enter a valid refill amount.");
                            return;
                        }

                        const item = inventoryRepository[repoIndex];
                        if (item) {
                            item.stock += qty;

                            const now = new Date();
                            const yyyy = now.getFullYear();
                            const mm = String(now.getMonth() + 1).padStart(2, '0');
                            const dd = String(now.getDate()).padStart(2, '0');

                            // Create synchronized audit fields
                            const cycleStr = `${yyyy}-${mm}`;
                            const dateStr = `${dd}/${mm}/${yyyy}, ${now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;

                            inventoryAuditLog.unshift({
                                id: Date.now(),
                                date: dateStr,
                                cycle: cycleStr,
                                itemName: item.name,
                                staffName: currentActiveSessionUser.name,
                                actionType: "Refilled",
                                quantity: qty,
                                remarks: "Managerial batch replenishment"
                            });

                            input.value = "";
                            saveInventoryRepository();
                            saveInventoryAuditLog();
                            customAlert(`Refilled ${qty} units for ${item.name}.`);
                            renderSuppliesLedgerDashboard();
                        }
                    }

                    function changeInventoryVisibleTo(index) {
                        const item = inventoryRepository[index];
                        if (!item) return;
                        const currentRoles = item.visibleTo && item.visibleTo !== 'all' ? item.visibleTo.split(',') : [];
                        const allRoles = [...new Set(globalRosterRepository.map(u => u.position).filter(Boolean))];
                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `
        <div class="system-inline-modal-overlay">
            <div class="system-inline-modal-box" style="width:320px;">
                <h3 style="margin-bottom:12px; border-bottom:1px solid var(--border); padding-bottom:6px;">👁️ Visible To — ${item.name}</h3>
                <p style="font-size:10px; color:var(--text-muted); margin-bottom:8px;">Select which roles can see this item:</p>
                <div style="max-height:240px; overflow-y:auto; display:flex; flex-direction:column; gap:4px; margin-bottom:12px;">
                    <label style="display:flex; align-items:center; gap:6px; font-size:11px; cursor:pointer; padding:4px 0;">
                        <input type="checkbox" id="invVisAll" ${currentRoles.length === 0 ? 'checked' : ''} onchange="document.querySelectorAll('.inv-vis-role-cb').forEach(c=>c.checked=!this.checked)">
                        <strong>All Staff</strong>
                    </label>
                    ${allRoles.map(r => `
                        <label style="display:flex; align-items:center; gap:6px; font-size:11px; cursor:pointer; padding:4px 0;">
                            <input type="checkbox" class="inv-vis-role-cb" value="${r}" ${currentRoles.includes(r) ? 'checked' : ''} onchange="if(this.checked)document.getElementById('invVisAll').checked=false">
                            ${r}
                        </label>
                    `).join('')}
                </div>
                <div style="display:flex; gap:8px; justify-content:flex-end;">
                    <button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Cancel</button>
                    <button class="action-btn" style="background:var(--primary);" onclick="saveInventoryVisibility(${index})">Save</button>
                </div>
            </div>
        </div>
    `;
                    }

                    function saveInventoryVisibility(index) {
                        const allCheck = document.getElementById('invVisAll');
                        if (allCheck && allCheck.checked) {
                            inventoryRepository[index].visibleTo = 'all';
                        } else {
                            const checked = [...document.querySelectorAll('.inv-vis-role-cb:checked')].map(cb => cb.value);
                            inventoryRepository[index].visibleTo = checked.length ? checked.join(',') : 'all';
                        }
                        closeSystemModalBox();
                        saveInventoryRepository();
                        customAlert("Visibility updated.");
                        renderSuppliesLedgerDashboard();
                    }

                    // Standard helper configurations
                    function toggleInventoryPinState(index) {
                        inventoryRepository[index].pinned = !inventoryRepository[index].pinned;
                        saveInventoryRepository();
                        renderSuppliesLedgerDashboard();
                    }

                    function updateInventoryMinLimit(index, value) {
                        inventoryRepository[index].minLimit = parseInt(value) || 0;
                        saveInventoryRepository();
                        renderSuppliesLedgerDashboard();
                    }

                    function adjustSuppliesCountValue(index, modifier) {
                        inventoryRepository[index].stock = Math.max(0, inventoryRepository[index].stock + modifier);
                        saveInventoryRepository();
                        renderSuppliesLedgerDashboard();
                    }

                    // Delete a supply item permanently from the inventory
                    function deleteInventoryItem(index) {
                        const item = inventoryRepository[index];
                        if (!item) return;
                        customConfirm(`Delete "${item.name}" from inventory? This cannot be undone.`, () => {
                            inventoryRepository.splice(index, 1);
                            saveInventoryRepository();
                            customAlert(`"${item.name}" has been deleted.`);
                            renderSuppliesLedgerDashboard();
                        });
                    }

                    function openAddNewInventoryModal() {
                        const roleOptions = [...new Set(globalRosterRepository.map(u => u.position).filter(Boolean))].map(r => `<option value="${r}">${r}</option>`).join('');
                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `
        <div class="system-inline-modal-overlay">
            <div class="system-inline-modal-box">
                <h3 style="margin-bottom:12px; border-bottom:1px solid var(--border); padding-bottom:6px;">➕ Register Supply Item</h3>
                <div class="form-group"><label>Item Reference Name</label><input type="text" id="invAddName"></div>
                <div class="form-group"><label>Category Group</label><input type="text" id="invAddCat" value="Consumables"></div>
                <div class="form-group"><label>Date Registered</label><input type="date" id="invAddDate" value="${getTodayISOString()}"></div>
                <div class="form-group"><label>Starting Stock level</label><input type="number" id="invAddSt" value="20"></div>
                <div class="form-group"><label>Minimum Threshold limit</label><input type="number" id="invAddTh" value="10"></div>
                <div class="form-group"><label>Unit type</label><input type="text" id="invAddUn" value="Units"></div>
                <div class="form-group">
                    <label>Visible To</label>
                    <select id="invAddVisible" style="width:100%; padding:6px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-size:11px;">
                        <option value="all">All Staff</option>
                        ${roleOptions}
                    </select>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:16px;">
                    <button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Dismiss</button>
                    <button class="action-btn" style="background:var(--primary);" onclick="commitAddNewInventoryItem()">Register Item</button>
                </div>
            </div>
        </div>
    `;
                    }

                    function commitAddNewInventoryItem() {
                        const name = document.getElementById('invAddName').value.trim();
                        const cat = document.getElementById('invAddCat').value.trim();
                        const date = document.getElementById('invAddDate').value;
                        const stock = parseInt(document.getElementById('invAddSt').value);
                        const thresh = parseInt(document.getElementById('invAddTh').value);
                        const unit = document.getElementById('invAddUn').value;
                        const visibleTo = document.getElementById('invAddVisible').value;

                        if (!name) { customAlert("Please provide valid supply information."); return; }
                        inventoryRepository.push({
                            id: Date.now(),
                            name: name,
                            category: cat,
                            date: date || new Date().toISOString().split('T')[0],
                            stock: stock,
                            minLimit: thresh,
                            unit: unit,
                            pinned: false,
                            visibleTo: visibleTo || 'all'
                        });
                        saveInventoryRepository();
                        closeSystemModalBox();
                        synchronizeWorkspaceCoreStatus();
                    }



                    // ===== EXPORT HUB FILTER HELPERS =====
                    function toggleExportDateInputs() {
                        const val = document.getElementById('exportDateRangeType').value;
                        ['exportDateDailyWrap', 'exportDateMonthlyWrap', 'exportDateYearlyWrap', 'exportDateFromWrap', 'exportDateToWrap'].forEach(id => {
                            document.getElementById(id).style.display = 'none';
                        });
                        if (val === 'daily') document.getElementById('exportDateDailyWrap').style.display = '';
                        else if (val === 'monthly') document.getElementById('exportDateMonthlyWrap').style.display = '';
                        else if (val === 'yearly') document.getElementById('exportDateYearlyWrap').style.display = '';
                        else if (val === 'custom') { document.getElementById('exportDateFromWrap').style.display = ''; document.getElementById('exportDateToWrap').style.display = ''; }
                    }

                    function toggleExportSingleStaff() {
                        const val = document.getElementById('exportStaffFilter').value;
                        document.getElementById('exportRoleWrap').style.display = val === 'role' ? '' : 'none';
                        document.getElementById('exportSingleStaffWrap').style.display = val === 'single' ? '' : 'none';
                        if (val === 'role') populateExportRoleSelector();
                        if (val === 'single') populateExportStaffSelector();
                    }

                    function populateExportRoleSelector() {
                        const sel = document.getElementById('exportRoleSelector');
                        if (!sel) return;
                        const roles = [...new Set(globalRosterRepository.map(s => s.position).filter(Boolean))];
                        sel.innerHTML = '<option value="">All Roles</option>' + roles.map(r => `<option value="${r}">${r}</option>`).join('');
                    }

                    function populateExportStaffSelector() {
                        const sel = document.getElementById('exportSingleStaffSelector');
                        if (!sel) return;
                        sel.innerHTML = '<option value="">Select Staff</option>' + globalRosterRepository.map(s => `<option value="${s.email}">${s.name} — ${s.position}</option>`).join('');
                    }

                    function getExportDateFilter() {
                        const type = document.getElementById('exportDateRangeType').value;
                        if (type === 'all') return null;
                        if (type === 'daily') {
                            const d = document.getElementById('exportDateDaily').value;
                            return d ? { start: d, end: d } : null;
                        }
                        if (type === 'monthly') {
                            const m = document.getElementById('exportDateMonthly').value;
                            return m ? { start: m + '-01', end: m + '-31' } : null;
                        }
                        if (type === 'yearly') {
                            const y = document.getElementById('exportDateYearly').value;
                            return y ? { start: y + '-01-01', end: y + '-12-31' } : null;
                        }
                        if (type === 'custom') {
                            const from = document.getElementById('exportDateFrom').value;
                            const to = document.getElementById('exportDateTo').value;
                            return (from && to) ? { start: from, end: to } : null;
                        }
                        return null;
                    }

                    function getExportStaffFilter() {
                        const type = document.getElementById('exportStaffFilter').value;
                        if (type === 'all') return null;
                        if (type === 'single') return document.getElementById('exportSingleStaffSelector').value || null;
                        return null;
                    }

                    function filterGlobalRoster(role, singleEmail) {
                        let filtered = [...globalRosterRepository];
                        if (role) filtered = filtered.filter(s => s.position === role);
                        if (singleEmail) filtered = filtered.filter(s => s.email === singleEmail);
                        return filtered;
                    }

                    // ===== MASTER EXPORT DISPATCHER =====
                    function runExport(source, mode) {
                        const dateFilter = getExportDateFilter();
                        const roleVal = document.getElementById('exportStaffFilter').value === 'role' ? document.getElementById('exportRoleSelector').value : null;
                        const singleEmail = document.getElementById('exportStaffFilter').value === 'single' ? document.getElementById('exportSingleStaffSelector').value : null;

                        let label = '';
                        const isExcel = mode === 'excel';

                        // Save originals for restoration
                        const origStaff = globalRosterRepository;
                        const origLeaves = globalLeaveRepository;
                        const origInventory = window.inventoryRepository || [];

                        // Apply staff filter
                        let effectiveStaff = globalRosterRepository;
                        if (roleVal) effectiveStaff = globalRosterRepository.filter(s => s.position === roleVal);
                        else if (singleEmail) effectiveStaff = globalRosterRepository.filter(s => s.email === singleEmail);

                        try {
                            if (source === 'staff_directory') {
                                label = 'Personnel Directory';
                                if (isExcel) {
                                    let csv = "Employee Name,Corporate Email,Position Profile,Agreement Class,ID Card Expiry,Licence Expiry,Contact Phone\n";
                                    effectiveStaff.forEach(s => csv += `"${s.name}","${s.email}","${s.position}","${s.style}","${s.idCardExpiry}","${s.healthLicenceExpiry}","${s.phone || ''}"\n`);
                                    triggerCSVDownload(`Personnel_Directory_${Date.now()}.csv`, csv);
                                } else {
                                    let rows = effectiveStaff.map(s => `<tr><td><strong>${s.name}</strong></td><td>${s.email}</td><td>${s.position}</td><td>${s.style}</td><td>${s.idCardExpiry}</td><td>${s.healthLicenceExpiry}</td></tr>`).join('');
                                    const logo = globalBrandingLogoUrl ? `<img src="${globalBrandingLogoUrl}" style="max-height:60px; display:block; margin:0 auto 12px;">` : '';
                                    const html = `
                            <div class="report-header">${logo}<p>Personnel Compliance Registry</p></div>
                            <div class="meta-details"><span><strong>Total Staff:</strong> ${effectiveStaff.length}</span><span><strong>Export Date:</strong> ${new Date().toLocaleDateString()}</span></div>
                            <table><thead><tr><th>Employee Name</th><th>Corporate Email</th><th>Position</th><th>Agreement Class</th><th>ID Card Expiry</th><th>Licence Expiry</th></tr></thead><tbody>${rows}</tbody></table>`;
                                    triggerPDFDownload(`Personnel_Directory_${Date.now()}.html`, html);
                                }

                            } else if (source === 'roster') {
                                label = 'Roster Matrix';
                                globalRosterRepository = effectiveStaff;
                                if (isExcel) { exportRosterToExcel(); } else { exportRosterToPDF(); }
                                globalRosterRepository = origStaff;

                            } else if (source === 'my_roster') {
                                label = 'My Personal Roster';
                                exportMyRosterToPDF();

                            } else if (source === 'leave' || source === 'leave_summary') {
                                label = 'Leave Ledger';
                                // Date filter for leaves
                                if (dateFilter) {
                                    globalLeaveRepository = origLeaves.filter(l => l.date >= dateFilter.start && l.date <= dateFilter.end);
                                } else {
                                    globalLeaveRepository = origLeaves;
                                }
                                // Also filter by staff if selected
                                if (roleVal || singleEmail) {
                                    const emails = new Set(effectiveStaff.map(s => s.email));
                                    globalLeaveRepository = globalLeaveRepository.filter(l => emails.has(l.employee));
                                }
                                if (isExcel) { exportLeaveSummaryToExcel(); } else { exportLeaveSummaryToPDF(); }
                                globalLeaveRepository = origLeaves;

                            } else if (source === 'discharge') {
                                label = 'Discharge Summaries';
                                if (isExcel) { exportDischargesToExcel(); } else { exportDischargesToPDF(); }

                            } else if (source === 'followup') {
                                label = 'Follow-up Cases';
                                if (isExcel) { exportFollowupCasesToExcel(); } else { exportFollowupCasesToPDF(); }

                            } else if (source === 'inventory') {
                                label = 'Supplies & Consumables';
                                if (isExcel) { exportInventoryToExcel(); } else { exportInventoryToPDF(); }

                            } else if (source === 'ot_sheet') {
                                label = 'Overtime Sheet';
                                globalRosterRepository = effectiveStaff;
                                if (isExcel) { exportSupervisorOTToExcel(); } else { exportSupervisorOTToPDF(); }
                                globalRosterRepository = origStaff;

                            } else if (source === 'master_ot') {
                                label = 'Master OT Ledger';
                                if (isExcel) { exportSupervisorOTToExcel(); } else { exportSupervisorOTToPDF(); }

                            } else if (source === 'ref_tracker') {
                                label = 'Reference Tracker';
                                if (isExcel) { exportRefTrackerToExcel(); } else { exportRefTrackerToPDF(); }

                            } else if (source === 'volume') {
                                label = 'Therapist Volume Analytics';
                                if (isExcel) { exportVolumeAnalyticsToExcel(); } else { exportVolumeAnalyticsToPDF(); }

                            } else if (source === 'fdo_sheets') {
                                label = "FDO's Sheets";
                                if (isExcel) {
                                    exportFdoSheets();
                                } else {
                                    const rows = fdoSheetData.map(r => {
                                        const diff = ((parseFloat(r.aasandha) || 0) - (parseFloat(r.newSoftware) || 0)).toFixed(2);
                                        return `<tr><td>${escHtml(formatDateToDDMMYYYY(r.date))}</td><td>${escHtml(r.aasandha)}</td><td>${escHtml(r.newSoftware)}</td><td>${diff}</td><td>${escHtml(r.remarks)}</td><td>${escHtml(r.filledBy)}</td><td>${escHtml(formatDateToDDMMYYYY(r.revisedDate))}</td><td>${escHtml(r.revisedBy)}</td></tr>`;
                                    }).join('');
                                    const logo = globalBrandingLogoUrl ? `<img src="${globalBrandingLogoUrl}" style="max-height:60px; display:block; margin:0 auto 12px;">` : '';
                                    const html = `
                            <div class="report-header">${logo}<p>FDO's Sheets Export</p></div>
                            <div class="meta-details"><span><strong>Total Rows:</strong> ${fdoSheetData.length}</span><span><strong>Export Date:</strong> ${new Date().toLocaleDateString()}</span></div>
                            <table><thead><tr><th>Date</th><th>Aasandha</th><th>New Software</th><th>Difference</th><th>Remarks</th><th>Filled By</th><th>Revised Date</th><th>Revised By</th></tr></thead><tbody>${rows}</tbody></table>`;
                                    triggerPDFDownload(`FDO_Sheets_${Date.now()}.html`, html);
                                }
                            } else if (source === 'handover') {
                                label = "Handover";
                                if (isExcel) {
                                    exportHandoverExcel();
                                } else {
                                    exportHandoverPDF();
                                }
                            } else if (source === 'solarelle_patients') {
                                label = "Solarelle Patients";
                                if (isExcel) {
                                    exportSolarelleExcel();
                                } else {
                                    exportSolarellePDF();
                                }
                            } else if (source === 'aasandha_assessment') {
                                label = 'Assessment';
                                if (isExcel) { exportAasandhaExcel(); } else { exportAasandhaPDF(); }
                            } else if (source === 'expiry_tracker') {
                                label = 'Expiry Tracker';
                                if (isExcel) { exportExpiryTrackerToExcel(); } else { exportExpiryTrackerToPDF(); }
                            } else if (source === 'personal_expiry') {
                                label = 'Personal Expiry Dates';
                                if (isExcel) { exportPersonalExpiryToExcel(); } else { exportPersonalExpiryToPDF(); }
                            } else if (source === 'fdo_attendance') {
                                label = 'FDO Attendance Sheet';
                                if (isExcel) { exportFdoAttendanceCSV(); } else { exportFdoAttendancePDF(); }
                            } else if (source === 'therapist_attendance') {
                                label = 'Therapist Attendance Sheet';
                                if (isExcel) { exportTherapistAttendanceExcel(); } else { exportTherapistAttendancePDF(); }
                            } else if (source === 'cash_drawer') {
                                label = 'Cash Drawer';
                                if (isExcel) { exportCashDrawerExcel(); } else { exportCashDrawerPDF(); }
                            } else if (source === 'pricing') {
                                label = 'Pricing Reference';
                                if (isExcel) { exportPricingExcel(); } else { exportPricingPDF(); }
                            } else if (source === 'patient_tracker') {
                                label = 'Patient Tracker';
                                if (isExcel) { exportPatientTracker(); } else { customAlert('PDF export not available for Patient Tracker. Please use Excel.'); }
                            } else if (source === 'discharge_request') {
                                label = 'Discharge Fill Request';
                                if (isExcel) { exportDischargeRequestExcel(); } else { exportDischargeRequestPDF(); }
                            } else if (source === 'maintenance') {
                                label = 'Maintenance Module';
                                if (isExcel) { exportMaintenanceToExcel(); } else { exportMaintenanceToPDF(); }
                            }

                            const dateInfo = dateFilter ? ` (${dateFilter.start} to ${dateFilter.end})` : ' (all dates)';
                            const staffInfo = roleVal ? ` — ${roleVal}` : (singleEmail ? ' — selected staff' : '');
                            customAlert(`✅ ${label} exported${dateInfo}${staffInfo}`);

                        } catch (e) {
                            globalRosterRepository = origStaff;
                            globalLeaveRepository = origLeaves;
                            console.error('Export error:', e);
                            customAlert('Export failed. Check console.');
                        }
                    }
                    function runExportAll(mode) {
                        const sources = [
                            'staff_directory', 'roster', 'my_roster', 'leave', 'leave_summary',
                            'discharge', 'followup', 'inventory', 'ot_sheet', 'ref_tracker',
                            'volume', 'master_ot', 'expiry_tracker', 'personal_expiry', 'fdo_sheets',
                            'maintenance',
                            'handover', 'solarelle_patients', 'aasandha_assessment', 'fdo_attendance',
                            'therapist_attendance', 'cash_drawer', 'pricing', 'patient_tracker', 'discharge_request'
                        ];
                        let success = 0, failed = 0;
                        sources.forEach(src => {
                            try {
                                runExport(src, mode);
                                success++;
                            } catch (e) {
                                console.error('Export All failed for', src, e);
                                failed++;
                            }
                        });
                        customAlert(`✅ Export All complete: ${success} exported, ${failed} failed.`);
                    }
                    // ===== END EXPORT HUB HELPERS =====


                    function triggerWorkspaceScanManual() {
                        autoScanAndRegisterAllLayoutElements();
                        filterMiniDictionary();
                        customAlert("Workspaces scanned! Any newly detected layout text elements, button labels, and placeholders have been integrated into the translation registry.");
                    }

                    function refreshDictionaryInlineStats() {
                        const allKeys = Object.keys(systemTextDictionary);
                        let overrides = 0;
                        allKeys.forEach(key => {
                            const val = systemTextDictionary[key] || "";
                            if (val !== key && val.trim() !== "") overrides++;
                        });
                        const keysEl = document.getElementById('dictTotalKeys');
                        if (keysEl) keysEl.innerText = allKeys.length;
                        const ovrEl = document.getElementById('dictTotalOverrides');
                        if (ovrEl) ovrEl.innerText = overrides;
                    }

                    let dictCurrentPage = 1;
                    const dictPageSize = 15;
                    let dictFilteredKeys = [];
                    let dictDebounce = null;

                    function renderDictionaryControlSettingsPanel() {
                        dictCurrentPage = 1;
                        const searchEl = document.getElementById('dictionaryMiniSearch');
                        if (searchEl) searchEl.value = "";
                        const filterEl = document.getElementById('dictionaryFilterMode');
                        if (filterEl) filterEl.value = "all";
                        filterMiniDictionary();
                    }

                    function debouncedDictionaryFilter() {
                        clearTimeout(dictDebounce);
                        dictDebounce = setTimeout(() => {
                            dictCurrentPage = 1;
                            filterMiniDictionary();
                        }, 200);
                    }

                    function filterMiniDictionary() {
                        const container = document.getElementById('miniDictionaryContainer');
                        if (!container) return;
                        const query = (document.getElementById('dictionaryMiniSearch')?.value || "").toLowerCase();
                        const mode = document.getElementById('dictionaryFilterMode')?.value || "all";
                        const allKeys = Object.keys(systemTextDictionary);
                        let totalKeys = allKeys.length;
                        let totalOverrides = 0;
                        const filtered = allKeys.filter(key => {
                            const val = systemTextDictionary[key] || "";
                            const isOverridden = (val !== key && val.trim() !== "");
                            if (isOverridden) totalOverrides++;
                            const matchQuery = key.toLowerCase().includes(query) || val.toLowerCase().includes(query);
                            if (mode === "overridden") return isOverridden && matchQuery;
                            if (mode === "default") return !isOverridden && matchQuery;
                            return matchQuery;
                        });
                        dictFilteredKeys = filtered;
                        const keysEl = document.getElementById('dictTotalKeys');
                        if (keysEl) keysEl.innerText = totalKeys;
                        const ovrEl = document.getElementById('dictTotalOverrides');
                        if (ovrEl) ovrEl.innerText = totalOverrides;
                        const totalPages = Math.ceil(filtered.length / dictPageSize) || 1;
                        if (dictCurrentPage > totalPages) dictCurrentPage = totalPages;
                        if (dictCurrentPage < 1) dictCurrentPage = 1;
                        const pageNumEl = document.getElementById('dictCurrentPageNum');
                        if (pageNumEl) pageNumEl.innerText = dictCurrentPage;
                        const progressEl = document.getElementById('dictPaginationProgress');
                        if (progressEl) {
                            const start = filtered.length === 0 ? 0 : (dictCurrentPage - 1) * dictPageSize + 1;
                            const end = Math.min(dictCurrentPage * dictPageSize, filtered.length);
                            progressEl.innerText = `Showing ${start} - ${end} of ${filtered.length} matches`;
                        }
                        const prevBtn = document.getElementById('btn_dict_prev');
                        const nextBtn = document.getElementById('btn_dict_next');
                        if (prevBtn) prevBtn.disabled = dictCurrentPage <= 1;
                        if (nextBtn) nextBtn.disabled = dictCurrentPage >= totalPages;
                        const startIdx = (dictCurrentPage - 1) * dictPageSize;
                        const pageKeys = filtered.slice(startIdx, startIdx + dictPageSize);
                        container.innerHTML = "";
                        if (pageKeys.length === 0) {
                            container.innerHTML = '<tr><td colspan="4" style="text-align:center; color:var(--text-muted); font-style:italic; padding:20px;">No matching terminology records found.</td></tr>';
                            return;
                        }
                        let html = "";
                        pageKeys.forEach(key => {
                            const val = systemTextDictionary[key] || "";
                            const isOverridden = (val !== key && val.trim() !== "");
                            const badge = isOverridden
                                ? '<span class="badge badge-success" style="font-size:8px;">Overridden</span>'
                                : '<span class="badge badge-primary" style="font-size:8px; opacity:0.75;">Default</span>';
                            const locationHtml = getTranslationUsageLocation(key);
                            const ek = key.replace(/"/g, '&quot;');
                            const ev = val.replace(/"/g, '&quot;');
                            html += `<tr style="background:${isOverridden ? 'rgba(16,185,129,0.02)' : 'transparent'};">
            <td style="text-align:left; font-family:monospace; font-size:10px; color:var(--text-muted); word-break:break-all; padding:10px 12px; border-bottom:1px solid var(--border);">${key}</td>
            <td style="text-align:left; padding:10px 12px; border-bottom:1px solid var(--border);">${locationHtml}</td>
            <td style="padding:8px 12px; border-bottom:1px solid var(--border);">
                <input type="text" value="${ev}" data-key="${ek}"
                    style="width:100%; padding:6px 10px; font-size:11px; border:1px solid var(--border); background:var(--bg-card); color:var(--text-body); border-radius:6px; font-weight:600;"
                    onchange="updateDictionaryKey(this, this.value)">
            </td>
            <td style="text-align:center; padding:10px 12px; border-bottom:1px solid var(--border);">${badge}</td>
        </tr>`;
                        });
                        container.innerHTML = html;
                    }

                    function getTranslationUsageLocation(key) {
                        const escapedKey = key.replace(/"/g, '\\"');
                        const els = document.querySelectorAll(`[data-trans-key="${escapedKey}"], [data-trans-placeholder-key="${escapedKey}"]`);
                        const locations = new Set();
                        els.forEach(el => {
                            const tag = el.tagName.toLowerCase();
                            let context = '';
                            let parent = el.parentElement;
                            for (let i = 0; i < 4 && parent; i++) {
                                if (parent.id && parent.id !== 'miniDictionaryContainer' && !parent.id.startsWith('unifAuth')) {
                                    context = parent.id.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
                                    break;
                                }
                                parent = parent.parentElement;
                            }
                            const label = context ? `${tag} in ${context}` : tag;
                            locations.add(label);
                        });
                        if (locations.size === 0) return '<span style="font-size:9px;color:var(--text-muted);font-style:italic;">not linked to any data-trans-key</span>';
                        return [...locations].slice(0, 3).map(l => `<span style="font-size:9px;color:var(--text-muted);background:var(--bg-inner);padding:1px 6px;border-radius:4px;border:1px solid var(--border);white-space:nowrap;">${l}</span>`).join(' ');
                    }

                    function updateDictionaryKey(input, value) {
                        const key = input.getAttribute('data-key');
                        systemTextDictionary[key] = value;
                        clearTimeout(dictDebounce);
                        dictDebounce = setTimeout(filterMiniDictionary, 500);
                    }

                    function changeDictionaryPage(dir) {
                        dictCurrentPage += dir;
                        filterMiniDictionary();
                    }
                    function filterFullDictionary() {
                        const queryEl = document.getElementById('dictionaryFullSearch');
                        const query = queryEl ? queryEl.value.toLowerCase() : "";
                        const modeEl = document.getElementById('dictionaryFilterMode');
                        const mode = modeEl ? modeEl.value : "all";
                        const container = document.getElementById('fullscreenDictionaryGridAnchor');
                        if (!container) return;

                        container.innerHTML = "";
                        let count = 0;

                        for (let key in systemTextDictionary) {
                            const dictionaryValue = systemTextDictionary[key] || "";
                            const isOverridden = (dictionaryValue !== key && dictionaryValue.trim() !== "");

                            if (mode === "overridden" && !isOverridden) continue;
                            if (mode === "default" && isOverridden) continue;

                            if (key.toLowerCase().includes(query) || dictionaryValue.toLowerCase().includes(query)) {
                                const div = document.createElement('div');
                                div.className = "dictionary-grid-row";
                                div.style = "display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 8px; align-items: center; background: var(--bg-inner); padding: 6px 10px; border-radius: 4px; border: 1px solid var(--border);";

                                div.innerHTML = `
                <div>
                    <span style="font-size: 9px; color: var(--text-muted); font-family: monospace; display: block;">${key}</span>
                    <strong style="font-size: 11px; color: var(--text);">${dictionaryValue}</strong>
                    ${isOverridden ? '<span style="font-size:8px; color:var(--success); font-weight:700; margin-left:6px;">✏️</span>' : ''}
                </div>
                <input type="text" 
                       value="${dictionaryValue}" 
                       style="width:100%; padding: 4px 8px; font-size: 12px; border: 1px solid var(--border); background: var(--bg-card); color: var(--text); border-radius: 4px;" 
                       oninput="systemTextDictionary['${key.replace(/'/g, "\\'")}'] = this.value; refreshDictionaryInlineStats();">
            `;
                                container.appendChild(div);
                                count++;
                            }
                        }

                        if (count === 0) {
                            container.innerHTML = `<div style="grid-column: span 2; text-align: center; color: var(--text-muted); font-style: italic; padding: 12px;">No matching system terms found.</div>`;
                        }
                        refreshDictionaryInlineStats();
                    }
                    function commitLocalSystemDictionaryOverrides() {
                        customAlert("Linguistic overrides generated cleanly. Rebuilding menu mappings.");
                        filterMiniDictionary();
                        synchronizeWorkspaceCoreStatus();
                    }

                    // Updated Chat Selection Handler
                    function selectActiveChatTarget(targetId) {
                        chatActivePeerEmail = targetId;
                        unreadMessageCounts[targetId] = 0; // Clear unread counts upon selection
                        renderCommsMessengerPanel();
                    }

                    // Complete Stretched Communications Hub Engine
                    function renderCommsMessengerPanel() {
                        const canBroadcast = allowedBroadcasterRoles.includes(currentActiveSessionUser.position);
                        const broadcastBlock = document.getElementById('adminBroadcastControlBlock');
                        const messengerBlock = document.getElementById('directMessengerBlock');

                        // Hide manual broadcast tab/panel for unauthorized users
                        const bcTab = document.getElementById('btn_comms_tab_broadcast');
                        const bcPanel = document.getElementById('commsPanelBroadcast');
                        if (bcTab) bcTab.style.display = canBroadcast ? '' : 'none';
                        if (bcPanel && !bcPanel.classList.contains('hidden')) {
                            if (!canBroadcast) bcPanel.classList.add('hidden');
                        }

                        if (messengerBlock) {
                            messengerBlock.className = canBroadcast ? "module-card span-8" : "module-card span-12";
                        }

                        // Update auth matrix visibility and scheduled tab/panel for scheduled broadcasts
                        const canSched = allowedScheduledBroadcasterRoles && allowedScheduledBroadcasterRoles.includes(currentActiveSessionUser.position);
                        const schedTab = document.getElementById('btn_comms_tab_scheduled');
                        const schedPanel = document.getElementById('commsPanelScheduled');
                        if (schedTab) schedTab.style.display = canSched ? '' : 'none';
                        if (schedPanel && !schedPanel.classList.contains('hidden')) {
                            if (!canSched) schedPanel.classList.add('hidden');
                        }

                        // 1. Re-render the sidebar conversation list based on the active tab (Direct vs Groups)
                        populateChatUserList();

                        // 2. Verify and display the active chat container vs empty placeholder state
                        const emptyState = document.getElementById('commsEmptyState');
                        const activeChat = document.getElementById('commsActiveChat');

                        if (chatActiveTab === 'groups' && chatActiveGroupId) {
                            if (emptyState) emptyState.style.display = 'none';
                            if (activeChat) activeChat.style.display = 'flex';
                            renderGroupChatHeader();
                            renderGroupMessages();
                        } else if (chatActiveTab === 'direct' && chatActivePeerEmail) {
                            if (emptyState) emptyState.style.display = 'none';
                            if (activeChat) activeChat.style.display = 'flex';
                            renderChatHeader();
                            renderChatMessages();
                        } else {
                            if (emptyState) emptyState.style.display = 'flex';
                            if (activeChat) activeChat.style.display = 'none';
                        }
                    }

                    // =========================================================
                    // GROUP CHAT CREATION MODAL HANDLERS
                    // =========================================================

                    // Opens the custom Group Chat builder dialog (Authorized managers only)
                    function openCreateGroupChatModal() {
                        let checkboxesHtml = "";
                        globalRosterRepository.forEach(staff => {
                            if (staff.email === currentActiveSessionUser.email) return;
                            checkboxesHtml += `
            <div style="display:flex; align-items:center; gap:8px; padding:4px 0;">
                <input type="checkbox" class="grp-member-check" value="${staff.email}">
                <span style="font-weight:600; font-size:11px;">${staff.name} (${lookupTranslationValue(staff.position)})</span>
            </div>
        `;
                        });

                        const mount = document.getElementById('systemGlobalModalMount');
                        if (!mount) return;
                        mount.innerHTML = `
        <div class="system-inline-modal-overlay">
            <div class="system-inline-modal-box" style="width:380px; max-height:85vh; overflow-y:auto;">
                <h3 style="margin-bottom:12px; border-bottom:1px solid var(--border); padding-bottom:6px;">👥 Build Custom Group Chat</h3>
                <div class="form-group">
                    <label>Group Chat Name</label>
                    <input type="text" id="newGroupChatName" placeholder="e.g. Front Office Desk Group" style="width:100%;">
                </div>
                <div class="form-group" style="margin-top:12px;">
                    <label>Select Team Participants</label>
                    <div style="background:var(--bg-inner); border:1px solid var(--border); border-radius:8px; padding:10px; max-height:180px; overflow-y:auto;">
                        ${checkboxesHtml}
                    </div>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:16px; border-top:1px dashed var(--border); padding-top:12px;">
                    <button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Dismiss</button>
                    <button class="action-btn" style="background:var(--success);" onclick="commitCreateGroupChat()">Create Group</button>
                </div>
            </div>
        </div>
    `;
                    }

                    // Saves and provisions the group chat across active rosters
                    function commitCreateGroupChat() {
                        const name = document.getElementById('newGroupChatName').value.trim();
                        if (!name) {
                            customAlert("Please provide a valid Group Chat Name.");
                            return;
                        }

                        let selectedMembers = [currentActiveSessionUser.email];
                        document.querySelectorAll('.grp-member-check').forEach(cb => {
                            if (cb.checked) {
                                selectedMembers.push(cb.value);
                            }
                        });

                        if (selectedMembers.length < 2) {
                            customAlert("Please select at least one other participant to form a group.");
                            return;
                        }

                        const groupId = "group_" + Date.now();
                        globalGroupChats.push({
                            id: groupId,
                            name: name,
                            members: selectedMembers,
                            creator: currentActiveSessionUser.email, // Standardized key (fixed from createdBy)
                            photo: "", // Initial empty string placeholder
                            createdAt: new Date().toISOString().split('T')[0]
                        });

                        closeSystemModalBox();
                        chatActivePeerEmail = null;
                        chatActiveGroupId = groupId; // Set the newly created group active
                        chatActiveTab = 'groups'; // Switch to groups tab

                        // Sync views
                        populateChatUserList();
                        renderChatHeader();
                        renderGroupMessages();

                        customAlert(`Group Chat "${name}" provisioned and created successfully.`);
                    }

                    // BACKGROUND CHAT SIMULATION TRAFFIC
