                    // ===== FRL MATRIX =====
                    let frlMatrixSelectedRoles = [];
                    function populateFrlMatrixYearSelect() {
                        const sel = document.getElementById('frlMatrixYearSelect');
                        if (!sel || sel.options.length > 0) return;
                        const now = new Date().getFullYear();
                        for (let y = 2022; y <= 2099; y++) {
                            const opt = document.createElement('option');
                            opt.value = String(y);
                            opt.textContent = String(y);
                            if (y === now) opt.selected = true;
                            sel.appendChild(opt);
                        }
                    }
                    function toggleFrlRoleDropdown() {
                        const dd = document.getElementById('frlMatrixRoleFilterDropdown');
                        if (!dd) return;
                        dd.style.display = dd.style.display === 'none' ? 'block' : 'none';
                    }
                    function populateFrlMatrixRoleFilter() {
                        const container = document.getElementById('frlMatrixRoleFilterDropdown');
                        if (!container || container.dataset.populated) return;
                        container.dataset.populated = '1';
                        const roles = new Set();
                        globalRosterRepository.forEach(u => { if (u.position) roles.add(u.position); });
                        container.innerHTML = '';
                        const allLabel = document.createElement('label');
                        allLabel.style.cssText = 'display:flex;align-items:center;gap:4px;font-size:10px;font-weight:600;cursor:pointer;padding:3px 4px;border-bottom:1px solid var(--border);margin-bottom:3px;';
                        const allCb = document.createElement('input');
                        allCb.type = 'checkbox';
                        allCb.checked = true;
                        allCb.style.cssText = 'accent-color:var(--primary);cursor:pointer;';
                        allCb.onchange = function () {
                            container.querySelectorAll('input[type="checkbox"]').forEach(cb => { if (cb !== allCb) cb.checked = false; });
                            frlMatrixSelectedRoles = [];
                            allCb.checked = true;
                            updateFrlRoleBtnLabel();
                            renderFrlMatrix();
                        };
                        allLabel.appendChild(allCb);
                        allLabel.appendChild(document.createTextNode('All'));
                        container.appendChild(allLabel);
                        [...roles].sort().forEach(r => {
                            const label = document.createElement('label');
                            label.style.cssText = 'display:flex;align-items:center;gap:4px;font-size:10px;font-weight:500;cursor:pointer;padding:3px 4px;border-radius:3px;';
                            label.onmouseover = function () { this.style.background = 'var(--bg-inner)'; };
                            label.onmouseout = function () { this.style.background = ''; };
                            const cb = document.createElement('input');
                            cb.type = 'checkbox';
                            cb.style.cssText = 'accent-color:var(--primary);cursor:pointer;';
                            cb.onchange = function () {
                                if (cb.checked) { frlMatrixSelectedRoles.push(r); allCb.checked = false; }
                                else { frlMatrixSelectedRoles = frlMatrixSelectedRoles.filter(v => v !== r); allCb.checked = frlMatrixSelectedRoles.length === 0; }
                                updateFrlRoleBtnLabel();
                                renderFrlMatrix();
                            };
                            label.appendChild(cb);
                            label.appendChild(document.createTextNode(r));
                            container.appendChild(label);
                        });
                    }
                    function updateFrlRoleBtnLabel() {
                        const btn = document.getElementById('frlMatrixRoleFilterBtn');
                        if (!btn) return;
                        if (frlMatrixSelectedRoles.length === 0) btn.innerHTML = '📋 All Roles ▾';
                        else btn.innerHTML = '📋 ' + frlMatrixSelectedRoles.length + ' selected ▾';
                    }
                    function getFrlMatrixSelectedRoles() { return frlMatrixSelectedRoles || []; }
                    function renderFrlMatrix() {
                        populateFrlMatrixYearSelect();
                        populateFrlMatrixRoleFilter();
                        const year = document.getElementById('frlMatrixYearSelect').value;
                        document.getElementById('frlMatrixYearLabel').textContent = year;
                        const selectedRoles = getFrlMatrixSelectedRoles();
                        const head = document.getElementById('frlMatrixHead');
                        const body = document.getElementById('frlMatrixBody');
                        const foot = document.getElementById('frlMatrixFoot');
                        if (!head || !body || !foot) return;
                        head.innerHTML = ''; body.innerHTML = ''; foot.innerHTML = '';
                        let staffList = globalRosterRepository.filter(u => u.name && u.active !== false);
                        if (selectedRoles.length > 0) staffList = staffList.filter(u => selectedRoles.includes(u.position));
                        staffList.sort((a, b) => a.name.localeCompare(b.name));
                        const frlLeaves = (globalLeaveRepository || []).filter(l =>
                            (l.type === 'Family Leave' || l.type === 'Family Responsibility Leave') &&
                            l.status === 'Approved' &&
                            l.date && l.date.startsWith(year)
                        );
                        const dayEntries = [];
                        const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
                        frlLeaves.forEach(l => {
                            const from = l.fromDate || l.date;
                            const to = l.toDate || l.date;
                            let d = new Date(from + 'T12:00:00');
                            const end = new Date(to + 'T12:00:00');
                            while (d <= end) {
                                dayEntries.push({ email: l.email, date: d.toISOString().slice(0, 10), duration: 1 });
                                d.setDate(d.getDate() + 1);
                            }
                        });
                        const byDate = {};
                        dayEntries.forEach(e => {
                            if (!byDate[e.date]) byDate[e.date] = {};
                            byDate[e.date][e.email] = (byDate[e.date][e.email] || 0) + e.duration;
                        });
                        const sortedDates = Object.keys(byDate).sort();
                        if (sortedDates.length === 0) {
                            head.innerHTML = '<tr><th>Date</th><th>Day</th>' + staffList.map(s => '<th>' + escHtml(s.name) + '</th>').join('') + '</tr>';
                            body.innerHTML = '<tr><td colspan="' + (2 + staffList.length) + '" style="text-align:center;padding:30px;color:var(--text-muted);font-style:italic;">No FRL records found for ' + year + '.</td></tr>';
                            foot.innerHTML = '';
                            return;
                        }
                        let theadHtml = '<tr><th style="min-width:90px;">Date</th><th style="min-width:40px;">Day</th>';
                        staffList.forEach(s => { theadHtml += '<th style="min-width:70px;text-align:center;">' + escHtml(s.name.split(' ')[0]) + '</th>'; });
                        theadHtml += '</tr>';
                        head.innerHTML = theadHtml;
                        let bodyHtml = '';
                        sortedDates.forEach(dateStr => {
                            const d = new Date(dateStr + 'T12:00:00');
                            const dayName = dayNames[d.getDay()];
                            bodyHtml += '<tr><td style="font-weight:600;font-size:10px;">' + formatDateShort(dateStr) + '</td><td style="font-size:10px;color:var(--text-muted);">' + dayName + '</td>';
                            staffList.forEach(s => {
                                const val = byDate[dateStr] && byDate[dateStr][s.email];
                                if (val) bodyHtml += '<td style="text-align:center;background:#d1fae5;font-weight:700;font-size:11px;">' + val + '</td>';
                                else bodyHtml += '<td style="text-align:center;color:#e5e7eb;">–</td>';
                            });
                            bodyHtml += '</tr>';
                        });
                        body.innerHTML = bodyHtml;
                        let footHtml = '<tr style="background:var(--primary-light);font-weight:800;"><td colspan="2" style="font-size:10px;">Total FRL Days</td>';
                        staffList.forEach(s => {
                            let total = 0;
                            sortedDates.forEach(dateStr => { if (byDate[dateStr] && byDate[dateStr][s.email]) total += byDate[dateStr][s.email]; });
                            footHtml += '<td style="text-align:center;font-size:12px;color:var(--primary);">' + total + '</td>';
                        });
                        footHtml += '</tr>';
                        foot.innerHTML = footHtml;
                    }
