                    function populateLeaveExporterDropdownFilters() {
                        const filterSelect = document.getElementById('leaveExportStaffFilter');
                        if (filterSelect) {
                            filterSelect.innerHTML = `<option value="all">All Roster Members</option>`;
                            globalRosterRepository.forEach(u => {
                                filterSelect.innerHTML += `<option value="${u.email}">${u.name}</option>`;
                            });
                        }
                        const typeFilter = document.getElementById('leaveExportTypeFilter');
                        if (typeFilter) {
                            const currentVal = typeFilter.value;
                            typeFilter.innerHTML = '<option value="all">All Leave Types</option>' + globalVisibleLeaveTypes.map(t => `<option value="${t}">${t}</option>`).join('');
                            typeFilter.value = currentVal;
                        }
                        const monthFilter = document.getElementById('leaveExportMonthFilter');
                        if (monthFilter && monthFilter.options.length === 0) {
                            const months = ["All Months", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                            monthFilter.innerHTML = months.map((m, i) => `<option value="${i === 0 ? 'all' : i}">${m}</option>`).join('');
                        }
                        const yearFilter = document.getElementById('leaveExportYearFilter');
                        if (yearFilter && yearFilter.options.length === 0) {
                            const years = [];
                            for (let y = 2022; y <= 2099; y++) years.push(y);
                            yearFilter.innerHTML = '<option value="all">All Years</option>' + years.map(y => `<option value="${y}">${y}</option>`).join('');
                        }
                    }

                    function exportStaffLeaveReportCSV() {
                        const staffEmail = document.getElementById('leaveExportStaffFilter').value;
                        const typeFilter = document.getElementById('leaveExportTypeFilter').value;

                        let records = globalLeaveRepository;
                        if (staffEmail !== 'all') {
                            records = records.filter(l => l.email === staffEmail);
                        }
                        if (typeFilter !== 'all') {
                            records = records.filter(l => l.type === typeFilter);
                        }

                        let csvContent = "Staff Name,Verified Email,Leave Type,Duration (Days),Leave Date,Verification Notes,Status\n";

                        records.forEach(l => {
                            csvContent += `"${l.employee}","${l.email}","${l.type}",${l.duration},"${l.date}","${l.note}","${l.status}"\n`;
                        });

                        downloadCSVAsXlsx("leave_consumption_report.csv", csvContent);
                        customAlert(`Report exported successfully! Compiled ${records.length} leave database log references.`);
                    }

                    function renderLeaveManagementPortlet() {
                        const anchor = document.getElementById('balanceCardsContainerAnchor');
                        if (anchor) {
                            anchor.innerHTML = "";
                            const headerEl = document.getElementById('lbl_leave_entitlements_title');
                            if (headerEl) {
                                headerEl.innerText = `📊 Clinical Leave Entitlements Allocation Balance (${currentActiveSessionUser.name})`;
                            }

                            // Read dynamic remaining balances
                            const email = currentActiveSessionUser?.email;
                            const sickMcUsed = email ? getStaffUsedLeaveDays(email, 'Sick Leave', 'With MC') : 0;
                            const sickNoMcUsed = email ? getStaffUsedLeaveDays(email, 'Sick Leave', 'Without MC') : 0;
                            const annualUsed = email ? getStaffUsedLeaveDays(email, 'Annual Leave', null) : 0;
                            const familyUsed = email ? getStaffUsedLeaveDays(email, 'Family Leave', null) : 0;
                            const sickMcLimit = getCeilingLimit('Sick Leave', 'With MC');
                            const sickNoMcLimit = getCeilingLimit('Sick Leave', 'Without MC');
                            const annualLimit = getCeilingLimit('Annual Leave', null);
                            const familyLimit = getCeilingLimit('Family Leave', null);
                            appendBalanceCardWidget(anchor, "Sick Leave (With MC)", Math.max(0, sickMcLimit - sickMcUsed), sickMcLimit);
                            appendBalanceCardWidget(anchor, "Sick Leave (Without MC)", Math.max(0, sickNoMcLimit - sickNoMcUsed), sickNoMcLimit);
                            appendBalanceCardWidget(anchor, "Annual Leave Limit", Math.max(0, annualLimit - annualUsed), annualLimit);
                            appendBalanceCardWidget(anchor, "FRL Responsibility", Math.max(0, familyLimit - familyUsed), familyLimit);
                        }

                        const tbody = document.getElementById('globalLeaveTableAnchor');
                        if (!tbody) return;

                        // Check leave approver permissions
                        const isLeaveApprover = allowedLeaveApproverRoles.includes(currentActiveSessionUser.position);

                        // Show all leaves in the verification queue
                        // Leave approvers see their own leaves (all statuses) + other staff leaves only while pending
                        let scope = isLeaveApprover
                            ? globalLeaveRepository.filter(l => l.email === currentActiveSessionUser.email || l.status === 'Pending Approval')
                            : globalLeaveRepository.filter(l => l.email === currentActiveSessionUser.email);

                        // 2. Filter dynamically based on search dropdown selections
                        const exporterBlock = document.getElementById('leaveExporterControls');
                        if (exporterBlock) exporterBlock.style.display = 'flex';
                        // Staff filter only for managers
                        const staffFilterEl = document.getElementById('leaveExportStaffFilter');
                        if (staffFilterEl) staffFilterEl.style.display = isLeaveApprover ? 'inline-block' : 'none';
                        // Hide export buttons for non-managers
                        const exportBtns = exporterBlock ? exporterBlock.querySelectorAll('.action-btn') : [];
                        exportBtns.forEach(btn => btn.style.display = isLeaveApprover ? 'inline-flex' : 'none');
                        const staffFilter = document.getElementById('leaveExportStaffFilter')?.value || 'all';
                        const typeFilter = document.getElementById('leaveExportTypeFilter')?.value || 'all';
                        const statusFilter = document.getElementById('leaveExportStatusFilter')?.value || 'all';
                        const monthVal = document.getElementById('leaveExportMonthFilter')?.value || 'all';
                        const yearVal = document.getElementById('leaveExportYearFilter')?.value || 'all';
                        if (staffFilter !== 'all' && isLeaveApprover) { scope = scope.filter(l => l.email === staffFilter); }
                        if (typeFilter !== 'all') { scope = scope.filter(l => l.type === typeFilter); }
                        if (statusFilter !== 'all') { scope = scope.filter(l => l.status === statusFilter); }
                        if (monthVal !== 'all' || yearVal !== 'all') {
                            scope = scope.filter(l => {
                                if (!l.submittedAt) return true;
                                const d = new Date(l.submittedAt);
                                const m = d.getMonth() + 1;
                                const y = d.getFullYear();
                                if (monthVal !== 'all' && m !== parseInt(monthVal)) return false;
                                if (yearVal !== 'all' && y !== parseInt(yearVal)) return false;
                                return true;
                            });
                        }

                        tbody.innerHTML = "";
                        if (scope.length === 0) {
                            tbody.innerHTML = `<tr><td colspan="11" style="text-align:center; color:var(--text-muted); font-style:italic;">No leaves logged inside current active structures.</td></tr>`;
                            return;
                        }

                        scope.forEach(item => {
                            const isPending = item.status === "Pending Approval";
                            const isAllowedToApprove = isLeaveApprover;

                            const tr = document.createElement('tr');
                            tr.innerHTML = `
            <td style="padding: 4px 6px; font-size: 10px;"><strong>${item.employee}</strong></td>
            <td style="padding: 4px 6px; font-size: 10px;">${item.type}</td>
            <td style="padding: 4px 6px; font-size: 10px; white-space: nowrap;">${item.duration}d</td>
            <td style="padding: 4px 6px; font-size: 10px; white-space: nowrap;">${item.fromDate ? formatDateToDDMMYYYY(item.fromDate) : formatDateToDDMMYYYY(item.date)}</td>
            <td style="padding: 4px 6px; font-size: 10px; white-space: nowrap;">${item.toDate ? formatDateToDDMMYYYY(item.toDate) : formatDateToDDMMYYYY(item.date)}</td>
            <td style="padding: 4px 6px; font-size: 10px; white-space: nowrap;">${item.submittedAt ? formatDateToDDMMYYYY(item.submittedAt.split('T')[0]) : '-'}</td>
            <td style="padding: 4px 6px; font-size: 10px; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${item.note}</td>
            <td style="padding: 4px 6px; font-size: 10px; text-align: center; white-space: nowrap;"><span class="badge ${item.status === 'Approved' ? 'badge-success' : item.status === 'Rejected' ? 'badge-danger' : 'badge-warning'}" style="font-size: 8px; padding: 2px 5px;">${item.status}</span></td>
            <td style="padding: 4px 6px; font-size: 10px; text-align: center; white-space: nowrap;">${item.mcStatus ? `<span style="font-size:9px; font-weight:700; color:${item.mcStatus === 'With MC' ? 'var(--danger)' : 'var(--text-muted)'};">${item.mcStatus}</span>` : '-'}</td>
            <td style="padding: 4px 6px; font-size: 10px; text-align: center; white-space: nowrap;">${item.approvedBy || '-'}</td>
            <td style="padding: 4px 6px; font-size: 10px; text-align: center; white-space: nowrap;">
                ${(isPending && isAllowedToApprove) ? `
                    <div style="display:flex; gap:2px;">
                        <button class="action-btn" style="background:var(--success); padding:2px 5px; font-size:9px;" onclick="auditLeaveRequestStatus(${item.id}, 'Approved');renderLeaveManagementPortlet()">Approve</button>
                        <button class="action-btn" style="background:var(--danger); padding:2px 5px; font-size:9px;" onclick="auditLeaveRequestStatus(${item.id}, 'Rejected');renderLeaveManagementPortlet()">Reject</button>
                    </div>
                ` : `<span style="font-style:italic; opacity:0.6; font-size:9px;">—</span>`}
            </td>
        `;
                            tbody.appendChild(tr);
                        });
                    }

                    function appendBalanceCardWidget(anchor, label, value, ceiling) {
                        const div = document.createElement('div');
                        div.className = "balance-mini-card";
                        div.style.cssText = 'min-height:50px;padding:6px 10px;flex:0 0 auto;min-width:130px;';
                        div.innerHTML = `
                <h5 style="font-size:8px !important;margin-bottom:2px;">${lookupTranslationValue(label)}</h5>
                <div class="counter-value" style="font-size:12px; font-weight:700;">${value} Days Left</div>
                <div style="font-size:7px; color:var(--text-muted); margin-top:1px;">Limit: ${ceiling} Days</div>
            `;
                        anchor.appendChild(div);
                    }

                    function executeStaffLeaveSubmissionPipeline() {
                        const type = document.getElementById('formLeaveType').value;
                        const note = document.getElementById('formLeaveNote').value.trim();
                        const dur = parseInt(document.getElementById('formLeaveDuration').value) || 1;

                        let date, duration, fromDate, toDate;

                        const rangeMode = document.getElementById('leaveDateRangeMode').style.display !== 'none';

                        if (rangeMode) {
                            fromDate = document.getElementById('formLeaveDateFrom').value;
                            toDate = document.getElementById('formLeaveDateTo').value;
                            if (!fromDate || !toDate) { customAlert("Please select both From and To dates."); return; }
                            if (new Date(fromDate) > new Date(toDate)) { customAlert("From date cannot be after To date."); return; }
                            date = fromDate;
                            duration = calculateLeaveBusinessDays(fromDate, toDate);
                        } else {
                            date = document.getElementById('formLeaveDate').value;
                            if (!date) { customAlert("Please select a date."); return; }
                            duration = dur || 1;
                            fromDate = date;
                            toDate = date;
                        }

                        if (!duration || duration < 1) { customAlert("No valid working days in selected range (Fridays are excluded)."); return; }

                        // Approval logic based on configurable settings
                        const needsApprovalSick = document.getElementById('leaveApprovalSick') ? document.getElementById('leaveApprovalSick').checked : true;
                        const needsApprovalAnnual = document.getElementById('leaveApprovalAnnual') ? document.getElementById('leaveApprovalAnnual').checked : true;
                        const needsApprovalFamily = document.getElementById('leaveApprovalFamily') ? document.getElementById('leaveApprovalFamily').checked : true;
                        const needsApprovalUmrah = document.getElementById('leaveApprovalUmrah') ? document.getElementById('leaveApprovalUmrah').checked : true;
                        const needsApprovalHajj = document.getElementById('leaveApprovalHajj') ? document.getElementById('leaveApprovalHajj').checked : true;
                        const needsApprovalNoPaid = document.getElementById('leaveApprovalNoPaid') ? document.getElementById('leaveApprovalNoPaid').checked : true;
                        const needsApprovalMaternity = document.getElementById('leaveApprovalMaternity') ? document.getElementById('leaveApprovalMaternity').checked : true;
                        const needsApprovalPaternity = document.getElementById('leaveApprovalPaternity') ? document.getElementById('leaveApprovalPaternity').checked : true;
                        const needsApprovalSpecial = document.getElementById('leaveApprovalSpecial') ? document.getElementById('leaveApprovalSpecial').checked : true;
                        const needsApproval = (type === "Sick Leave" && needsApprovalSick) || (type === "Annual Leave" && needsApprovalAnnual) || (type === "Family Leave" && needsApprovalFamily) || (type === "Family Responsibility Leave" && needsApprovalFamily) || (type === "Umrah Leave" && needsApprovalUmrah) || (type === "Hajj Leave" && needsApprovalHajj) || (type === "No Paid Leave" && needsApprovalNoPaid) || (type === "Maternity Leave" && needsApprovalMaternity) || (type === "Paternity Leave" && needsApprovalPaternity) || (type === "Special Leave" && needsApprovalSpecial);
                        const isAutoApproved = !needsApproval;
                        const status = isAutoApproved ? "Approved" : "Pending Approval";

                        const mcRadio = document.querySelector('input[name="mcStatus"]:checked');
                        const mcStatus = type === 'Sick Leave' && mcRadio ? mcRadio.value : '';

                        // Ceiling check for all leave types
                        const email = currentActiveSessionUser?.email;
                        if (email) {
                            if (type === 'Sick Leave') {
                                const mcCheck = mcStatus || 'With MC';
                                const used = getStaffUsedLeaveDays(email, 'Sick Leave', mcCheck);
                                const limit = getCeilingLimit('Sick Leave', mcCheck);
                                if (used + duration > limit) {
                                    customAlert(`${mcCheck} ceiling exceeded: you have used ${used}d of ${limit}d, and this request adds ${duration}d.`);
                                    return;
                                }
                            } else {
                                const used = getStaffUsedLeaveDays(email, type, null);
                                const limit = getCeilingLimit(type, null);
                                if (used + duration > limit) {
                                    customAlert(`${type} ceiling exceeded: you have used ${used}d of ${limit}d, and this request adds ${duration}d.`);
                                    return;
                                }
                            }
                        }

                        globalLeaveRepository.push({
                            id: Date.now(),
                            email: currentActiveSessionUser.email,
                            employee: currentActiveSessionUser.name,
                            type: type,
                            duration: duration,
                            date: date,
                            fromDate: fromDate,
                            toDate: toDate,
                            mcStatus: mcStatus,
                            note: note || "Personal allocations time off.",
                            status: status,
                            submittedAt: new Date().toISOString(),
                            approvedBy: null
                        });

                        // Deduct balance immediately for auto-approved leaves
                        if (isAutoApproved) {
                            const user = globalRosterRepository.find(u => u.email === currentActiveSessionUser.email);
                            if (user) {
                                if (type === "Sick Leave") user.sickBalance = Math.max(0, (user.sickBalance || 0) - duration);
                                if (type === "Annual Leave") user.annualBalance = Math.max(0, (user.annualBalance || 0) - duration);
                                if (type === "Family Leave" || type === "Family Responsibility Leave") user.familyBalance = Math.max(0, (user.familyBalance || 0) - duration);
                                if (type === "Umrah Leave") user.umrahBalance = Math.max(0, (user.umrahBalance || 0) - duration);
                                if (type === "Hajj Leave") user.hajjBalance = Math.max(0, (user.hajjBalance || 0) - duration);
                                if (type === "No Paid Leave") user.noPaidBalance = Math.max(0, (user.noPaidBalance || 0) - duration);
                                if (type === "Maternity Leave") user.maternityBalance = Math.max(0, (user.maternityBalance || 0) - duration);
                                if (type === "Paternity Leave") user.paternityBalance = Math.max(0, (user.paternityBalance || 0) - duration);
                                if (type === "Special Leave") user.specialBalance = Math.max(0, (user.specialBalance || 0) - duration);
                            }
                        }

                        // Show appropriate message
                        if (isAutoApproved) {
                            customAlert(type + " request auto-approved! " + duration + " day(s) deducted from your balance.");
                        } else {
                            customAlert(type + " request submitted for management approval.");
                        }

                        document.getElementById('formLeaveNote').value = "";
                        // Send external email notification if configured
                        sendLeaveExternalNotification({ employee: currentActiveSessionUser.name, email: currentActiveSessionUser.email, type, duration, date, fromDate, toDate, note, status });
                        // Auto-sync to Leave Tracking for all auto-approved leaves
                        if (status === "Approved") {
                            syncLeaveToTracking({ email: currentActiveSessionUser.email, employee: currentActiveSessionUser.name, type, fromDate, toDate });
                        }
                        synchronizeWorkspaceCoreStatus();
                        // Refresh sick leave matrix if on that tab
                        const sickTab = document.getElementById('ls_tab_sick');
                        if (sickTab && sickTab.style.display !== 'none') renderSickLeaveMatrix();
                        // Refresh FRL matrix if on that tab
                        const frlTab = document.getElementById('ls_tab_frl');
                        if (frlTab && frlTab.style.display !== 'none') renderFrlMatrix();
                        // Refresh Leave Tracking tab if on it
                        const trackTab = document.getElementById('ls_tab_tracking');
                        if (trackTab && trackTab.style.display !== 'none') renderLeaveTracking();
                    }

                    // Send external email notification for leave request
                    function sendLeaveExternalNotification(info) {
                        const raw = globalLeaveNotificationEmail;
                        if (!raw) return;
                        // Support comma, semicolon, or newline separated recipients
                        const recipients = raw.split(/[\n,;]+/).map(e => e.trim()).filter(e => e);
                        if (recipients.length === 0) return;
                        const recipientStr = recipients.join(',');
                        showRosterToast('📧 Opening email client to notify ' + recipients.length + ' recipient(s): ' + recipients[0] + (recipients.length > 1 ? ' +' + (recipients.length - 1) : ''));
                        const subject = encodeURIComponent('[Leave Request] ' + info.employee + ' - ' + info.type);
                        const body = encodeURIComponent(
                            'Leave Request Details\n' +
                            '========================\n' +
                            'Employee: ' + info.employee + '\n' +
                            'Email: ' + info.email + '\n' +
                            'Type: ' + info.type + '\n' +
                            'Duration: ' + info.duration + ' day(s)\n' +
                            'Date: ' + info.date + '\n' +
                            'From: ' + (info.fromDate || info.date) + '\n' +
                            'To: ' + (info.toDate || info.date) + '\n' +
                            'Status: ' + info.status + '\n' +
                            'Note: ' + (info.note || 'N/A') + '\n' +
                            '========================\n' +
                            'Sent from Physio Solutions ERP'
                        );
                        const link = document.createElement('a');
                        link.href = 'mailto:' + recipientStr + '?subject=' + subject + '&body=' + body;
                        link.style.display = 'none';
                        document.body.appendChild(link);
                        link.click();
                        document.body.removeChild(link);
                    }

                    function generateLeaveRequestMessage() {
                        const type = document.getElementById('formLeaveType').value;
                        const rangeMode = document.getElementById('leaveDateRangeMode').style.display !== 'none';
                        let days, rejoinDate, date, fromDate, toDate;
                        if (rangeMode) {
                            fromDate = document.getElementById('formLeaveDateFrom').value;
                            toDate = document.getElementById('formLeaveDateTo').value;
                            if (!fromDate || !toDate) return;
                            date = fromDate;
                            days = calculateLeaveBusinessDays(fromDate, toDate);
                            const rejoind = new Date(toDate);
                            rejoind.setDate(rejoind.getDate() + 1);
                            rejoinDate = rejoind.getFullYear() + '-' + String(rejoind.getMonth() + 1).padStart(2, '0') + '-' + String(rejoind.getDate()).padStart(2, '0');
                        } else {
                            date = document.getElementById('formLeaveDate').value;
                            if (!date) return;
                            days = parseInt(document.getElementById('formLeaveDuration').value) || 1;
                            fromDate = date;
                            toDate = date;
                            const rejoind = new Date(date);
                            rejoind.setDate(rejoind.getDate() + days);
                            rejoinDate = rejoind.getFullYear() + '-' + String(rejoind.getMonth() + 1).padStart(2, '0') + '-' + String(rejoind.getDate()).padStart(2, '0');
                        }
                        const templateForType = globalLeaveMessageTemplates[type] || globalLeaveMessageTemplates["Sick Leave"] || "{type} leave on {date} for {days} days";
                        const msg = templateForType
                            .replace(/{type}/g, type)
                            .replace(/{days}/g, days)
                            .replace(/{rejoinDate}/g, rejoinDate)
                            .replace(/{date}/g, date || '')
                            .replace(/{fromDate}/g, fromDate || '')
                            .replace(/{toDate}/g, toDate || '');
                        document.getElementById('formLeaveNote').value = msg;
                    }

                    function loadLeaveConfigSettings() {
                        // Restore visible leave types checkboxes
                        try {
                            const visSaved = localStorage.getItem('physioVisibleLeaveTypes');
                            if (visSaved) {
                                globalVisibleLeaveTypes = JSON.parse(visSaved);
                                const checkboxMap = {
                                    "Sick Leave": "lSickShow", "Annual Leave": "lAnnualShow", "Family Leave": "lFamilyShow",
                                    "Umrah Leave": "lUmrahShow", "Hajj Leave": "lHajjShow", "No Paid Leave": "lNoPaidShow",
                                    "Maternity Leave": "lMaternityShow", "Paternity Leave": "lPaternityShow", "Special Leave": "lSpecialShow"
                                };
                                Object.keys(checkboxMap).forEach(type => {
                                    const el = document.getElementById(checkboxMap[type]);
                                    if (el) el.checked = globalVisibleLeaveTypes.includes(type);
                                });
                            }
                        } catch (e) { }
                        populateLeaveTypeDropdown();
                        try {
                            const saved = localStorage.getItem('physioLeaveConfig');
                            if (saved) {
                                const cfg = JSON.parse(saved);
                                if (cfg.messageTemplates) globalLeaveMessageTemplates = Object.assign({}, globalLeaveMessageTemplates, cfg.messageTemplates);
                                else if (cfg.messageTemplate) globalLeaveMessageTemplates["Sick Leave"] = cfg.messageTemplate;
                                if (cfg.managementRoles) {
                                    globalManagementRoles = cfg.managementRoles;
                                    // Sync granular arrays from legacy management roles
                                    allowedPortalSwitcherRoles.length = 0;
                                    allowedLeaveApproverRoles.length = 0;
                                    allowedManagementDashboardRoles.length = 0;
                                    cfg.managementRoles.forEach(function(r) {
                                        allowedPortalSwitcherRoles.push(r);
                                        allowedLeaveApproverRoles.push(r);
                                        allowedManagementDashboardRoles.push(r);
                                    });
                                }
                                if (cfg.managementStaff) globalManagementStaff = cfg.managementStaff;

                                if (cfg.notificationEmail) globalLeaveNotificationEmail = cfg.notificationEmail;
                                // Restore approval rules checkboxes (even if tab not opened)
                                if (cfg.approvalRules) {
                                    const sick = document.getElementById('leaveApprovalSick');
                                    const annual = document.getElementById('leaveApprovalAnnual');
                                    const family = document.getElementById('leaveApprovalFamily');
                                    if (sick) sick.checked = cfg.approvalRules.sick !== false;
                                    if (annual) annual.checked = cfg.approvalRules.annual !== false;
                                    if (family) family.checked = cfg.approvalRules.family !== false;
                                }
                                // Restore Without MC limit
                                if (cfg.withoutMcLimit !== undefined) {
                                    const limitEl = document.getElementById('withoutMcLimitInput');
                                    if (limitEl) limitEl.value = cfg.withoutMcLimit;
                                }
                            }
                        } catch (e) { }
                    }
                    function saveLeaveConfigSettings() {
                        ["Umrah Leave", "Hajj Leave", "No Paid Leave", "Maternity Leave", "Paternity Leave", "Special Leave", "Sick Leave", "Annual Leave", "Family Leave"].forEach(type => {
                            const el = document.getElementById('leaveMsgTemplate_' + type);
                            if (el && el.value.trim()) globalLeaveMessageTemplates[type] = el.value.trim();
                        });
                        const roleCheckboxes = document.querySelectorAll('#managementRolesCheckboxContainer input[type="checkbox"]');
                        const selectedRoles = [];
                        roleCheckboxes.forEach(cb => { if (cb.checked) selectedRoles.push(cb.value); });
                        globalManagementRoles = selectedRoles.length > 0 ? selectedRoles : [];
                        // Sync granular permission arrays from the legacy management roles selection
                        allowedPortalSwitcherRoles.length = 0;
                        allowedLeaveApproverRoles.length = 0;
                        allowedManagementDashboardRoles.length = 0;
                        selectedRoles.forEach(r => {
                            allowedPortalSwitcherRoles.push(r);
                            allowedLeaveApproverRoles.push(r);
                            allowedManagementDashboardRoles.push(r);
                        });
                        const staffCheckboxes = document.querySelectorAll('#managementStaffCheckboxContainer input[type="checkbox"]:checked');
                        globalManagementStaff = Array.from(staffCheckboxes).map(cb => cb.value);
                        const emailInput = document.getElementById('leaveNotificationEmail');
                        const rawEmails = emailInput ? emailInput.value.trim() : '';
                        // Normalize: split by newline or comma, trim each, remove empties, dedupe
                        const emailList = [...new Set(rawEmails.split(/[\n,]+/).map(e => e.trim()).filter(e => e))];
                        globalLeaveNotificationEmail = emailList.join(',');
                        // Save Leave Approval Rules checkboxes
                        const sick = document.getElementById('leaveApprovalSick');
                        const annual = document.getElementById('leaveApprovalAnnual');
                        const family = document.getElementById('leaveApprovalFamily');
                        const umrah = document.getElementById('leaveApprovalUmrah');
                        const hajj = document.getElementById('leaveApprovalHajj');
                        const nopaid = document.getElementById('leaveApprovalNoPaid');
                        const maternity = document.getElementById('leaveApprovalMaternity');
                        const paternity = document.getElementById('leaveApprovalPaternity');
                        const special = document.getElementById('leaveApprovalSpecial');
                        const approvalRules = {
                            sick: sick ? sick.checked : true,
                            annual: annual ? annual.checked : true,
                            family: family ? family.checked : true,
                            umrah: umrah ? umrah.checked : true,
                            hajj: hajj ? hajj.checked : true,
                            nopaid: nopaid ? nopaid.checked : true,
                            maternity: maternity ? maternity.checked : true,
                            paternity: paternity ? paternity.checked : true,
                            special: special ? special.checked : true
                        };
                        const withoutMcLimitEl = document.getElementById('withoutMcLimitInput');
                        const withoutMcLimit = withoutMcLimitEl ? parseInt(withoutMcLimitEl.value) || 3 : 3;
                        localStorage.setItem('physioLeaveConfig', JSON.stringify({
                            messageTemplates: globalLeaveMessageTemplates,
                            managementRoles: globalManagementRoles,
                            managementStaff: globalManagementStaff,
                            notificationEmail: globalLeaveNotificationEmail,
                            approvalRules: approvalRules,
                            withoutMcLimit: withoutMcLimit
                        }));
                        savePermissionRegistry(); // persist granular permissions too
                        customAlert("Leave configuration saved successfully.");
                    }
                    function resetLeaveMessageTemplates() {
                        globalLeaveMessageTemplates = {
                            "Umrah Leave": "I would like to request umrah leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Hajj Leave": "I would like to request hajj leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "No Paid Leave": "I would like to request no paid leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Maternity Leave": "I would like to request maternity leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Paternity Leave": "I would like to request paternity leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Special Leave": "I would like to request special leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Sick Leave": "I would like to request sick leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Annual Leave": "I would like to request annual leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}.",
                            "Family Leave": "I would like to request family leave on {date} for {days} day(s) ({fromDate} to {toDate}) and rejoin on {rejoinDate}."
                        };
                        populateLeaveConfigSettings();
                        updateLeaveMsgPreview();
                        customAlert("All message templates reset to defaults.");
                    }
                    function updateLeaveMsgPreview() {
                        const preview = document.getElementById('leaveMsgPreview');
                        if (preview) {
                            const template = document.getElementById('leaveMsgTemplate_Sick Leave').value || globalLeaveMessageTemplates["Sick Leave"] || "";
                            preview.innerText = template.replace(/{type}/g, 'Sick Leave').replace(/{days}/g, '3').replace(/{rejoinDate}/g, '2026-06-25').replace(/{date}/g, '2026-06-22').replace(/{fromDate}/g, '2026-06-22').replace(/{toDate}/g, '2026-06-24');
                        }
                    }
                    function populateLeaveConfigSettings() {
                        ["Umrah Leave", "Hajj Leave", "No Paid Leave", "Maternity Leave", "Paternity Leave", "Special Leave", "Sick Leave", "Annual Leave", "Family Leave"].forEach(type => {
                            const el = document.getElementById('leaveMsgTemplate_' + type);
                            if (el) el.value = globalLeaveMessageTemplates[type] || "";
                        });
                        updateLeaveMsgPreview();
                        // Populate roles checkboxes
                        const container = document.getElementById('managementRolesCheckboxContainer');
                        if (container) {
                            const allRoles = Object.keys(globalRolePermissionsMatrix || {});
                            container.innerHTML = allRoles.map(role =>
                                '<label style="display:flex;align-items:center;gap:8px;font-size:11px;font-weight:500;cursor:pointer;padding:5px 8px;border-radius:6px;border:1px solid var(--border);background:var(--bg-card);transition:all 0.15s;">' +
                                '<input type="checkbox" value="' + role + '" ' + (globalManagementRoles.includes(role) ? 'checked' : '') + ' style="width:15px;height:15px;accent-color:var(--primary);cursor:pointer;"> ' + role +
                                '</label>'
                            ).join('');
                        }
                        // Populate staff checkboxes
                        const staffContainer = document.getElementById('managementStaffCheckboxContainer');
                        if (staffContainer && globalRosterRepository) {
                            staffContainer.innerHTML = globalRosterRepository
                                .filter(u => u.email)
                                .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
                                .map(u =>
                                    '<label style="display:flex;align-items:center;gap:8px;font-size:11px;font-weight:500;cursor:pointer;padding:5px 8px;border-radius:6px;border:1px solid var(--border);background:var(--bg-card);transition:all 0.15s;overflow:hidden;">' +
                                    '<input type="checkbox" value="' + u.email + '" ' + (globalManagementStaff.includes(u.email) ? 'checked' : '') + ' onchange="updateMgmtStaffCount()" style="width:15px;height:15px;accent-color:var(--primary);cursor:pointer;flex-shrink:0;"> ' +
                                    '<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + (u.name || 'Unknown') + '</span>' +
                                    '<span style="font-size:9px;color:var(--text-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-left:auto;">' + u.email + '</span>' +
                                    '</label>'
                                ).join('');
                            updateMgmtStaffCount();
                        }
                        const emailInput = document.getElementById('leaveNotificationEmail');
                        if (emailInput) emailInput.value = globalLeaveNotificationEmail.replace(/,/g, '\n');
                        // Restore Leave Approval Rules checkboxes
                        try {
                            const saved = localStorage.getItem('physioLeaveConfig');
                            if (saved) {
                                const cfg = JSON.parse(saved);
                                if (cfg.approvalRules) {
                                    const sick = document.getElementById('leaveApprovalSick');
                                    const annual = document.getElementById('leaveApprovalAnnual');
                                    const family = document.getElementById('leaveApprovalFamily');
                                    const umrah = document.getElementById('leaveApprovalUmrah');
                                    const hajj = document.getElementById('leaveApprovalHajj');
                                    const nopaid = document.getElementById('leaveApprovalNoPaid');
                                    const maternity = document.getElementById('leaveApprovalMaternity');
                                    const paternity = document.getElementById('leaveApprovalPaternity');
                                    const special = document.getElementById('leaveApprovalSpecial');
                                    if (sick) sick.checked = cfg.approvalRules.sick !== false;
                                    if (annual) annual.checked = cfg.approvalRules.annual !== false;
                                    if (family) family.checked = cfg.approvalRules.family !== false;
                                    if (umrah) umrah.checked = cfg.approvalRules.umrah !== false;
                                    if (hajj) hajj.checked = cfg.approvalRules.hajj !== false;
                                    if (nopaid) nopaid.checked = cfg.approvalRules.nopaid !== false;
                                    if (maternity) maternity.checked = cfg.approvalRules.maternity !== false;
                                    if (paternity) paternity.checked = cfg.approvalRules.paternity !== false;
                                    if (special) special.checked = cfg.approvalRules.special !== false;
                                }
                            }
                        } catch (e) { }
                    }
                    function updateMgmtStaffCount() {
                        const badge = document.getElementById('mgmtStaffCount');
                        if (badge) {
                            const checked = document.querySelectorAll('#managementStaffCheckboxContainer input:checked').length;
                            badge.textContent = checked + ' selected';
                        }
                    }
                    function toggleLeaveDateRangeMode() {
                        const duration = parseInt(document.getElementById('formLeaveDuration').value) || 1;
                        const singleMode = document.getElementById('leaveSingleDateMode');
                        const rangeMode = document.getElementById('leaveDateRangeMode');
                        const durDisplay = document.getElementById('leaveDurationDisplay');

                        if (duration > 1) {
                            singleMode.style.display = 'none';
                            rangeMode.style.display = 'grid';
                            durDisplay.style.display = 'block';
                            const today = new Date().toISOString().split('T')[0];
                            document.getElementById('formLeaveDateFrom').value = today;
                            const nextDay = new Date();
                            nextDay.setDate(nextDay.getDate() + duration - 1);
                            document.getElementById('formLeaveDateTo').value = nextDay.toISOString().split('T')[0];
                            calculateLeaveDuration();
                            generateLeaveRequestMessage();
                        } else {
                            singleMode.style.display = 'grid';
                            rangeMode.style.display = 'none';
                            durDisplay.style.display = 'none';
                            generateLeaveRequestMessage();
                        }
                    }

                    function getCurrentLeaveDuration() {
                        const rangeMode = document.getElementById('leaveDateRangeMode');
                        const isRange = rangeMode && rangeMode.style.display !== 'none';
                        if (isRange) {
                            const from = document.getElementById('formLeaveDateFrom')?.value;
                            const to = document.getElementById('formLeaveDateTo')?.value;
                            if (from && to) return Math.max(1, calculateLeaveBusinessDays(from, to));
                        }
                        const durInput = document.getElementById('formLeaveDuration');
                        return durInput ? (parseInt(durInput.value) || 1) : 1;
                    }

                    function updateLeaveCeilingWarning() {
                        const warnEl = document.getElementById('leaveCeilingWarning');
                        if (!warnEl) return;
                        const type = document.getElementById('formLeaveType')?.value;
                        const email = currentActiveSessionUser?.email;
                        if (!type || !email) { warnEl.style.display = 'none'; return; }
                        const rangeMode = document.getElementById('leaveDateRangeMode');
                        const isRange = rangeMode && rangeMode.style.display !== 'none';
                        let duration = 1;
                        if (isRange) {
                            const from = document.getElementById('formLeaveDateFrom')?.value;
                            const to = document.getElementById('formLeaveDateTo')?.value;
                            if (from && to) duration = Math.max(1, calculateLeaveBusinessDays(from, to));
                        } else {
                            const durInput = document.getElementById('formLeaveDuration');
                            if (durInput) duration = parseInt(durInput.value) || 1;
                        }

                        let used, limit, label;
                        if (type === 'Sick Leave') {
                            const mcRadio = document.querySelector('input[name="mcStatus"]:checked');
                            const mcStatus = mcRadio ? mcRadio.value : 'With MC';
                            used = getStaffUsedLeaveDays(email, 'Sick Leave', mcStatus);
                            limit = getCeilingLimit('Sick Leave', mcStatus);
                            label = mcStatus;
                        } else {
                            used = getStaffUsedLeaveDays(email, type, null);
                            limit = getCeilingLimit(type, null);
                            label = type;
                        }
                        if (used + duration > limit) {
                            warnEl.style.display = 'block';
                            warnEl.innerHTML = `⚠️ ${label} would exceed allocation: ${used}d used of ${limit}d limit, requesting ${duration}d — only ${Math.max(0, limit - used)}d remaining`;
                        } else {
                            warnEl.style.display = 'none';
                        }
                    }

                    function toggleLeaveMcField() {
                        const type = document.getElementById('formLeaveType').value;
                        const mcField = document.getElementById('sickLeaveMcField');
                        if (!mcField) return;
                        if (type !== 'Sick Leave') { mcField.style.display = 'none'; return; }
                        mcField.style.display = 'block';
                        const email = currentActiveSessionUser?.email;

                        const usedWithMc = email ? getStaffUsedLeaveDays(email, 'Sick Leave', 'With MC') : 0;
                        const usedNoMc = email ? getStaffUsedLeaveDays(email, 'Sick Leave', 'Without MC') : 0;
                        const limitWithMc = getCeilingLimit('Sick Leave', 'With MC');
                        const limitNoMc = getCeilingLimit('Sick Leave', 'Without MC');
                        const consecutiveDays = getCurrentLeaveDuration();

                        const withoutMcRadio = document.querySelector('input[name="mcStatus"][value="Without MC"]');
                        const withMcRadio = document.querySelector('input[name="mcStatus"][value="With MC"]');
                        if (!withoutMcRadio || !withMcRadio) return;

                        const noMcExhausted = usedNoMc >= limitNoMc;
                        const withMcExhausted = usedWithMc >= limitWithMc;
                        const consecutiveRule = consecutiveDays > 2;

                        withoutMcRadio.disabled = noMcExhausted || consecutiveRule;
                        withMcRadio.disabled = withMcExhausted;

                        let infoLines = [];
                        if (noMcExhausted) {
                            withoutMcRadio.checked = false;
                            infoLines.push(`Without MC limit (${limitNoMc}d) exhausted — MC required`);
                        }
                        if (withMcExhausted) {
                            withMcRadio.checked = false;
                            infoLines.push(`With MC limit (${limitWithMc}d) exhausted`);
                        }
                        if (consecutiveRule && !noMcExhausted) {
                            withoutMcRadio.checked = false;
                            infoLines.push(`Leave ${consecutiveDays} consecutive days requires a Medical Certificate`);
                        }
                        if (!noMcExhausted && !withMcExhausted && !consecutiveRule) {
                            const info = mcField.querySelector('.mc-limit-info');
                            if (info) info.remove();
                            return;
                        }
                        if ((noMcExhausted || consecutiveRule) && !withMcExhausted && !withMcRadio.checked) withMcRadio.checked = true;

                        let info = mcField.querySelector('.mc-limit-info');
                        if (!info) {
                            info = document.createElement('div');
                            info.className = 'mc-limit-info';
                            info.style.cssText = 'font-size:9px;color:var(--danger);margin-top:6px;font-weight:600;';
                            mcField.appendChild(info);
                        }
                        info.innerHTML = infoLines.join('<br>');
                    }

                    // Calculate leave duration excluding Fridays and holidays
                    function calculateLeaveDuration() {
                        const fromDate = document.getElementById('formLeaveDateFrom').value;
                        const toDate = document.getElementById('formLeaveDateTo').value;
                        if (!fromDate || !toDate) return;

                        const days = calculateLeaveBusinessDays(fromDate, toDate);
                        const display = document.getElementById('leaveDurationValue');
                        const note = document.getElementById('leaveDurationNote');

                        if (display) display.innerText = days + " Day" + (days !== 1 ? "s" : "");

                        // Show specific holiday names and Friday count
                        const start = new Date(fromDate);
                        const end = new Date(toDate);
                        let fridaysCount = 0;
                        let holidayNames = [];

                        const cur = new Date(start);
                        while (cur <= end) {
                            const dayOfWeek = cur.getDay();
                            const ds = cur.getFullYear() + '-' + String(cur.getMonth() + 1).padStart(2, '0') + '-' + String(cur.getDate()).padStart(2, '0');

                            if (dayOfWeek === 5) {
                                fridaysCount++;
                            } else if (psCalData[ds] && (psCalData[ds].t === 'holiday' || psCalData[ds].t === 'special')) {
                                if (!holidayNames.includes(psCalData[ds].n)) {
                                    holidayNames.push(psCalData[ds].n);
                                }
                            }

                            cur.setDate(cur.getDate() + 1);
                        }

                        if (note) {
                            let notes = [];
                            if (fridaysCount > 0) notes.push(fridaysCount + " Friday(s)");
                            if (holidayNames.length > 0) notes.push(holidayNames.length + " holiday(s): " + holidayNames.join(", "));

                            if (notes.length > 0) {
                                note.innerText = "(Excludes " + notes.join(" | ") + ")";
                            } else {
                                note.innerText = "";
                            }
                        }
                    }

                    // Calculate business days excluding Fridays (day 5) and public holidays
                    function calculateLeaveBusinessDays(fromDateStr, toDateStr) {
                        const fp = fromDateStr.split('-');
                        const tp = toDateStr.split('-');
                        const start = new Date(parseInt(fp[0]), parseInt(fp[1]) - 1, parseInt(fp[2]));
                        const end = new Date(parseInt(tp[0]), parseInt(tp[1]) - 1, parseInt(tp[2]));
                        let count = 0;
                        const current = new Date(start.getFullYear(), start.getMonth(), start.getDate());

                        while (current <= end) {
                            const dayOfWeek = current.getDay(); // 0=Sun, 1=Mon, ..., 5=Fri, 6=Sat
                            // Use LOCAL date string, not UTC toISOString
                            const dateStr = current.getFullYear() + '-' + String(current.getMonth() + 1).padStart(2, '0') + '-' + String(current.getDate()).padStart(2, '0');

                            // Exclude Fridays (5) and public holidays from psCalData
                            if (dayOfWeek !== 5 && !isPSCalHoliday(dateStr)) {
                                count++;
                            }
                            current.setDate(current.getDate() + 1);
                        }
                        return count;
                    } function isPublicHoliday(dateStr) {
                        // Check psCalData for holidays (synced from PS Calendar)
                        if (typeof psCalData !== 'undefined' && psCalData[dateStr]) {
                            const entry = psCalData[dateStr];
                            return entry.t === 'holiday' || entry.t === 'special';
                        }

                        // Fallback hardcoded holidays
                        const holidays = [
                            "2026-01-01", "2026-01-18", "2026-03-11", "2026-04-10",
                            "2026-04-11", "2026-04-12", "2026-05-01", "2026-05-11",
                            "2026-05-12", "2026-07-26", "2026-09-16", "2026-11-03",
                            "2026-11-11", "2026-12-25"
                        ];
                        return holidays.includes(dateStr);
                    }

