                    let profileIsEditing = false;
                    let localProfileUploadedPhotoBase64 = "";
                    let globalStagedCustomFiles = {};

                    // Helper to convert files to Base64 (photo upload pipeline)
function handleSimulatedPhotoChange(inputElement, event) {
    if (event) event.stopPropagation();
    const file = inputElement.files[0];
    if (!file) return;
    compressAndResizeImage(file, 300).then(function (data) {
        localProfileUploadedPhotoBase64 = data;
        const previewAnchor = document.getElementById('myProfileCardAvatarAnchor');
        if (previewAnchor) {
            previewAnchor.innerHTML = '<img src="' + data + '" style="width:100%; height:100%; object-fit:cover; display:block;">';
        }
    });
}

                    // Helper to capture custom field attachments in Edit Mode
                    function handleCustomFieldFileUpload(inputElement, fieldId, event) {
                        if (event) event.stopPropagation();
                        const file = inputElement.files[0];
                        if (!file) return;
                        const maxDim = file.type.startsWith('image/') ? 800 : 99999;
                        compressAndResizeImage(file, maxDim).then(function (data) {
                            globalStagedCustomFiles[fieldId] = {
                                name: file.name,
                                data: data
                            };
                        });
                    }

