                    function autoScanAndRegisterAllLayoutElements() {
                        const textSelectors = 'button, label, th, h1, h2, h3, h4, h5, h6, p, option, span';
                        const textElements = document.querySelectorAll(textSelectors);

                        textElements.forEach(el => {
                            if (
                                el.closest('script') ||
                                el.closest('style') ||
                                el.id === 'rosterDraftStatusBadge' ||
                                el.id === 'systemGlobalModalMount' ||
                                el.closest('#fullscreenDictionaryGridAnchor') ||
                                el.closest('#dictionaryMiniSearch')
                            ) {
                                return;
                            }

                            if (el.children.length === 0) {
                                const rawText = el.innerText.trim();
                                // Guard: Do not register or scan numbers/dates
                                if (rawText.length > 0 && !isExcludedFromDictionary(rawText)) {
                                    if (!el.hasAttribute('data-trans-key')) {
                                        el.setAttribute('data-trans-key', rawText);
                                    }
                                    const key = el.getAttribute('data-trans-key');
                                    if (systemTextDictionary[key] === undefined) {
                                        systemTextDictionary[key] = key;
                                    }
                                    el.innerText = lookupTranslationValue(key);
                                }
                            } else {
                                Array.from(el.childNodes).forEach(node => {
                                    if (node.nodeType === Node.TEXT_NODE) {
                                        const rawText = node.textContent.trim();
                                        // Guard: Do not register or scan numbers/dates
                                        if (rawText.length > 0 && !isExcludedFromDictionary(rawText)) {
                                            if (!node._transKey) {
                                                node._transKey = rawText;
                                            }
                                            const key = node._transKey;
                                            if (systemTextDictionary[key] === undefined) {
                                                systemTextDictionary[key] = key;
                                            }
                                            node.textContent = lookupTranslationValue(key);
                                        }
                                    }
                                });
                            }
                        });

                        const inputElements = document.querySelectorAll('input[placeholder], textarea[placeholder]');
                        inputElements.forEach(input => {
                            if (input.id === 'dictionaryMiniSearch') {
                                return;
                            }
                            const rawPlaceholder = input.getAttribute('placeholder');
                            // Guard: Do not register or scan placeholders matching numbers/dates
                            if (rawPlaceholder && rawPlaceholder.trim().length > 0 && !isExcludedFromDictionary(rawPlaceholder)) {
                                if (!input.hasAttribute('data-trans-placeholder-key')) {
                                    input.setAttribute('data-trans-placeholder-key', rawPlaceholder);
                                }
                                const key = input.getAttribute('data-trans-placeholder-key');
                                if (systemTextDictionary[key] === undefined) {
                                    systemTextDictionary[key] = key;
                                }
                                input.setAttribute('placeholder', lookupTranslationValue(key));
                            }
                        });
                    }
