                    function moveSidebarItem(index, direction) {
                        const targetIndex = index + direction;
                        if (targetIndex >= 0 && targetIndex < globalSidebarOrder.length) {
                            // Swap items inside the global array
                            const temp = globalSidebarOrder[index];
                            globalSidebarOrder[index] = globalSidebarOrder[targetIndex];
                            globalSidebarOrder[targetIndex] = temp;

                            renderSidebarOrderingPanel();
                            rebuildDynamicPortalMenus();
                            renderAccessControlMatrix();
                            // Refresh modal if open
                            if (document.getElementById('sidebarOrderingModalOverlay')) {
                                showSidebarOrderingModal();
                            }
                        }
                    }

