                    function toggleStaffActiveStatus(email, isChecked) {
                        if (currentActiveSessionUser.position !== "Admin") {
                            customAlert("Only Administrative profiles are authorized to modify account activation statuses.");
                            renderStaffComplianceDirectory();
                            return;
                        }
                        const staff = globalRosterRepository.find(u => u.email === email);
                        if (staff) {
                            if (staff.email === currentActiveSessionUser.email) {
                                customAlert("You cannot deactivate your own administrative account.");
                                renderStaffComplianceDirectory();
                                return;
                            }

                            stagedActiveStatusChanges[email] = isChecked;
                        }
                        renderStaffComplianceDirectory();
                    }

                    function commitStagedActiveStatuses() {
                        const pendingEmails = Object.keys(stagedActiveStatusChanges);

                        if (pendingEmails.length === 0) {
                            customAlert("No pending status changes to save.");
                            return;
                        }

                        pendingEmails.forEach(email => {
                            const staff = globalRosterRepository.find(u => u.email === email);
                            if (staff) {
                                staff.active = stagedActiveStatusChanges[email];
                            }
                        });

                        stagedActiveStatusChanges = {};

                        customAlert("Operational active statuses successfully updated and synced across all modules.");

                        synchronizeWorkspaceCoreStatus();
                    }
                    // ==========================================
                    // THERAPIST PERFORMANCE & VOLUME MODULE ENGINE
                    // ==========================================
                    let globalVolumeMasterDatabase = [];
                    let localVolumeDrafts = {};
                    let currentActiveVolumeViewMode = 'table';

                    function populateVolumeAnalyticsFilters() {
                        const sel = document.getElementById('analyticsTherapistFilter');
                        if (!sel) return;

                        sel.innerHTML = `<option value="all">All Therapists (Aggregate)</option>`;

                        const inputDateVal = new Date(document.getElementById('volumeTargetDate').value);

                        globalRosterRepository.forEach(staff => {
                            let isExpiredForNewMonth = false;
                            if (staff.lastDayOfWorking) {
                                const end = new Date(staff.lastDayOfWorking);
                                if (end.getFullYear() < inputDateVal.getFullYear() ||
                                    (end.getFullYear() === inputDateVal.getFullYear() && end.getMonth() < inputDateVal.getMonth())) {
                                    isExpiredForNewMonth = true;
                                }
                            }

                            const isActive = staff.active !== false && (!stagedActiveStatusChanges || stagedActiveStatusChanges[staff.email] !== false);

                            if (!isExpiredForNewMonth && isActive && allowedVolumeEntryRoles.includes(staff.position)) {
                                sel.innerHTML += `<option value="${staff.email}">${staff.name}</option>`;
                            }
                        });
                    }



                    function getSelectedVolumeRoles() {
                        try {
                            const stored = localStorage.getItem('physioVolumeSelectedStaff');
                            if (stored) {
                                const parsed = JSON.parse(stored);
                                if (Array.isArray(parsed) && parsed.length === 0) return null;
                                return parsed;
                            }
                        } catch (e) { }
                        return null;
                    }

                    function renderAnalyticsTherapistFilter() {
                        const sel = document.getElementById('analyticsTherapistFilter');
                        if (!sel) return;
                        const currentVal = sel.value;
                        if (!hasVolumeGridAccess() && currentActiveSessionUser) {
                            sel.innerHTML = `<option value="${currentActiveSessionUser.email}" data-trans-key="${currentActiveSessionUser.name}">${currentActiveSessionUser.name}</option>`;
                            sel.disabled = true;
                            return;
                        }
                        sel.disabled = false;
                        let html = '<option value="all" data-trans-key="All Therapists (Aggregate)">All Therapists (Aggregate)</option>';
                        globalRosterRepository.forEach(s => {
                            if (s.active === false) return;
                            if (!allowedVolumeEntryRoles.includes(s.position)) return;
                            html += `<option value="${s.email}" data-trans-key="${s.name}">${s.name}</option>`;
                        });
                        sel.innerHTML = html;
                        if ([...sel.options].some(o => o.value === currentVal)) sel.value = currentVal;
                    }

                    function renderVolumeRoleFilterBar() {
                        const bar = document.getElementById('volumeRoleFilterBar');
                        if (!bar) return;
                        const targetDateStr = document.getElementById('volumeTargetDate').value;
                        const targetDate = new Date(targetDateStr);
                        const selected = getSelectedVolumeRoles();
                        bar.innerHTML = `<label style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:var(--text-muted);margin-right:4px;white-space:nowrap;">Staff:</label>`;
                        globalRosterRepository.forEach(s => {
                            if (s.active === false) return;
                            if (stagedActiveStatusChanges && stagedActiveStatusChanges[s.email] === false) return;
                            if (!allowedVolumeEntryRoles.includes(s.position)) return;
                            if (s.lastDayOfWorking) {
                                const end = new Date(s.lastDayOfWorking);
                                if (targetDate > end) return;
                            }
                            if (s.joiningDate) {
                                const start = new Date(s.joiningDate);
                                if (targetDate < start) return;
                            }
                            const checked = !selected || selected.includes(s.email) ? 'checked' : '';
                            bar.innerHTML += `
            <label style="font-size:10px;display:flex;align-items:center;gap:3px;cursor:pointer;white-space:nowrap;">
                <input type="checkbox" class="vol-staff-cb" value="${s.email}" ${checked} onchange="onVolumeStaffFilterChange()">
                ${s.name}
            </label>
        `;
                        });
                        bar.innerHTML += `<button class="action-btn" onclick="resetVolumeStaffFilter()" style="margin-left:auto;padding:2px 8px;font-size:9px;">Reset</button>`;
                    }

                    function onVolumeStaffFilterChange() {
                        const cbs = document.querySelectorAll('.vol-staff-cb:checked');
                        const selected = Array.from(cbs).map(cb => cb.value);
                        localStorage.setItem('physioVolumeSelectedStaff', JSON.stringify(selected));
                        renderVolumeEntryGrid();
                    }

                    function resetVolumeStaffFilter() {
                        localStorage.removeItem('physioVolumeSelectedStaff');
                        renderVolumeRoleFilterBar();
                        renderVolumeEntryGrid();
                    }

                    function shiftVolumeDate(delta) {
                        const el = document.getElementById('volumeTargetDate');
                        if (!el || !el.value) return;
                        const d = new Date(el.value);
                        d.setDate(d.getDate() + delta);
                        el.value = d.toISOString().split('T')[0];
                        renderVolumeEntryGrid();
                    }

                    function renderVolumeEntryGrid() {
                        const targetDateStr = document.getElementById('volumeTargetDate').value;
                        const targetDate = new Date(targetDateStr);

                        const thead = document.getElementById('volumeEntryGridHead');
                        const tbody = document.getElementById('volumeEntryGridBody');
                        const tfoot = document.getElementById('volumeEntryGridFoot');
                        if (!thead || !tbody || !tfoot) return;

                        tbody.innerHTML = "";
                        thead.innerHTML = "";
                        tfoot.innerHTML = "";

                        renderVolumeRoleFilterBar();

                        const selectedEmails = getSelectedVolumeRoles();
                        const activeCols = globalTableSchemas.therapist_volume || [];
                        const drafts = localVolumeDrafts[targetDateStr] || {};
                        const isLockedBySend = globalVolumeMasterDatabase.some(e => e.date === targetDateStr && e.finalized);

                        // 1. Generate table headers dynamically based on schema config
                        let headRow = "<tr>";
                        activeCols.forEach(col => {
                            if (col.key !== "date") {
                                headRow += `<th style="background:var(--primary);color:#fff;">${lookupTranslationValue(col.name)}</th>`;
                            }
                        });
                        headRow += "</tr>";
                        thead.innerHTML = headRow;

                        // 2. Generate input cells dynamically based on schema config
                        globalRosterRepository.forEach(staff => {
                            if (staff.active === false) return;
                            if (stagedActiveStatusChanges && stagedActiveStatusChanges[staff.email] === false) return;
                            if (!allowedVolumeEntryRoles.includes(staff.position)) return;
                            if (selectedEmails && !selectedEmails.includes(staff.email)) return;
                            if (staff.lastDayOfWorking) {
                                const end = new Date(staff.lastDayOfWorking);
                                // Hide if target date is AFTER the last working day (strictly greater)
                                if (targetDate > end) return;
                            }
                            if (staff.joiningDate) {
                                const start = new Date(staff.joiningDate);
                                if (targetDate < start) return;
                            }

                            const isLockedBySend = globalVolumeMasterDatabase.some(e => e.date === targetDateStr && e.finalized);
                            const isDisabled = isLockedBySend;
                            const savedRec = globalVolumeMasterDatabase.find(e => e.date === targetDateStr && e.email === staff.email) || {};
                            const draftRec = drafts[staff.email] || {};
                            const statusVal = savedRec._status || draftRec._status || 'active';
                            const inputDisabled = isDisabled || statusVal !== 'active';

                            let rowHtml = `<tr style="${statusVal === 'left' ? 'opacity:0.4;' : statusVal !== 'active' ? 'opacity:0.65;' : ''}">`;

                            activeCols.forEach(col => {
                                const normKey = col.key.toLowerCase();
                                if (normKey === "date") return;

                                const savedValue = savedRec[col.key] !== undefined ? savedRec[col.key] : (draftRec[col.key] !== undefined ? draftRec[col.key] : "");

                                if (normKey === "name" || normKey === "therapist name") {
                                    const statusMap = { active: '✅ Active', leave: '🚫 On Leave', dayoff: '🌴 Day Off', left: '⚫ Left/Resigned' };
                                    const currentStatus = savedRec._status || draftRec._status || 'active';
                                    rowHtml += `
                    <td style="display:flex; flex-direction:column; gap:2px;">
                        <strong style="font-size:11px;">${staff.name}</strong>
                        <select id="volStatus_${staff.email}" onchange="toggleVolStaffStatus('${staff.email}', this.value)" ${isDisabled ? 'disabled' : ''} style="font-size:8px; padding:1px 2px; border-radius:3px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); max-width:110px;">
                            <option value="active" ${currentStatus === 'active' ? 'selected' : ''}>✅ Active</option>
                            <option value="leave" ${currentStatus === 'leave' ? 'selected' : ''}>🚫 On Leave</option>
                            <option value="dayoff" ${currentStatus === 'dayoff' ? 'selected' : ''}>🌴 Day Off</option>
                            <option value="left" ${currentStatus === 'left' ? 'selected' : ''}>⚫ Left/Resigned</option>
                        </select>
                    </td>
                `;
                                } else if (normKey === "addedby" || normKey === "added by") {
                                    const addVal = savedValue || (currentActiveSessionUser ? currentActiveSessionUser.name : "");
                                    rowHtml += `
                    <td>
                        <span style="color:var(--text-muted); font-size:0.9em;">${addVal}</span>
                    </td>
                `;
                                } else if (normKey === "patients" || normKey === "patients logged") {
                                    rowHtml += `
                    <td>
                        <input type="number" id="volInput_${staff.email}_${col.key}" value="${savedValue}" min="0" max="100" 
                            style="width:60px;" ${inputDisabled ? 'disabled' : ''} 
                            oninput="recalculateEntryGridTotals()">
                    </td>
                `;
                                } else if (normKey === "notes" || normKey === "notes remarks") {
                                    rowHtml += `
                    <td>
                        <input type="text" id="volInput_${staff.email}_${col.key}" value="${savedValue}" placeholder="Notes..." ${inputDisabled ? 'disabled' : ''}>
                    </td>
                `;
                                } else {
                                    const inputType = col.type === "number" ? "number" : col.type === "date" ? "date" : "text";
                                    rowHtml += `
                    <td>
                        <input type="${inputType}" id="volInput_${staff.email}_${col.key}" value="${savedValue}" placeholder="Enter ${col.name}..." ${inputDisabled ? 'disabled' : ''}>
                    </td>
                `;
                                }
                            });

                            rowHtml += `</tr>`;
                            tbody.innerHTML += rowHtml;
                        });

                        // 3. Render Table Footer with Auto-Summing Patients Column
                        tfoot.innerHTML = `
        <tr style="background: rgba(0, 34, 68, 0.03); font-weight:700; border-top: 2px solid var(--border);">
            <td style="padding:10px;">Total Summary</td>
            <td id="volumeEntryGridTotalPatients" style="padding:10px; font-weight:800; color:var(--text-heading);">0 Patients</td>
            ${activeCols.length > 3 ? `<td colspan="${activeCols.length - 3}"></td>` : ""}
        </tr>
    `;

                        // Recalculate sums instantly on render
                        recalculateEntryGridTotals();
                    }

                    function recalculateEntryGridTotals() {
                        let total = 0;
                        globalRosterRepository.forEach(staff => {
                            if (!allowedVolumeEntryRoles.includes(staff.position)) return;

                            // Find Patients Logged column key dynamically
                            const patientsKey = (globalTableSchemas.therapist_volume.find(col => col.key === "patients" || col.key === "patients_logged") || { key: "patients" }).key;
                            const el = document.getElementById(`volInput_${staff.email}_${patientsKey}`);
                            if (el) {
                                total += parseInt(el.value) || 0;
                            }
                        });

                        const displayCell = document.getElementById('volumeEntryGridTotalPatients');
                        if (displayCell) {
                            displayCell.innerText = `${total} Patients`;
                        }
                    }

                    function toggleVolStaffStatus(email, status) {
                        const targetDateStr = document.getElementById('volumeTargetDate').value;
                        if (!localVolumeDrafts[targetDateStr]) localVolumeDrafts[targetDateStr] = {};
                        if (!localVolumeDrafts[targetDateStr][email]) localVolumeDrafts[targetDateStr][email] = {};
                        localVolumeDrafts[targetDateStr][email]._status = status;

                        // Also save in the database if a record exists
                        const existingRec = globalVolumeMasterDatabase.find(e => e.date === targetDateStr && e.email === email);
                        if (existingRec) {
                            existingRec._status = status;
                        }

                        const isDisabled = status !== 'active';
                        const activeCols = globalTableSchemas.therapist_volume || [];
                        activeCols.forEach(col => {
                            const el = document.getElementById(`volInput_${email}_${col.key}`);
                            if (el) el.disabled = isDisabled;
                        });

                        // Update row opacity
                        const row = document.querySelector(`#volStatus_${email}`)?.closest('tr');
                        if (row) {
                            row.style.opacity = status === 'left' ? '0.4' : status !== 'active' ? '0.65' : '1';
                        }

                        recalculateEntryGridTotals();
                    }

                    function saveVolumeAsDraft() {
                        const targetDateStr = document.getElementById('volumeTargetDate').value;
                        localVolumeDrafts[targetDateStr] = {};

                        const activeCols = globalTableSchemas.therapist_volume || [];

                        globalRosterRepository.forEach(staff => {
                            if (!allowedVolumeEntryRoles.includes(staff.position)) return;

                            localVolumeDrafts[targetDateStr][staff.email] = {};
                            localVolumeDrafts[targetDateStr][staff.email]._status = document.getElementById(`volStatus_${staff.email}`)?.value || 'active';

                            activeCols.forEach(col => {
                                const el = document.getElementById(`volInput_${staff.email}_${col.key}`);
                                if (el && !el.disabled) {
                                    localVolumeDrafts[targetDateStr][staff.email][col.key] = el.value;
                                }
                            });
                        });

                        customAlert("Draft saved cleanly. You may change values before submitting via 'Save & Send'.");
                    }

                    function submitVolumeMaster() {
                        const targetDateStr = document.getElementById('volumeTargetDate').value;
                        const activeCols = globalTableSchemas.therapist_volume || [];
                        let recordsAdded = 0;

                        globalRosterRepository.forEach(staff => {
                            if (!allowedVolumeEntryRoles.includes(staff.position)) return;

                            const patInput = document.querySelector(`[id^="volInput_${staff.email}_patients"]`);
                            const statusVal = document.getElementById(`volStatus_${staff.email}`)?.value || 'active';
                            if (patInput && !patInput.disabled && patInput.value !== "" && statusVal === 'active') {
                                globalVolumeMasterDatabase = globalVolumeMasterDatabase.filter(e => !(e.date === targetDateStr && e.email === staff.email));

                                let newRecord = {
                                    date: targetDateStr,
                                    email: staff.email,
                                    name: staff.name,
                                    addedBy: currentActiveSessionUser ? currentActiveSessionUser.name : "",
                                    finalized: true
                                };

                                activeCols.forEach(col => {
                                    const el = document.getElementById(`volInput_${staff.email}_${col.key}`);
                                    if (el) {
                                        newRecord[col.key] = col.type === "number" ? parseInt(el.value) || 0 : el.value;
                                    }
                                });

                                newRecord.average = parseFloat(patInput.value) || 0;

                                globalVolumeMasterDatabase.push(newRecord);
                                recordsAdded++;
                            }
                        });

                        if (recordsAdded === 0) {
                            customAlert("Please input valid patients volume parameters.");
                            return;
                        }

                        delete localVolumeDrafts[targetDateStr];
                        customAlert("Database modified. Logged " + recordsAdded + " active entries successfully.");
                        renderVolumeEntryGrid();
                        renderVolumeAnalytics();
                    }

                    function hasVolumeGridAccess() {
                        return currentActiveSessionUser && allowedVolumeEntryGridRoles.includes(currentActiveSessionUser.position);
                    }

                    function syncVolumeTabVisibility() {
                        const entryBtn = document.querySelector('.vol-tab-btn[data-voltab="entry"]');
                        if (entryBtn) {
                            entryBtn.style.display = hasVolumeGridAccess() ? '' : 'none';
                        }
                    }

                    function switchVolumeSubTab(tab) {
                        syncVolumeTabVisibility();
                        if (tab === 'entry' && !hasVolumeGridAccess()) { tab = 'analytics'; }
                        document.querySelectorAll('.vol-tab-btn').forEach(b => {
                            if (b.dataset.voltab === tab) {
                                b.style.background = 'var(--primary)';
                                b.style.color = '#fff';
                                b.style.fontWeight = '700';
                            } else {
                                b.style.background = 'transparent';
                                b.style.color = 'var(--text-muted)';
                                b.style.fontWeight = '600';
                            }
                        });
                        document.getElementById('vol_tab_entry').style.display = tab === 'entry' ? 'block' : 'none';
                        document.getElementById('vol_tab_analytics').style.display = tab === 'analytics' ? 'block' : 'none';
                        if (tab === 'analytics') {
                            renderAnalyticsTherapistFilter();
                            renderVolumeAnalytics();
                        }
                        if (tab === 'entry') renderVolumeEntryGrid();
                    }

                    function switchVolumeView(mode) {
                        currentActiveVolumeViewMode = mode;
                        const tableBtn = document.getElementById('btn_toggle_vol_table');
                        const chartBtn = document.getElementById('btn_toggle_vol_chart');
                        if (mode === 'table') {
                            document.getElementById('volumeTableView').classList.remove('hidden');
                            document.getElementById('volumeChartView').classList.add('hidden');
                            tableBtn.style.background = 'var(--primary)';
                            tableBtn.style.color = '#fff';
                            chartBtn.style.background = 'var(--bg-inner)';
                            chartBtn.style.color = 'var(--text-body)';
                            chartBtn.style.border = '1px solid var(--border)';
                        } else {
                            document.getElementById('volumeTableView').classList.add('hidden');
                            document.getElementById('volumeChartView').classList.remove('hidden');
                            chartBtn.style.background = 'var(--primary)';
                            chartBtn.style.color = '#fff';
                            tableBtn.style.background = 'var(--bg-inner)';
                            tableBtn.style.color = 'var(--text-body)';
                            tableBtn.style.border = '1px solid var(--border)';
                        }
                    }

                    // Helper to hide/show the Month input based on Horizon selection
                    function toggleHorizonInputVisibility(horizonValue) {
                        const wrapper = document.getElementById('analyticsMonthWrapper');
                        if (wrapper) {
                            wrapper.style.display = (horizonValue === 'month') ? 'flex' : 'none';
                        }
                    }

                    // Updates the display style of target wrappers to 'flex' for stacked label structure
                    function handleHorizonSelectionChange(value) {
                        document.getElementById('wrapperAnalyticsDay').style.display = (value === 'day') ? 'flex' : 'none';
                        document.getElementById('wrapperAnalyticsMonth').style.display = (value === 'month') ? 'flex' : 'none';
                        document.getElementById('wrapperAnalyticsRange').style.display = (value === 'range') ? 'flex' : 'none';
                        document.getElementById('wrapperAnalyticsYear').style.display = (value === 'year') ? 'flex' : 'none';
                    }

                    function renderVolumeAnalytics() {
                        renderAnalyticsTherapistFilter();
                        const therapistFilter = document.getElementById('analyticsTherapistFilter').value;
                        const horizon = document.getElementById('analyticsHorizonFilter').value;

                        const dayVal = document.getElementById('analyticsDateFilter').value;
                        const monthVal = document.getElementById('analyticsMonthFilter').value;
                        const rangeStart = document.getElementById('analyticsRangeStart').value;
                        const rangeEnd = document.getElementById('analyticsRangeEnd').value;
                        const yearVal = document.getElementById('analyticsYearFilter').value;

                        const tbody = document.getElementById('analyticsTableBody');
                        if (!tbody) return;
                        tbody.innerHTML = "";

                        // Filters current records
                        let dataset = globalVolumeMasterDatabase.filter(record => {
                            const matchTherapist = (therapistFilter === "all" || record.email === therapistFilter);
                            if (!matchTherapist) return false;

                            const recYear = record.date ? record.date.substring(0, 4) : "";
                            const recMonth = record.date ? record.date.substring(0, 7) : "";

                            if (horizon === "day") {
                                return record.date === dayVal;
                            } else if (horizon === "month") {
                                return recMonth === monthVal;
                            } else if (horizon === "range") {
                                return recMonth >= rangeStart && recMonth <= rangeEnd;
                            } else if (horizon === "year") {
                                return recYear === yearVal;
                            } else {
                                return true;
                            }
                        });

                        // Fallback template values if globalVolumeMasterDatabase has not been populated
                        if (dataset.length === 0 && globalVolumeMasterDatabase.length === 0) {
                            dataset = [];
                        }

                        dataset = dataset.filter(r => {
                            const staff = globalRosterRepository.find(u => u.email === r.email);
                            if (!staff) return true;
                            if (staff.active === false) return false;
                            if (stagedActiveStatusChanges && stagedActiveStatusChanges[r.email] === false) return false;
                            if (staff.lastDayOfWorking && r.date && r.date > staff.lastDayOfWorking) return false;
                            return true;
                        });

                        if (!hasVolumeGridAccess() && currentActiveSessionUser) {
                            dataset = dataset.filter(r => r.email === currentActiveSessionUser.email);
                        }

                        const activeCols = globalTableSchemas.therapist_volume || [];
                        dataset.forEach(r => {
                            let rowHtml = "<tr>";
                            activeCols.forEach(col => {
                                const normKey = col.key.toLowerCase();
                                const rawVal = r[col.key] !== undefined ? r[col.key] : "";

                                if (normKey === 'date') {
                                    rowHtml += `<td><strong>${formatDateToDDMMYYYY(r.date || rawVal)}</strong></td>`;
                                } else if (normKey === 'name' || normKey === 'therapist name') {
                                    rowHtml += `<td>${r.name || rawVal}</td>`;
                                } else if (normKey === 'patients' || normKey === 'patients logged') {
                                    rowHtml += `<td><span class="badge badge-primary">${r.patients || rawVal} Patients</span></td>`;
                                } else if (normKey === 'average' || normKey === 'active work avg') {
                                    rowHtml += `<td><strong>${typeof r.average === 'number' ? r.average.toFixed(1) : rawVal}</strong></td>`;
                                } else if (normKey === 'notes' || normKey === 'notes remarks') {
                                    rowHtml += `<td>${r.notes || rawVal || '-'}</td>`;
                                } else {
                                    rowHtml += `<td>${rawVal || '-'}</td>`;
                                }
                            });
                            rowHtml += "</tr>";
                            tbody.innerHTML += rowHtml;
                        });

                        // Calculate sum of logged patients dynamically from selected subset
                        const totalPatients = dataset.reduce((sum, item) => sum + (parseInt(item.patients) || 0), 0);
                        const tfoot = document.getElementById('analyticsTableFoot');
                        if (tfoot) {
                            let footHtml = "<tr>";
                            activeCols.forEach((col, index) => {
                                const normKey = col.key.toLowerCase();

                                // Render the aggregated sum directly in the matched "Patients Logged" column space
                                if (normKey === 'patients' || normKey === 'patients logged' || col.name.toLowerCase().includes('patients')) {
                                    footHtml += `<td style="padding: 10px; font-weight:800; color:var(--text-heading); border-top: 2px solid var(--border); text-align:center;"><span class="badge badge-primary" style="font-size:10px; padding: 4px 8px;">${totalPatients} Patients</span></td>`;
                                } else if (index === 0) {
                                    footHtml += `<td style="padding: 10px; font-weight:800; color:var(--text-heading); border-top: 2px solid var(--border); text-align:left;">Total Logged</td>`;
                                } else {
                                    footHtml += `<td style="border-top: 2px solid var(--border);"></td>`;
                                }
                            });
                            footHtml += "</tr>";
                            tfoot.innerHTML = footHtml;
                        }

                        renderFlexVisualCharts(dataset);
                    }

                    // Draws the visual CSS charts using absolute peak-height calculations (avoids percentage margins)
                    function renderFlexVisualCharts(dataset) {
                        const chartContainer = document.getElementById('visualChartContainer');
                        const labelContainer = document.getElementById('visualChartLabels');
                        const chartStyle = document.getElementById('chartStyleSelector').value;

                        if (!chartContainer || !labelContainer) return;

                        chartContainer.innerHTML = "";
                        labelContainer.innerHTML = "";

                        if (dataset.length === 0) {
                            chartContainer.innerHTML = `<div style="margin: auto; color: var(--text-muted); font-style: italic;">No performance datasets map to current filters.</div>`;
                            return;
                        }

                        // Aggregate by therapist name so each person appears once with total patients
                        const agg = {};
                        dataset.forEach(d => {
                            if (!agg[d.email]) agg[d.email] = { ...d, patients: 0, count: 0 };
                            agg[d.email].patients += (d.patients || 0);
                            agg[d.email].count++;
                        });
                        dataset = Object.values(agg);

                        const maxVal = Math.max(...dataset.map(d => d.patients), 5);
                        const colors = ['var(--primary)', 'var(--success)', 'var(--warning)', 'var(--danger)', '#8b5cf6', '#ec4899', '#14b8a6', '#f97316', '#06b6d4', '#84cc16'];

                        // ---- Special layout charts (non-flex-bar) ----
                        if (chartStyle === "pie") {
                            const total = dataset.reduce((s, d) => s + (d.patients || 0), 0);
                            let conic = dataset.map((d, i) => {
                                const pct = ((d.patients || 0) / total) * 100;
                                return `${colors[i % colors.length]} ${i === 0 ? 0 : dataset.slice(0, i).reduce((s, x) => s + (x.patients / total) * 100, 0)}% ${dataset.slice(0, i + 1).reduce((s, x) => s + (x.patients / total) * 100, 0)}%`;
                            }).join(', ');
                            chartContainer.style.cssText = 'display:flex; align-items:center; justify-content:center; gap:20px; min-height:200px;';
                            chartContainer.innerHTML = `
            <div style="width:160px; height:160px; border-radius:50%; background:conic-gradient(${conic}); border:3px solid var(--border); flex-shrink:0;"></div>
            <div style="display:flex; flex-direction:column; gap:4px; font-size:10px;">
                ${dataset.map((d, i) => `<span style="display:flex; align-items:center; gap:6px;"><span style="width:10px; height:10px; border-radius:2px; background:${colors[i % colors.length]}; flex-shrink:0;"></span>${d.name}: ${d.patients} (${((d.patients / total) * 100).toFixed(1)}%)</span>`).join('')}
            </div>`;
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "donut") {
                            const total = dataset.reduce((s, d) => s + (d.patients || 0), 0);
                            let conic = dataset.map((d, i) => {
                                return `${colors[i % colors.length]} ${i === 0 ? 0 : dataset.slice(0, i).reduce((s, x) => s + (x.patients / total) * 100, 0)}% ${dataset.slice(0, i + 1).reduce((s, x) => s + (x.patients / total) * 100, 0)}%`;
                            }).join(', ');
                            chartContainer.style.cssText = 'display:flex; align-items:center; justify-content:center; gap:20px; min-height:200px;';
                            chartContainer.innerHTML = `
            <div style="position:relative; width:160px; height:160px; flex-shrink:0;">
                <div style="width:160px; height:160px; border-radius:50%; background:conic-gradient(${conic});"></div>
                <div style="position:absolute; top:35px; left:35px; width:90px; height:90px; border-radius:50%; background:var(--bg-card); display:flex; align-items:center; justify-content:center; font-size:18px; font-weight:800; color:var(--text-heading);">${total}</div>
            </div>
            <div style="display:flex; flex-direction:column; gap:4px; font-size:10px;">
                ${dataset.map((d, i) => `<span style="display:flex; align-items:center; gap:6px;"><span style="width:10px; height:10px; border-radius:2px; background:${colors[i % colors.length]}; flex-shrink:0;"></span>${d.name}: ${d.patients} (${((d.patients / total) * 100).toFixed(1)}%)</span>`).join('')}
            </div>`;
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "treemap") {
                            const total = dataset.reduce((s, d) => s + (d.patients || 0), 0);
                            chartContainer.style.cssText = 'display:grid; grid-template-columns: repeat(auto-fit, minmax(80px, 1fr)); gap:4px; min-height:200px; align-content:start;';
                            chartContainer.innerHTML = dataset.map((d, i) => {
                                const pct = ((d.patients || 0) / total) * 100;
                                return `<div style="background:${colors[i % colors.length]}; border-radius:6px; padding:8px; display:flex; flex-direction:column; align-items:center; justify-content:center; min-height:60px; color:#fff; font-size:10px; font-weight:700; text-align:center;"><span>${d.name}</span><span style="font-size:14px; margin-top:2px;">${d.patients}</span></div>`;
                            }).join('');
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "sunburst") {
                            const total = dataset.reduce((s, d) => s + (d.patients || 0), 0);
                            let innerConic = dataset.map((d, i) => `${colors[i % colors.length]} ${i === 0 ? 0 : dataset.slice(0, i).reduce((s, x) => s + (x.patients / total) * 100, 0)}% ${dataset.slice(0, i + 1).reduce((s, x) => s + (x.patients / total) * 100, 0)}%`).join(', ');
                            chartContainer.style.cssText = 'display:flex; align-items:center; justify-content:center; gap:16px; min-height:200px;';
                            chartContainer.innerHTML = `
            <div style="position:relative; width:180px; height:180px; flex-shrink:0;">
                <div style="width:180px; height:180px; border-radius:50%; background:conic-gradient(${innerConic});"></div>
                <div style="position:absolute; top:55px; left:55px; width:70px; height:70px; border-radius:50%; background:conic-gradient(${innerConic}); border:4px solid var(--bg-card);"></div>
                <div style="position:absolute; top:70px; left:70px; width:40px; height:40px; border-radius:50%; background:var(--bg-card); display:flex; align-items:center; justify-content:center; font-size:14px; font-weight:800; color:var(--text-heading);">${total}</div>
            </div>
            <div style="display:flex; flex-direction:column; gap:3px; font-size:9px;">
                ${dataset.map((d, i) => `<span style="display:flex; align-items:center; gap:4px;"><span style="width:8px; height:8px; border-radius:50%; background:${colors[i % colors.length]}; flex-shrink:0;"></span>${d.name}: ${d.patients}</span>`).join('')}
            </div>`;
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "radar") {
                            const count = dataset.length;
                            const cx = 100, cy = 100, r = 80;
                            const angleStep = (2 * Math.PI) / count;
                            const points = dataset.map((d, i) => {
                                const angle = i * angleStep - Math.PI / 2;
                                const val = (d.patients / maxVal) * r;
                                return { x: cx + val * Math.cos(angle), y: cy + val * Math.sin(angle), label: d.name.split(' ')[0], val: d.patients };
                            });
                            const polyPts = points.map(p => `${p.x},${p.y}`).join(' ');
                            chartContainer.style.cssText = 'display:flex; align-items:center; justify-content:center; min-height:200px;';
                            chartContainer.innerHTML = `
            <svg width="200" height="200" viewBox="0 0 200 200">
                ${[0.25, 0.5, 0.75, 1].map(l => {
                                const lr = l * r;
                                const lpts = points.map((_, i) => {
                                    const angle = i * angleStep - Math.PI / 2;
                                    return `${cx + lr * Math.cos(angle)},${cy + lr * Math.sin(angle)}`;
                                }).join(' ');
                                return `<polygon points="${lpts}" fill="none" stroke="var(--border)" stroke-width="1"/>`;
                            }).join('')}
                ${points.map(p => {
                                const angle = points.indexOf(p) * angleStep - Math.PI / 2;
                                const lx = cx + (r + 14) * Math.cos(angle);
                                const ly = cy + (r + 14) * Math.sin(angle);
                                const anchor = angle > Math.PI / 2 && angle < 3 * Math.PI / 2 ? 'end' : 'start';
                                return `<line x1="${cx}" y1="${cy}" x2="${cx + r * Math.cos(angle)}" y2="${cy + r * Math.sin(angle)}" stroke="var(--border)" stroke-width="1"/>
                        <text x="${lx}" y="${ly}" text-anchor="${anchor}" font-size="8" fill="var(--text-muted)">${p.label}</text>`;
                            }).join('')}
                <polygon points="${polyPts}" fill="rgba(0,114,227,0.15)" stroke="var(--primary)" stroke-width="2"/>
                ${points.map(p => `<circle cx="${p.x}" cy="${p.y}" r="3" fill="var(--primary)"/>`).join('')}
            </svg>
            <div style="display:flex; flex-direction:column; gap:3px; font-size:9px; margin-left:12px;">
                ${dataset.map((d, i) => `<span style="display:flex; align-items:center; gap:4px;"><span style="width:8px; height:8px; border-radius:50%; background:${colors[i % colors.length]}; flex-shrink:0;"></span>${d.name}: ${d.patients}</span>`).join('')}
            </div>`;
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "heatmap") {
                            chartContainer.style.cssText = 'display:grid; grid-template-columns: repeat(auto-fill, minmax(40px, 1fr)); gap:3px; min-height:200px; align-content:start; padding:8px;';
                            chartContainer.innerHTML = dataset.map(d => {
                                const intensity = (d.patients / maxVal);
                                const bg = `rgba(0, 114, 227, ${0.15 + intensity * 0.75})`;
                                return `<div style="background:${bg}; border-radius:4px; padding:6px 4px; display:flex; flex-direction:column; align-items:center; justify-content:center; min-height:50px; font-size:8px; font-weight:700; color:${intensity > 0.5 ? '#fff' : 'var(--text-heading)'}; text-align:center; border:1px solid var(--border);"><span>${d.patients}</span><span style="font-size:7px; font-weight:400; margin-top:2px;">${d.name.split(' ')[0]}</span></div>`;
                            }).join('');
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "boxplot") {
                            const vals = dataset.map(d => d.patients).sort((a, b) => a - b);
                            const min = vals[0], max = vals[vals.length - 1];
                            const q1 = vals[Math.floor(vals.length * 0.25)], med = vals[Math.floor(vals.length * 0.5)], q3 = vals[Math.floor(vals.length * 0.75)];
                            const range = max - min || 1;
                            const toPct = v => ((v - min) / range) * 100;
                            chartContainer.style.cssText = 'display:flex; align-items:center; justify-content:center; min-height:200px;';
                            chartContainer.innerHTML = `
            <div style="position:relative; width:80%; height:100px; border-left:2px solid var(--border); border-right:2px solid var(--border); display:flex; align-items:center; justify-content:center;">
                <div style="position:absolute; left:${toPct(Math.min(...vals))}%; width:${toPct(Math.max(...vals)) - toPct(Math.min(...vals))}%; height:2px; background:var(--text-muted); top:50%;"></div>
                <div style="position:absolute; left:${toPct(q1)}%; width:${toPct(q3) - toPct(q1)}%; height:60px; background:rgba(0,114,227,0.15); border:2px solid var(--primary); border-radius:4px; top:20px;"></div>
                <div style="position:absolute; left:${toPct(med)}%; width:2px; height:60px; background:var(--danger); top:20px;"></div>
                <div style="position:absolute; left:${toPct(min)}%; top:45px; font-size:9px; font-weight:700; color:var(--text-muted);">Min: ${min}</div>
                <div style="position:absolute; left:${toPct(q1)}%; top:5px; font-size:8px; color:var(--text-muted);">Q1: ${q1}</div>
                <div style="position:absolute; left:${toPct(med)}%; top:85px; font-size:9px; font-weight:700; color:var(--danger);">Median: ${med}</div>
                <div style="position:absolute; left:${toPct(q3)}%; top:5px; font-size:8px; color:var(--text-muted);">Q3: ${q3}</div>
                <div style="position:absolute; left:${toPct(max)}%; top:45px; font-size:9px; font-weight:700; color:var(--text-muted);">Max: ${max}</div>
            </div>`;
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "sankey") {
                            const total = dataset.reduce((s, d) => s + (d.patients || 0), 0);
                            chartContainer.style.cssText = 'display:flex; flex-direction:column; gap:6px; justify-content:center; min-height:200px; padding:12px;';
                            chartContainer.innerHTML = dataset.map((d, i) => {
                                const pct = (d.patients / total) * 100;
                                return `<div style="display:flex; align-items:center; gap:8px;">
                <span style="width:80px; font-size:9px; text-align:right; font-weight:600; color:var(--text-heading); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${d.name.split(' ')[0]}</span>
                <div style="flex:1; height:24px; background:var(--bg-inner); border-radius:0 12px 12px 0; position:relative;">
                    <div style="width:${pct}%; height:100%; background:${colors[i % colors.length]}; border-radius:0 12px 12px 0; display:flex; align-items:center; padding-left:6px;">
                        <span style="font-size:9px; font-weight:700; color:#fff; white-space:nowrap;">${d.patients}</span>
                    </div>
                </div>
            </div>`;
                            }).join('');
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "funnel") {
                            chartContainer.style.cssText = 'display:flex; flex-direction:column; align-items:center; justify-content:flex-end; gap:4px; min-height:200px; padding:12px;';
                            const sorted = [...dataset].sort((a, b) => b.patients - a.patients);
                            const maxW = 100;
                            sorted.forEach((d, i) => {
                                const w = (d.patients / sorted[0].patients) * maxW;
                                const div = document.createElement('div');
                                div.style.cssText = `width:${w}%; height:28px; background:${colors[i % colors.length]}; border-radius:4px; display:flex; align-items:center; justify-content:center; color:#fff; font-size:9px; font-weight:700; transition:width 0.3s ease;`;
                                div.innerText = `${d.name.split(' ')[0]}: ${d.patients}`;
                                chartContainer.appendChild(div);
                            });
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "gantt") {
                            chartContainer.style.cssText = 'display:flex; flex-direction:column; gap:6px; justify-content:center; min-height:200px; padding:12px; overflow-y:auto;';
                            dataset.forEach((d, i) => {
                                const dur = d.patients;
                                const w = (dur / maxVal) * 100;
                                const div = document.createElement('div');
                                div.style.cssText = `display:flex; align-items:center; gap:8px;`;
                                div.innerHTML = `
                <span style="width:70px; font-size:9px; font-weight:600; color:var(--text-heading); text-align:right; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${d.name.split(' ')[0]}</span>
                <div style="flex:1; height:22px; background:var(--bg-inner); border-radius:4px; position:relative;">
                    <div style="width:${w}%; height:100%; background:${colors[i % colors.length]}; border-radius:4px; display:flex; align-items:center; padding-left:6px;">
                        <span style="font-size:8px; font-weight:700; color:#fff;">${d.patients}</span>
                    </div>
                </div>
                <span style="font-size:8px; color:var(--text-muted); width:50px;">${formatDateToDDMMYYYY(d.date).substring(0, 5)}</span>`;
                                chartContainer.appendChild(div);
                            });
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "bubble") {
                            chartContainer.style.cssText = 'display:flex; align-items:flex-end; justify-content:center; gap:12px; min-height:200px; padding:8px;';
                            dataset.forEach((d, i) => {
                                const r = 10 + (d.patients / maxVal) * 40;
                                const div = document.createElement('div');
                                div.style.cssText = `display:flex; flex-direction:column; align-items:center; gap:4px;`;
                                div.innerHTML = `
                <div style="width:${r * 2}px; height:${r * 2}px; border-radius:50%; background:${colors[i % colors.length]}; display:flex; align-items:center; justify-content:center; color:#fff; font-size:${Math.max(8, r * 0.4)}px; font-weight:700; opacity:0.85;">${d.patients}</div>
                <span style="font-size:8px; font-weight:600; color:var(--text-heading); text-align:center;">${d.name.split(' ')[0]}</span>`;
                                chartContainer.appendChild(div);
                            });
                            labelContainer.innerHTML = '';
                            return;
                        }
                        if (chartStyle === "waterfall") {
                            let running = 0;
                            chartContainer.style.cssText = 'display:flex; align-items:flex-end; gap:4px; min-height:200px; padding:8px 4px;';
                            dataset.forEach((d, i) => {
                                const isLast = i === dataset.length - 1;
                                const h = (d.patients / maxVal) * 85;
                                const startH = (running / maxVal) * 85;
                                const div = document.createElement('div');
                                div.style.cssText = `flex:1; display:flex; flex-direction:column; align-items:center; justify-content:flex-end; position:relative;`;
                                const bar = document.createElement('div');
                                bar.style.cssText = `width:100%; height:${h}%; min-height:6px; background:${isLast ? 'var(--success)' : 'var(--primary)'}; border-radius:3px 3px 0 0; display:flex; align-items:flex-start; justify-content:center; position:relative; transition:height 0.3s ease;`;
                                bar.innerHTML = `<span style="color:#fff; font-size:8px; font-weight:700; margin-top:2px;">${d.patients}</span>`;
                                div.appendChild(bar);
                                if (!isLast) {
                                    const connector = document.createElement('div');
                                    connector.style.cssText = `position:absolute; bottom:${startH}%; width:100%; height:2px; background:var(--text-muted); opacity:0.3;`;
                                    div.appendChild(connector);
                                }
                                running += d.patients;
                                chartContainer.appendChild(div);
                            });
                            dataset.forEach(item => {
                                const labelEl = document.createElement('span');
                                labelEl.style = "flex: 1; text-align: center; font-size: 7px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color:var(--text-muted);";
                                labelEl.innerText = `${item.name.split(' ')[0]} (${formatDateToDDMMYYYY(item.date).substring(0, 5)})`;
                                labelContainer.appendChild(labelEl);
                            });
                            chartContainer.style.cssText += ';border-bottom:2px solid var(--border);margin-bottom:8px;';
                            return;
                        }

                        // ---- Standard flex-bar layout for bar/histogram/line/area/scatter ----
                        chartContainer.style.cssText = 'display:flex; align-items:flex-end; gap:12px; min-height:200px; border-bottom:2px solid var(--border); padding-bottom:10px; margin-bottom:8px; background:var(--bg-inner); border-radius:8px; padding:12px;';
                        dataset.forEach(item => {
                            const heightPercent = (item.patients / maxVal) * 85;
                            const barBlock = document.createElement('div');

                            if (chartStyle === "bar" || chartStyle === "histogram") {
                                barBlock.style = `
                flex: 1; 
                height: ${heightPercent}%; 
                background: ${colors[dataset.indexOf(item) % colors.length]}; 
                border-radius: 4px 4px 0 0; 
                position: relative; 
                min-width: 18px;
                display: flex;
                align-items: flex-start;
                justify-content: center;
                transition: height 0.3s ease;
            `;
                                barBlock.innerHTML = `<span style="color: white; font-size: 8px; font-weight: 700; margin-top: 4px;">${item.patients}</span>`;
                            } else if (chartStyle === "line") {
                                const itemColor = colors[dataset.indexOf(item) % colors.length];
                                barBlock.style = `
                flex: 1;
                height: ${heightPercent}%;
                position: relative;
                min-width: 18px;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: flex-start;
            `;
                                barBlock.innerHTML = `
                <div style="width: 8px; height: 8px; border-radius: 50%; background: ${itemColor}; border: 2px solid var(--bg-inner); box-shadow: 0 0 0 2px ${itemColor}; margin-top: -4px;"></div>
                <div style="position: absolute; top: -20px; font-size: 8px; font-weight: 700; color: var(--text-heading);">${item.patients}</div>
            `;
                            } else if (chartStyle === "area") {
                                const itemColor = colors[dataset.indexOf(item) % colors.length];
                                barBlock.style = `
                flex: 1;
                height: ${heightPercent}%;
                position: relative;
                min-width: 18px;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: flex-start;
                background: linear-gradient(to top, ${itemColor}20 0%, ${itemColor}05 100%);
                border-top: 2px solid ${itemColor};
            `;
                                barBlock.innerHTML = `
                <div style="width: 8px; height: 8px; border-radius: 50%; background: ${itemColor}; border: 2px solid var(--bg-inner); box-shadow: 0 0 0 2px ${itemColor}; margin-top: -5px;"></div>
                <div style="position: absolute; top: -20px; font-size: 8px; font-weight: 700; color: var(--text-heading);">${item.patients}</div>
            `;
                            } else if (chartStyle === "scatter") {
                                const itemColor = colors[dataset.indexOf(item) % colors.length];
                                barBlock.style = `
                flex: 1;
                height: ${heightPercent}%;
                position: relative;
                min-width: 18px;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: flex-start;
            `;
                                barBlock.innerHTML = `
                <div style="width: 10px; height: 10px; background: ${itemColor}; border-radius: 4px; transform: rotate(45deg); margin-top: -5px;"></div>
                <div style="position: absolute; top: -20px; font-size: 8px; font-weight: 700; color: var(--text-heading);">${item.patients}</div>
            `;
                            }

                            chartContainer.appendChild(barBlock);

                            const labelEl = document.createElement('span');
                            labelEl.style = "flex: 1; text-align: center; font-size: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;";
                            labelEl.innerText = `${item.name.split(' ')[0]} (${formatDateToDDMMYYYY(item.date).substring(0, 5)})`;
                            labelContainer.appendChild(labelEl);
                        });
                    }
                    // ==========================================
                    // FOLLOW-UP CASES MODULE BUSINESS LOGIC
                    // ==========================================

                    /**
                     * 1. Populates the therapist drop-down menu with active therapists 
                     * from the global roster directory.
                     */
                    function populateFollowupTherapistsDropdown() {
                        const sel = document.getElementById('followupTherapistSelector');
                        if (!sel) return;
                        sel.innerHTML = "";

                        globalRosterRepository.forEach(staff => {
                            if (allowedAssignedPractitionerRoles.includes(staff.position)) {
                                sel.innerHTML += `<option value="${staff.email}">${staff.name}</option>`;
                            }
                        });
                    }

                    /**
                     * 2. Renders the followup cases table.
                     * Contains role-based view filters (Therapists only see their assigned cases).
                     */
                    function renderFollowupCasesTable() {
                        const tbody = document.getElementById('followupCasesTableBody');
                        const entryCard = document.getElementById('followupEntryCard');
                        if (!tbody) return;
                        tbody.innerHTML = "";

                        const canRegister = allowedFollowupRoles.includes(currentActiveSessionUser.position);
                        const ledgerPanel = document.getElementById('followupLedgerPanel');

                        if (entryCard) {
                            if (canRegister) {
                                entryCard.classList.remove('hidden');
                                if (ledgerPanel) { ledgerPanel.classList.remove('span-12'); ledgerPanel.classList.add('span-8'); }
                            } else {
                                entryCard.classList.add('hidden');
                                if (ledgerPanel) { ledgerPanel.classList.remove('span-8'); ledgerPanel.classList.add('span-12'); }
                            }
                        }

                        // Retrieves "YYYY-MM" from the month input
                        const filterMonth = document.getElementById('followupMonthSelector') ? document.getElementById('followupMonthSelector').value : "";

                        let filtered = globalFollowupCasesRepository;

                        // Checks if a month is selected, then evaluates the first 7 characters ("YYYY-MM")
                        if (filterMonth) {
                            filtered = filtered.filter(c => c.date.substring(0, 7) === filterMonth);
                        }

                        const isTherapist = currentActiveSessionUser.position === "Physiotherapist" || currentActiveSessionUser.position === "Head of Physio";
                        if (isTherapist) {
                            filtered = filtered.filter(c => c.therapistEmail === currentActiveSessionUser.email);
                        }

                        if (filtered.length === 0) {
                            tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; color:var(--text-muted); font-style:italic;">No follow-up cases mapped for this month.</td></tr>`;
                            return;
                        }

                        filtered.forEach((c, index) => {
                            const canEdit = (c.assignedByEmail === currentActiveSessionUser.email || currentActiveSessionUser.position === "Admin");
                            const actionHtml = canEdit ?
                                `<button class="action-btn" style="padding:2px 6px;" onclick="openEditFollowupModal(${c.id})">✏️ Edit</button>` :
                                `<span style="font-style:italic; opacity:0.6; font-size:10px;">Locked</span>`;

                            const tr = document.createElement('tr');
                            tr.innerHTML = `
            <td><strong>${index + 1}</strong></td>
            <td>${c.date}</td>
            <td><strong>${c.patientName}</strong></td>
            <td>${c.idCard}</td>
            <td>${c.details}</td>
            <td>${c.fdoName}</td>
            <td><span class="badge badge-primary">${c.therapistName}</span></td>
            <td>${actionHtml}</td>
        `;
                            tbody.appendChild(tr);
                        });
                    }

                    /**
                     * 3. Commits a new follow-up case entry to the repository array.
                     * Automatically triggers a notification alert inside the system logs.
                     */
                    function commitFollowupCaseEntry() {
                        if (!allowedFollowupRoles.includes(currentActiveSessionUser.position)) return;
                        const date = document.getElementById('followupDate').value;
                        const name = document.getElementById('followupPatientName').value.trim();
                        const idCard = document.getElementById('followupIdCard').value.trim();
                        const tEmail = document.getElementById('followupTherapistSelector').value;
                        const details = document.getElementById('followupDetails').value.trim();

                        if (!date || !name || !idCard || !details) {
                            customAlert("Please enter valid patient details and case observations.");
                            return;
                        }

                        const therapistStaff = globalRosterRepository.find(u => u.email === tEmail);
                        const therapistName = therapistStaff ? therapistStaff.name : "Physiotherapist";

                        const newCase = {
                            id: Date.now(),
                            date: date,
                            patientName: name,
                            idCard: idCard,
                            details: details,
                            assignedByEmail: currentActiveSessionUser.email,
                            fdoName: currentActiveSessionUser.name,
                            therapistEmail: tEmail,
                            therapistName: therapistName
                        };

                        globalFollowupCasesRepository.push(newCase);

                        // Write a notification alert into the system logs
                        systemAlertLogs.unshift({
                            id: Date.now(),
                            tier: 'urgent',
                            text: `New Follow-up assigned to ${therapistName} for patient: ${name}`,
                            channel: 'Follow-up alert',
                            timestamp: 'Just Now',
                            lifespan: '24 hours'
                        });

                        // Reset input fields
                        document.getElementById('followupPatientName').value = "";
                        document.getElementById('followupIdCard').value = "";
                        document.getElementById('followupDetails').value = "";

                        customAlert(`Follow-up case successfully assigned to ${therapistName}. Therapist alert notification triggered.`);
                        synchronizeWorkspaceCoreStatus();
                    }

                    /**
                     * 4. Opens the inline system modal to edit followup case files.
                     * (Only allowed for the assigning user or an Admin).
                     */
                    function openEditFollowupModal(caseId) {
                        const target = globalFollowupCasesRepository.find(c => c.id === caseId);
                        if (!target) return;

                        let selectorHtml = "";
                        globalRosterRepository.forEach(staff => {
                            if (staff.position === "Physiotherapist" || staff.position === "Head of Physio" || staff.position === "Head of Training and Recruitment") {
                                const isSelected = (staff.email === target.therapistEmail) ? "selected" : "";
                                selectorHtml += `<option value="${staff.email}" ${isSelected}>${staff.name}</option>`;
                            }
                        });

                        const mount = document.getElementById('systemGlobalModalMount');
                        mount.innerHTML = `
        <div class="system-inline-modal-overlay">
            <div class="system-inline-modal-box">
                <h3 style="margin-bottom:12px; border-bottom:1px solid var(--border); padding-bottom:6px;">✏️ Modify Case Details: ${target.patientName}</h3>
                <div class="form-group">
                    <label>Target Date</label>
                    <input type="date" id="editFollowupDate" value="${target.date}">
                </div>
                <div class="form-group">
                    <label>Patient Name</label>
                    <input type="text" id="editFollowupPatientName" value="${target.patientName}">
                </div>
                <div class="form-group">
                    <label>ID Card Number</label>
                    <input type="text" id="editFollowupIdCard" value="${target.idCard}">
                </div>
                <div class="form-group">
                    <label>Assigned Therapist</label>
                    <select id="editFollowupTherapist" style="width: 100%; padding: 8px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body);">
                        ${selectorHtml}
                    </select>
                </div>
                <div class="form-group">
                    <label>Details & Instructions</label>
                    <textarea id="editFollowupDetails" style="height:60px;">${target.details}</textarea>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:16px;">
                    <button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Dismiss</button>
                    <button class="action-btn" style="background:var(--success);" onclick="commitFollowupEdit(${caseId})">Update Details</button>
                </div>
            </div>
        </div>
    `;
                    }

                    /**
                     * 5. Saves modifications to a followup case.
                     */
                    function commitFollowupEdit(caseId) {
                        const target = globalFollowupCasesRepository.find(c => c.id === caseId);
                        if (target) {
                            target.date = document.getElementById('editFollowupDate').value;
                            target.patientName = document.getElementById('editFollowupPatientName').value.trim();
                            target.idCard = document.getElementById('editFollowupIdCard').value.trim();

                            const tEmail = document.getElementById('editFollowupTherapist').value;
                            const therapistStaff = globalRosterRepository.find(u => u.email === tEmail);

                            target.therapistEmail = tEmail;
                            target.therapistName = therapistStaff ? therapistStaff.name : "Physiotherapist";
                            target.details = document.getElementById('editFollowupDetails').value.trim();

                            customAlert("Follow-up case parameters synchronized successfully.");
                            closeSystemModalBox();
                            synchronizeWorkspaceCoreStatus();
                        }
                    }
                    // =========================================================================
                    // REFACTORED OPERATIONAL TIMESHEET SYSTEM LOGIC
                    // =========================================================================

                    /**
                     * Calculates dates from the 21st of the previous month to the 21st of the current month
                     */
                    function generateOTTimesheet31DaysList() {
                        const list = [];
                        const year = parseInt(globalOTSelectedYear);
                        const monthIndex = parseInt(globalOTSelectedMonth) - 1;

                        const startDay = parseInt(globalOTCycleStartDay) || 21;

                        const startDate = new Date(Date.UTC(year, monthIndex - 1, startDay));
                        const endDate = new Date(Date.UTC(year, monthIndex, startDay - 1));

                        let current = new Date(startDate);
                        while (current <= endDate) {
                            const dayName = current.toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' });
                            const month = current.getUTCMonth() + 1;
                            const day = current.getUTCDate();
                            const yr = current.getUTCFullYear();

                            const formattedDay = String(day).padStart(2, '0');
                            const formattedMonth = String(month).padStart(2, '0');

                            // Formatted as dd/mm/yyyy
                            list.push({
                                fullDate: `${formattedDay}/${formattedMonth}/${yr}`,
                                dayName: dayName
                            });
                            current.setUTCDate(current.getUTCDate() + 1);
                        }
                        return list;
                    }

                    /**
                     * Updates global date properties and triggers UI rendering
                     */
                    function changeActiveOTCycle() {
                        const isOvertimeTracker = (globalActiveViewportModule === 'overtime_tracker');
                        const isMasterOT = (globalActiveViewportModule === 'master_ot_sheet');
                        const isAdminOT = (globalActiveViewportModule === 'admin_master_ot');

                        let activeValue = "";
                        if (isOvertimeTracker) {
                            activeValue = document.getElementById('otTrackerCycleSelector').value;
                        } else if (isMasterOT) {
                            activeValue = document.getElementById('masterOtCycleSelector').value;
                        } else if (isAdminOT) {
                            activeValue = document.getElementById('adminOtCycleSelector').value;
                        }

                        if (activeValue && activeValue.length === 7) {
                            globalOTSelectedYear = activeValue.substring(0, 4);
                            globalOTSelectedMonth = activeValue.substring(5, 7);
                        }

                        // Sync values across all overtime workspaces and therapist attendance sheet
                        const elements = ['otTrackerCycleSelector', 'masterOtCycleSelector', 'adminOtCycleSelector', 'therapistAttSheetMonth'];
                        elements.forEach(id => {
                            const el = document.getElementById(id);
                            if (el) {
                                el.value = `${globalOTSelectedYear}-${globalOTSelectedMonth}`;
                            }
                        });

                        synchronizeWorkspaceCoreStatus();
                    }

                    /**
                     * Renders the therapist timesheet grid
                     */
                    function convertDateKeyToISO(dateKey) {
                        const parts = dateKey.split('/');
                        if (parts.length !== 3) return "";
                        const d = parts[0].padStart(2, '0');
                        const m = parts[1].padStart(2, '0');
                        const y = parts[2];
                        return `${y}-${m}-${d}`;
                    }
                    function isDateAfterLastWorkingDay(dateKey, lastWorkingDayStr) {
                        if (!lastWorkingDayStr || lastWorkingDayStr === "N/A" || lastWorkingDayStr === "") return false;

                        const parts = dateKey.split('/');
                        if (parts.length !== 3) return false;
                        // Parse day (parts[0]) and month (parts[1]) correctly
                        const cellDate = new Date(parts[2], parts[1] - 1, parts[0]);

                        const lParts = lastWorkingDayStr.split('-');
                        if (lParts.length !== 3) return false;
                        const lastDate = new Date(lParts[0], lParts[1] - 1, lParts[2]);

                        cellDate.setHours(0, 0, 0, 0);
                        lastDate.setHours(0, 0, 0, 0);

                        return cellDate > lastDate;
                    }
                    function toggleQuotaExpiryInputVisibility(checkboxId, wrapperId) {
                        const isChecked = document.getElementById(checkboxId).checked;
                        document.getElementById(wrapperId).style.display = isChecked ? 'block' : 'none';
                    }

                    function getOtAttColor(val) {
                        const el = function (id) { var e = document.getElementById(id); return e && e.value ? e.value : null; };
                        const map = {
                            'Present': el('colPresent') || globalStatusColors.Present || '#b7e9ff',
                            'OFF': el('colOff') || globalStatusColors.OFF || '#cbd5e1',
                            'Sick Leave': el('colSick') || globalStatusColors.Sick || '#f84e4e',
                            'Annual Leave': el('colAnnual') || globalStatusColors.Annual || '#f59e0b',
                            'FRL': el('colFamily') || globalStatusColors.FRL || '#10b981',
                            'Absent': '#ef4444',
                            'Umrah Leave': el('colUmrah') || globalStatusColors.Umrah || '#8b5cf6',
                            'Hajj Leave': el('colHajj') || globalStatusColors.Hajj || '#06b6d4',
                            'No Paid Leave': el('colNoPaid') || globalStatusColors.NoPaid || '#f97316',
                            'Maternity Leave': el('colMaternity') || globalStatusColors.Maternity || '#ec4899',
                            'Paternity Leave': el('colPaternity') || globalStatusColors.Paternity || '#3b82f6',
                            'Special Leave': el('colSpecial') || globalStatusColors.Special || '#14b8a6'
                        };
                        return (map[val] || 'transparent') + '88';
                    }
                    function renderActiveStaffOTCycleInteractiveTable() {
                        const container = document.getElementById('activeStaffOTCycleInputsTableBody');
                        if (!container) return;
                        container.innerHTML = "";

                        const cycleDatesList = generateOTTimesheet31DaysList();
                        const route = currentActiveSessionUser.email;

                        if (!localUserOTSheetDraft[route]) {
                            localUserOTSheetDraft[route] = {};
                        }
                        if (!localUserOTSheetDraft[route][globalOTSelectedYear]) {
                            localUserOTSheetDraft[route][globalOTSelectedYear] = {};
                        }
                        if (!localUserOTSheetDraft[route][globalOTSelectedYear][globalOTSelectedMonth]) {
                            localUserOTSheetDraft[route][globalOTSelectedYear][globalOTSelectedMonth] = {};
                            cycleDatesList.forEach(d => {
                                const isFri = (d.dayName === "Fri");
                                localUserOTSheetDraft[route][globalOTSelectedYear][globalOTSelectedMonth][d.fullDate] = {
                                    patients150: 0,
                                    patients200: 0,
                                    hours: 0,
                                    attendance: isFri ? "OFF" : "Present",
                                    notes: ""
                                };
                            });
                        }

                        const currentDraft = localUserOTSheetDraft[route][globalOTSelectedYear][globalOTSelectedMonth];

                        cycleDatesList.forEach(item => {
                            const dateKey = item.fullDate;
                            const isFri = (item.dayName === "Fri");
                            const draft = currentDraft[dateKey] || { patients150: 0, patients200: 0, hours: 0, attendance: isFri ? "OFF" : "Present", notes: "" };

                            // Checks for approved leaves to auto-populate the sheet
                            const isoDate = convertDateKeyToISO(dateKey);
                            const matchedApprovedLeave = globalLeaveRepository.find(l =>
                                l.email === route &&
                                l.status === "Approved" &&
                                l.date === isoDate
                            );

                            if (matchedApprovedLeave) {
                                draft.attendance = matchedApprovedLeave.type;
                            }

                            // Check if date is past Last Working Day
                            const isPastLastDay = isDateAfterLastWorkingDay(dateKey, currentActiveSessionUser.lastDayOfWorking);
                            const disabledAttr = isPastLastDay ? "disabled" : "";
                            const rowStyle = isPastLastDay ? "background:rgba(239, 68, 68, 0.05); opacity:0.75;" : "";

                            const tr = document.createElement('tr');
                            if (rowStyle) tr.style = rowStyle;

                            tr.innerHTML = `
            <td style="font-weight:700;">${dateKey} ${isPastLastDay ? '<br><span style="color:var(--danger); font-size:8px;">[Lifecycle End]</span>' : ''}</td>
            <td>${lookupTranslationValue(item.dayName)}</td>
            <td>
                <input type="number" class="ot-grid-input" value="${draft.patients150 !== "" && draft.patients150 !== undefined ? draft.patients150 : 0}" min="0" oninput="updateLocalOTTimesheetCell('${dateKey}', 'patients150', this.value)" ${disabledAttr}>
            </td>
            <td>
                <input type="number" class="ot-grid-input" value="${draft.patients200 !== "" && draft.patients200 !== undefined ? draft.patients200 : 0}" min="0" oninput="updateLocalOTTimesheetCell('${dateKey}', 'patients200', this.value)" ${disabledAttr}>
            </td>
            <td>
                <input type="number" class="ot-grid-input" value="${draft.hours || 0}" min="0" step="0.5" oninput="updateLocalOTTimesheetCell('${dateKey}', 'hours', this.value)" ${disabledAttr}>
            </td>
            <td style="background:${getOtAttColor(draft.attendance)};">
                <select class="ot-select-attendance" onchange="updateLocalOTTimesheetCell('${dateKey}', 'attendance', this.value); this.parentElement.style.background=getOtAttColor(this.value)" ${disabledAttr}>
                    ${(() => {
                                    const stdOptions = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL"];
                                    let html = stdOptions.map(v => `<option value="${v}" ${draft.attendance === v ? 'selected' : ''}>${v}</option>`).join('');
                                    if (draft.attendance && !stdOptions.includes(draft.attendance)) {
                                        html += `<option value="${draft.attendance}" selected>${draft.attendance}</option>`;
                                    }
                                    return html;
                                })()}
                </select>
            </td>
            <td>
                <input type="text" class="ot-notes-input" value="${draft.notes || ''}" placeholder="Optional entries..." oninput="updateLocalOTTimesheetCell('${dateKey}', 'notes', this.value)" ${disabledAttr}>
            </td>
        `;
                            container.appendChild(tr);
                        });

                        calculateAndRenderLocalOTTimesheetFootTotals();
                    }

                    function updateLocalOTTimesheetCell(dateKey, property, value) {
                        const route = currentActiveSessionUser.email;
                        const currentDraft = localUserOTSheetDraft[route][globalOTSelectedYear][globalOTSelectedMonth];

                        if (property === 'patients150' || property === 'patients200' || property === 'hours') {
                            currentDraft[dateKey][property] = parseFloat(value) || 0;
                        } else {
                            currentDraft[dateKey][property] = value;
                        }
                        calculateAndRenderLocalOTTimesheetFootTotals();
                    }

                    function calculateAndRenderLocalOTTimesheetFootTotals() {
                        const route = currentActiveSessionUser.email;
                        const currentDraft = localUserOTSheetDraft[route]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || {};

                        let sum150 = 0;
                        let sum200 = 0;
                        let sumHours = 0;
                        let sumAttendance = 0;
                        let sumNotes = 0;

                        for (let k in currentDraft) {
                            sum150 += parseFloat(currentDraft[k].patients150) || 0;
                            sum200 += parseFloat(currentDraft[k].patients200) || 0;
                            sumHours += parseFloat(currentDraft[k].hours) || 0;
                            if (currentDraft[k].attendance === 'Present') sumAttendance++;
                            if (currentDraft[k].notes && currentDraft[k].notes.trim() !== '') sumNotes++;
                        }

                        const tfootSum150 = document.getElementById('tfootSum150');
                        const tfootSum200 = document.getElementById('tfootSum200');
                        const tfootSumHours = document.getElementById('tfootSumHours');
                        const tfootSumAttendance = document.getElementById('tfootSumAttendance');
                        const tfootSumNotes = document.getElementById('tfootSumNotes');

                        if (tfootSum150) tfootSum150.innerText = sum150;
                        if (tfootSum200) tfootSum200.innerText = sum200;
                        if (tfootSumHours) tfootSumHours.innerText = `${sumHours} hrs`;
                        if (tfootSumAttendance) tfootSumAttendance.innerText = `${sumAttendance} Days`;
                        if (tfootSumNotes) tfootSumNotes.innerText = `${sumNotes} Records`;
                    }

                    /**
                     * Commits a therapist's OT draft session to the Master Database
                     */
                    function submitActiveOTSheetToMaster() {
                        const route = currentActiveSessionUser.email;
                        const currentDraft = localUserOTSheetDraft[route]?.[globalOTSelectedYear]?.[globalOTSelectedMonth];

                        if (!currentDraft) {
                            customAlert("Please populate log entries first.");
                            return;
                        }

                        if (!globalTherapistOTSubmissions[route]) {
                            globalTherapistOTSubmissions[route] = {};
                        }
                        if (!globalTherapistOTSubmissions[route][globalOTSelectedYear]) {
                            globalTherapistOTSubmissions[route][globalOTSelectedYear] = {};
                        }

                        globalTherapistOTSubmissions[route][globalOTSelectedYear][globalOTSelectedMonth] = JSON.parse(JSON.stringify(currentDraft));
                        customAlert("Timesheet validated and compiled. Dispatched directly to the Master OT matrix.");
                        synchronizeWorkspaceCoreStatus();
                    }

                    /**
                     * Renders column visibility checkboxes for therapists on the Master Sheet
                     */
                    function getSupervisorOtAllowedRoles() {
                        try {
                            const saved = JSON.parse(localStorage.getItem('supervisorOtAllowedRoles'));
                            if (Array.isArray(saved) && saved.length > 0) return saved;
                        } catch (e) { }
                        return allowedAdminOTStaffRoles.slice();
                    }
                    function saveSupervisorOtRolesConfig(roles) {
                        localStorage.setItem('supervisorOtAllowedRoles', JSON.stringify(roles));
                        renderSupervisorMultiTherapistOTGrid();
                    }
                    function openSupervisorOtRolesConfig() {
                        const mount = document.getElementById('systemGlobalModalMount');
                        if (!mount) return;
                        const currentRoles = getSupervisorOtAllowedRoles();
                        const allPositions = [...new Set(globalRosterRepository.map(t => t.position))].sort();
                        const unchecked = allPositions.filter(p => !currentRoles.includes(p));
                        const ordered = [...currentRoles, ...unchecked];

                        let html = '<div class="system-inline-modal-overlay" onclick="if(event.target===this)closeSystemModalBox()" style="cursor:pointer;">';
                        html += '<div class="system-inline-modal-box" style="width:420px;max-height:80vh;overflow-y:auto;cursor:default;" onclick="event.stopPropagation()">';
                        html += '<h3 style="margin-bottom:4px;font-size:13px;">Configure Supervisor OT Roles</h3>';
                        html += '<p style="font-size:10px;color:var(--text-muted);margin-bottom:12px;">Check roles to include in the Supervisor Overtime & Attendance Entry Panel. Use ↑↓ arrows to set display order.</p>';
                        html += '<div id="supervisorOtRoleSortableList" style="display:flex;flex-direction:column;gap:4px;">';
                        ordered.forEach((pos, idx) => {
                            const checked = currentRoles.includes(pos) ? 'checked' : '';
                            html += `<div class="supervisor-ot-role-row" data-role="${pos}" style="display:flex;align-items:center;gap:6px;padding:4px 6px;border-radius:6px;background:var(--bg-surface);${checked ? '' : 'opacity:0.5;'}">`;
                            html += `<button class="action-btn" style="padding:1px 6px;font-size:10px;min-width:auto;line-height:1.4;" onclick="moveSupervisorOtRoleRow(this,-1)" ${idx === 0 ? 'disabled' : ''} title="Move up">↑</button>`;
                            html += `<button class="action-btn" style="padding:1px 6px;font-size:10px;min-width:auto;line-height:1.4;" onclick="moveSupervisorOtRoleRow(this,1)" ${idx === ordered.length - 1 ? 'disabled' : ''} title="Move down">↓</button>`;
                            html += `<input type="checkbox" value="${pos}" ${checked} onchange="this.closest('.supervisor-ot-role-row').style.opacity=this.checked?'':'0.5'">`;
                            html += `<span style="font-size:11px;font-weight:600;">${pos}</span>`;
                            const count = globalRosterRepository.filter(t => t.position === pos).length;
                            html += `<span style="font-size:9px;color:var(--text-muted);margin-left:auto;">${count} staff</span>`;
                            html += '</div>';
                        });
                        html += '</div>';
                        html += '<div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;">';
                        html += '<button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Cancel</button>';
                        html += '<button class="action-btn" style="background:var(--primary);" onclick="saveSupervisorOtRolesFromModal()">Save</button>';
                        html += '</div></div></div>';
                        mount.innerHTML = html;
                    }
                    function moveSupervisorOtRoleRow(btn, dir) {
                        const row = btn.closest('.supervisor-ot-role-row');
                        if (!row) return;
                        const list = document.getElementById('supervisorOtRoleSortableList');
                        const rows = [...list.querySelectorAll('.supervisor-ot-role-row')];
                        const idx = rows.indexOf(row);
                        const target = idx + dir;
                        if (target < 0 || target >= rows.length) return;
                        if (dir < 0) list.insertBefore(row, rows[target]);
                        else list.insertBefore(row, rows[target].nextSibling);
                        const newRows = [...list.querySelectorAll('.supervisor-ot-role-row')];
                        newRows.forEach(r => {
                            const btns = r.querySelectorAll('button');
                            if (btns[0]) btns[0].disabled = false;
                            if (btns[1]) btns[1].disabled = false;
                        });
                        newRows[0].querySelectorAll('button')[0].disabled = true;
                        newRows[newRows.length - 1].querySelectorAll('button')[1].disabled = true;
                    }
                    function saveSupervisorOtRolesFromModal() {
                        const rows = document.querySelectorAll('#supervisorOtRoleSortableList .supervisor-ot-role-row');
                        const selected = [];
                        rows.forEach(row => {
                            const cb = row.querySelector('input[type="checkbox"]');
                            if (cb.checked) selected.push(cb.value);
                        });
                        if (selected.length === 0) {
                            customAlert("At least one role must be selected.");
                            return;
                        }
                        closeSystemModalBox();
                        saveSupervisorOtRolesConfig(selected);
                    }
                    function getMasterOtAllowedRoles() {
                        try {
                            const saved = JSON.parse(localStorage.getItem('masterOtAllowedRoles'));
                            if (Array.isArray(saved) && saved.length > 0) return saved;
                        } catch (e) { }
                        return ['Physiotherapist', 'Head of Physio', 'Admin', 'General Manager'];
                    }

                    function saveMasterOtRolesConfig(roles) {
                        localStorage.setItem('masterOtAllowedRoles', JSON.stringify(roles));
                        // remove therapists whose role is no longer allowed
                        const allowed = roles;
                        masterOtDisplayTherapists = masterOtDisplayTherapists.filter(email => {
                            const u = globalRosterRepository.find(t => t.email === email);
                            return u && allowed.includes(u.position);
                        });
                        if (masterOtDisplayTherapists.length === 0) {
                            // pick first therapist from the first allowed role
                            const first = globalRosterRepository.find(t => allowed.includes(t.position));
                            if (first) masterOtDisplayTherapists.push(first.email);
                        }
                        renderMasterOTScheduleMatrix();
                    }

