                    function renderMasterOtTherapistFilters() {
                        const container = document.getElementById('masterOtTherapistFilterContainer');
                        if (!container) return;
                        container.innerHTML = "";

                        const roles = getMasterOtAllowedRoles();
                        const roleLabels = {};
                        roles.forEach(r => roleLabels[r] = r);
                        const roleEmails = {};
                        roles.forEach(r => roleEmails[r] = []);

                        const eligible = [];
                        globalRosterRepository.forEach(t => {
                            if (roles.includes(t.position)) {
                                eligible.push(t);
                                roleEmails[t.position].push(t.email);
                            }
                        });

                        const allEmails = eligible.map(t => t.email);
                        const allSelected = allEmails.every(e => masterOtDisplayTherapists.includes(e));
                        const noneSelected = allEmails.every(e => !masterOtDisplayTherapists.includes(e));

                        // "All" checkbox
                        const allLabel = document.createElement('label');
                        Object.assign(allLabel.style, { display: "inline-flex", alignItems: "center", gap: "4px", fontSize: "10px", fontWeight: "700", cursor: "pointer", color: "var(--primary)" });
                        allLabel.innerHTML = `<input type="checkbox" ${allSelected ? 'checked' : ''} onchange="toggleMasterOtAllTherapists(this.checked)"> All`;
                        container.appendChild(allLabel);

                        container.appendChild(document.createTextNode(' | '));

                        // Role-level checkboxes
                        roles.forEach(role => {
                            const roleEmailsList = roleEmails[role];
                            const roleSelected = roleEmailsList.length > 0 && roleEmailsList.every(e => masterOtDisplayTherapists.includes(e));
                            const rolePartially = roleEmailsList.some(e => masterOtDisplayTherapists.includes(e)) && !roleSelected;
                            const label = document.createElement('label');
                            Object.assign(label.style, { display: "inline-flex", alignItems: "center", gap: "4px", fontSize: "10px", fontWeight: "600", cursor: "pointer" });
                            const checked = roleSelected ? 'checked' : '';
                            label.style.color = roleSelected ? 'var(--primary)' : rolePartially ? 'var(--text-muted)' : '';
                            label.innerHTML = `<input type="checkbox" ${checked} onchange="toggleMasterOtRoleSelection('${role}',this.checked)"> ${roleLabels[role]}`;
                            container.appendChild(label);
                            container.appendChild(document.createTextNode('  '));
                        });

                        container.appendChild(document.createElement('hr'));
                        const lastHr = container.lastElementChild;
                        Object.assign(lastHr.style, { margin: "4px 0", border: "none", borderTop: "1px solid var(--border)" });

                        // Individual therapist checkboxes
                        eligible.forEach(t => {
                            const isChecked = masterOtDisplayTherapists.includes(t.email);
                            const label = document.createElement('label');
                            Object.assign(label.style, { display: "inline-flex", alignItems: "center", gap: "4px", fontSize: "10px", fontWeight: "600", cursor: "pointer" });
                            label.innerHTML = `<input type="checkbox" ${isChecked ? 'checked' : ''} value="${t.email}" onchange="toggleMasterOtTherapistSelection('${t.email}')"> ${t.name}`;
                            container.appendChild(label);
                        });
                    }

                    function toggleMasterOtRoleSelection(role, checked) {
                        const roleEmails = [];
                        globalRosterRepository.forEach(t => {
                            if (t.position === role) roleEmails.push(t.email);
                        });
                        if (checked) {
                            roleEmails.forEach(e => { if (!masterOtDisplayTherapists.includes(e)) masterOtDisplayTherapists.push(e); });
                        } else {
                            const remaining = masterOtDisplayTherapists.filter(e => !roleEmails.includes(e));
                            if (remaining.length === 0) {
                                customAlert("At least one therapist must remain selected.");
                                renderMasterOTScheduleMatrix();
                                return;
                            }
                            masterOtDisplayTherapists.length = 0;
                            remaining.forEach(e => masterOtDisplayTherapists.push(e));
                        }
                        renderMasterOTScheduleMatrix();
                    }

                    function toggleMasterOtAllTherapists(checked) {
                        const allowedRoles = getMasterOtAllowedRoles();
                        const allEmails = [];
                        globalRosterRepository.forEach(t => {
                            if (allowedRoles.includes(t.position)) {
                                allEmails.push(t.email);
                            }
                        });
                        if (checked) {
                            masterOtDisplayTherapists.length = 0;
                            allEmails.forEach(e => masterOtDisplayTherapists.push(e));
                        } else {
                            if (allEmails.length <= 1) {
                                customAlert("At least one therapist must remain selected.");
                                renderMasterOTScheduleMatrix();
                                return;
                            }
                            // keep only the first one
                            masterOtDisplayTherapists.length = 0;
                            masterOtDisplayTherapists.push(allEmails[0]);
                        }
                        renderMasterOTScheduleMatrix();
                    }

                    function toggleMasterOtTherapistSelection(email) {
                        const idx = masterOtDisplayTherapists.indexOf(email);
                        if (idx !== -1) {
                            if (masterOtDisplayTherapists.length <= 1) {
                                customAlert("At least one therapist must remain selected.");
                                renderMasterOTScheduleMatrix();
                                return;
                            }
                            masterOtDisplayTherapists.splice(idx, 1);
                        } else {
                            masterOtDisplayTherapists.push(email);
                        }
                        renderMasterOTScheduleMatrix();
                    }

                    /**
                     * Renders the Master OT Grid Matrix compiling all submitted data
                     */
                    function renderMasterOTScheduleMatrix() {
                        renderMasterOtTherapistFilters();

                        const thead = document.getElementById('masterOTScheduleMatrixTableHead');
                        const tbody = document.getElementById('masterOTScheduleMatrixTableBody');
                        const tfoot = document.getElementById('masterOTMatrixAggregateFoot');

                        if (!thead || !tbody || !tfoot) return;

                        thead.innerHTML = "";
                        tbody.innerHTML = "";
                        tfoot.innerHTML = "";

                        const activeMetric = document.getElementById('masterOtMetricSelector').value;
                        const activeCount = masterOtDisplayTherapists.length;

                        let hRow1 = `
        <tr>
            <th rowspan="2" style="text-align:left; min-width:100px;background:var(--primary);color:#fff;">Date</th>
            <th rowspan="2" style="text-align:center;background:var(--primary);color:#fff;">Day</th>
            <th colspan="${activeCount}" style="text-align:center; border-bottom:1px solid var(--border);background:var(--primary);color:#fff;">Therapist Grid Tracking Metrics</th>
        </tr>
    `;
                        let hRow2 = `<tr>`;
                        masterOtDisplayTherapists.forEach(email => {
                            const info = globalRosterRepository.find(u => u.email === email);
                            hRow2 += `<th style="text-align:center;background:var(--primary);color:#fff;">${info ? info.name : email}</th>`;
                        });
                        hRow2 += `</tr>`;
                        thead.innerHTML = hRow1 + hRow2;

                        const scheduleDates = generateOTTimesheet31DaysList();

                        const activeStaffTracking = masterOtDisplayTherapists.map(email => {
                            const info = globalRosterRepository.find(u => u.email === email);
                            return {
                                email: email,
                                name: info ? info.name : email,
                                totals: { ot: 0, patients150: 0, patients200: 0, present: 0, sick: 0, off: 0, frl: 0, annual: 0, absent: 0, otherLeaves: {} }
                            };
                        });

                        // Pre-index approved leaves for O(1) lookup by email|date
                        const leaveLookup = {};
                        (globalLeaveRepository || []).forEach(l => {
                            if (l.status === "Approved") {
                                leaveLookup[l.email + '|' + l.date] = l;
                            }
                        });

                        scheduleDates.forEach(d => {
                            const tr = document.createElement('tr');
                            let colsHtml = `
            <td style="text-align:left; font-weight:700;">${d.fullDate}</td>
            <td>${lookupTranslationValue(d.dayName)}</td>
        `;

                            activeStaffTracking.forEach(staff => {
                                const submissions = globalTherapistOTSubmissions[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || {};
                                const cell = submissions[d.fullDate] || { patients150: "", patients200: "", hours: "", attendance: "", notes: "" };

                                let displayAttendance = cell.attendance;

                                // First: Check attendance from Operational Attendance & Overtime Timesheet
                                if (displayAttendance === "") {
                                    displayAttendance = (d.dayName === "Fri") ? "OFF" : "-";
                                }

                                // Fallback to leave system for all approved leave types (O(1) lookup)
                                if (displayAttendance === "-" || displayAttendance === "OFF" || displayAttendance === "Present" || displayAttendance === "") {
                                    const isoDate = convertDateKeyToISO(d.fullDate);
                                    const matchedApprovedLeave = leaveLookup[staff.email + '|' + isoDate];

                                    if (matchedApprovedLeave) {
                                        const lt = matchedApprovedLeave.type;
                                        if (lt === "Family Leave" || lt === "Family Responsibility Leave") {
                                            displayAttendance = "FRL";
                                        } else if (lt === "Sick Leave") {
                                            displayAttendance = "Sick Leave";
                                        } else if (lt === "Annual Leave") {
                                            displayAttendance = "Annual Leave";
                                        } else if (lt === "No Paid Leave" || lt === "No Pay Leave") {
                                            displayAttendance = "No Paid Leave";
                                        } else {
                                            displayAttendance = lt;
                                        }
                                    }
                                }

                                if (displayAttendance === "Present") {
                                    staff.totals.present++;
                                    staff.totals.ot += parseFloat(cell.hours) || 0;
                                    staff.totals.patients150 += parseFloat(cell.patients150) || 0;
                                    staff.totals.patients200 += parseFloat(cell.patients200) || 0;
                                } else if (displayAttendance === "Sick Leave") {
                                    staff.totals.sick++;
                                } else if (displayAttendance === "Annual Leave") {
                                    staff.totals.annual++;
                                } else if (displayAttendance === "FRL") {
                                    staff.totals.frl++;
                                } else if (displayAttendance === "Absent") {
                                    staff.totals.absent++;
                                } else if (displayAttendance === "OFF") {
                                    staff.totals.off++;
                                } else if (displayAttendance && displayAttendance !== "-" && !["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL"].includes(displayAttendance)) {
                                    staff.totals.otherLeaves[displayAttendance] = (staff.totals.otherLeaves[displayAttendance] || 0) + 1;
                                }

                                let displayVal = "";
                                let colorHex = "transparent";

                                // Support displaying therapist daily notes in cells
                                if (activeMetric === "hours") {
                                    displayVal = displayAttendance === "Present" ? `${cell.hours} hrs` : displayAttendance;
                                } else if (activeMetric === "patients150") {
                                    displayVal = displayAttendance === "Present" ? cell.patients150 : displayAttendance;
                                } else if (activeMetric === "patients200") {
                                    displayVal = displayAttendance === "Present" ? cell.patients200 : displayAttendance;
                                } else if (activeMetric === "notes") {
                                    displayVal = cell.notes || "-"; // Displays notes written by therapist
                                } else {
                                    displayVal = displayAttendance;
                                }

                                // Sync visual colors
                                const attColorMap = {
                                    'OFF': globalStatusColors.OFF,
                                    'Sick Leave': globalStatusColors.Sick,
                                    'Annual Leave': globalStatusColors.Annual,
                                    'FRL': globalStatusColors.FRL,
                                    'Present': globalStatusColors.Present,
                                    'Absent': '#ef4444',
                                    'Umrah Leave': globalStatusColors.Umrah,
                                    'Hajj Leave': globalStatusColors.Hajj,
                                    'No Paid Leave': globalStatusColors.NoPaid,
                                    'Maternity Leave': globalStatusColors.Maternity,
                                    'Paternity Leave': globalStatusColors.Paternity,
                                    'Special Leave': globalStatusColors.Special
                                };
                                colorHex = (attColorMap[displayAttendance] || 'transparent') + '88';

                                // Build a hover tooltip containing the therapist notes
                                const cellTooltip = cell.notes ? `Therapist Note: ${cell.notes}` : "No therapist notes written.";

                                colsHtml += `<td title="${cellTooltip}" style="background:${colorHex}; font-weight:700; color:var(--text-heading); cursor:pointer;">${displayVal}</td>`;
                            });

                            tr.innerHTML = colsHtml;
                            tbody.appendChild(tr);
                        });

                        const masterBgCol = (type) => getOtAttColor(type) || '#cbd5e188';
                        let totalOtRow = `<tr><td colspan="2" style="text-align:right;">OVERTIME TOTAL HOURS</td>`;
                        let total150Row = `<tr><td colspan="2" style="text-align:right;">SUM 150 PATIENTS</td>`;
                        let total200Row = `<tr><td colspan="2" style="text-align:right;">SUM 200 PATIENTS</td>`;
                        let attendanceRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${masterBgCol('Present')}; color:#000;">ATTENDANCE DAYS</td>`;
                        let sickRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${masterBgCol('Sick Leave')}; color:#000;">SICK LEAVE DAYS</td>`;
                        let offRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${masterBgCol('OFF')}; color:#000;">OFF DAYS</td>`;
                        let frlRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${masterBgCol('FRL')}; color:#000;">FRL DAYS</td>`;
                        let annualRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${masterBgCol('Annual Leave')}; color:#000;">ANNUAL LEAVE DAYS</td>`;

                        activeStaffTracking.forEach(staff => {
                            const savedManualOverallVal = globalSupervisorManualOTHours[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth];
                            const finalOTHours = (savedManualOverallVal !== undefined) ? savedManualOverallVal : staff.totals.ot;

                            totalOtRow += `<td>${finalOTHours} hrs</td>`;
                            total150Row += `<td>${staff.totals.patients150}</td>`;
                            total200Row += `<td>${staff.totals.patients200}</td>`;
                            attendanceRow += `<td style="color:var(--text-body);">${staff.totals.present} Days</td>`;
                            sickRow += `<td style="color:var(--text-body);">${staff.totals.sick} Days</td>`;
                            offRow += `<td style="color:var(--text-body);">${staff.totals.off} Days</td>`;
                            frlRow += `<td style="color:var(--text-body);">${staff.totals.frl} Days</td>`;
                            annualRow += `<td style="color:var(--text-body);">${staff.totals.annual} Days</td>`;
                        });

                        // Build dynamic leave rows for non-standard types (Umrah, Hajj, etc.) - only if count > 0
                        const allOtherTypes = new Set();
                        activeStaffTracking.forEach(s => { Object.keys(s.totals.otherLeaves).forEach(k => allOtherTypes.add(k)); });
                        let otherLeaveRows = "";
                        allOtherTypes.forEach(type => {
                            let hasNonZero = false;
                            const typeBg = masterBgCol(type);
                            let row = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${typeBg}; color:#000;">${type.toUpperCase()} DAYS</td>`;
                            activeStaffTracking.forEach(s => {
                                const count = s.totals.otherLeaves[type] || 0;
                                if (count > 0) hasNonZero = true;
                                row += `<td style="color:var(--text-body);">${count} Days</td>`;
                            });
                            row += "</tr>";
                            if (hasNonZero) otherLeaveRows += row;
                        });

                        tfoot.innerHTML = totalOtRow + "</tr>" + total150Row + "</tr>" + total200Row + "</tr>" + attendanceRow + "</tr>" + sickRow + "</tr>" + offRow + "</tr>" + frlRow + "</tr>" + annualRow + "</tr>" + otherLeaveRows;
                    }

                    // =========================================================================
                    // ADMIN COMPARATIVE GRID & AUTO-RECONCILIATION ENGINE
                    // =========================================================================

                    /**
                     * Initializes Admin Comparative structure bounds
                     */
                    function initializeAdminComparativeDatabase() {
                        const cycleDates = generateOTTimesheet31DaysList();
                        globalRosterRepository.forEach(t => {
                            if (!globalAdminComparativeDatabase[t.email]) {
                                globalAdminComparativeDatabase[t.email] = {};
                            }
                            if (!globalAdminComparativeDatabase[t.email][globalOTSelectedYear]) {
                                globalAdminComparativeDatabase[t.email][globalOTSelectedYear] = {};
                            }
                            if (!globalAdminComparativeDatabase[t.email][globalOTSelectedYear][globalOTSelectedMonth]) {
                                globalAdminComparativeDatabase[t.email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                                cycleDates.forEach(d => {
                                    globalAdminComparativeDatabase[t.email][globalOTSelectedYear][globalOTSelectedMonth][d.fullDate] = {
                                        patients150: 0,
                                        patients200: 0,
                                        hours: 0,
                                        attendance: "Present",
                                        notes: "Baseline"
                                    };
                                });
                            }
                        });
                    }

                    /**
                     * Renders batch daily entry table for administrators
                     */
                    function renderAdminComparativeEntryGrid() {
                        initializeAdminComparativeDatabase();

                        const picker = document.getElementById('adminBatchEntryDatePicker');
                        if (!picker) return;

                        const targetDate = picker.value;
                        const tbody = document.getElementById('adminBatchTherapistsEntryTableBody');
                        if (!tbody) return;
                        tbody.innerHTML = "";

                        // Loop through therapists in exact matching sequence
                        globalRosterRepository.forEach(staff => {
                            if (staff.position !== "Physiotherapist" && staff.position !== "Head of Physio" && staff.position !== "Admin" && staff.position !== "General Manager") return;

                            const record = globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth][targetDate] ||
                                { patients150: 0, patients200: 0, hours: 0, attendance: "OFF", notes: "No Record" };

                            const tr = document.createElement('tr');
                            tr.innerHTML = `
            <td><strong>${staff.name}</strong></td>
            <td><span class="badge badge-primary">${lookupTranslationValue(staff.position)}</span></td>
            <td>
                <input type="number" id="admInput_${staff.email}_150" class="ot-grid-input" value="${record.patients150 || 0}">
            </td>
            <td>
                <input type="number" id="admInput_${staff.email}_200" class="ot-grid-input" value="${record.patients200 || 0}">
            </td>
            <td>
                <input type="number" id="admInput_${staff.email}_hours" class="ot-grid-input" value="${record.hours || 0}" step="0.5">
            </td>
            <td>
                <select id="admInput_${staff.email}_attendance" class="ot-select-attendance">
                    ${(() => {
                                    const stdOptions = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL"];
                                    let html = stdOptions.map(v => `<option value="${v}" ${record.attendance === v ? 'selected' : ''}>${v}</option>`).join('');
                                    if (record.attendance && !stdOptions.includes(record.attendance)) {
                                        html += `<option value="${record.attendance}" selected>${record.attendance}</option>`;
                                    }
                                    return html;
                                })()}
                </select>
            </td>
            <td>
                <input type="text" id="admInput_${staff.email}_notes" class="ot-notes-input" value="${record.notes || ''}">
            </td>
        `;
                            tbody.appendChild(tr);
                        });
                    }

                    function populateAdminBatchDates() {
                        const picker = document.getElementById('adminBatchEntryDatePicker');
                        if (!picker) return;

                        const activeDateValue = picker.value;
                        picker.innerHTML = "";

                        const dates = generateOTTimesheet31DaysList();
                        dates.forEach(d => {
                            picker.innerHTML += `<option value="${d.fullDate}">${d.fullDate} (${lookupTranslationValue(d.dayName)})</option>`;
                        });

                        if (activeDateValue) picker.value = activeDateValue;
                    }

                    /**
                     * Saves daily overrides for all therapists simultaneously
                     */
                    function commitAdminBatchDailyOverwrites() {
                        const picker = document.getElementById('adminBatchEntryDatePicker');
                        if (!picker) return;

                        const targetDate = picker.value;

                        globalRosterRepository.forEach(staff => {
                            if (staff.position !== "Physiotherapist" && staff.position !== "Head of Physio" && staff.position !== "Admin" && staff.position !== "General Manager") return;

                            const input150 = document.getElementById(`admInput_${staff.email}_150`);
                            const input200 = document.getElementById(`admInput_${staff.email}_200`);
                            const inputHours = document.getElementById(`admInput_${staff.email}_hours`);
                            const inputAttendance = document.getElementById(`admInput_${staff.email}_attendance`);
                            const inputNotes = document.getElementById(`admInput_${staff.email}_notes`);

                            if (input150 && input200 && inputHours && inputAttendance) {
                                globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth][targetDate] = {
                                    patients150: parseFloat(input150.value) || 0,
                                    patients200: parseFloat(input200.value) || 0,
                                    hours: parseFloat(inputHours.value) || 0,
                                    attendance: inputAttendance.value,
                                    notes: inputNotes ? inputNotes.value : "Baseline Override"
                                };
                            }
                        });

                        customAlert("Comparative administrative baseline records logged successfully.");
                        renderAdminComparativeEntryGrid();
                        executeAutoReconciliationCompareCheck();
                    }

                    /**
                     * Compares therapist submissions against administrative entries
                     */
                    function executeAutoReconciliationCompareCheck() {
                        const tbody = document.getElementById('reconciliationDiscrepanciesTableBody');
                        const alertBox = document.getElementById('discrepancyTrackerAlertBox');
                        if (!tbody) return;

                        tbody.innerHTML = "";
                        initializeAdminComparativeDatabase();

                        const datesList = generateOTTimesheet31DaysList();
                        let discrepancyCount = 0;

                        datesList.forEach(d => {
                            const dateKey = d.fullDate;

                            globalRosterRepository.forEach(staff => {
                                if (staff.position !== "Physiotherapist" && staff.position !== "Head of Physio" && staff.position !== "Admin" && staff.position !== "General Manager") return;

                                const therapistData = globalTherapistOTSubmissions[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth]?.[dateKey] ||
                                    { patients150: 0, patients200: 0, hours: 0, attendance: "OFF", notes: "" };

                                const adminData = globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth][dateKey] ||
                                    { patients150: 0, patients200: 0, hours: 0, attendance: "OFF", notes: "" };

                                // Field Comparison Check
                                const fieldsToCompare = ['hours', 'patients150', 'patients200', 'attendance'];
                                let mismatchFound = false;
                                let mismatchText = [];

                                fieldsToCompare.forEach(f => {
                                    if (String(therapistData[f]) !== String(adminData[f])) {
                                        mismatchFound = true;
                                        mismatchText.push(f);
                                    }
                                });

                                if (mismatchFound) {
                                    discrepancyCount++;
                                    const tr = document.createElement('tr');
                                    tr.style.background = "rgba(239, 68, 68, 0.03)";

                                    let metricsSummary = mismatchText.map(f => {
                                        const label = f === 'hours' ? 'OT Hours' : f === 'patients150' ? '150 Patients' : f === 'patients200' ? '200 Patients' : 'Attendance';
                                        return `<strong>${label}</strong>`;
                                    }).join(", ");

                                    let therapistVals = mismatchText.map(f => therapistData[f]).join(" / ");
                                    let adminVals = mismatchText.map(f => adminData[f]).join(" / ");

                                    tr.innerHTML = `
                    <td><strong>${dateKey}</strong></td>
                    <td>${staff.name}</td>
                    <td>${metricsSummary}</td>
                    <td style="color:var(--danger); font-weight:700;">${therapistVals}</td>
                    <td style="color:var(--success); font-weight:700;">${adminVals}</td>
                    <td>
                        <div style="display:flex; gap:6px;">
                            <button class="action-btn" style="background:var(--success); padding:3px 6px;" onclick="resolveSingleDiscrepancy('${staff.email}', '${dateKey}', 'therapist')">Use Therapist Value</button>
                            <button class="action-btn" style="background:var(--primary); padding:3px 6px;" onclick="resolveSingleDiscrepancy('${staff.email}', '${dateKey}', 'admin')">Use Admin Value</button>
                        </div>
                    </td>
                `;
                                    tbody.appendChild(tr);
                                }
                            });
                        });

                        if (discrepancyCount === 0) {
                            tbody.innerHTML = `
            <tr>
                <td colspan="6" style="text-align:center; color:var(--success); font-weight:700; padding:12px;">
                    ✅ All records match perfectly. Integrity check completed with zero discrepancies!
                </td>
            </tr>
        `;
                            if (alertBox) alertBox.style.display = 'none';
                        } else {
                            if (alertBox) {
                                alertBox.style.display = 'block';
                                alertBox.className = "broadcast-alert-banner urgent";
                                alertBox.innerHTML = `
                <div style="display:flex; align-items:center; gap:8px;">
                    <strong>[DISCREPANCY ALERT]</strong>
                    <span>System tracked ${discrepancyCount} data integrity anomalies between therapist logs and admin baselines. Resolve them below to proceed.</span>
                </div>
            `;
                            }
                        }
                    }

                    /**
                     * Resolves a mismatch and updates both databases
                     */
                    function resolveSingleDiscrepancy(email, dateKey, resolutionMode) {
                        if (!globalTherapistOTSubmissions[email]) return;

                        const therapistTarget = globalTherapistOTSubmissions[email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth];
                        const adminTarget = globalAdminComparativeDatabase[email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth];

                        if (!therapistTarget || !adminTarget) return;

                        if (resolutionMode === 'therapist') {
                            adminTarget[dateKey] = JSON.parse(JSON.stringify(therapistTarget[dateKey]));
                        } else {
                            therapistTarget[dateKey] = JSON.parse(JSON.stringify(adminTarget[dateKey]));
                        }

                        customAlert(`Discrepancy resolved for ${email} on ${dateKey}. Changes synced.`);
                        executeAutoReconciliationCompareCheck();
                        renderMasterOTScheduleMatrix();
                    }

                    /**
                     * Exports Master Overtime spreadsheet as CSV
                     */
                    function exportMasterOTSheetCSV() {
                        const dates = generateOTTimesheet31DaysList();
                        let csvContent = "";

                        let head = "Date,Day";
                        masterOtDisplayTherapists.forEach(email => {
                            const staff = globalRosterRepository.find(u => u.email === email);
                            const name = staff ? staff.name : email;
                            head += `,${name} (Attendance),${name} (Hours),${name} (150 Column),${name} (200 Column)`;
                        });
                        csvContent += head + "\n";

                        dates.forEach(d => {
                            let row = `${d.fullDate},${d.dayName}`;
                            masterOtDisplayTherapists.forEach(email => {
                                const submissions = globalTherapistOTSubmissions[email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || {};
                                const cell = submissions[d.fullDate] || { patients150: 0, patients200: 0, hours: 0, attendance: "OFF" };
                                row += `,${cell.attendance},${cell.hours},${cell.patients150},${cell.patients200}`;
                            });
                            csvContent += row + "\n";
                        });

                        downloadCSVAsXlsx(`Master_OT_Sheet_${globalOTSelectedYear}_${globalOTSelectedMonth}.csv`, csvContent);
                    }
                    function renderSupervisorMultiTherapistOTGrid() {
                        const thead = document.getElementById('supervisorOTGridHeader');
                        const tbody = document.getElementById('supervisorOTGridBody');
                        const tfoot = document.getElementById('supervisorOTGridFooter');

                        if (!thead || !tbody || !tfoot) return;

                        thead.innerHTML = "";
                        tbody.innerHTML = "";
                        tfoot.innerHTML = "";

                        const supervisorRoles = getSupervisorOtAllowedRoles();
                        const activeTherapists = globalRosterRepository.filter(u => u.active !== false && supervisorRoles.includes(u.position));
                        const activeCount = activeTherapists.length;

                        // 1. Build Header row
                        let hRow1 = `
        <tr>
            <th rowspan="2" style="text-align:left; min-width:90px;background:var(--primary);color:#fff;">Date</th>
            <th rowspan="2" style="text-align:center; min-width:60px;background:var(--primary);color:#fff;">Day</th>
    `;
                        let hRow2 = `<tr>`;

                        activeTherapists.forEach(staff => {
                            hRow1 += `<th colspan="4" style="text-align:center; border-bottom:1px solid var(--border); background:var(--primary);color:#fff;">${staff.name}</th>`;
                            hRow2 += `
            <th style="font-size:9px;background:var(--primary);color:#fff;">Patients 150</th>
            <th style="font-size:9px;background:var(--primary);color:#fff;">Patients 200</th>
            <th style="font-size:9px;background:var(--primary);color:#fff;">Attendance Status</th>
            <th style="font-size:9px;background:var(--primary);color:#fff;">Notes</th>
        `;
                        });

                        hRow1 += `</tr>`;
                        hRow2 += `</tr>`;
                        thead.innerHTML = hRow1 + hRow2;

                        const datesList = generateOTTimesheet31DaysList();

                        // Prepare total calculators for all status metrics
                        const STANDARD_ATTENDANCE = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL", "Family Responsibility Leave", "Family Leave"];

                        const therapistTotals = activeTherapists.map(t => ({
                            email: t.email,
                            username: t.username,
                            sum150: 0,
                            sum200: 0,
                            present: 0,
                            sick: 0,
                            off: 0,
                            frl: 0,
                            annual: 0,
                            absent: 0,
                            otherLeaves: {}
                        }));

                        // Pre-index approved leaves for O(1) lookup by email|date
                        const leaveLookup = {};
                        (globalLeaveRepository || []).forEach(l => {
                            if (l.status === "Approved") {
                                leaveLookup[l.email + '|' + l.date] = l;
                            }
                        });

                        datesList.forEach(d => {
                            const tr = document.createElement('tr');
                            let rowHtml = `
            <td style="text-align:left; font-weight:700;">${d.fullDate}</td>
            <td style="font-weight:600;">${lookupTranslationValue(d.dayName)}</td>
        `;

                            activeTherapists.forEach((staff, idx) => {
                                if (!globalAdminComparativeDatabase[staff.email]) globalAdminComparativeDatabase[staff.email] = {};
                                if (!globalAdminComparativeDatabase[staff.email][globalOTSelectedYear]) globalAdminComparativeDatabase[staff.email][globalOTSelectedYear] = {};
                                if (!globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth]) {
                                    globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                                }

                                const adminSubmissions = globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth];
                                const isFri = (d.dayName === "Fri");
                                const cell = adminSubmissions[d.fullDate] || { patients150: 0, patients200: 0, hours: 0, attendance: isFri ? "OFF" : "Present", notes: "" };

                                // Default Patients value to 0 instead of empty
                                const p150Val = (cell.patients150 !== "" && cell.patients150 !== undefined) ? cell.patients150 : 0;
                                const p200Val = (cell.patients200 !== "" && cell.patients200 !== undefined) ? cell.patients200 : 0;

                                // Find Approved Leaves (O(1) lookup)
                                const isoDate = convertDateKeyToISO(d.fullDate);
                                const matchedApprovedLeave = leaveLookup[staff.email + '|' + isoDate];

                                // Find Regular Roster OFF schedules 
                                const rosterShift = (activeCompiledShiftSchedules[staff.email] && activeCompiledShiftSchedules[staff.email][isoDate]) || "";
                                const isRosterOff = (rosterShift === "OFF");

                                let selectedAttendance = cell.attendance || (isFri ? "OFF" : "Present");
                                if (matchedApprovedLeave) {
                                    selectedAttendance = matchedApprovedLeave.type; // Auto-sync leave status has highest priority
                                } else if (isRosterOff) {
                                    selectedAttendance = "OFF"; // Auto-sync OFF day status has next priority
                                } else if (isFri) {
                                    selectedAttendance = "OFF"; // Friday default has next priority
                                }

                                // Check if date is past therapist's Last Working Day
                                const isPastLastDay = isDateAfterLastWorkingDay(d.fullDate, staff.lastDayOfWorking);
                                const disabledAttr = isPastLastDay ? "disabled" : "";
                                const cellStyle = isPastLastDay ? "background:rgba(239, 68, 68, 0.05); opacity:0.75;" : "";

                                // Calculate totals dynamically based on the current active status
                                const tTotal = therapistTotals[idx];
                                if (selectedAttendance === "Present") {
                                    tTotal.present++;
                                    tTotal.sum150 += parseFloat(p150Val) || 0;
                                    tTotal.sum200 += parseFloat(p200Val) || 0;
                                } else if (selectedAttendance === "Sick Leave") {
                                    tTotal.sick++;
                                } else if (selectedAttendance === "Annual Leave") {
                                    tTotal.annual++;
                                } else if (selectedAttendance === "FRL" || selectedAttendance === "Family Responsibility Leave" || selectedAttendance === "Family Leave") {
                                    tTotal.frl++;
                                } else if (selectedAttendance === "Absent") {
                                    tTotal.absent++;
                                } else if (selectedAttendance === "OFF") {
                                    tTotal.off++;
                                } else if (selectedAttendance && !STANDARD_ATTENDANCE.includes(selectedAttendance)) {
                                    tTotal.otherLeaves[selectedAttendance] = (tTotal.otherLeaves[selectedAttendance] || 0) + 1;
                                }

                                const input150Id = `sup_150_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const input200Id = `sup_200_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const inputAttId = `sup_att_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const inputNotesId = `sup_notes_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;

                                rowHtml += `
                <td style="${cellStyle}">
                    <input type="number" id="${input150Id}" value="${p150Val}" style="width:45px; text-align:center; font-size:10px; border:1px solid var(--border); border-radius:4px;" ${disabledAttr} onfocus="this.select()">
                </td>
                <td style="${cellStyle}">
                    <input type="number" id="${input200Id}" value="${p200Val}" style="width:45px; text-align:center; font-size:10px; border:1px solid var(--border); border-radius:4px;" ${disabledAttr} onfocus="this.select()">
                </td>
                <td style="background:${getOtAttColor(selectedAttendance)}; ${cellStyle}">
                    <select id="${inputAttId}" class="ot-select-attendance" style="width:90px; font-size:9px;" ${disabledAttr} onchange="document.getElementById('${inputAttId}').parentElement.style.background=getOtAttColor(this.value);supervisorAutoSaveSingleCell('${staff.email}','${d.fullDate}','${input150Id}','${input200Id}','${inputAttId}','${inputNotesId}')">
                        ${(() => {
                                        const stdOptions = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL"];
                                        let html = stdOptions.map(v => `<option value="${v}" ${selectedAttendance === v ? 'selected' : ''}>${v}</option>`).join('');
                                        if (selectedAttendance && !stdOptions.includes(selectedAttendance)) {
                                            html += `<option value="${selectedAttendance}" selected>${selectedAttendance}</option>`;
                                        }
                                        return html;
                                    })()}
                    </select>
                </td>
                <td style="${cellStyle}">
                    <input type="text" id="${inputNotesId}" value="${cell.notes || ''}" placeholder="${isPastLastDay ? 'Ended' : 'Remarks...'}" style="width:80px; font-size:9px; border:1px solid var(--border); border-radius:4px; padding:2px;" ${disabledAttr} onfocus="this.select()">
                </td>
            `;
                            });

                            tr.innerHTML = rowHtml;
                            tbody.appendChild(tr);
                        });

                        // 2. Render all dynamic Totals and Status counts in the footer
                        const adminBgCol = (type) => getOtAttColor(type) || '#cbd5e188';
                        let total150Row = `<tr><td colspan="2" style="text-align:right; font-weight:800; color:var(--text-heading);">SUM 150 PATIENTS</td>`;
                        let total200Row = `<tr><td colspan="2" style="text-align:right; font-weight:800; color:var(--text-heading);">SUM 200 PATIENTS</td>`;
                        let totalOtRow = `<tr><td colspan="2" style="text-align:right; font-weight:800; color:var(--primary);">OVERTIME TOTAL HOURS</td>`;
                        let attendanceRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${adminBgCol('Present')}; color:#000;">ATTENDANCE DAYS</td>`;
                        let sickRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${adminBgCol('Sick Leave')}; color:#000;">SICK LEAVE DAYS</td>`;
                        let offRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${adminBgCol('OFF')}; color:#000;">OFF DAYS</td>`;
                        let frlRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${adminBgCol('FRL')}; color:#000;">FRL DAYS</td>`;
                        let annualRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${adminBgCol('Annual Leave')}; color:#000;">ANNUAL LEAVE DAYS</td>`;
                        let absentRow = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:#ef444488; color:#000;">ABSENT DAYS</td>`;

                        therapistTotals.forEach(t => {
                            const savedManualVal = globalSupervisorManualOTHours[t.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || "";

                            total150Row += `<td colspan="4" style="text-align:center; font-weight:700;">${t.sum150}</td>`;
                            total200Row += `<td colspan="4" style="text-align:center; font-weight:700;">${t.sum200}</td>`;
                            totalOtRow += `
            <td colspan="4" style="text-align:center; background:rgba(0, 75, 135, 0.05);">
                <input type="number" id="sup_total_hours_${t.username}" value="${savedManualVal}" step="0.5" placeholder="0" style="width:65px; text-align:center; font-weight:800; border:1px solid var(--border); border-radius:4px; padding:2px; color:var(--primary);"> hrs
            </td>
        `;
                            attendanceRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.present} Days</td>`;
                            sickRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.sick} Days</td>`;
                            offRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.off} Days</td>`;
                            frlRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.frl} Days</td>`;
                            annualRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.annual} Days</td>`;
                            absentRow += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${t.absent} Days</td>`;
                        });

                        // Build dynamic leave rows for non-standard types (Umrah, Hajj, etc.) - only if count > 0
                        const allOtherTypes = new Set();
                        therapistTotals.forEach(t => { Object.keys(t.otherLeaves).forEach(k => allOtherTypes.add(k)); });
                        let otherLeaveRows = "";
                        allOtherTypes.forEach(type => {
                            let hasNonZero = false;
                            const typeBg = adminBgCol(type);
                            let row = `<tr><td colspan="2" style="text-align:right; font-weight:700; background:${typeBg}; color:#000;">${type.toUpperCase()} DAYS</td>`;
                            therapistTotals.forEach(t => {
                                const count = t.otherLeaves[type] || 0;
                                if (count > 0) hasNonZero = true;
                                row += `<td colspan="4" style="text-align:center; color:var(--text-body); font-weight:600;">${count} Days</td>`;
                            });
                            row += "</tr>";
                            if (hasNonZero) otherLeaveRows += row;
                        });

                        tfoot.innerHTML = total150Row + "</tr>" + total200Row + "</tr>" + totalOtRow + "</tr>" +
                            attendanceRow + "</tr>" + sickRow + "</tr>" + offRow + "</tr>" +
                            frlRow + "</tr>" + annualRow + "</tr>" + absentRow + "</tr>" + otherLeaveRows;
                    }

                    function commitAllSupervisorAdminOverwrites() {
                        supervisorSaveAllGridData();
                        customAlert("Roster matrix and status overrides saved successfully!");
                        synchronizeWorkspaceCoreStatus();
                    }
                    function supervisorSaveAllGridData() {
                        const activeTherapists = globalRosterRepository.filter(u => u.position === "Physiotherapist" || u.position === "Head of Physio" || u.position === "Admin" || u.position === "General Manager");
                        const datesList = generateOTTimesheet31DaysList();

                        // Process daily override cell records
                        datesList.forEach(d => {
                            activeTherapists.forEach(staff => {
                                const input150Id = `sup_150_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const input200Id = `sup_200_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const inputAttId = `sup_att_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;
                                const inputNotesId = `sup_notes_${staff.username}_${d.fullDate.replace(/\//g, '_')}`;

                                const el150 = document.getElementById(input150Id);
                                const el200 = document.getElementById(input200Id);
                                const elAtt = document.getElementById(inputAttId);
                                const elNotes = document.getElementById(inputNotesId);
                                if (!el150 || !elAtt) return;

                                const val150 = parseFloat(el150.value) || 0;
                                const val200 = parseFloat(el200 ? el200.value : 0) || 0;
                                const valAtt = elAtt.value;
                                const valNotes = elNotes ? elNotes.value : '';

                                if (!globalAdminComparativeDatabase[staff.email]) globalAdminComparativeDatabase[staff.email] = {};
                                if (!globalAdminComparativeDatabase[staff.email][globalOTSelectedYear]) globalAdminComparativeDatabase[staff.email][globalOTSelectedYear] = {};
                                if (!globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth]) {
                                    globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                                }

                                globalAdminComparativeDatabase[staff.email][globalOTSelectedYear][globalOTSelectedMonth][d.fullDate] = {
                                    patients150: val150,
                                    patients200: val200,
                                    hours: 0,
                                    attendance: valAtt,
                                    notes: valNotes
                                };
                            });
                        });

                        // Process manual overall total overtime hours inside the footer
                        activeTherapists.forEach(staff => {
                            const inputOverallHoursEl = document.getElementById(`sup_total_hours_${staff.username}`);
                            if (inputOverallHoursEl) {
                                const finalOverallHoursVal = parseFloat(inputOverallHoursEl.value) || 0;
                                if (!globalSupervisorManualOTHours[staff.email]) globalSupervisorManualOTHours[staff.email] = {};
                                if (!globalSupervisorManualOTHours[staff.email][globalOTSelectedYear]) globalSupervisorManualOTHours[staff.email][globalOTSelectedYear] = {};
                                globalSupervisorManualOTHours[staff.email][globalOTSelectedYear][globalOTSelectedMonth] = finalOverallHoursVal;
                            }
                        });
                    }
                    var supervisorAutoSaveTimer = null;
                    function supervisorAutoSaveSingleCell(email, dateKey, input150Id, input200Id, inputAttId, inputNotesId) {
                        const el150 = document.getElementById(input150Id);
                        const elAtt = document.getElementById(inputAttId);
                        if (!el150 || !elAtt) return;

                        const val150 = parseFloat(el150.value) || 0;
                        const val200 = parseFloat(document.getElementById(input200Id) ? document.getElementById(input200Id).value : 0) || 0;
                        const valAtt = elAtt.value;
                        const valNotes = document.getElementById(inputNotesId) ? document.getElementById(inputNotesId).value : '';

                        if (!globalAdminComparativeDatabase[email]) globalAdminComparativeDatabase[email] = {};
                        if (!globalAdminComparativeDatabase[email][globalOTSelectedYear]) globalAdminComparativeDatabase[email][globalOTSelectedYear] = {};
                        if (!globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth]) {
                            globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                        }

                        globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth][dateKey] = {
                            patients150: val150,
                            patients200: val200,
                            hours: 0,
                            attendance: valAtt,
                            notes: valNotes
                        };

                        const indicator = document.getElementById('supAutoSaveIndicator');
                        if (indicator) { indicator.style.opacity = '1'; setTimeout(function () { if (indicator) indicator.style.opacity = '0'; }, 2000); }

                        if (supervisorAutoSaveTimer) clearTimeout(supervisorAutoSaveTimer);
                        supervisorAutoSaveTimer = setTimeout(function () {
                            supervisorAutoSaveTimer = null;
                            renderSupervisorMultiTherapistOTGrid();
                        }, 100);
                    }
                    function triggerActiveTimesheetComparison() {
                        const tbody = document.getElementById('supervisorComparisonReportTableBody');
                        const reportBox = document.getElementById('reconciliationComparisonReportBox');
                        if (!tbody || !reportBox) return;

                        tbody.innerHTML = "";
                        reportBox.classList.add('hidden');

                        const activeTherapists = globalRosterRepository.filter(u => u.position === "Physiotherapist" || u.position === "Head of Physio" || u.position === "Admin" || u.position === "General Manager");
                        const datesList = generateOTTimesheet31DaysList();
                        let discrepancyCount = 0;

                        datesList.forEach(d => {
                            const dateKey = d.fullDate;

                            activeTherapists.forEach(staff => {
                                // Therapist submissions (Master OT)
                                const therapistData = (globalTherapistOTSubmissions[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth]?.[dateKey]) ||
                                    { patients150: "", patients200: "", hours: "", attendance: "", notes: "" };

                                // Supervisor logs (Admin Ledger)
                                const adminData = (globalAdminComparativeDatabase[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth]?.[dateKey]) ||
                                    { patients150: "", patients200: "", hours: "", attendance: "", notes: "" };

                                const isoDate = convertDateKeyToISO(dateKey);
                                const matchedApprovedLeave = globalLeaveRepository.find(l =>
                                    l.email === staff.email &&
                                    l.status === "Approved" &&
                                    l.date === isoDate
                                );
                                const rosterShift = (activeCompiledShiftSchedules[staff.email] && activeCompiledShiftSchedules[staff.email][isoDate]) || "";
                                const isRosterOff = (rosterShift === "OFF");

                                let expectedAttendanceTherapist = therapistData.attendance;
                                let expectedAttendanceAdmin = adminData.attendance;

                                if (matchedApprovedLeave) {
                                    expectedAttendanceTherapist = matchedApprovedLeave.type;
                                    expectedAttendanceAdmin = matchedApprovedLeave.type;
                                } else if (isRosterOff) {
                                    expectedAttendanceTherapist = "OFF";
                                    expectedAttendanceAdmin = "OFF";
                                }

                                const mismatchList = [];
                                if (String(therapistData.patients150) !== String(adminData.patients150)) mismatchList.push("Patients 150");
                                if (String(therapistData.patients200) !== String(adminData.patients200)) mismatchList.push("Patients 200");
                                if (String(expectedAttendanceTherapist) !== String(expectedAttendanceAdmin)) mismatchList.push("Attendance Status");

                                if (mismatchList.length > 0) {
                                    discrepancyCount++;
                                    const tr = document.createElement('tr');
                                    tr.style.background = "rgba(239, 68, 68, 0.02)";

                                    const metricsStr = mismatchList.map(m => `<strong>${m}</strong>`).join(", ");
                                    const therapistDisplay = mismatchList.map(m => {
                                        if (m === "Patients 150") return therapistData.patients150 || "0";
                                        if (m === "Patients 200") return therapistData.patients200 || "0";
                                        return expectedAttendanceTherapist || "None";
                                    }).join(" / ");

                                    const adminDisplay = mismatchList.map(m => {
                                        if (m === "Patients 150") return adminData.patients150 || "0";
                                        if (m === "Patients 200") return adminData.patients200 || "0";
                                        return expectedAttendanceAdmin || "None";
                                    }).join(" / ");

                                    tr.innerHTML = `
                    <td style="text-align:left;"><strong>${dateKey}</strong></td>
                    <td>${staff.name}</td>
                    <td>${metricsStr}</td>
                    <td style="color:var(--danger); font-weight:700;">${therapistDisplay}</td>
                    <td style="color:var(--success); font-weight:700;">${adminDisplay}</td>
                    <td>
                        <div style="display:flex; justify-content:center; gap:6px;">
                            <button class="action-btn" style="background:var(--success); padding:3px 6px;" onclick="resolveManualDiscrepancy('${staff.email}', '${dateKey}', 'therapist')">Keep Therapist</button>
                            <button class="action-btn" style="background:var(--primary); padding:3px 6px;" onclick="resolveManualDiscrepancy('${staff.email}', '${dateKey}', 'admin')">Keep Supervisor</button>
                        </div>
                    </td>
                `;
                                    tbody.appendChild(tr);
                                }
                            });
                        });

                        if (discrepancyCount === 0) {
                            tbody.innerHTML = `
            <tr>
                <td colspan="6" style="text-align:center; color:var(--success); font-weight:700; padding:15px; font-size:11px;">
                    ✅ Excellent! All Submitted timesheets and Admin Overtime Ledgers match perfectly.
                </td>
            </tr>
        `;
                            reportBox.className = "broadcast-alert-banner success";
                            reportBox.innerHTML = `<div><strong>[MATCH PERFECT]</strong> All active timesheets match the supervisor manual ledger exactly.</div>`;
                        } else {
                            reportBox.className = "broadcast-alert-banner urgent";
                            reportBox.innerHTML = `<div><strong>[DISCREPANCIES DETECTED]</strong> Found ${discrepancyCount} data mismatches between submitted timesheets and supervisor overrides. Resolve them below.</div>`;
                        }
                        reportBox.classList.remove('hidden');
                    }

                    function resolveManualDiscrepancy(email, dateKey, source) {
                        // 1. Initialize therapist submissions database safely if uninstantiated
                        if (!globalTherapistOTSubmissions[email]) globalTherapistOTSubmissions[email] = {};
                        if (!globalTherapistOTSubmissions[email][globalOTSelectedYear]) globalTherapistOTSubmissions[email][globalOTSelectedYear] = {};
                        if (!globalTherapistOTSubmissions[email][globalOTSelectedYear][globalOTSelectedMonth]) {
                            globalTherapistOTSubmissions[email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                        }

                        // 2. Initialize therapist drafts database safely if uninstantiated
                        if (!localUserOTSheetDraft[email]) localUserOTSheetDraft[email] = {};
                        if (!localUserOTSheetDraft[email][globalOTSelectedYear]) localUserOTSheetDraft[email][globalOTSelectedYear] = {};
                        if (!localUserOTSheetDraft[email][globalOTSelectedYear][globalOTSelectedMonth]) {
                            localUserOTSheetDraft[email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                        }

                        // 3. Initialize supervisor comparative database safely if uninstantiated
                        if (!globalAdminComparativeDatabase[email]) globalAdminComparativeDatabase[email] = {};
                        if (!globalAdminComparativeDatabase[email][globalOTSelectedYear]) globalAdminComparativeDatabase[email][globalOTSelectedYear] = {};
                        if (!globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth]) {
                            globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth] = {};
                        }

                        const therapistMonth = globalTherapistOTSubmissions[email][globalOTSelectedYear][globalOTSelectedMonth];
                        const draftMonth = localUserOTSheetDraft[email][globalOTSelectedYear][globalOTSelectedMonth];
                        const adminMonth = globalAdminComparativeDatabase[email][globalOTSelectedYear][globalOTSelectedMonth];

                        // Ensure all internal date structures are instantiated securely
                        if (!therapistMonth[dateKey]) {
                            therapistMonth[dateKey] = { patients150: "", patients200: "", hours: "", attendance: "Present", notes: "" };
                        }
                        if (!draftMonth[dateKey]) {
                            draftMonth[dateKey] = { patients150: "", patients200: "", hours: "", attendance: "Present", notes: "" };
                        }
                        if (!adminMonth[dateKey]) {
                            adminMonth[dateKey] = { patients150: "", patients200: "", hours: "", attendance: "Present", notes: "" };
                        }

                        if (source === 'therapist') {
                            // Keep Therapist: Copy from therapist's submission (or active draft) over supervisor's ledger
                            const therapistSourceVal = (therapistMonth[dateKey].patients150 !== "" || therapistMonth[dateKey].patients200 !== "")
                                ? therapistMonth[dateKey]
                                : draftMonth[dateKey];

                            const copy = JSON.parse(JSON.stringify(therapistSourceVal));
                            adminMonth[dateKey] = copy;
                        } else if (source === 'admin') {
                            // Keep Supervisor: Overwrite both therapist's submission and therapist's draft
                            const copy = JSON.parse(JSON.stringify(adminMonth[dateKey]));
                            therapistMonth[dateKey] = copy;
                            draftMonth[dateKey] = copy;
                        }

                        customAlert("Discrepancy resolved and database registers synchronized.");
                        triggerActiveTimesheetComparison(); // Refreshes the compare list details
                        synchronizeWorkspaceCoreStatus(); // Refreshes active spreadsheet views across all modules instantly
                    }
                    function exportSupervisorOTToPDF() {
                        const activeTherapists = globalRosterRepository.filter(u => u.position === "Physiotherapist" || u.position === "Head of Physio" || u.position === "Admin" || u.position === "General Manager");
                        const datesList = generateOTTimesheet31DaysList();
                        const monthNames = {
                            "01": "January", "02": "February", "03": "March", "04": "April",
                            "05": "May", "06": "June", "07": "July", "08": "August",
                            "09": "September", "10": "October", "11": "November", "12": "December"
                        };
                        const activeMonthName = monthNames[globalOTSelectedMonth] || globalOTSelectedMonth; const activeYearValue = globalOTSelectedYear;

                        let htmlContent = `<table>
                <thead>
                    <tr>
                        <th rowspan="2" style="text-align:left;">Date</th>
                        <th rowspan="2">Day</th>
    `;

                        activeTherapists.forEach(staff => {
                            htmlContent += `<th colspan="4" style="text-align:center; background:#e0f2fe;">${staff.name}</th>`;
                        });

                        htmlContent += `</tr><tr>`;
                        activeTherapists.forEach(() => {
                            htmlContent += `
            <th>150 Pat</th>
            <th>200 Pat</th>
            <th>Status</th>
            <th>Notes</th>
        `;
                        });
                        htmlContent += `</tr></thead><tbody>`;

                        const STANDARD_ATTENDANCE_PDF = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL", "Family Responsibility Leave", "Family Leave"];

                        const therapistTotals = activeTherapists.map(t => ({
                            email: t.email,
                            sum150: 0,
                            sum200: 0,
                            present: 0,
                            sick: 0,
                            off: 0,
                            frl: 0,
                            annual: 0,
                            absent: 0,
                            otherLeaves: {}
                        }));

                        datesList.forEach(d => {
                            htmlContent += `<tr><td style="text-align:left; font-weight:bold;">${d.fullDate}</td><td>${d.dayName}</td>`;

                            activeTherapists.forEach((staff, idx) => {
                                const adminSubmissions = globalAdminComparativeDatabase[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || {};
                                const cell = adminSubmissions[d.fullDate] || { patients150: 0, patients200: 0, hours: 0, attendance: "Present", notes: "" };
                                const isoDate = convertDateKeyToISO(d.fullDate);
                                const matchedApprovedLeave = globalLeaveRepository.find(l => l.email === staff.email && l.status === "Approved" && l.date === isoDate);
                                const rosterShift = (activeCompiledShiftSchedules[staff.email] && activeCompiledShiftSchedules[staff.email][isoDate]) || "";
                                const isRosterOff = (rosterShift === "OFF");
                                const isFri = (d.dayName === "Fri");
                                let selectedAttendance = cell.attendance || (isFri ? "OFF" : "Present");
                                if (matchedApprovedLeave) { selectedAttendance = matchedApprovedLeave.type; }
                                else if (isRosterOff) { selectedAttendance = "OFF"; }
                                else if (isFri) { selectedAttendance = "OFF"; }
                                const p150Val = cell.patients150 || 0;
                                const p200Val = cell.patients200 || 0;
                                const tTotal = therapistTotals[idx];
                                if (selectedAttendance === "Present") { tTotal.present++; tTotal.sum150 += parseFloat(p150Val) || 0; tTotal.sum200 += parseFloat(p200Val) || 0; }
                                else if (selectedAttendance === "Sick Leave") { tTotal.sick++; }
                                else if (selectedAttendance === "Annual Leave") { tTotal.annual++; }
                                else if (selectedAttendance === "FRL" || selectedAttendance === "Family Responsibility Leave" || selectedAttendance === "Family Leave") { tTotal.frl++; }
                                else if (selectedAttendance === "Absent") { tTotal.absent++; }
                                else if (selectedAttendance === "OFF") { tTotal.off++; }
                                else if (selectedAttendance && !STANDARD_ATTENDANCE_PDF.includes(selectedAttendance)) { tTotal.otherLeaves[selectedAttendance] = (tTotal.otherLeaves[selectedAttendance] || 0) + 1; }

                                htmlContent += `<td>${p150Val}</td><td>${p200Val}</td><td style="font-weight:bold;">${selectedAttendance}</td><td>${cell.notes || '-'}</td>`;
                            });
                            htmlContent += `</tr>`;
                        });

                        htmlContent += `</tbody><tfoot>`;

                        const pdfBgCol = (key, fallback) => ((globalStatusColors && globalStatusColors[key]) || fallback) + '88';
                        const fw = 'font-weight:bold;background:#f8fafc;';
                        let r150 = `<tr><td colspan="2" style="text-align:right;${fw}">SUM 150 PATIENTS</td>`;
                        let r200 = `<tr><td colspan="2" style="text-align:right;${fw}">SUM 200 PATIENTS</td>`;
                        let rOt = `<tr><td colspan="2" style="text-align:right;${fw}">OVERTIME TOTAL HOURS</td>`;
                        let rPresent = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#b7e9ff;color:#000;">ATTENDANCE DAYS</td>`;
                        let rSick = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#f84e4e88;color:#000;">SICK LEAVE DAYS</td>`;
                        let rOff = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#cbd5e188;color:#000;">OFF DAYS</td>`;
                        let rFrl = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#10b98188;color:#000;">FRL DAYS</td>`;
                        let rAnnual = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#f59e0b88;color:#000;">ANNUAL LEAVE DAYS</td>`;
                        let rAbsent = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:#ef444488;color:#000;">ABSENT DAYS</td>`;

                        activeTherapists.forEach(staff => {
                            const tTotal = therapistTotals.find(item => item.email === staff.email);
                            const savedManualVal = globalSupervisorManualOTHours[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || "0";
                            r150 += `<td colspan="4" style="${fw}">${tTotal.sum150}</td>`;
                            r200 += `<td colspan="4" style="${fw}">${tTotal.sum200}</td>`;
                            rOt += `<td colspan="4" style="${fw}background:#fef08a;">${savedManualVal} hrs</td>`;
                            rPresent += `<td colspan="4" style="${fw}">${tTotal.present} Days</td>`;
                            rSick += `<td colspan="4" style="${fw}">${tTotal.sick} Days</td>`;
                            rOff += `<td colspan="4" style="${fw}">${tTotal.off} Days</td>`;
                            rFrl += `<td colspan="4" style="${fw}">${tTotal.frl} Days</td>`;
                            rAnnual += `<td colspan="4" style="${fw}">${tTotal.annual} Days</td>`;
                            rAbsent += `<td colspan="4" style="${fw}">${tTotal.absent} Days</td>`;
                        });

                        const pdfOtherBg = (t) => {
                            const map = { 'Umrah Leave': 'Umrah', 'Hajj Leave': 'Hajj', 'No Paid Leave': 'NoPaid', 'Maternity Leave': 'Maternity', 'Paternity Leave': 'Paternity', 'Special Leave': 'Special', 'Family Leave': 'FRL', 'Family Responsibility Leave': 'FRL' };
                            return (globalStatusColors && globalStatusColors[map[t]]) || '#cbd5e1';
                        };
                        const allOtherTypes = new Set();
                        therapistTotals.forEach(t => { Object.keys(t.otherLeaves).forEach(k => allOtherTypes.add(k)); });
                        let otherLeaveRows = "";
                        allOtherTypes.forEach(type => {
                            let hasNonZero = false;
                            const typeBg = pdfOtherBg(type);
                            let row = `<tr><td colspan="2" style="text-align:right;font-weight:700;background:${typeBg}88;color:#000;">${type.toUpperCase()} DAYS</td>`;
                            therapistTotals.forEach(t => {
                                const count = t.otherLeaves[type] || 0;
                                if (count > 0) hasNonZero = true;
                                row += `<td colspan="4" style="${fw}">${count} Days</td>`;
                            });
                            row += "</tr>";
                            if (hasNonZero) otherLeaveRows += row;
                        });

                        htmlContent += r150 + "</tr>" + r200 + "</tr>" + rOt + "</tr>" + rPresent + "</tr>" + rSick + "</tr>" + rOff + "</tr>" + rFrl + "</tr>" + rAnnual + "</tr>" + rAbsent + "</tr>" + otherLeaveRows;
                        htmlContent += `</tfoot></table>`;

                        openPrintablePDFWindow('Supervisor Overtime & Attendance Ledger Summary', '<span><strong>Billing Period Cycle:</strong> ' + activeMonthName + ' ' + activeYearValue + '</span>', htmlContent);
                    }

                    function exportSupervisorOTToExcel() {
                        const activeTherapists = globalRosterRepository.filter(u => u.position === "Physiotherapist" || u.position === "Head of Physio" || u.position === "Admin" || u.position === "General Manager");
                        const datesList = generateOTTimesheet31DaysList();
                        const monthNames = {
                            "01": "January", "02": "February", "03": "March", "04": "April",
                            "05": "May", "06": "June", "07": "July", "08": "August",
                            "09": "September", "10": "October", "11": "November", "12": "December"
                        };
                        const activeMonthName = monthNames[globalOTSelectedMonth] || globalOTSelectedMonth; const activeYearValue = globalOTSelectedYear;

                        let csvContent = `PHYSIO SOLUTIONS - Supervisor Overtime Ledger Summary - ${activeMonthName} ${activeYearValue}\n\n`;

                        let headRow1 = "Date,Day";
                        activeTherapists.forEach(staff => { headRow1 += `,${staff.name},,,,`; });
                        csvContent += headRow1 + "\n";

                        let headRow2 = ",";
                        activeTherapists.forEach(() => { headRow2 += `,Patients 150,Patients 200,Attendance,Notes,`; });
                        csvContent += headRow2 + "\n";

                        const STANDARD_ATTENDANCE_CSV = ["Present", "Absent", "OFF", "Sick Leave", "Annual Leave", "FRL", "Family Responsibility Leave", "Family Leave"];

                        const therapistTotals = activeTherapists.map(t => ({
                            email: t.email, sum150: 0, sum200: 0, present: 0, sick: 0, off: 0, frl: 0, annual: 0, absent: 0, otherLeaves: {}
                        }));

                        datesList.forEach(d => {
                            let rowStr = `${d.fullDate},${d.dayName}`;
                            activeTherapists.forEach((staff, idx) => {
                                const adminSubmissions = globalAdminComparativeDatabase[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || {};
                                const cell = adminSubmissions[d.fullDate] || { patients150: 0, patients200: 0, hours: 0, attendance: "Present", notes: "" };

                                const isoDate = convertDateKeyToISO(d.fullDate);
                                const matchedApprovedLeave = globalLeaveRepository.find(l => l.email === staff.email && l.status === "Approved" && l.date === isoDate);
                                const rosterShift = (activeCompiledShiftSchedules[staff.email] && activeCompiledShiftSchedules[staff.email][isoDate]) || "";
                                const isRosterOff = (rosterShift === "OFF");
                                const isFri = (d.dayName === "Fri");

                                let selectedAttendance = cell.attendance || (isFri ? "OFF" : "Present");
                                if (matchedApprovedLeave) { selectedAttendance = matchedApprovedLeave.type; }
                                else if (isRosterOff) { selectedAttendance = "OFF"; }
                                else if (isFri) { selectedAttendance = "OFF"; }

                                const p150Val = cell.patients150 || 0;
                                const p200Val = cell.patients200 || 0;

                                const tTotal = therapistTotals[idx];
                                if (selectedAttendance === "Present") {
                                    tTotal.present++; tTotal.sum150 += parseFloat(p150Val) || 0; tTotal.sum200 += parseFloat(p200Val) || 0;
                                } else if (selectedAttendance === "Sick Leave") { tTotal.sick++; }
                                else if (selectedAttendance === "Annual Leave") { tTotal.annual++; }
                                else if (selectedAttendance === "FRL" || selectedAttendance === "Family Responsibility Leave" || selectedAttendance === "Family Leave") { tTotal.frl++; }
                                else if (selectedAttendance === "Absent") { tTotal.absent++; }
                                else if (selectedAttendance === "OFF") { tTotal.off++; }
                                else if (selectedAttendance && !STANDARD_ATTENDANCE_CSV.includes(selectedAttendance)) { tTotal.otherLeaves[selectedAttendance] = (tTotal.otherLeaves[selectedAttendance] || 0) + 1; }

                                rowStr += `,${p150Val},${p200Val},"${selectedAttendance}","${cell.notes || '-'}",`;
                            });
                            csvContent += rowStr + "\n";
                        });

                        csvContent += "\n";

                        let r150 = "SUM 150 PATIENTS,";
                        let r200 = "SUM 200 PATIENTS,";
                        let rOt = "OVERTIME TOTAL HOURS,";
                        let rPresent = "ATTENDANCE DAYS,";
                        let rSick = "SICK LEAVE DAYS,";
                        let rOff = "OFF DAYS,";
                        let rFrl = "FRL DAYS,";
                        let rAnnual = "ANNUAL LEAVE DAYS,";
                        let rAbsent = "ABSENT DAYS,";

                        activeTherapists.forEach(staff => {
                            const tTotal = therapistTotals.find(item => item.email === staff.email);
                            const savedManualVal = globalSupervisorManualOTHours[staff.email]?.[globalOTSelectedYear]?.[globalOTSelectedMonth] || "0";
                            r150 += `,${tTotal.sum150},,,,`;
                            r200 += `,${tTotal.sum200},,,,`;
                            rOt += `,${savedManualVal} hrs,,,,`;
                            rPresent += `,${tTotal.present} Days,,,,`;
                            rSick += `,${tTotal.sick} Days,,,,`;
                            rOff += `,${tTotal.off} Days,,,,`;
                            rFrl += `,${tTotal.frl} Days,,,,`;
                            rAnnual += `,${tTotal.annual} Days,,,,`;
                            rAbsent += `,${tTotal.absent} Days,,,,`;
                        });

                        // Build dynamic leave rows for non-standard types (Umrah, Hajj, etc.) - only if count > 0
                        const allOtherTypes = new Set();
                        therapistTotals.forEach(t => { Object.keys(t.otherLeaves).forEach(k => allOtherTypes.add(k)); });
                        let otherLeaveRows = "";
                        allOtherTypes.forEach(type => {
                            let hasNonZero = false;
                            let row = `${type.toUpperCase()} DAYS,`;
                            therapistTotals.forEach(t => {
                                const count = t.otherLeaves[type] || 0;
                                if (count > 0) hasNonZero = true;
                                row += `,${count} Days,,,,`;
                            });
                            if (hasNonZero) otherLeaveRows += row + "\n";
                        });

                        csvContent += r150 + "\n" + r200 + "\n" + rOt + "\n" + rPresent + "\n" + rSick + "\n" + rOff + "\n" + rFrl + "\n" + rAnnual + "\n" + rAbsent + "\n" + otherLeaveRows;

                        downloadCSVAsXlsx(`Supervisor_OT_Ledger_${activeMonthName}_${activeYearValue}.csv`, csvContent);
                    }
                    function hasTherapistAttendanceGridAccess() {
                        return currentActiveSessionUser && allowedTherapistAttendanceRoles.includes(currentActiveSessionUser.position);
                    }

                    function getTasFilter() {
                        try { return JSON.parse(localStorage.getItem('therapistAttFilter')) || {}; } catch (e) { return {}; }
                    }
                    function setTasTypeFilter(type) {
                        const f = getTasFilter(); f.type = type; localStorage.setItem('therapistAttFilter', JSON.stringify(f));
                        const btns = document.querySelectorAll('#tasFilterBar [data-tas-type]');
                        btns.forEach(b => b.style.background = b.dataset.tasType === type ? 'var(--primary)' : '');
                        renderTherapistAttendanceSheet();
                    }
                    function openTasRoleConfigModal() {
                        const mount = document.getElementById('systemGlobalModalMount');
                        if (!mount) return;
                        const f = getTasFilter();
                        const savedRoles = f.roles && f.roles.length ? f.roles : null;
                        const allPositions = [...new Set(globalRosterRepository.map(t => t.position))].sort();
                        const checkedSet = new Set(savedRoles || allPositions);
                        const unchecked = allPositions.filter(p => !checkedSet.has(p));
                        const ordered = [...allPositions.filter(p => checkedSet.has(p)), ...unchecked];

                        let html = '<div class="system-inline-modal-overlay" onclick="if(event.target===this)closeSystemModalBox()" style="cursor:pointer;">';
                        html += '<div class="system-inline-modal-box" style="width:420px;max-height:80vh;overflow-y:auto;cursor:default;" onclick="event.stopPropagation()">';
                        html += '<h3 style="margin-bottom:4px;font-size:13px;">Configure Therapist Attendance Roles</h3>';
                        html += '<p style="font-size:10px;color:var(--text-muted);margin-bottom:12px;">Check roles to include. Use ↑↓ arrows to set display order.</p>';
                        html += '<div id="tasRoleSortableList" style="display:flex;flex-direction:column;gap:4px;">';
                        ordered.forEach((pos, idx) => {
                            const checked = checkedSet.has(pos) ? 'checked' : '';
                            html += `<div class="tas-role-row" data-role="${pos}" style="display:flex;align-items:center;gap:6px;padding:4px 6px;border-radius:6px;background:var(--bg-surface);${checked ? '' : 'opacity:0.5;'}">`;
                            html += `<button class="action-btn" style="padding:1px 6px;font-size:10px;min-width:auto;line-height:1.4;" onclick="moveTasRoleRow(this,-1)" ${idx === 0 ? 'disabled' : ''} title="Move up">↑</button>`;
                            html += `<button class="action-btn" style="padding:1px 6px;font-size:10px;min-width:auto;line-height:1.4;" onclick="moveTasRoleRow(this,1)" ${idx === ordered.length - 1 ? 'disabled' : ''} title="Move down">↓</button>`;
                            html += `<input type="checkbox" value="${pos}" ${checked} onchange="this.closest('.tas-role-row').style.opacity=this.checked?'':'0.5'">`;
                            html += `<span style="font-size:11px;font-weight:600;">${pos}</span>`;
                            const count = globalRosterRepository.filter(t => t.position === pos).length;
                            html += `<span style="font-size:9px;color:var(--text-muted);margin-left:auto;">${count} staff</span>`;
                            html += '</div>';
                        });
                        html += '</div>';
                        html += '<div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;">';
                        html += '<button class="action-btn" style="background:var(--danger);" onclick="closeSystemModalBox()">Cancel</button>';
                        html += '<button class="action-btn" style="background:var(--primary);" onclick="saveTasRoleConfigFromModal()">Save</button>';
                        html += '</div></div></div>';
                        mount.innerHTML = html;
                    }
                    function moveTasRoleRow(btn, dir) {
                        const row = btn.closest('.tas-role-row');
                        if (!row) return;
                        const list = document.getElementById('tasRoleSortableList');
                        const rows = [...list.querySelectorAll('.tas-role-row')];
                        const idx = rows.indexOf(row);
                        const target = idx + dir;
                        if (target < 0 || target >= rows.length) return;
                        if (dir < 0) list.insertBefore(row, rows[target]);
                        else list.insertBefore(row, rows[target].nextSibling);
                        const newRows = [...list.querySelectorAll('.tas-role-row')];
                        newRows.forEach(r => {
                            const btns = r.querySelectorAll('button');
                            if (btns[0]) btns[0].disabled = false;
                            if (btns[1]) btns[1].disabled = false;
                        });
                        newRows[0].querySelectorAll('button')[0].disabled = true;
                        newRows[newRows.length - 1].querySelectorAll('button')[1].disabled = true;
                    }
                    function saveTasRoleConfigFromModal() {
                        const rows = document.querySelectorAll('#tasRoleSortableList .tas-role-row');
                        const selected = [];
                        rows.forEach(row => {
                            const cb = row.querySelector('input[type="checkbox"]');
                            if (cb.checked) selected.push(cb.value);
                        });
                        if (selected.length === 0) {
                            customAlert("At least one role must be selected.");
                            return;
                        }
                        closeSystemModalBox();
                        const f = getTasFilter();
                        f.roles = selected;
                        localStorage.setItem('therapistAttFilter', JSON.stringify(f));
                        renderTherapistAttendanceSheet();
                    }
                    function renderTherapistAttendanceSheet() {
                        const btns = document.querySelectorAll('#tasFilterBar [data-tas-type]');
                        const activeType = (getTasFilter().type) || 'all';
                        btns.forEach(b => b.style.background = b.dataset.tasType === activeType ? 'var(--primary)' : '');
                        const monthEl = document.getElementById('therapistAttSheetMonth');
                        const month = monthEl ? monthEl.value : '';
                        if (!month) {
                            ['tasFtHead', 'tasFtBody', 'tasFtFoot', 'tasPtHead', 'tasPtBody', 'tasPtFoot'].forEach(id => {
                                const el = document.getElementById(id);
                                if (el) el.innerHTML = '';
                            });
                            const ftBody = document.getElementById('tasFtBody');
                            if (ftBody) ftBody.innerHTML = '<tr><td colspan="14" style="text-align:center;padding:30px;color:var(--text-muted);">Select a month.</td></tr>';
                            return;
                        }

                        const cycleRangeFromInputs = getTherapistAttendanceCycleRangeFromInputs();
                        const cycleStart = cycleRangeFromInputs ? cycleRangeFromInputs.cycleStart : (() => {
                            const [yr, mn] = (month || '').split('-').map(Number);
                            const monthIndex = mn - 1;
                            const startDay = parseInt(globalOTCycleStartDay) || 21;
                            return new Date(Date.UTC(yr, monthIndex - 1, startDay));
                        })();
                        const cycleEnd = cycleRangeFromInputs ? cycleRangeFromInputs.cycleEnd : (() => {
                            const [yr, mn] = (month || '').split('-').map(Number);
                            const monthIndex = mn - 1;
                            const startDay = parseInt(globalOTCycleStartDay) || 21;
                            return new Date(Date.UTC(yr, monthIndex, startDay - 1));
                        })();
                        const cycleRangeEl = document.getElementById('tasCycleRange');
                        if (cycleRangeEl) {
                            cycleRangeEl.innerText = '';
                        }
                        const tasDays = [];
                        let cur = new Date(cycleStart);
                        while (cur <= cycleEnd) {
                            tasDays.push({
                                day: cur.getUTCDate(),
                                month: cur.getUTCMonth() + 1,
                                year: cur.getUTCFullYear(),
                                dateStr: String(cur.getUTCDate()).padStart(2, '0') + '/' + String(cur.getUTCMonth() + 1).padStart(2, '0') + '/' + cur.getUTCFullYear()
                            });
                            cur.setUTCDate(cur.getUTCDate() + 1);
                        }

                        const monthKey = (monthEl && monthEl.value) ? monthEl.value : cycleEnd.toISOString().slice(0, 7);
                        const [yr, mn] = monthKey.split('-').map(Number);
                        const f = getTasFilter();
                        const selectedRoles = f.roles && f.roles.length ? f.roles : null;
                        let allTherapists = globalRosterRepository.filter(u => {
                            if (u.active === false) return false;
                            if (selectedRoles && !selectedRoles.includes(u.position)) return false;
                            return true;
                        });
                        if (!hasTherapistAttendanceGridAccess() && currentActiveSessionUser) {
                            allTherapists = allTherapists.filter(t => t.email === currentActiveSessionUser.email);
                        }

                        const ftTherapists = activeType === 'all' || activeType === 'fulltime' ? allTherapists.filter(t => t.style !== "Part-Time") : [];
                        const ptTherapists = activeType === 'all' || activeType === 'parttime' ? allTherapists.filter(t => t.style === "Part-Time") : [];

                        function getTasMonthData(email) {
                            if (!globalAdminComparativeDatabase[email]) return {};
                            if (!globalAdminComparativeDatabase[email][yr]) return {};
                            return globalAdminComparativeDatabase[email][yr][String(mn).padStart(2, '0')] || {};
                        }
                        function computeStats(t) {
                            let present = 0, sum150 = 0, sum200 = 0;
                            const submissions = getTasMonthData(t.email);
                            tasDays.forEach(d => {
                                const cell = submissions[d.dateStr];
                                if (!cell) return;
                                if (cell.attendance === 'Present') {
                                    present++;
                                    sum150 += parseFloat(cell.patients150) || 0;
                                    sum200 += parseFloat(cell.patients200) || 0;
                                }
                            });
                            const otHrs = globalSupervisorManualOTHours[t.email]?.[yr]?.[String(mn).padStart(2, '0')] || 0;
                            const key = t.email + '_' + month;
                            let rates = {};
                            try { rates = JSON.parse(localStorage.getItem('therapistAttRates_' + key)) || {}; } catch (e) { }
                            const rateAtt = rates.rateAtt !== undefined ? rates.rateAtt : 75;
                            const rate150 = rates.rate150 !== undefined ? rates.rate150 : 150;
                            const rate200 = rates.rate200 !== undefined ? rates.rate200 : 200;
                            const rateOt = rates.rateOt !== undefined ? rates.rateOt : 150;
                            return { present, sum150, sum200, otHrs, rateAtt, rate150, rate200, rateOt };
                        }

                        function renderSection(headId, bodyId, footId, therapists, showAttendance) {
                            const head = document.getElementById(headId);
                            const body = document.getElementById(bodyId);
                            const foot = document.getElementById(footId);
                            if (!head || !body || !foot) return;

                            const cols = showAttendance
                                ? ['Name', 'Attended', 'Rate', 'Total', '150 PATIENTS', 'Rate', 'Total', '200 PATIENTS', 'Rate', 'Total', 'OT (Hrs)', 'Rate', 'Total', 'Grand Total']
                                : ['Name', '150 PATIENTS', 'Rate', 'Total', '200 PATIENTS', 'Rate', 'Total', 'OT (Hrs)', 'Rate', 'Total', 'Grand Total'];
                            const colspan = cols.length;
                            head.innerHTML = '<tr>' + cols.map(c => '<th style="background:var(--primary);color:#fff;padding:6px 4px;font-size:10px;text-transform:none;">' + c + '</th>').join('') + '</tr>';

                            let bodyHtml = '';
                            let grandTotal = 0;

                            therapists.forEach(t => {
                                const s = computeStats(t);
                                const totalAtt = s.present * s.rateAtt;
                                const total150 = s.sum150 * s.rate150;
                                const total200 = s.sum200 * s.rate200;
                                const totalOt = s.otHrs * s.rateOt;
                                const rowTotal = totalAtt + total150 + total200 + totalOt;
                                grandTotal += rowTotal;

                                const onChange = `onchange="saveTherapistAttRate('${t.email}','${month}','att',this.value);renderTherapistAttendanceSheet()"`;
                                const onChange150 = `onchange="saveTherapistAttRate('${t.email}','${month}','150',this.value);renderTherapistAttendanceSheet()"`;
                                const onChange200 = `onchange="saveTherapistAttRate('${t.email}','${month}','200',this.value);renderTherapistAttendanceSheet()"`;
                                const onChangeOt = `onchange="saveTherapistAttRate('${t.email}','${month}','ot',this.value);renderTherapistAttendanceSheet()"`;

                                if (showAttendance) {
                                    bodyHtml += `<tr>
                    <td style="font-weight:600;padding:6px 8px;">${t.name}</td>
                    <td style="text-align:center;">${s.present}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rateAtt}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChange} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${totalAtt.toFixed(2)}</td>
                    <td style="text-align:center;">${s.sum150}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rate150}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChange150} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${total150.toFixed(2)}</td>
                    <td style="text-align:center;">${s.sum200}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rate200}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChange200} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${total200.toFixed(2)}</td>
                    <td style="text-align:center;">${s.otHrs}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rateOt}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChangeOt} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${totalOt.toFixed(2)}</td>
                    <td style="text-align:center;font-weight:800;color:var(--primary);">${rowTotal.toFixed(2)}</td>
                </tr>`;
                                } else {
                                    bodyHtml += `<tr>
                    <td style="font-weight:600;padding:6px 8px;">${t.name}</td>
                    <td style="text-align:center;">${s.sum150}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rate150}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChange150} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${total150.toFixed(2)}</td>
                    <td style="text-align:center;">${s.sum200}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rate200}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChange200} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${total200.toFixed(2)}</td>
                    <td style="text-align:center;">${s.otHrs}</td>
                    <td style="text-align:center;"><input type="number" value="${s.rateOt}" min="0" step="5" style="width:55px;text-align:center;font-size:10px;border:1px solid var(--border);border-radius:4px;padding:2px;" ${onChangeOt} onfocus="this.select()"></td>
                    <td style="text-align:center;font-weight:600;">${totalOt.toFixed(2)}</td>
                    <td style="text-align:center;font-weight:800;color:var(--primary);">${rowTotal.toFixed(2)}</td>
                </tr>`;
                                }
                            });

                            body.innerHTML = bodyHtml || '<tr><td colspan="' + colspan + '" style="text-align:center;padding:20px;color:var(--text-muted);">No therapists found.</td></tr>';
                            foot.innerHTML = '<tr style="font-weight:800;"><td colspan="' + (colspan - 1) + '" style="text-align:right;padding:8px 10px;">GRAND TOTAL</td><td style="text-align:center;padding:8px 10px;color:var(--primary);">' + grandTotal.toFixed(2) + '</td></tr>';
                        }

                        renderSection('tasFtHead', 'tasFtBody', 'tasFtFoot', ftTherapists, true);
                        renderSection('tasPtHead', 'tasPtBody', 'tasPtFoot', ptTherapists, false);
                        const ftHeading = document.getElementById('tasFtHeading');
                        const ptHeading = document.getElementById('tasPtHeading');
                        if (ftHeading) ftHeading.style.display = ftTherapists.length ? '' : 'none';
                        if (ptHeading) ptHeading.style.display = ptTherapists.length ? '' : 'none';
                    }

                    function saveTherapistAttRate(email, month, field, val) {
                        const key = 'therapistAttRates_' + email + '_' + month;
                        let rates = {};
                        try { rates = JSON.parse(localStorage.getItem(key)) || {}; } catch (e) { }
                        if (field === 'att') rates.rateAtt = parseFloat(val) || 0;
                        else if (field === '150') rates.rate150 = parseFloat(val) || 0;
                        else if (field === '200') rates.rate200 = parseFloat(val) || 0;
                        else if (field === 'ot') rates.rateOt = parseFloat(val) || 0;
                        localStorage.setItem(key, JSON.stringify(rates));
                    }

                    function exportTherapistAttendancePDF() {
                        const monthEl = document.getElementById('therapistAttSheetMonth');
                        const month = monthEl ? monthEl.value : '';
                        if (!month) return;
                        const moduleEl = document.getElementById('mod_therapist_attendance_sheet');
                        if (!moduleEl) return;
                        const tables = moduleEl.querySelectorAll('.premium-table');
                        if (!tables.length) return;
                        let html = '';
                        tables.forEach(t => { html += resolveExportCSSVars(bakeTableStyles(t)) + '<br>'; });
                        openPrintablePDFWindow('Therapist Attendance ' + month, '<span><strong>Month:</strong> ' + month + '</span>', html);
                    }

                    function exportTherapistAttendanceExcel() {
                        const monthEl = document.getElementById('therapistAttSheetMonth');
                        const month = monthEl ? monthEl.value : '';
                        if (!month) return;
                        const btns = document.querySelectorAll('#tasFilterBar [data-tas-type]');
                        const activeType = (getTasFilter().type) || 'all';
                        const [yr, mn] = month.split('-').map(Number);
                        const startDay = parseInt(globalOTCycleStartDay) || 21;
                        const cycleStart = new Date(Date.UTC(yr, mn - 2, startDay));
                        const cycleEnd = new Date(Date.UTC(yr, mn - 1, startDay - 1));
                        const tasDays = [];
                        let cur = new Date(cycleStart);
                        while (cur <= cycleEnd) {
                            tasDays.push(cur.getUTCDate() + '/' + (cur.getUTCMonth() + 1) + '/' + cur.getUTCFullYear());
                            cur.setUTCDate(cur.getUTCDate() + 1);
                        }
                        const f = getTasFilter();
                        const selectedRoles = f.roles && f.roles.length ? f.roles : null;
                        let allTherapists = globalRosterRepository.filter(function (u) {
                            if (u.active === false) return false;
                            if (selectedRoles && !selectedRoles.includes(u.position)) return false;
                            return true;
                        });
                        if (!hasTherapistAttendanceGridAccess() && currentActiveSessionUser) {
                            allTherapists = allTherapists.filter(function (t) { return t.email === currentActiveSessionUser.email; });
                        }
                        const ftTherapists = activeType === 'all' || activeType === 'fulltime' ? allTherapists.filter(function (t) { return t.style !== "Part-Time"; }) : [];
                        const ptTherapists = activeType === 'all' || activeType === 'parttime' ? allTherapists.filter(function (t) { return t.style === "Part-Time"; }) : [];

                        function getTasMonthData(email) {
                            if (!globalAdminComparativeDatabase[email]) return {};
                            if (!globalAdminComparativeDatabase[email][yr]) return {};
                            return globalAdminComparativeDatabase[email][yr][String(mn).padStart(2, '0')] || {};
                        }

                        var rows = [['Type', 'Name', 'Attended', 'Rate', 'Total', '150 PATIENTS', 'Rate', 'Total', '200 PATIENTS', 'Rate', 'Total', 'OT (Hrs)', 'Rate', 'Total', 'Grand Total']];
                        var grandTotal = 0;

                        function addTherapistRows(therapists, typeLabel) {
                            therapists.forEach(function (t) {
                                var submissions = getTasMonthData(t.email);
                                var present = 0, sum150 = 0, sum200 = 0;
                                tasDays.forEach(function (dateStr) {
                                    var cell = submissions[dateStr];
                                    if (!cell) return;
                                    if (cell.attendance === 'Present') {
                                        present++;
                                        sum150 += parseFloat(cell.patients150) || 0;
                                        sum200 += parseFloat(cell.patients200) || 0;
                                    }
                                });
                                var otHrs = globalSupervisorManualOTHours[t.email]?.[yr]?.[String(mn).padStart(2, '0')] || 0;
                                var key = t.email + '_' + month;
                                var rates = {};
                                try { rates = JSON.parse(localStorage.getItem('therapistAttRates_' + key)) || {}; } catch (e) { }
                                var rateAtt = rates.rateAtt !== undefined ? rates.rateAtt : 75;
                                var rate150 = rates.rate150 !== undefined ? rates.rate150 : 150;
                                var rate200 = rates.rate200 !== undefined ? rates.rate200 : 200;
                                var rateOt = rates.rateOt !== undefined ? rates.rateOt : 150;
                                var totalAtt = present * rateAtt;
                                var total150 = sum150 * rate150;
                                var total200 = sum200 * rate200;
                                var totalOt = otHrs * rateOt;
                                var rowTotal = totalAtt + total150 + total200 + totalOt;
                                grandTotal += rowTotal;
                                rows.push([typeLabel, t.name, present, rateAtt, totalAtt.toFixed(2), sum150, rate150, total150.toFixed(2), sum200, rate200, total200.toFixed(2), otHrs, rateOt, totalOt.toFixed(2), rowTotal.toFixed(2)]);
                            });
                        }

                        addTherapistRows(ftTherapists, 'Full-Time');
                        addTherapistRows(ptTherapists, 'Part-Time');
                        rows.push(['', 'GRAND TOTAL', '', '', '', '', '', '', '', '', '', '', '', '', grandTotal.toFixed(2)]);

                        var csv = rows.map(function (r) { return r.map(function (c) { return typeof c === 'string' && (c.includes(',') || c.includes('"')) ? '"' + c.replace(/"/g, '""') + '"' : c; }).join(','); }).join('\n');
                        downloadCSVAsXlsx('Therapist_Attendance_' + month + '.xlsx', csv);
                    }

                    function renderDischargeCustomFieldsFormInputs(containerEl) {
                        const container = containerEl || document.getElementById('dischargeEntryFormInputs');
                        if (!container) return;
                        container.innerHTML = "";
                        const currentSchema = globalTableSchemas.discharge;

                        currentSchema.forEach(col => {
                            let inputHtml = "";
                            let extraStyle = "";
                            const normKey = col.key.toLowerCase();
                            if (normKey === 'number') {
                                const now = new Date();
                                const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
                                const monthRecords = dischargeRecords.filter(r => r.endDate && r.endDate.startsWith(currentMonth));
                                const nextNum = monthRecords.reduce((max, r) => Math.max(max, parseInt(r.number, 10) || 0), 0) + 1;
                                inputHtml = `<input type="text" id="pDischargeField_number" value="${nextNum}" readonly style="padding:8px; border-radius:6px; border:1px solid var(--border); background:var(--bg-subtle); color:var(--text-muted); font-size:11px; width:100%;">`;
                            } else if (normKey === 'therapistname' || normKey === 'discharged_by' || normKey === 'therapist_name') {
                                inputHtml = `<input type="text" id="pDischargeField_therapistName" value="${escapeHtml(currentActiveSessionUser ? currentActiveSessionUser.name : '')}" readonly style="padding:8px; border-radius:6px; border:1px solid var(--border); background:var(--bg-subtle); color:var(--text-muted); font-size:11px; width:100%;">`;
                            } else if (normKey === 'diagnosis' || normKey === 'clinical_diagnoses') {
                                let optionsHtml = globalDiagnosisOptions.map(opt => `<option value="${escapeHtml(opt)}">${escapeHtml(opt)}</option>`).join("");
                                inputHtml = `
                <div style="display:flex; gap:4px; align-items:center; width:100%;">
                    <select id="pDischargeField_diagnosis" required style="flex:1; min-width:0; width:100%; padding:8px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-size:11px;">
                        ${optionsHtml}
                    </select>
                    <button class="action-btn" type="button" onclick="openAddDiagnosisOptionModal()" style="padding:4px 8px; font-size:10px; white-space:nowrap;">➕ Add</button>
                </div>
            `;
                                extraStyle = "";
                            } else if (normKey === 'startdate' || normKey === 'enddate') {
                                inputHtml = `<input type="date" id="pDischargeField_${col.key}" required min="2022-01-01">`;
                            } else if (col.type === "date") {
                                inputHtml = `<input type="date" id="pDischargeField_${col.key}" required min="2022-01-01">`;
                            } else if (col.type === "number") {
                                inputHtml = `<input type="number" id="pDischargeField_${col.key}" required placeholder="0" min="0">`;
                            } else if (normKey === 'notes') {
                                inputHtml = `<textarea id="pDischargeField_notes" required placeholder="Enter notes (min 20 characters)..." style="width:100%; padding:8px; border-radius:6px; border:1px solid var(--border); background:var(--bg-inner); color:var(--text-body); font-size:11px; font-family:inherit; resize:vertical; min-height:100px;"></textarea>`;
                                extraStyle = "grid-column:1/-1;";
                            } else {
                                inputHtml = `<input type="text" id="pDischargeField_${col.key}" required placeholder="Enter ${col.name.toLowerCase()}...">`;
                            }

                            container.innerHTML += `
            <div class="form-group" style="${extraStyle}">
                <label>${escapeHtml(col.name)}</label>
                ${inputHtml}
            </div>
        `;
                        });
                        container.querySelectorAll('input:not([readonly]), select, textarea').forEach(el => {
                            el.addEventListener('input', function () { this.style.border = ''; this.style.outline = ''; });
                            el.addEventListener('change', function () { this.style.border = ''; this.style.outline = ''; });
                        });
                    }

                    // =========================================================
                    // SECURITY UTILITY: HTML ESCAPE FUNCTION
                    // Prevents XSS by sanitizing any user-supplied content 
                    // before injecting into innerHTML
                    // =========================================================
                    function escapeHtml(str) {
                        if (str === null || str === undefined) return '';
                        return String(str)
                            .replace(/&/g, '&amp;')
                            .replace(/</g, '&lt;')
                            .replace(/>/g, '&gt;')
                            .replace(/"/g, '&quot;')
                            .replace(/'/g, '&#039;');
                    }

                    // =========================================================
                    // MISSING FUNCTION STUBS - Prevent runtime errors
                    // =========================================================

                    // enforceGlobalSpellcheck
                    function enforceGlobalSpellcheck() {
                        const fields = document.querySelectorAll('input[type="text"], textarea');
                        fields.forEach(field => {
                            field.setAttribute('spellcheck', 'true');
                            field.setAttribute('autocomplete', 'on');
                            field.setAttribute('autocorrect', 'on');
                        });
                    }

                    // ---------------------------------------------------------
                    // Sidebar Layout Toggle & Workspace Stretching Handler
                    // ---------------------------------------------------------
                    function toggleSidebarLayout() {
                        const sidebar = document.getElementById('sidebarContainerElement');
                        if (!sidebar) return;

                        // On mobile (< 768px), use overlay mode with expanded class
                        if (window.innerWidth <= 768) {
                            const isExpanded = sidebar.classList.toggle('expanded');
                            const overlay = document.getElementById('sidebarOverlay');
                            if (overlay) overlay.classList.toggle('active', isExpanded);
                            if (isExpanded) {
                                sidebar.classList.remove('collapsed');
                            } else {
                                sidebar.classList.add('collapsed');
                            }
                            const mblLogo = document.getElementById('topNavLogo');
                            if (mblLogo) {
                                if (!isExpanded) {
                                    const sbImg = document.querySelector('#sidebarBrandLabelText img');
                                    if (sbImg && !mblLogo.querySelector('img')) {
                                        mblLogo.appendChild(sbImg.cloneNode(true));
                                    }
                                    mblLogo.style.display = 'block';
                                } else {
                                    mblLogo.style.display = 'none';
                                }
                            }
                            return;
                        }

    // Desktop with hover-expand: toggle button is hidden, skip collapse behavior
    if (window.innerWidth > 768) return;
    const isCollapsed = sidebar.classList.toggle('collapsed');

    const topNavLogo = document.getElementById('topNavLogo');
    if (topNavLogo) {
        if (isCollapsed) {
            const sidebarImg = document.querySelector('#sidebarBrandLabelText img');
            if (sidebarImg && !topNavLogo.querySelector('img')) {
                topNavLogo.appendChild(sidebarImg.cloneNode(true));
            }
            topNavLogo.style.display = 'block';
        } else {
            topNavLogo.style.display = 'none';
        }
    }

    // Save user preference to browser memory
    localStorage.setItem('sidebar_collapsed_preference', isCollapsed ? 'true' : 'false');

                        // Smoothly recalculate visual layouts after transitions finish
                        setTimeout(() => {
                            if (globalActiveViewportModule === 'therapist_volume') {
                                renderVolumeAnalytics();
                            }
                        }, 300);
                    }

                    // On window resize, reset sidebar for current viewport
                    window.addEventListener('resize', function () {
                        const sidebar = document.getElementById('sidebarContainerElement');
                        const overlay = document.getElementById('sidebarOverlay');
                        if (!sidebar) return;
                        if (window.innerWidth > 768) {
                            sidebar.classList.remove('expanded');
                            sidebar.classList.remove('collapsed');
                            if (overlay) overlay.classList.remove('active');
                            const logo = document.getElementById('topNavLogo');
                            if (logo) logo.style.display = 'block';
                        } else {
                            // On mobile, ensure collapsed class is present by default
                            sidebar.classList.add('collapsed');
                            sidebar.classList.remove('expanded');
                        }
                    });

                    // =========================================================
                    // UNIFIED INITIALIZATION PROCESS (Start after DOM is ready)
                    // =========================================================
                    document.addEventListener('DOMContentLoaded', function () {
                        // 1. Run core data seeding and date variable setups
                        runSystemRosterCoreInitialization();

                        // 2. Start the live clock ticks
                        updateDashboardLiveClock();
                        setInterval(updateDashboardLiveClock, 1000);

                        // 3. Enforce spellcheck settings
                        enforceGlobalSpellcheck();

                        // 4. Keyboard Enter-key submit listener
                        document.addEventListener('keydown', function (e) {
                            if (e.key === 'Enter') {
                                const modalOverlay = document.querySelector('#systemGlobalModalMount .system-inline-modal-overlay');
                                if (modalOverlay) { closeSystemModalBox(); e.preventDefault(); return; }
                                const authContainer = document.getElementById('authContainer');
                                const authContainerSplit = document.getElementById('authContainerSplit');
                                const compactVisible = authContainer && !authContainer.classList.contains('hidden');
                                const splitVisible = authContainerSplit && !authContainerSplit.classList.contains('hidden');
                                if (compactVisible || splitVisible) {
                                    const recoveryField = document.getElementById('recoveryEmailField');
                                    const otpField = document.getElementById('recoveryOtpField');
                                    if (recoveryField && recoveryField.offsetParent !== null) {
                                        executeRecoveryStepOneSubmit();
                                    } else if (otpField && otpField.offsetParent !== null) {
                                        executeRecoveryStepTwoSubmit();
                                    } else {
                                        executeSimulatedAuthenticationChallenge();
                                    }
                                }
                            }
                        });

                        // 5. Render active login layouts and theme configurations
                        renderAuthViewLayoutBox();
                        onRosterCycleChange();
                        loadRosterColorDefaults();
                        applySavedLoginTheme();
                        initLoginPortalConfig();

                        // Init biometric settings
                        const isBiometricEnabled = localStorage.getItem('physioBiometricEnabled') === 'true';
                        const bioToggle = document.getElementById('biometricToggle');
                        if (bioToggle) {
                            bioToggle.checked = isBiometricEnabled;
                            toggleBiometricSetting(isBiometricEnabled);
                        }
                        const hasCredential = !!localStorage.getItem('physioBiometricCredentialId');
                        if (hasCredential) {
                            const info = document.getElementById('biometricRegisteredInfo');
                            if (info) {
                                info.style.display = 'block';
                                info.textContent = '?? Biometric credential registered on this device.';
                            }
                        }
                        loadBrandingConfig();
                        rebuildSystemRosterGridSkeleton();
                        initializeTranslationObserver();
                        updateDynamicLogos();
                        updateDynamicLogosSplit();
                        // Desktop hover-expand: show/hide topNavLogo on sidebar hover
                        const sidebarEl = document.getElementById('sidebarContainerElement');
                        if (sidebarEl) {
                            sidebarEl.addEventListener('mouseenter', function () {
                                if (window.innerWidth > 768) {
                                    const logo = document.getElementById('topNavLogo');
                                    if (logo) logo.style.display = 'none';
                                }
                            });
                            sidebarEl.addEventListener('mouseleave', function () {
                                if (window.innerWidth > 768) {
                                    const logo = document.getElementById('topNavLogo');
                                    if (logo) logo.style.display = 'block';
                                }
                            });
                        }
                        loadLeaveConfigSettings();
                        loadDashboardLeaveVisibility();
                        loadExpiryTrackerData();
                        loadPersonalExpiryData();
                        loadExpiryCategories();
                        loadScheduledBroadcastTemplates();
                        // Delay first check to ensure session is active
                        setTimeout(() => {
                            checkAndTriggerScheduledBroadcasts();
                        }, 3000);
                        // Re-check every 5 minutes for due broadcasts
                        setInterval(checkAndTriggerScheduledBroadcasts, 300000);
                    });
                    function renderDashboardLeaveVerificationQueue() {
                        const tbody = document.getElementById('dashboardLeaveVerificationBody');
                        if (!tbody) return;
                        const userPos = currentActiveSessionUser.position;
                        const canViewAll = allowedManagementDashboardRoles.includes(userPos) || allowedLeaveApproverRoles.includes(userPos);
                        const canApprove = allowedLeaveApproverRoles.includes(userPos);
                        const allLeaves = canViewAll
                            ? globalLeaveRepository.filter(l => l.email === currentActiveSessionUser.email || l.status === 'Pending Approval')
                            : globalLeaveRepository.filter(l => l.email === currentActiveSessionUser.email);
                        if (allLeaves.length === 0) {
                            tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);font-style:italic;">No leave requests found.</td></tr>`;
                            return;
                        }
                        allLeaves.sort((a, b) => (b.submittedAt || '').localeCompare(a.submittedAt || ''));
                        allLeaves.forEach(item => {
                            const isPending = item.status === "Pending Approval";
                            const isManagerial = canApprove;
                            const tr = document.createElement('tr');
                            tr.innerHTML = `
            <td style="padding:4px 6px;font-size:10px;"><strong>${item.employee}</strong></td>
            <td style="padding:4px 6px;font-size:10px;">${item.type}</td>
            <td style="padding:4px 6px;font-size:10px;white-space:nowrap;">${item.duration}d</td>
            <td style="padding:4px 6px;font-size:10px;white-space:nowrap;">${formatDateToDDMMYYYY(item.date)}</td>
            <td style="padding:4px 6px;font-size:10px;white-space:nowrap;">${item.submittedAt ? formatDateToDDMMYYYY(item.submittedAt.split('T')[0]) : '-'}</td>
            <td style="padding:4px 6px;font-size:10px;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${item.note || '-'}</td>
            <td style="padding:4px 6px;font-size:10px;text-align:center;white-space:nowrap;"><span class="badge ${item.status === 'Approved' ? 'badge-success' : item.status === 'Rejected' ? 'badge-danger' : 'badge-warning'}" style="font-size:8px;padding:2px 5px;">${item.status}</span></td>
            <td style="padding:4px 6px;font-size:10px;text-align:center;white-space:nowrap;">${item.approvedBy || '-'}</td>
            <td style="padding:4px 6px;font-size:10px;text-align:center;white-space:nowrap;">
                ${(isPending && isManagerial) ? `
                    <div style="display:flex; gap:2px;">
                        <button class="action-btn" style="background:var(--success);padding:2px 5px;font-size:9px;" onclick="auditLeaveRequestStatus(${item.id}, 'Approved');renderDashboardLeaveVerificationQueue();">Approve</button>
                        <button class="action-btn" style="background:var(--danger);padding:2px 5px;font-size:9px;" onclick="auditLeaveRequestStatus(${item.id}, 'Rejected');renderDashboardLeaveVerificationQueue();">Reject</button>
                    </div>
                ` : `<span style="font-style:italic;opacity:0.6;font-size:9px;">—</span>`}
            </td>
        `;
                            tbody.appendChild(tr);
                        });
                    }

                    function renderDashboardQuickActions() {
                        const container = document.getElementById('dashboardQuickActionsContainer');
                        if (!container) return;
                        container.innerHTML = "";

                        if (globalDashboardQuickActions.length === 0) {
                            container.innerHTML = `<span style="font-style:italic; color:var(--text-muted); text-align:center; display:block; padding:12px;">No quick actions configured.</span>`;
                            return;
                        }

                        const allowed = currentActiveSessionUser ? getAllowedModulesForRole(currentActiveSessionUser.position) : [];
                        const visible = globalDashboardQuickActions.filter(a => {
                            if (a.type === 'link' && a.linkType === 'url') return true;
                            return allowed.includes(a.target);
                        });

                        visible.forEach(action => {
                            const btn = document.createElement('button');
                            btn.className = "action-btn";
                            btn.style = "width:100%; justify-content:center; background:var(--bg-inner); color:var(--text-heading); border:1px solid var(--border); font-size:11px; padding:8px 6px;";
                            let icon;
                            if (action.type === 'link') {
                                icon = action.linkType === 'url' ? '🌐' : '⚙️';
                                btn.onclick = action.linkType === 'url'
                                    ? () => window.open(action.target, "_blank")
                                    : () => triggerSelectedModuleShift(action.target);
                            } else {
                                icon = action.icon;
                                btn.onclick = () => triggerSelectedModuleShift(action.target);
                            }
                            btn.innerHTML = `<span style="font-size:16px; display:block; margin-bottom:2px;">${icon}</span><span style="font-size:9px; font-weight:600;">${action.label}</span>`;
                            container.appendChild(btn);
                        });
                    }

                    function commitAddCustomQuickAction() {
                        const type = document.getElementById('newQuickActionType').value;
                        if (type === 'icon') {
                            const icon = document.getElementById('newQuickActionIcon').value.trim();
                            const label = document.getElementById('newQuickActionLabel').value.trim();
                            const target = document.getElementById('newQuickActionTarget').value;
                            if (!icon || !label) { customAlert("Please fill in icon and label."); return; }
                            globalDashboardQuickActions.push({ type: "icon", icon, label, target });
                            document.getElementById('newQuickActionIcon').value = "";
                            document.getElementById('newQuickActionLabel').value = "";
                        } else {
                            const icon = document.getElementById('newQuickActionUrlIcon').value.trim() || '🌐';
                            const label = document.getElementById('newQuickActionUrlTitle').value.trim();
                            const target = document.getElementById('newQuickActionUrl').value.trim();
                            if (!label || !target) { customAlert("Please fill in both title and URL."); return; }
                            globalDashboardQuickActions.push({ type: "link", icon, label, linkType: "url", target });
                            document.getElementById('newQuickActionUrlIcon').value = '';
                            document.getElementById('newQuickActionUrlTitle').value = "";
                            document.getElementById('newQuickActionUrl').value = "";
                        }
                        customAlert("Quick action added successfully.");
                        renderQuickActionsEditor();
                        if (typeof synchronizeWorkspaceCoreStatus === 'function') synchronizeWorkspaceCoreStatus();
                    }

                    function toggleQuickActionType(val) {
                        document.getElementById('quickActionIconFields').style.display = val === 'icon' ? 'flex' : 'none';
                        document.getElementById('quickActionUrlFields').style.display = val === 'url' ? 'flex' : 'none';
                    }

                    function renderQuickActionsEditor() {
                        const container = document.getElementById('quickActionsEditorContainer');
                        if (!container) return;
                        container.innerHTML = "";

                        globalDashboardQuickActions.forEach((action, index) => {
                            const div = document.createElement('div');
                            div.style.cssText = 'display: flex; align-items: center; gap: 8px; padding: 6px 8px; background: var(--bg-inner); border: 1px solid var(--border); border-radius: 6px;';
                            let display = '';
                            if (action.type === 'link') {
                                const ico = action.icon || (action.linkType === 'url' ? '🌐' : '🔗');
                                display = '<span style="font-size:14px;">' + ico + '</span><span style="font-size: 10px; font-weight: 600; flex: 1;">' + action.label + '</span><span style="font-size: 9px; color: var(--text-muted);">' + (action.linkType === 'url' ? 'URL' : 'Module') + ': ' + action.target + '</span>';
                            } else {
                                display = '<span style="font-size: 14px;">' + action.icon + '</span><span style="font-size: 10px; font-weight: 600; flex: 1;">' + action.label + '</span><span style="font-size: 9px; color: var(--text-muted);">' + action.target + '</span>';
                            }
                            div.innerHTML = display + '<button onclick="removeQuickAction(' + index + ')" style="background: none; border: none; color: var(--danger); cursor: pointer; font-size: 12px; padding: 2px 4px;">×</button>';
                            container.appendChild(div);
                        });
                    }

                    function removeQuickAction(index) {
                        globalDashboardQuickActions.splice(index, 1);
                        renderQuickActionsEditor();
                        customAlert("Quick action removed.");
                    }

                    function updateDashboardLiveClock() {
                        const clockEl = document.getElementById('dashboardLiveTime');
                        if (clockEl) {
                            const now = new Date();
                            clockEl.innerText = now.toLocaleString();
                        }
                    }
                    // Clock interval is started after DOM is ready (see DOMContentLoaded below)

                    // Dynamic Sub-Tab Switching Logic for Administrative Core
                    function switchAdminHubSubTab(tabName) {
                        // Hide all sub-tab contents
                        document.querySelectorAll('.admin-sub-tab-content').forEach(el => {
                            el.classList.add('hidden');
                            el.style.setProperty('display', 'none', 'important');
                        });

                        // Remove active class from all buttons and reset their look
                        document.querySelectorAll('.admin-tab-btn').forEach(btn => {
                            btn.classList.remove('active');
                            btn.style.backgroundColor = 'transparent';
                            btn.style.color = 'var(--text-muted)';
                        });

                        // Show target sub-tab content
                        const targetContent = document.getElementById(`admin_sub_${tabName}`);
                        if (targetContent) {
                            targetContent.classList.remove('hidden');
                            targetContent.style.display = '';
                            setTimeout(initColorSwatches, 50);
                            if (tabName === 'schema') {
                                setTimeout(refreshDictionaryInlineStats, 100);
                                setTimeout(renderQuickActionsEditor, 50);
                                setTimeout(renderCustomFieldsConfiguratorList, 50);
                                setTimeout(() => {
                                    const sel = document.getElementById('builderTableSelector');
                                    if (sel) loadActiveSchemaStructure(sel.value);
                                }, 50);
                            }
                            if (tabName === 'dictionary') {
                                setTimeout(() => { renderDictionaryControlSettingsPanel(); }, 50);
                            }
                            if (tabName === 'leave_config') {
                                setTimeout(populateLeaveConfigSettings, 50);
                            }
                            if (tabName === 'expiry_config') {
                                setTimeout(loadExpiryCategories, 50);
                            }
                            if (tabName === 'logs') {
                                setTimeout(toggleSchedDaySelector, 50);
                            }
                            if (tabName === 'clinical') {
                                setTimeout(populateAasandhaInlineConfig, 50);
                                setTimeout(populateDischargeInlineConfig, 80);
                            }

                        }

                        // Mark the selected button as active
                        const targetBtn = document.getElementById(`btn_admin_tab_${tabName}`);
                        if (targetBtn) {
                            targetBtn.classList.add('active');
                            targetBtn.style.backgroundColor = 'var(--primary-light)';
                            targetBtn.style.color = 'var(--primary)';
                        }

                        // Retranslate dynamically rendered elements
                        if (typeof autoScanAndRegisterAllLayoutElements === 'function') {
                            autoScanAndRegisterAllLayoutElements();
                        }

                        // Force active spellcheck parameters globally across all text nodes
                        enforceGlobalSpellcheck();
                    }

                    // =========================================================
                    // DOCUMENT REFERENCE TRACKER - FULLY INTEGRATED MODULE ENGINE
                    // =========================================================

                    // 1. Populates the year dropdown chronologically descending up to 2099
                    function populateReferenceYearSelector() {
                        const yearSel = document.getElementById('referenceYearSelector');
                        if (!yearSel) return;
                        yearSel.innerHTML = '<option value="all">All Years</option>';

                        const currentYear = new Date().getFullYear(); // Evaluates to 2026

                        // Populate descending from 2099 down to 2022
                        for (let yr = 2099; yr >= 2022; yr--) {
                            const opt = document.createElement('option');
                            opt.value = String(yr);
                            opt.innerText = String(yr);
                            if (yr === currentYear) {
                                opt.selected = true; // Auto-select current year (2026)
                            }
                            yearSel.appendChild(opt);
                        }
                    }

                    // 2. Extracts the next available sequence code dynamically per Year and Type
                    function getNextSequenceNumber(type, year) {
                        let maxSeq = 0;
                        referenceRepository.forEach(ref => {
                            let refYear = "";
                            if (ref.date) {
                                if (ref.date.includes('-')) {
                                    refYear = ref.date.split('-')[0];
                                } else if (ref.date.includes('/')) {
                                    refYear = ref.date.split('/')[2];
                                }
                            }
                            if (ref.type === type && String(refYear) === String(year)) {
                                const parts = ref.refId.split('-');
                                if (parts.length > 1) {
                                    const seqPart = parts[1].split('/')[0];
                                    const seq = parseInt(seqPart, 10);
                                    if (!isNaN(seq) && seq > maxSeq) {
                                        maxSeq = seq;
                                    }
                                }
                            }
                        });
                        return maxSeq + 1;
                    }

                    // 3. Updates the live UI sequence preview and status board counters
                    function updateSequentialIDLivePreview() {
                        const typeInput = document.getElementById('docRefField_type') || document.getElementById('docRefField_target_category');
                        const type = typeInput ? typeInput.value : "P";

                        const dateInput = document.getElementById('docRefField_date');
                        const recordDate = dateInput ? dateInput.value : getTodayISOString();
                        const selectedYear = recordDate ? recordDate.split('-')[0] : String(new Date().getFullYear());

                        // Calculate and render live preview
                        const nextSeq = getNextSequenceNumber(type, selectedYear);
                        const seqNumber = String(nextSeq).padStart(3, '0');
                        const previewID = `PS/${type}-${seqNumber}/${selectedYear}`;

                        const targetSpan = document.getElementById('lblLivePreviewID');
                        if (targetSpan) {
                            targetSpan.innerText = previewID;
                        }

                        // Update the status board counters for Patient, Admin, and Memo
                        const nextP = getNextSequenceNumber('P', selectedYear);
                        const nextA = getNextSequenceNumber('A', selectedYear);
                        const nextM = getNextSequenceNumber('M', selectedYear);

                        const lblP = document.getElementById('lblStatusBoard_P');
                        const lblA = document.getElementById('lblStatusBoard_A');
                        const lblM = document.getElementById('lblStatusBoard_M');

                        if (lblP) lblP.innerText = `#${String(nextP).padStart(3, '0')}`;
                        if (lblA) lblA.innerText = `#${String(nextA).padStart(3, '0')}`;
                        if (lblM) lblM.innerText = `#${String(nextM).padStart(3, '0')}`;
                    }

                    // 4. Synchronizes native date value with formatted text display
                    function syncDatePickerToVisibleInput(val) {
                        const visibleInput = document.getElementById('docRefField_date_visible');
                        if (visibleInput && val) {
                            const parts = val.split('-');
                            if (parts.length === 3) {
                                visibleInput.value = `${parts[2]}/${parts[1]}/${parts[0]}`;
                            }
                        }
                        updateSequentialIDLivePreview();
                    }

                    // 5. Renders generator form input fields dynamically
                    function renderDynamicDocumentReferenceGeneratorFields() {
                        const container = document.getElementById('dynamicReferenceGeneratorInputsContainer');
                        if (!container) return;

                        // Check if input fields already exist to avoid resetting typing values
                        if (document.getElementById('docRefField_type') || document.getElementById('docRefField_target_category')) {
                            updateSequentialIDLivePreview();
                            return;
                        }

                        container.innerHTML = "";
                        const currentSchema = globalTableSchemas.sequential_id || [];

                        // Render live sequence counts board & preview card
                        let statusBoard = `
        <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 12px; background: rgba(0,0,0,0.02); padding: 8px; border-radius: 6px; border: 1px solid var(--border);">
            <div style="text-align: center;">
                <span style="font-size: 8px; color: var(--text-muted); display: block; font-weight:700;">PATIENT (P)</span>
                <strong id="lblStatusBoard_P" style="font-size: 11px; color: var(--primary);">#001</strong>
            </div>
            <div style="text-align: center; border-left: 1px dashed var(--border); border-right: 1px dashed var(--border);">
                <span style="font-size: 8px; color: var(--text-muted); display: block; font-weight:700;">ADMIN (A)</span>
                <strong id="lblStatusBoard_A" style="font-size: 11px; color: var(--warning);">#001</strong>
            </div>
            <div style="text-align: center;">
                <span style="font-size: 8px; color: var(--text-muted); display: block; font-weight:700;">Memo (M)</span>
                <strong id="lblStatusBoard_M" style="font-size: 11px; color: var(--success);">#001</strong>
            </div>
        </div>
        
        <div id="sequentialLivePreviewBox" style="background: var(--primary-light); color: var(--primary); padding: 10px; border-radius: 6px; border: 1px solid var(--border); margin-bottom: 12px; text-align: center; font-weight: 700; font-size: 11px;">
            🎯 Next Target Sequence ID: <span id="lblLivePreviewID">PS/P-.../2026</span>
        </div>
    `;
                        container.innerHTML = statusBoard;

                        currentSchema.forEach(col => {
                            const normKey = col.key.toLowerCase();
                            if (normKey === 'refid' || normKey === 'identifier_code') return;

                            let inputHtml = "";
                            if (col.type === "date") {
                                inputHtml = `
                <div style="display: flex; align-items: center; position: relative;">
                    <input type="text" id="docRefField_${col.key}_visible" placeholder="DD/MM/YYYY" value="${getTodayFormattedDDMMYYYY()}" style="padding: 8px; border-radius: 6px; flex: 1; padding-right: 32px; background: var(--bg-inner); color: var(--text-body); cursor: pointer;" readonly>
                    <span style="position: absolute; right: 10px; cursor: pointer; font-size: 13px; user-select: none;">📅</span>
                    <input type="date" id="docRefField_${col.key}" value="${getTodayISOString()}" style="position: absolute; left: 0; top: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; z-index: 2;" onchange="syncDatePickerToVisibleInput(this.value)">
                </div>
            `;
                            } else if (col.type === "number") {
                                inputHtml = `<input type="number" id="docRefField_${col.key}" placeholder="0" style="padding: 8px; border-radius: 6px;">`;
                            } else if (col.type === "file") {
                                inputHtml = `<input type="file" id="docRefField_${col.key}" style="padding: 4px;">`;
                            } else if (normKey === 'type' || normKey === 'target_category') {
                                inputHtml = `
                <select id="docRefField_${col.key}" onchange="updateSequentialIDLivePreview()" style="padding: 8px; border-radius: 6px; cursor: pointer;">
                    <option value="P">Patient Document (P)</option>
                    <option value="A">Administrative File (A)</option>
                    <option value="M">Memo Form (M)</option>
                </select>
            `;
                            } else {
                                inputHtml = `<input type="text" id="docRefField_${col.key}" placeholder="Enter values..." style="padding: 8px; border-radius: 6px;">`;
                            }

                            container.innerHTML += `
            <div class="form-group" style="margin-bottom: 10px;">
                <label style="font-weight: 700; font-size: 9px; margin-bottom: 4px;">${col.name}</label>
                ${inputHtml}
            </div>
        `;
                        });

                        updateSequentialIDLivePreview();
                    }

                    // 6. Generates, registers, and commits the dynamic ID to the database array
                    function commitSequentialReferenceEntry(event) {
                        if (event) {
                            event.preventDefault();
                        }

                        const typeInput = document.getElementById('docRefField_type') || document.getElementById('docRefField_target_category');
                        const holderInput = document.getElementById('docRefField_holder') || document.getElementById('docRefField_receipt_holder');
                        const remarksInput = document.getElementById('docRefField_remarks') || document.getElementById('docRefField_action_remarks');

                        const dateInput = document.getElementById('docRefField_date');
                        const recordDate = dateInput ? dateInput.value : getTodayISOString();

                        const type = typeInput ? typeInput.value : "P";
                        const holder = holderInput ? holderInput.value.trim() : "";
                        const remarks = remarksInput ? remarksInput.value.trim() : "";

                        if (!holder || !remarks) {
                            customAlert("Please fill standard tracking parameter values.");
                            return;
                        }

                        const selectedYear = recordDate ? recordDate.split('-')[0] : String(new Date().getFullYear());
                        const nextSeq = getNextSequenceNumber(type, selectedYear);
                        const seqNumber = String(nextSeq).padStart(3, '0');
                        const refId = `PS/${type}-${seqNumber}/${selectedYear}`;

                        referenceRepository.push({
                            date: recordDate,
                            refId: refId,
                            type: type,
                            holder: holder,
                            remarks: remarks
                        });

                        // Clear input fields
                        if (holderInput) holderInput.value = "";
                        if (remarksInput) remarksInput.value = "";

                        // Reset date input back to today's defaults
                        if (dateInput) dateInput.value = getTodayISOString();
                        const visibleDateInput = document.getElementById('docRefField_date_visible');
                        if (visibleDateInput) visibleDateInput.value = getTodayFormattedDDMMYYYY();

                        updateSequentialIDLivePreview();
                        synchronizeWorkspaceCoreStatus();

                        customAlert(`Sequential ID Generated successfully! Identifier Code: ${refId}`);
                    }

                    // 7. Renders the modern sequential log list registry table
                    function renderDocumentRegistryTracker() {
                        const tbody = document.getElementById('referenceTrackerTableBody');
                        if (!tbody) return;
                        tbody.innerHTML = "";

                        const currentSchema = globalTableSchemas.sequential_id || [];

                        const selectedYear = document.getElementById('referenceYearSelector')?.value || "all";
                        const selectedMonth = document.getElementById('referenceMonthSelector')?.value || "all";
                        const searchQuery = document.getElementById('referenceSearchInput')?.value.toLowerCase() || "";

                        const filteredReferences = referenceRepository.filter(ref => {
                            let refYear = "";
                            let refMonth = "";

                            if (ref.date) {
                                if (ref.date.includes('-')) {
                                    const parts = ref.date.split('-');
                                    refYear = parts[0];
                                    refMonth = parts[1];
                                } else if (ref.date.includes('/')) {
                                    const parts = ref.date.split('/');
                                    refYear = parts[2];
                                    refMonth = parts[1];
                                }
                            }

                            const matchesYear = (selectedYear === "all" || String(refYear) === String(selectedYear));
                            const matchesMonth = (selectedMonth === "all" || String(refMonth) === String(selectedMonth));

                            const matchesSearch = !searchQuery ||
                                (ref.refId && ref.refId.toLowerCase().includes(searchQuery)) ||
                                (ref.holder && ref.holder.toLowerCase().includes(searchQuery)) ||
                                (ref.remarks && ref.remarks.toLowerCase().includes(searchQuery)) ||
                                (ref.date && ref.date.toLowerCase().includes(searchQuery)) ||
                                (formatDateToDDMMYYYY(ref.date).toLowerCase().includes(searchQuery));

                            return matchesYear && matchesMonth && matchesSearch;
                        });

                        if (filteredReferences.length === 0) {
                            tbody.innerHTML = `
            <tr>
                <td colspan="${currentSchema.length}" style="text-align:center; color:var(--text-muted); font-style:italic; padding: 24px;">
                    No sequential tracking entries match this query.
                </td>
            </tr>`;
                            return;
                        }

                        filteredReferences.forEach(ref => {
                            const tr = document.createElement('tr');
                            tr.style.transition = "background-color 0.2s ease";
                            tr.onmouseover = () => tr.style.backgroundColor = "rgba(0, 75, 135, 0.02)";
                            tr.onmouseout = () => tr.style.backgroundColor = "transparent";

                            let rowHtml = "";
                            currentSchema.forEach(col => {
                                const normKey = col.key.toLowerCase();
                                const propVal = ref[col.key] !== undefined ? ref[col.key] : "";

                                if (normKey === 'date' || normKey === 'compiled_reference_date') {
                                    const formattedDate = formatDateToDDMMYYYY(ref.date || propVal);
                                    rowHtml += `<td style="font-weight: 500; color: var(--text-muted);">${formattedDate}</td>`;
                                } else if (normKey === 'refid' || normKey === 'identifier_code') {
                                    rowHtml += `<td style="white-space: nowrap;"><code style="font-family: monospace; font-size: 11px; background: rgba(0,0,0,0.04); padding: 3px 6px; border-radius: 4px; font-weight: 700; color: var(--text-heading); white-space: nowrap;">${ref.refId || propVal}</code></td>`;
                                } else if (normKey === 'type' || normKey === 'target_category') {
                                    const typeVal = ref.type || propVal;
                                    let badgeClass = "badge-primary";
                                    let labelText = "Patient (P)";
                                    if (typeVal === "A") {
                                        badgeClass = "badge-warning";
                                        labelText = "Admin (A)";
                                    } else if (typeVal === "M") {
                                        badgeClass = "badge-success";
                                        labelText = "Memo (M)";
                                    }
                                    rowHtml += `<td><span class="badge ${badgeClass}" style="letter-spacing:0.3px; padding: 3px 6px;">${labelText}</span></td>`;
                                } else if (normKey === 'holder' || normKey === 'receipt_holder') {
                                    rowHtml += `<td style="font-weight: 600; color: var(--text-heading);">${ref.holder || propVal}</td>`;
                                } else if (normKey === 'remarks' || normKey === 'action_remarks') {
                                    rowHtml += `<td style="color: var(--text-muted); font-size: 10px; max-width: 250px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" title="${ref.remarks || propVal}">${ref.remarks || propVal}</td>`;
                                } else {
                                    rowHtml += `<td>${propVal || '-'}</td>`;
                                }
                            });
                            tr.innerHTML = rowHtml;
                            tbody.appendChild(tr);
                        });
                    }
                    // =========================================================
                    // UNIFIED TASKS & CALENDAR NOTES ENGINE
                    // =========================================================

                    // State Variables
                    let activeSelectedNotesDate = getTodayISOString();
                    let activeSelectedTasksDate = getTodayISOString();
                    let notebookPriorityDashboardLinkedDate = getTodayISOString();

                    let calendarNotesRepository = {};

                    let personalChecklistTasks = [];

                    // Sync helpers for layered date inputs (dd/mm/yyyy display)
                    function syncDatePicker_notes(val) {
                        const visible = document.getElementById('historicalNotesDatePicker_visible');
                        if (visible && val) {
                            visible.value = formatDateToDDMMYYYY(val);
                        }
                        shiftSelectedNotesDatePicker(val);
                    }

                    function syncDatePicker_tasks(val) {
                        const visible = document.getElementById('tasksDatePicker_visible');
                        if (visible && val) {
                            visible.value = formatDateToDDMMYYYY(val);
                        }
                        shiftSelectedTasksDatePicker(val);
                    }

                    // Date Shifting Helpers
                    function shiftSelectedNotesDatePicker(val) {
                        activeSelectedNotesDate = val;

                        // Sync the visual input box
                        const visible = document.getElementById('historicalNotesDatePicker_visible');
                        if (visible && val) {
                            visible.value = formatDateToDDMMYYYY(val);
                        }

                        renderNotesNotebookTaskPlanner();
                        renderNotesListByMonth();
                    }

                    function shiftSelectedTasksDatePicker(val) {
                        activeSelectedTasksDate = val;

                        // Sync the visual input box
                        const visible = document.getElementById('tasksDatePicker_visible');
                        if (visible && val) {
                            visible.value = formatDateToDDMMYYYY(val);
                        }

                        renderPersonalChecklistTasks();
                        renderTasksListByMonth();
                    }

                    // Render Calendar Grid and Selected Date Note
                    function renderNotesNotebookTaskPlanner() {
                        const grid = document.getElementById('notesCalendarGrid');
                        if (!grid) return;
                        grid.innerHTML = "";

                        let selectedDate = new Date(activeSelectedNotesDate);
                        let sampleDates = [];
                        for (let i = -3; i <= 3; i++) {
                            let d = new Date(selectedDate);
                            d.setDate(d.getDate() + i);
                            sampleDates.push(d.toISOString().split('T')[0]);
                        }

                        sampleDates.forEach(date => {
                            const btn = document.createElement('div');
                            btn.className = `calendar-day-btn ${activeSelectedNotesDate === date ? 'active' : ''}`;
                            btn.innerText = date.substring(8);
                            btn.onclick = () => {
                                shiftSelectedNotesDatePicker(date);
                            };
                            grid.appendChild(btn);
                        });

                        const notesField = document.getElementById('notesAreaField');
                        if (notesField) {
                            notesField.value = calendarNotesRepository[activeSelectedNotesDate] || "";
                        }

                        const notesPicker = document.getElementById('historicalNotesDatePicker');
                        if (notesPicker) {
                            notesPicker.value = activeSelectedNotesDate;
                        }

                        const syncToggle = document.getElementById('syncNoteToDashboardToggle');
                        if (syncToggle) {
                            syncToggle.checked = (notebookPriorityDashboardLinkedDate === activeSelectedNotesDate);
                        }
                    }

                    // Save Notes Operations
                    function autoSaveCurrentDateNote() {
                        const notesField = document.getElementById('notesAreaField');
                        if (notesField) {
                            calendarNotesRepository[activeSelectedNotesDate] = notesField.value;
                        }
                        renderNotesListByMonth();
                    }

                    function commitManualNotesSave() {
                        const notesField = document.getElementById('notesAreaField');
                        if (notesField) {
                            calendarNotesRepository[activeSelectedNotesDate] = notesField.value;
                            customAlert(`Notes notebook successfully committed for: ${formatDateToDDMMYYYY(activeSelectedNotesDate)}`);
                        }
                        renderNotesListByMonth();
                    }

                    function toggleNotePriorityOnDashboard() {
                        const syncToggle = document.getElementById('syncNoteToDashboardToggle');
                        notebookPriorityDashboardLinkedDate = (syncToggle && syncToggle.checked) ? activeSelectedNotesDate : "";
                    }

                    // Render Personal Tasks list
                    function renderPersonalChecklistTasks() {
                        const list = document.getElementById('personalTasksList');
                        if (!list) return;
                        list.innerHTML = "";

                        const targetTasks = personalChecklistTasks.filter(t => t.date === activeSelectedTasksDate);

                        if (targetTasks.length === 0) {
                            list.innerHTML = `<li style="font-style:italic; color:var(--text-muted); font-size:10px; text-align:center; padding:12px;">No checklist tasks assigned for this date.</li>`;
                            return;
                        }

                        targetTasks.forEach(t => {
                            const li = document.createElement('li');
                            li.style.cssText = "display:flex; justify-content:space-between; align-items:center; padding:8px 10px; background:var(--bg-inner); border:1px solid var(--border); border-radius:6px; box-shadow:var(--card-shadow);";
                            li.innerHTML = `
            <div style="display:flex; gap:8px; align-items:center;">
                <input type="checkbox" ${t.done ? 'checked' : ''} onchange="toggleTaskStateChecked(${t.id})">
                <span style="text-decoration:${t.done ? 'line-through' : 'none'}; opacity:${t.done ? '0.6' : '1'}; font-size:11px;">${escapeHtml(t.text)}</span>
            </div>
            <button class="action-btn" style="background:var(--danger); padding:4px 8px; font-size:9px;" onclick="deleteTaskItemRecord(${t.id})">🗑️</button>
        `;
                            list.appendChild(li);
                        });

                        const tasksPicker = document.getElementById('tasksDatePicker');
                        if (tasksPicker) {
                            tasksPicker.value = activeSelectedTasksDate;
                        }
                    }

                    // Task Mutation Handlers
                    function addNewPersonalTask() {
                        const input = document.getElementById('newTaskInput');
                        if (!input) return;
                        const text = input.value.trim();
                        if (!text) return;

                        personalChecklistTasks.push({
                            id: Date.now(),
                            text: text,
                            done: false,
                            date: activeSelectedTasksDate
                        });

                        input.value = "";
                        renderPersonalChecklistTasks();
                        renderTasksListByMonth();

                        if (globalActiveViewportModule === 'my_dashboard') {
                            renderDashboardTasks();
                        }
                    }

                    function toggleTaskStateChecked(id) {
                        const task = personalChecklistTasks.find(t => t.id === id);
                        if (task) {
                            task.done = !task.done;
                        }
                        renderPersonalChecklistTasks();
                        renderTasksListByMonth();
                        if (globalActiveViewportModule === 'my_dashboard') {
                            renderDashboardTasks();
                        }
                    }

                    function deleteTaskItemRecord(id) {
                        personalChecklistTasks = personalChecklistTasks.filter(t => t.id !== id);
                        renderPersonalChecklistTasks();
                        renderTasksListByMonth();
                        if (globalActiveViewportModule === 'my_dashboard') {
                            renderDashboardTasks();
                        }
                    }

                    // Month-based Search Ledgers for Notes and Tasks
                    function renderNotesListByMonth() {
                        const selector = document.getElementById('notesMonthSelector');
                        const tbody = document.getElementById('notesMonthlyListTableBody');
                        if (!selector || !tbody) return;

                        const selectedMonth = selector.value;
                        tbody.innerHTML = "";

                        let count = 0;
                        const sortedDates = Object.keys(calendarNotesRepository).sort((a, b) => new Date(b) - new Date(a));

                        sortedDates.forEach(dateKey => {
                            if (!selectedMonth || dateKey.substring(0, 7) === selectedMonth) {
                                const parts = dateKey.split('-');
                                let dayName = "-";
                                if (parts.length === 3) {
                                    const dObj = new Date(parts[0], parts[1] - 1, parts[2]);
                                    dayName = dObj.toLocaleDateString('en-US', { weekday: 'short' });
                                }

                                const tr = document.createElement('tr');
                                tr.innerHTML = `
                <td><strong style="cursor:pointer; color:var(--primary);" onclick="shiftSelectedNotesDatePicker('${dateKey}')">${formatDateToDDMMYYYY(dateKey)}</strong></td>
                <td><span class="badge badge-dark" style="font-size:9px;">${lookupTranslationValue(dayName)}</span></td>
                <td style="text-align:left; max-width:180px; word-break:break-word;">${escapeHtml(calendarNotesRepository[dateKey])}</td>
            `;
                                tbody.appendChild(tr);
                                count++;
                            }
                        });

                        if (count === 0) {
                            tbody.innerHTML = `<tr><td colspan="3" style="text-align:center; color:var(--text-muted); font-style:italic;">No notes found for this month.</td></tr>`;
                        }
                    }

                    function renderTasksListByMonth() {
                        const selector = document.getElementById('tasksMonthSelector');
                        const tbody = document.getElementById('tasksMonthlyListTableBody');
                        if (!selector || !tbody) return;

                        const selectedMonth = selector.value;
                        tbody.innerHTML = "";

                        let count = 0;
                        const sortedTasks = [...personalChecklistTasks].sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));

                        sortedTasks.forEach(t => {
                            const taskDate = t.date || new Date(t.id).toISOString().split('T')[0];

                            if (!selectedMonth || taskDate.substring(0, 7) === selectedMonth) {
                                const parts = taskDate.split('-');
                                let dayName = "-";
                                if (parts.length === 3) {
                                    const dObj = new Date(parts[0], parts[1] - 1, parts[2]);
                                    dayName = dObj.toLocaleDateString('en-US', { weekday: 'short' });
                                }

                                const tr = document.createElement('tr');
                                tr.innerHTML = `
                <td><strong style="cursor:pointer; color:var(--primary);" onclick="shiftSelectedTasksDatePicker('${taskDate}')">${formatDateToDDMMYYYY(taskDate)}</strong></td>
                <td><span class="badge badge-dark" style="font-size:9px;">${lookupTranslationValue(dayName)}</span></td>
                <td style="text-align:left; text-decoration:${t.done ? 'line-through' : 'none'}; opacity:${t.done ? '0.6' : '1'};">${escapeHtml(t.text)}</td>
                <td><span class="badge ${t.done ? 'badge-success' : 'badge-warning'}">${t.done ? 'Done' : 'Pending'}</span></td>
            `;
                                tbody.appendChild(tr);
                                count++;
                            }
                        });

                        if (count === 0) {
                            tbody.innerHTML = `<tr><td colspan="4" style="text-align:center; color:var(--text-muted); font-style:italic;">No tasks found for this month.</td></tr>`;
                        }
                    }

                    // Live Dashboard Today's Shift
                    function renderDashboardTodayShift() {
                        const el = document.getElementById('dashboardTodayShiftDetail');
                        if (!el) return;
                        const today = new Date();
                        const todayStr = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
                        const cycleMonth = todayStr.slice(0, 7);
                        const email = currentActiveSessionUser ? currentActiveSessionUser.email : '';
                        if (!email) { el.innerHTML = ''; return; }

                        let rosterData = null;
                        try {
                            const versions = getRosterVersions(cycleMonth);
                            if (versions.length > 0) {
                                const saved = localStorage.getItem(`rosterDraft_${cycleMonth}_${versions[versions.length - 1]}`);
                                if (saved) rosterData = JSON.parse(saved);
                            }
                            if (!rosterData) {
                                const pubData = tryLoadPublishedRoster(cycleMonth);
                                if (pubData) rosterData = pubData;
                            }
                        } catch (e) { }

                        if (!rosterData) {
                            el.innerHTML = `<span style="font-size:11px;color:var(--text-muted);">📋 No roster published for this month</span>`;
                            return;
                        }

                        // Find today's date in roster format
                        const d = String(today.getDate()).padStart(2, '0');
                        const m = today.toLocaleDateString('en-US', { month: 'short' });
                        const y = String(today.getFullYear()).slice(-2);
                        const yFull = today.getFullYear();
                        const dateStr = `${d}-${m}-${y}`;
                        const displayDate = `${d}-${m}-${yFull}`;

                        const myData = rosterData.therapists.find(t => t.email === email);
                        if (!myData) {
                            el.innerHTML = `<span style="font-size:11px;color:var(--text-muted);">📋 You are not in this month's roster</span>`;
                            return;
                        }

                        const assignment = rosterData.assignments[email] && rosterData.assignments[email][dateStr];
                        if (!assignment || assignment === 'OFF' || assignment === 'LEAVE' || assignment === 'HOLIDAY') {
                            const labels = { 'OFF': 'Day Off', 'LEAVE': 'On Leave', 'HOLIDAY': 'Public Holiday' };
                            el.innerHTML = `<span style="font-size:13px;">📋 ${displayDate}: <strong style="color:var(--text-muted);">${labels[assignment] || 'Day Off'}</strong></span>`;
                            return;
                        }

                        const shiftDef = ROSTER_SHIFT_TYPES[assignment];
                        if (!shiftDef) {
                            el.innerHTML = `<span style="font-size:11px;color:var(--text-muted);">📋 ${displayDate}: ${assignment}</span>`;
                            return;
                        }

                        el.innerHTML = `<span style="font-size:13px;">📋 ${displayDate}: <strong style="color:${shiftDef.textColor};background:${shiftDef.color};padding:3px 10px;border-radius:4px;border:1px solid ${shiftDef.borderColor};">${shiftDef.label}</strong> (${shiftDef.time})</span>`;
                    }

                    // ─── Today's Duty Roster Widget ────────────────────────────────────────────

                    function renderDashboardDutyRoster(data) {
                        const container = document.getElementById('dashboardDutyRoster');
                        if (!container) return;

                        const today = new Date();
                        const d = String(today.getDate()).padStart(2, '0');
                        const m = today.toLocaleDateString('en-US', { month: 'short' });
                        const yFull = today.getFullYear();
                        const dateStr = d + '-' + m + '-' + String(yFull).slice(-2);
                        const displayDate = d + '-' + m + '-' + yFull;

                        // Group therapists by shift type
                        const groups = {
                            '1ST_MR': [], '1ST_AF': [], '2ND_MR': [], '2ND_AF': [],
                            'THU_1ST': [], 'THU_2ND': [], 'OFF': [], 'LEAVE': [], 'HOLIDAY': []
                        };

                        data.therapists.forEach(t => {
                            const a = data.assignments[t.email] && data.assignments[t.email][dateStr] || 'OFF';
                            if (groups[a]) groups[a].push(t.name);
                        });

                        const sections = [
                            { key: '1ST_MR', title: '1st Floor Morning', time: '(08:00-15:40)', color: '#dbeafe', textColor: '#1e40af' },
                            { key: '1ST_AF', title: '1st Floor Afternoon', time: '(14:20-22:00)', color: '#fef3c7', textColor: '#92400e' },
                            { key: '2ND_MR', title: '2nd Floor Morning', time: '(08:00-15:40)', color: '#d1fae5', textColor: '#065f46' },
                            { key: '2ND_AF', title: '2nd Floor Afternoon', time: '(14:20-22:00)', color: '#fce7f3', textColor: '#9d174d' }
                        ];

                        const isThursday = today.getDay() === 4;

                        let html = `<div style="padding:14px;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;margin-top:12px;border-left:6px solid var(--primary);">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">
            <span style="font-size:18px;">👥</span>
            <span style="font-weight:700;font-size:15px;color:var(--text-heading);">Today's Duty Roster — ${displayDate}</span>
        </div>`;

                        if (isThursday) {
                            // Thursday: show only Thursday sections (hide regular grid)
                            const thu1 = groups['THU_1ST'];
                            const thu2 = groups['THU_2ND'];
                            html += `<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:16px;">`;
                            html += `<div style="background:#c7d2fe;border:1px solid #818cf8;border-radius:8px;padding:14px;">
            <div style="font-weight:700;font-size:13px;color:#3730a3;margin-bottom:10px;">Thursday — Floor 1 (08:00-15:00)</div>
            <div style="display:flex;flex-direction:column;gap:8px;">`;
                            if (thu1.length === 0) {
                                html += `<span style="font-size:11px;color:var(--text-muted);font-style:italic;">—</span>`;
                            } else {
                                thu1.forEach(n => { html += `<span style="font-size:13px;font-weight:600;color:var(--text-body);padding:6px 10px;background:rgba(255,255,255,0.6);border-radius:4px;">${escHtml(n)}</span>`; });
                            }
                            html += `</div></div>`;
                            html += `<div style="background:#ddd6fe;border:1px solid #a78bfa;border-radius:8px;padding:14px;">
            <div style="font-weight:700;font-size:13px;color:#5b21b6;margin-bottom:10px;">Thursday — Floor 2 (08:00-15:00)</div>
            <div style="display:flex;flex-direction:column;gap:8px;">`;
                            if (thu2.length === 0) {
                                html += `<span style="font-size:11px;color:var(--text-muted);font-style:italic;">—</span>`;
                            } else {
                                thu2.forEach(n => { html += `<span style="font-size:13px;font-weight:600;color:var(--text-body);padding:6px 10px;background:rgba(255,255,255,0.6);border-radius:4px;">${escHtml(n)}</span>`; });
                            }
                            html += `</div></div>`;
                            html += `</div>`;
                        } else {
                            // Non-Thursday: show regular 4-section grid
                            html += `<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;">`;
                            sections.forEach(s => {
                                const names = groups[s.key];
                                html += `<div style="background:${s.color}22;border:1px solid ${s.color};border-radius:8px;padding:10px;">
                <div style="font-weight:700;font-size:13px;color:${s.textColor};margin-bottom:4px;">${s.title}</div>
                <div style="font-size:10px;color:${s.textColor};opacity:0.7;margin-bottom:8px;">${s.time}</div>
                <div style="display:flex;flex-direction:column;gap:4px;">`;
                                if (names.length === 0) {
                                    html += `<span style="font-size:11px;color:var(--text-muted);font-style:italic;">—</span>`;
                                } else {
                                    names.forEach(n => {
                                        html += `<span style="font-size:12px;font-weight:600;color:var(--text-body);padding:3px 6px;background:rgba(255,255,255,0.6);border-radius:4px;">${escHtml(n)}</span>`;
                                    });
                                }
                                html += `</div></div>`;
                            });
                            html += `</div>`;
                        }

                        // Add OFF/LEAVE/HOLIDAY as a footer
                        const offNames = groups['OFF'];
                        const leaveNames = groups['LEAVE'];
                        const holidayNames = groups['HOLIDAY'];
                        if (offNames.length || leaveNames.length || holidayNames.length) {
                            html += `<div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--border);display:flex;flex-wrap:wrap;gap:8px;font-size:12px;">`;
                            if (offNames.length) {
                                html += `<span style="color:var(--text-muted);font-weight:600;">Off: ${offNames.map(n => escHtml(n)).join(', ')}</span>`;
                            }
                            if (leaveNames.length) {
                                html += `<span style="color:#991b1b;font-weight:600;">Leave: ${leaveNames.map(n => escHtml(n)).join(', ')}</span>`;
                            }
                            if (holidayNames.length) {
                                html += `<span style="color:#9a3412;font-weight:600;">Holiday: ${holidayNames.map(n => escHtml(n)).join(', ')}</span>`;
                            }
                            html += `</div>`;
                        }

                        html += `</div>`;
                        container.innerHTML = html;
                    }

                    function renderDashboardDutyRosterWidget() {
                        const container = document.getElementById('dashboardDutyRoster');
                        if (!container) return;
                        const role = currentActiveSessionUser ? currentActiveSessionUser.position : '';
                        if (!role || !allowedDutyRosterRoles.includes(role)) { container.innerHTML = ''; return; }

                        const today = new Date();
                        const todayStr = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
                        const cycleMonth = todayStr.slice(0, 7);

                        let rosterData = null;
                        try {
                            const pubData = tryLoadPublishedRoster(cycleMonth);
                            if (pubData) rosterData = pubData;
                        } catch (e) { }

                        if (!rosterData) { container.innerHTML = ''; return; }
                        renderDashboardDutyRoster(rosterData);
                    }

                    // Live Dashboard Tasks Renderer
                    function renderDashboardUpcomingHolidays() {
                        const widget = document.getElementById('dashboardUpcomingHolidaysWidget');
                        if (!widget) return;

                        const today = new Date();
                        today.setHours(0, 0, 0, 0);
                        const thirtyDaysLater = new Date(today);
                        thirtyDaysLater.setDate(today.getDate() + 30);

                        const upcoming = [];

                        // Use psCalData (new calendar system) - only actual holidays/special days, NOT Fridays
                        Object.keys(psCalData).forEach(dateStr => {
                            const dp = dateStr.split('-');
                            const date = new Date(parseInt(dp[0]), parseInt(dp[1]) - 1, parseInt(dp[2]));
                            if (date >= today && date <= thirtyDaysLater) {
                                const item = psCalData[dateStr];
                                // Only show holidays and special days (not regular working days or prof-dev)
                                if (item.t === 'holiday' || item.t === 'special') {
                                    const daysUntil = Math.ceil((date - today) / (1000 * 60 * 60 * 24));
                                    const typeConfig = getPSCalTypeConfig(item.t);
                                    upcoming.push({
                                        date: dateStr,
                                        daysUntil: daysUntil,
                                        type: item.t,
                                        name: item.n,
                                        bg: typeConfig ? typeConfig.bg : '#e5e7eb',
                                        border: typeConfig ? typeConfig.border : '#d1d5db',
                                        text: typeConfig ? typeConfig.text : '#6b7280'
                                    });
                                }
                            }
                        });

                        upcoming.sort((a, b) => a.daysUntil - b.daysUntil);

                        if (upcoming.length === 0) {
                            widget.innerHTML = '<span style="color: var(--text-muted); font-size: 10px; font-style: italic;">No upcoming holidays in the next 30 days.</span>';
                            return;
                        }

                        // Compact vertical list (not stretched horizontal)
                        widget.innerHTML = '';
                        widget.style.cssText = 'display: flex; flex-direction: column; gap: 4px; max-height: 140px; overflow-y: auto; padding-right: 4px;';

                        upcoming.slice(0, 5).forEach(item => {
                            const div = document.createElement('div');
                            div.style.cssText = 'display: flex; align-items: center; gap: 8px; padding: 5px 8px; background: var(--bg-inner); border: 1px solid var(--border); border-radius: 5px; border-left: 3px solid ' + item.border + ';';
                            div.innerHTML = '<span style="font-size: 9px; font-weight: 700; color: ' + item.text + '; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1;">' + item.name + '</span><span style="font-size: 9px; font-weight: 600; color: var(--text-heading); white-space: nowrap;">' + formatDateToDDMMYYYY(item.date) + '</span><span style="font-size: 8px; color: var(--text-muted); white-space: nowrap;">' + (item.daysUntil === 0 ? 'Today' : item.daysUntil === 1 ? '1d' : item.daysUntil + 'd') + '</span>';
                            widget.appendChild(div);
                        });
                    }

                    function renderDashboardTasks() {
                        const listAnchor = document.getElementById('dashboardTasksListAnchor');
                        if (!listAnchor) return;

                        const todayStr = getTodayISOString();
                        const todaysTasks = personalChecklistTasks.filter(t => t.date === todayStr);

                        if (todaysTasks.length === 0) {
                            listAnchor.innerHTML = `
            <div style="text-align:center; color:var(--text-muted); font-style:italic; padding:12px; font-size:10px;">
                No operational tasks scheduled for today.
            </div>
        `;
                            return;
                        }

                        let html = `<ul style="list-style:none; display:flex; flex-direction:column; gap:6px;">`;
                        todaysTasks.forEach(t => {
                            html += `
            <li style="padding:8px; background:var(--bg-inner); border:1px solid var(--border); border-radius:6px; display:flex; justify-content:space-between; align-items:center; box-shadow:var(--card-shadow);">
                <span style="font-size:11px; text-decoration:${t.done ? 'line-through' : 'none'}; opacity:${t.done ? '0.6' : '1'};">${escapeHtml(t.text)}</span>
                <span class="badge ${t.done ? 'badge-success' : 'badge-warning'}" style="font-size:8px; cursor:pointer;" onclick="toggleTaskStateChecked(${t.id})">
                    ${t.done ? 'Verified' : 'Pending'}
                </span>
            </li>
        `;
                        });
                        html += `</ul>`;
                        listAnchor.innerHTML = html;
                    }
                    // Adds a new task directly from the dashboard mapped to today's date
                    function addNewDashboardTask() {
                        const input = document.getElementById('dashNewTaskInput');
                        if (!input) return;
                        const text = input.value.trim();
                        if (!text) return;

                        const todayStr = getTodayISOString();
                        personalChecklistTasks.push({
                            id: Date.now(),
                            text: text,
                            done: false,
                            date: todayStr
                        });

                        input.value = "";
                        renderDashboardTasks();
                        renderTasksListByMonth();

                        // Sync with the main Tasks tab list if its selected date matches today's date
                        if (activeSelectedTasksDate === todayStr) {
                            renderPersonalChecklistTasks();
                        }
                    }

                    // Automatically saves the note typed on the dashboard directly to today's ledger entry
                    function autoSaveDashboardTodayNote(val) {
                        const todayStr = getTodayISOString();
                        calendarNotesRepository[todayStr] = val;

                        // Sync with the main Notes Notebook textarea if its selected date matches today's date
                        if (activeSelectedNotesDate === todayStr) {
                            const notesField = document.getElementById('notesAreaField');
                            if (notesField) {
                                notesField.value = val;
                            }
                        }
                        renderNotesListByMonth();
                    }
