                    function saveBroadcasterRolesConfiguration() {
                        const rolesList = Object.keys(globalRolePermissionsMatrix);
                        let chosen = [];
                        rolesList.forEach(role => {
                            const el = document.getElementById(`broadcasterRoleSel_${role}`);
                            if (el && el.checked) {
                                chosen.push(role);
                            }
                        });

                        if (chosen.length === 0) {
                            customAlert("Please authorize at least one broadcaster profile.");
                            return;
                        }

                        allowedBroadcasterRoles.length = 0;
                        chosen.forEach(function(r) { allowedBroadcasterRoles.push(r); });
                        savePermissionRegistry();
                        customAlert("Broadcast Center authorization updated successfully.");
                        synchronizeWorkspaceCoreStatus();
                    }

