                    function savePersonalExpiryItem() {
                        const editId = document.getElementById('personalExpiryEditId').value;
                        const name = document.getElementById('personalExpiryName').value.trim();
                        const category = document.getElementById('personalExpiryCategory').value;
                        const expiryDate = document.getElementById('personalExpiryDate').value;
                        const status = document.getElementById('personalExpiryStatus').value;
                        const notes = document.getElementById('personalExpiryNotes').value.trim();
                        if (!name) { customAlert("Please enter an item name."); return; }
                        if (!expiryDate) { customAlert("Please select an expiry date."); return; }
                        if (editId) {
                            const idx = globalPersonalExpiryItems.findIndex(i => i.id === parseInt(editId));
                            if (idx >= 0) {
                                globalPersonalExpiryItems[idx] = { ...globalPersonalExpiryItems[idx], name, category, expiryDate, status, notes };
                            }
                        } else {
                            globalPersonalExpiryItems.push({ id: Date.now(), email: currentActiveSessionUser.email, name, category, expiryDate, status, notes, createdAt: new Date().toISOString() });
                        }
                        savePersonalExpiryData();
                        closePersonalExpiryModal();
                        renderPersonalExpiry();
                        customAlert(editId ? "Personal date updated." : "Personal date added.");
                    }
                    function deletePersonalExpiryItem(id) {
                        if (!confirm("Delete this personal date?")) return;
                        globalPersonalExpiryItems = globalPersonalExpiryItems.filter(i => i.id !== id);
                        savePersonalExpiryData();
                        renderPersonalExpiry();
                    }
                    function renderPersonalExpiry() {
                        const container = document.getElementById('personalExpiryGrid');
                        const notice = document.getElementById('personalExpiryContextNotice');
                        if (!container) return;
                        const filter = document.getElementById('personalExpiryCategoryFilter').value;
                        const search = (document.getElementById('personalExpirySearchField').value || '').toLowerCase();
                        let items = globalPersonalExpiryItems.filter(i => i.email === currentActiveSessionUser.email);
                        if (filter === 'expired') items = items.filter(i => getExpiryState(i.expiryDate).label === 'expired');
                        else if (filter === 'warning') items = items.filter(i => getExpiryState(i.expiryDate).label === 'warning');
                        if (search) items = items.filter(i => i.name.toLowerCase().includes(search) || i.category.toLowerCase().includes(search));
                        items.sort((a, b) => {
                            if (!a.expiryDate) return 1;
                            if (!b.expiryDate) return -1;
                            return new Date(a.expiryDate) - new Date(b.expiryDate);
                        });
                        if (notice) {
                            const total = globalPersonalExpiryItems.filter(i => i.email === currentActiveSessionUser.email).length;
                            const expired = globalPersonalExpiryItems.filter(i => i.email === currentActiveSessionUser.email && getExpiryState(i.expiryDate).label === 'expired').length;
                            const warning = globalPersonalExpiryItems.filter(i => i.email === currentActiveSessionUser.email && getExpiryState(i.expiryDate).label === 'warning').length;
                            notice.textContent = total + ' items  ·  ' + expired + ' expired  ·  ' + warning + ' expiring soon';
                        }
                        if (items.length === 0) {
                            container.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted);font-size:12px;">No personal expiry dates. Click "Add Personal Date" to get started.</div>';
                            return;
                        }
                        container.innerHTML = items.map(item => {
                            const state = getExpiryState(item.expiryDate);
                            const isExpired = state.label === 'expired';
                            const isWarning = state.label === 'warning';
                            const daysLeft = item.expiryDate ? Math.ceil((new Date(item.expiryDate) - new Date()) / (1000 * 60 * 60 * 24)) : null;
                            let statusBadge = '<span class="badge badge-success">Active</span>';
                            if (isExpired) statusBadge = '<span class="badge badge-danger">Expired</span>';
                            else if (isWarning) statusBadge = '<span class="badge badge-warning">' + daysLeft + ' days left</span>';
                            else if (daysLeft !== null && daysLeft > 0) statusBadge = '<span class="badge badge-success">' + daysLeft + ' days left</span>';
                            return '<div class="staff-card" style="border-left:5px solid ' + state.color + ';">' +
                                '<div class="staff-card-header">' +
                                '<div style="flex:1;min-width:0;">' +
                                '<div style="font-size:14px;font-weight:700;color:var(--text-heading);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + item.name + '</div>' +
                                '<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">' + item.category + '</div>' +
                                '</div>' +
                                '<div style="text-align:right;flex-shrink:0;">' + statusBadge + '</div>' +
                                '</div>' +
                                '<div class="staff-card-body">' +
                                '<div class="staff-card-compliance-list">' +
                                '<div class="compliance-badge"><span>Expiry Date</span><span style="font-weight:700;color:' + state.color + ';">' + (item.expiryDate ? formatDateToDDMMYYYY(item.expiryDate) : '-') + '</span></div>' +
                                '<div class="compliance-badge"><span>Status</span><span>' + (item.status || 'active') + '</span></div>' +
                                (item.notes ? '<div class="compliance-badge"><span>Notes</span><span>' + item.notes + '</span></div>' : '') +
                                '</div>' +
                                '</div>' +
                                '<div style="display:flex;gap:6px;margin-top:8px;">' +
                                '<button class="action-btn" onclick="openAddPersonalExpiryModal(' + item.id + ')" style="flex:1;justify-content:center;padding:5px 8px;font-size:10px;background:var(--primary);">✏️ Edit</button>' +
                                '<button class="action-btn" onclick="deletePersonalExpiryItem(' + item.id + ')" style="flex:1;justify-content:center;padding:5px 8px;font-size:10px;background:var(--danger);">🗑️ Delete</button>' +
                                '</div>' +
                                '</div>';
                        }).join('');
                    }

                    // Bind Expiry Modal events on DOM ready
                    document.addEventListener('DOMContentLoaded', function () {
                        // Personal Expiry Modal
                        var pov = document.getElementById('personalExpiryModal');
                        if (pov) {
                            pov.addEventListener('click', function (e) { if (e.target === this) this.style.display = 'none'; });
                            document.getElementById('personalExpiryModalCloseBtn').addEventListener('click', function () { pov.style.display = 'none'; });
                            document.getElementById('personalExpiryCancelBtn').addEventListener('click', function () { pov.style.display = 'none'; });
                            document.getElementById('personalExpirySaveBtn').addEventListener('click', savePersonalExpiryItem);
                        }
                        // Expiry Tracker Modal
                        var ov = document.getElementById('expiryItemModal');
                        if (ov) {
                            ov.addEventListener('click', function (e) { if (e.target === this) this.style.display = 'none'; });
                            var closeBtn = document.getElementById('expiryModalCloseBtn');
                            if (closeBtn) closeBtn.addEventListener('click', function () { ov.style.display = 'none'; });
                            var cancelBtn = document.getElementById('expiryCancelBtn');
                            if (cancelBtn) cancelBtn.addEventListener('click', function () { ov.style.display = 'none'; });
                            var saveBtn = document.getElementById('expirySaveBtn');
                            if (saveBtn) saveBtn.addEventListener('click', saveExpiryItem);
                        }
                    });

                    // ==========================================
                    // INITIALIZATION
                    // ==========================================

                    document.addEventListener('DOMContentLoaded', () => {
                        function syncAllMonthPickers() {
                            document.querySelectorAll('input[type="month"]').forEach(el => el.value = new Date().toISOString().slice(0, 7));
                        }
                        syncAllMonthPickers();
                        var stored = localStorage.getItem('physioFdoAttManual');
                        if (!stored || stored === '{}') {
                            localStorage.setItem('physioFdoAttManual', JSON.stringify({}));
                        }
                        const observer = new MutationObserver(() => {
                            document.querySelectorAll('input[type="month"]').forEach(el => { if (!el.value) el.value = new Date().toISOString().slice(0, 7); });
                            const fdoMod = document.getElementById('mod_fdo_sheets');
                            if (fdoMod && !fdoMod.classList.contains('hidden') && !document.getElementById('mod_fdo_sheets').hidden) {
                                initFdoSheets();
                            }
                            const solMod = document.getElementById('mod_solarelle_patients');
                            if (solMod && !solMod.classList.contains('hidden')) {
                                const tb = document.getElementById('solarelleBody');
                                if (tb && tb.children.length === 0) initSolarellePatients();
                            }
                            const seaMod = document.getElementById('mod_seales');
                            if (seaMod && !seaMod.classList.contains('hidden')) {
                                const tb = document.getElementById('sealesBody');
                                if (tb && !tb.dataset.initialized) initSealesTracker();
                            }
                            const aaMod = document.getElementById('mod_aasandha_assessment');
                            if (aaMod && !aaMod.classList.contains('hidden')) {
                                const dateInput = document.getElementById('aaEntryDate');
                                if (dateInput && !dateInput.value) dateInput.value = new Date().toISOString().slice(0, 10);
                                populateAasandhaDropdowns();
                                const frm = document.getElementById('aaInlineForm');
                                if (frm) frm.style.display = 'flex';
                                const tb = document.getElementById('aasandhaBody');
                                if (tb) renderAasandhaTable();
                                const dcPicker = document.getElementById('dischargeMonthPicker');
                                if (dcPicker) dcPicker.value = new Date().toISOString().slice(0, 7);
                                populateDischargeDropdowns();
                                const dcFrm = document.getElementById('dischargeInlineForm');
                                if (dcFrm) dcFrm.style.display = 'flex';
                            }
                            const fdoAttMod = document.getElementById('mod_fdo_attendance');
                            if (fdoAttMod && !fdoAttMod.classList.contains('hidden')) {
                                renderOtAttendance();
                            }
                        });
                        document.querySelectorAll('.view-module').forEach(el => {
                            observer.observe(el, { attributes: true, attributeFilter: ['class'] });
                        });
                    });
        if ('serviceWorker' in navigator && location.protocol !== 'file:') {
            navigator.serviceWorker.register('sw.js').catch(function (err) {
                console.log('SW registration failed:', err);
            });
        }